# The chat and run a log line belongs to (ELI-368). Each reply opens a
# log_scope with its chat (Pipe.pipe) and each run inside it another with no
# run yet (_PipeTurn.run); the run id is set once known (_PipeTurn.our_run_id).
# The scope's end puts the caller's ids back, so a task that consumes replies
# one after another never logs one reply's ids on the next. asyncio copies the
# context into every task a reply starts, so the turn writer and other
# background work log under the reply's ids, and two replies at once (two
# tasks) never see each other's.
_LOG_CHAT = contextvars.ContextVar("pipe_log_chat", default=None)
_LOG_RUN = contextvars.ContextVar("pipe_log_run", default=None)


@contextlib.contextmanager
def log_scope(chat_id=None, run_id=None):
    """pipe_log lines inside carry these ids (None: no tag); the caller's ids
    come back when the block ends."""
    tokens = ((_LOG_CHAT, _LOG_CHAT.set(chat_id)), (_LOG_RUN, _LOG_RUN.set(run_id)))
    try:
        yield
    finally:
        for var, token in tokens:
            try:
                var.reset(token)
            except ValueError:
                # Closed from another context (an async generator finalized by
                # another task): our values were never set there, so nothing
                # to undo.
                pass


def log_run(run_id):
    """The run this scope's lines belong to from now on (None: no run)."""
    _LOG_RUN.set(run_id)


def pipe_log(*args):
    """Log to stdout so it appears in OWUI's backend logs.

    A line logged inside a reply ends with `chat_id=<id> runId=<id>` (a run id
    the line already names is not repeated): central logs index both, so
    `logtrace <chat id>` finds the whole turn.
    """
    msg = ' '.join(str(a) for a in args)
    chat, run = _LOG_CHAT.get(), _LOG_RUN.get()
    tags = []
    # Only the tag itself counts as already there for the chat: a run id like
    # msg-<chat id>-... contains the chat id, and a search for chat_id=<id>
    # must still find its line.
    if chat and f"chat_id={chat}" not in msg:
        tags.append(f"chat_id={chat}")
    if run and run not in msg:
        tags.append(f"runId={run}")
    print(f"[openclaw-pipe] {' '.join([msg, *tags])}", flush=True)



# The event loop holds tasks weakly, so a bare create_task() can be collected
# before it runs. spawn_background keeps a reference until the task is done.
_BACKGROUND_TASKS: set = set()


def spawn_background(coro):
    task = asyncio.create_task(coro)
    _BACKGROUND_TASKS.add(task)
    task.add_done_callback(_BACKGROUND_TASKS.discard)
    return task


# --- identity --------------------------------------------------------------

def _generate_device_identity():
    """New Ed25519 identity: dict with id, publicKey and privateKey (PEM)."""
    pk = ed25519.Ed25519PrivateKey.generate()
    pub = pk.public_key()
    raw = pub.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw
    )
    pub_b64 = base64.urlsafe_b64encode(raw).decode().rstrip("=")
    did = hashlib.sha256(raw).hexdigest()
    pem = pk.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption()
    ).decode()
    return dict(id=did, publicKey=pub_b64, privateKey=pem)


def _sign_challenge(ident, nonce, ts, token_str="", scopes=None):
    """Sign the WebSocket challenge. The Gateway checks the signed scope list
    against the scopes requested."""
    parts = [
        "v2", ident["id"], "webchat", "cli", "operator",
        ",".join(GATEWAY_SCOPES if scopes is None else scopes), str(ts), token_str, nonce
    ]
    pk = serialization.load_pem_private_key(
        ident["privateKey"].encode(), password=None, backend=default_backend()
    )
    sig = pk.sign(("|".join(parts)).encode())
    return dict(
        id=ident["id"],
        publicKey=ident["publicKey"],
        signature=base64.urlsafe_b64encode(sig).decode().rstrip("="),
        signedAt=ts,
        nonce=nonce
    )


def _parse_device_identity(raw):
    """Parse DEVICE_IDENTITY JSON, handling unescaped newlines in PEM keys."""
    if not raw:
        return None
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        pass
    try:
        def _fix_pem(m):
            return m.group(1) + m.group(2).replace("\n", "").replace("\r", "") + m.group(3)
        fixed = re.sub(
            r'("privateKey":\s*")(.*?)("[, \\}])',
            _fix_pem, raw, flags=re.DOTALL
        )
        return json.loads(fixed)
    except Exception:
        return None


# --- state -----------------------------------------------------------------


def _state_dir(path=None):
    """Return the persistent bridge state directory, creating it if possible."""
    root = path or os.environ.get("OPENCLAW_BRIDGE_STATE_DIR") or "/data/openclaw-bridge"
    try:
        os.makedirs(root, mode=0o700, exist_ok=True)
        return root
    except Exception as ex:
        fallback = "/tmp/openclaw-bridge"
        os.makedirs(fallback, mode=0o700, exist_ok=True)
        pipe_log(f"STATE_DIR unavailable ({root}: {ex}); using {fallback}")
        return fallback


def _read_json_file(path):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return None
    except Exception as ex:
        pipe_log(f"Failed reading {path}: {ex}")
        return None


def _write_json_file(path, data):
    try:
        tmp = f"{path}.tmp"
        with open(tmp, "w") as f:
            json.dump(data, f, separators=(",", ":"))
        os.chmod(tmp, 0o600)
        os.replace(tmp, path)
        return True
    except Exception as ex:
        pipe_log(f"Failed writing {path}: {ex}")
        return False




# Sub-agent child index (ELI-152). The Gateway has no "children of" read and
# `sessions.list {spawnedBy}` drops ended children after 30 min, so the Pipe
# and Status Action share this flock-guarded file. `tasks` title a child before
# its transcript has the spawn message (ELI-178). `runs` let a cleanup "delete"
# child be read via `agent.wait` (ELI-276, ELI-277).

_SUBAGENT_INDEX_NAME = "subagent-children.json"
_SUBAGENT_INDEX_KEEP_MS = 180 * 86400 * 1000
_SUBAGENT_INDEX_PER_PARENT = 200
_SUBAGENT_SNAPSHOT_KEYS = ("key", "label", "status", "startedAt", "createdAt", "updatedAt", "endedAt",
                           "lastRunError", "spawnedBy", "parentSessionKey", "gone")


def _subagent_ended(row) -> bool:
    """Whether a child row's run is over; keep it, as cleanup "delete" removes
    the session soon after (ELI-276)."""
    return (row or {}).get("status") not in (None, "running", "queued") and row.get("hasActiveRun") is not True


def _subagent_index_path():
    return os.path.join(_state_dir(), _SUBAGENT_INDEX_NAME)


def _subagent_index_read() -> dict:
    data = _read_json_file(_subagent_index_path())
    if not isinstance(data, dict) or not isinstance(data.get("parents"), dict):
        return {"seeded": False, "parents": {}}
    return data


def _subagent_index_update(change) -> None:
    """Apply `change(index)` to the file under its lock, then prune it."""
    path = _subagent_index_path()
    try:
        import fcntl
    except ImportError:
        fcntl = None
    try:
        with open(path + ".lock", "a") as lock:
            if fcntl:
                fcntl.flock(lock, fcntl.LOCK_EX)
            index = _subagent_index_read()
            change(index)
            now = int(time.time() * 1000)
            parents = index["parents"]
            for parent in [p for p, e in parents.items() if now - (e.get("at") or 0) > _SUBAGENT_INDEX_KEEP_MS]:
                del parents[parent]
            for entry in parents.values():
                children = entry["children"]
                if len(children) > _SUBAGENT_INDEX_PER_PARENT:
                    # A key with no row yet is the newest spawn: kept first.
                    newest = sorted(children, key=lambda k: -((children[k] or {}).get("startedAt")
                                                              or (children[k] or {}).get("createdAt")
                                                              or now))
                    entry["children"] = {k: children[k] for k in newest[:_SUBAGENT_INDEX_PER_PARENT]}
                for field in ("tasks", "runs"):
                    if entry.get(field):
                        entry[field] = {k: t for k, t in entry[field].items() if k in entry["children"]}
            _write_json_file(path, index)
    except Exception as ex:
        pipe_log(f"[subagents] could not update the child index: {ex}")


def _subagent_children(parent) -> dict:
    """{child key: its last row (or None, a spawn not read yet)} of `parent`."""
    entry = _subagent_index_read()["parents"].get(parent) or {}
    return dict(entry.get("children") or {})


def _subagent_tasks(parent) -> dict:
    """{child key: the task its spawn call was given} of `parent`."""
    entry = _subagent_index_read()["parents"].get(parent) or {}
    return dict(entry.get("tasks") or {})


def _subagent_runs(parent) -> dict:
    """{child key: {"runId", "label", "error"}} of `parent`'s spawns."""
    entry = _subagent_index_read()["parents"].get(parent) or {}
    return dict(entry.get("runs") or {})


def _subagent_record(child) -> dict | None:
    """{"parent", "row", "task", "run"} for one child, or None if unknown."""
    for parent, entry in _subagent_index_read()["parents"].items():
        if child in (entry.get("children") or {}):
            return {"parent": parent, "row": entry["children"][child],
                    "task": (entry.get("tasks") or {}).get(child),
                    "run": (entry.get("runs") or {}).get(child) or {}}
    return None


def _subagent_remember(parent, rows=(), keys=(), tasks=None, runs=None) -> None:
    """Merge spawned `keys`, read `rows`, `tasks` and `runs` into `parent`'s entry."""
    rows, keys, tasks, runs = list(rows), list(keys), dict(tasks or {}), dict(runs or {})
    if not parent or not (rows or keys or tasks or runs):
        return

    def change(index):
        entry = index["parents"].setdefault(parent, {"at": 0, "children": {}})
        entry["at"] = int(time.time() * 1000)
        for key in [*keys, *tasks, *runs]:
            entry["children"].setdefault(key, None)
        if tasks:
            entry.setdefault("tasks", {}).update(tasks)
        for key, fields in runs.items():
            entry.setdefault("runs", {}).setdefault(key, {}).update(fields)
        for row in rows:
            entry["children"][row["key"]] = {k: row[k] for k in _SUBAGENT_SNAPSHOT_KEYS if row.get(k) is not None}
    _subagent_index_update(change)


def _subagent_index_seeded() -> bool:
    return bool(_subagent_index_read().get("seeded"))


def _subagent_index_mark_seeded(rows=()) -> None:
    """Fold every child in `rows` (one full list) in by its parent, once."""
    rows = list(rows)

    def change(index):
        now = int(time.time() * 1000)
        for row in rows:
            parent = row.get("spawnedBy") or row.get("parentSessionKey")
            if not parent or not row.get("key") or row["key"] == parent:
                continue
            entry = index["parents"].setdefault(parent, {"at": now, "children": {}})
            entry["children"].setdefault(
                row["key"], {k: row[k] for k in _SUBAGENT_SNAPSHOT_KEYS if row.get(k) is not None})
        index["seeded"] = True
    _subagent_index_update(change)


# --- turns -----------------------------------------------------------------

# ---------------------------------------------------------------------------
# Turn identity (ELI-100, docs/design/agent-turns.md 2.2)
# ---------------------------------------------------------------------------
# A run's message is decided from its run id alone, so any process agrees.
#   msg-<chat>-<M>-<suffix>   pipe-started run: message M
#   owui-action-<...>         Status Action runs (/compact): none
#   anything else             agent turn: uuid5(TURN_NS, "<key>:<run>")

TURN_NS = uuid.UUID("6f1c3e2a-9d4b-4c6e-8a1f-0e0a1b100100")
ACTION_RUN_PREFIX = "owui-action-"
_UUID_RE = r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"
# `parse_pipe_run_id`'s kind of a run that writes a reply.
PIPE_RUN_REPLY = "reply"
_PIPE_RUN_RE = re.compile(rf"^msg-(?P<chat>{_UUID_RE})-(?P<message>{_UUID_RE})-(?P<rest>.+)$")


def pipe_run_id(chat_id: str, message_id: str, kind: str | None = None) -> str:
    """Run id for a pipe run writing into `message_id`; `_run_id_sent_at` reads the trailing time."""
    return f"msg-{chat_id}-{message_id}-{kind + '-' if kind else ''}{time.time()}"


def parse_pipe_run_id(run_id: str) -> dict | None:
    """{chat, message, kind} of a pipe-started run id, else None."""
    m = _PIPE_RUN_RE.match(run_id or "")
    if not m:
        return None
    head = m.group("rest").split("-", 1)[0]
    kind = head if head in ("input", "resume") else PIPE_RUN_REPLY
    return {"chat": m.group("chat"), "message": m.group("message"), "kind": kind}


def parse_announce_run_id(run_id: str) -> dict | None:
    """{child_session, child_run} of a sub-agent announce run, else None.
    Id shape: `announce:v1:<childSessionKey>:<childRunId>[:wake|:retry-<n>]` (announce-idempotency-D7LnUTJR.mjs:4-10)."""
    if not (run_id or "").startswith("announce:v1:"):
        return None
    rest = re.sub(r":(?:wake|retry-\d+)$", "", run_id[len("announce:v1:"):])
    child_session, _, child_run = rest.rpartition(":")
    if not child_session.startswith("agent:") or not child_run:
        return None
    return {"child_session": child_session, "child_run": child_run}


def turn_message_id(session_key: str, run_id: str, chat_id: str | None = None) -> str | None:
    """The message `run_id` renders into, or None (Status Action runs). A pipe
    run id is only trusted inside the chat it was minted for."""
    if not run_id or run_id.startswith(ACTION_RUN_PREFIX):
        return None
    parsed = parse_pipe_run_id(run_id)
    if parsed and (chat_id is None or parsed["chat"] == chat_id):
        return parsed["message"]
    return str(uuid.uuid5(TURN_NS, f"{session_key}:{run_id}"))


# ---------------------------------------------------------------------------
# Claim: one message per run, anchored at the tail (DESIGN 2.3)
# ---------------------------------------------------------------------------
# The claim lives in Open WebUI's DB under the chat's row lock, so every
# process agrees: whoever inserts M first owns it.

_TURN_WRITERS_ATTR = "_openclaw_turn_writers"


def _live_turn_writers() -> set:
    """Writer ids alive in this process. Kept on `open_webui.socket.main` so
    every load of this Function (a redeploy keeps old modules alive) shares it."""
    mod = sys.modules.get("open_webui.socket.main")
    if mod is None:
        return set()
    writers = getattr(mod, _TURN_WRITERS_ATTR, None)
    if writers is None:
        writers = set()
        setattr(mod, _TURN_WRITERS_ATTR, writers)
    return writers


def _register_turn_writer(writer_id: str) -> None:
    _live_turn_writers().add(writer_id)


def _retire_turn_writer(writer_id: str) -> None:
    _live_turn_writers().discard(writer_id)


# Writer id: `<host>/<boot>/<pid>.<start>:<uuid>`; boot id and start time
# guard against a reused pid. Another host's or boot's writer is judged gone:
# a takeover across hosts would need a shared lease.
_WRITER_ID_RE = re.compile(r"^(?P<host>[^/]*)/(?P<boot>[^/]*)/(?P<pid>\d+)\.(?P<start>\d+):")


def _proc_start(pid: int) -> str | None:
    """Start time of process `pid` (/proc/<pid>/stat field 22), None if gone."""
    try:
        with open(f"/proc/{pid}/stat") as f:
            return f.read().rsplit(")", 1)[1].split()[19]
    except (OSError, IndexError):
        return None


def _boot_id() -> str:
    try:
        with open("/proc/sys/kernel/random/boot_id") as f:
            return f.read().strip()[:8]
    except OSError:
        return ""


def turn_writer_id() -> str:
    import socket
    pid = os.getpid()
    return f"{socket.gethostname()}/{_boot_id()}/{pid}.{_proc_start(pid) or 0}:{uuid.uuid4()}"


def _turn_writer_alive(writer: str | None) -> bool:
    if not writer:
        return False
    if writer in _live_turn_writers():
        return True
    m = _WRITER_ID_RE.match(writer)
    if not m or int(m.group("pid")) == os.getpid():
        return False
    import socket
    if (m.group("host"), m.group("boot")) != (socket.gethostname(), _boot_id()):
        return False
    return _proc_start(int(m.group("pid"))) == m.group("start")


def _writer_may_take_over(existing: dict) -> bool:
    """A recorded writer's message can be taken only when that writer is gone
    and the message is unfinished. A stub with no writer is handed over only
    with `takeover=True` (DESIGN 2.6)."""
    writer = (existing.get("meta") or {}).get("openclaw_writer")
    return bool(writer) and existing.get("done") is False and not _turn_writer_alive(writer)


async def _uncancellable(coro):
    """Await `coro`, a write to Open WebUI's DB, to its end even if this task is
    cancelled meanwhile, then let the cancel go on. A cancel inside the DB call
    can wedge it and hold SQLite's write lock for good (ELI-205)."""
    task = spawn_background(coro)
    try:
        return await asyncio.shield(task)
    except asyncio.CancelledError:
        if not task.done():
            await asyncio.wait({task})
        raise


async def _owui_upsert_message(chat_id: str, message_id: str, fields: dict):
    """Open WebUI's message upsert, never cut short by a cancel (ELI-205)."""
    from open_webui.models.chats import Chats
    return await _uncancellable(
        Chats.upsert_message_to_chat_by_id_and_message_id(chat_id, message_id, fields))


async def _claim_turn_message(chat_id: str, user_id: str, message_id: str, run_id: str,
                              writer_id: str, takeover: bool = False) -> dict:
    """Claim `message_id` for `run_id` under the chat's row lock, inserting it
    under the deepest leaf. Never cut short by a cancel (ELI-205).

    Returns {claimed, how: new|takeover|taken, message_id, parent, messages}."""
    return await _uncancellable(_claim_turn_message_now(
        chat_id, user_id, message_id, run_id, writer_id, takeover))


async def _claim_turn_message_now(chat_id: str, user_id: str, message_id: str, run_id: str,
                                  writer_id: str, takeover: bool) -> dict:
    from open_webui.models.chats import Chats
    from open_webui.models.chat_messages import ChatMessages
    from sqlalchemy.orm.attributes import flag_modified

    async with Chats._chat_transaction(chat_id) as (db, chat):
        if chat is None:
            # Deleted in Open WebUI while its session lives on (ELI-218).
            return {"claimed": False, "how": "gone", "message_id": message_id,
                    "parent": None, "messages": {}}
        data = chat.chat or {}
        history = data.get("history") or {"messages": {}, "currentId": None}
        msgs = history.setdefault("messages", {})
        existing = msgs.get(message_id)
        if existing is not None:
            holder = (existing.get("meta") or {}).get("openclaw_writer")
            held = bool(holder) and holder != writer_id and _turn_writer_alive(holder)
            if held or not (takeover or _writer_may_take_over(existing)):
                return {"claimed": False, "how": "taken", "message_id": message_id,
                        "parent": existing.get("parentId"), "messages": {}}
            meta = {**(existing.get("meta") or {}), "openclaw_run": run_id,
                    "openclaw_writer": writer_id}
            msgs[message_id] = {**existing, "meta": meta}
            changed = {message_id: msgs[message_id]}
            how, parent = "takeover", existing.get("parentId")
        else:
            parent = _deepest_leaf_id(msgs, history.get("currentId"))
            leaf = msgs.get(parent) or {}
            model = leaf.get("model") or next(iter(data.get("models") or []), None)
            msgs[message_id] = {
                "id": message_id, "parentId": parent, "childrenIds": [], "role": "assistant",
                "content": "", "output": [], "done": False, "model": model,
                "modelName": leaf.get("modelName") or model, "timestamp": int(time.time()),
                "meta": {"openclaw_run": run_id, "openclaw_writer": writer_id},
            }
            changed = {message_id: msgs[message_id]}
            if parent:
                msgs[parent] = {**leaf, "childrenIds": [*(leaf.get("childrenIds") or []), message_id]}
                changed[parent] = msgs[parent]
            history["currentId"] = message_id
            chat.current_message_id = message_id
            how = "new"
        chat.chat = {**data, "history": history}
        flag_modified(chat, "chat")
        chat.updated_at = int(time.time())
        for mid, m in changed.items():
            await ChatMessages.upsert_message(mid, chat_id, user_id, m, db=db)
        return {"claimed": True, "how": how, "message_id": message_id, "parent": parent,
                "messages": changed}


# ---------------------------------------------------------------------------
# Owner rule: who continues an interrupted run (DESIGN 2.7)
# ---------------------------------------------------------------------------
# The Gateway recovers only rows still `running`; the pipe resumes only rows
# already terminal with an outside kill, so a run never gets two continuations.

MAX_TURN_RESUMES = 3
# The exit reaches the row only as text (pinned in
# test_fixture_openclaw_exit_errors.json): SIGTERM 143, SIGKILL / OOM 137.
_EXTERNAL_KILL_RE = re.compile(r"process exited with (?:code (?:143|137)\b|signal SIG[A-Z]+)")


def turn_owner(row: dict, stop_notice_before: bool = False) -> str:
    """`gateway`, `pipe` or `none` for an interrupted run's settled row.
    `stop_notice_before`: a stop-mode shutdown came first (never recovered)."""
    status = (row or {}).get("status")
    if status == "running":
        return "gateway"
    if status == "interrupted":
        # 2026.10: marked for restart recovery, not started yet.
        return "gateway"
    if status == "failed" and _EXTERNAL_KILL_RE.search(str(row.get("lastRunError") or "")):
        return "pipe"
    if status == "killed" and stop_notice_before:
        return "pipe"
    return "none"


def judges_cut_runs_after_listening(version) -> bool:
    """A 2026.10+ Gateway serves rows before its recovery pass judged cut runs
    (about 8 s). 2026.9.3 marks within ms. Unknown versions count as old."""
    m = re.match(r"\s*(\d{4})\.(\d{1,2})\.", str(version or ""))
    return bool(m) and (int(m.group(1)), int(m.group(2))) >= (2026, 10)


def next_continuation(row: dict, stop_notice_before: bool, resumes_so_far: int,
                      after_restart: bool = False) -> str:
    """`gateway`, `wait`, `resume` or `finalize` for M's writer when its run settles.
    A resume into a busy session fails after a restart recovery (M3-crash
    04351f67), so it is never sent then. MAX_TURN_RESUMES stops an OOM loop.
    `after_restart`: the idle no-status row is not a settle yet."""
    if after_restart and not (row or {}).get("hasActiveRun") and (row or {}).get("status") is None:
        return "gateway"
    owner = turn_owner(row, stop_notice_before)
    if owner == "gateway":
        return "gateway"
    if (row or {}).get("hasActiveRun"):
        return "wait"
    if owner == "pipe" and resumes_so_far < MAX_TURN_RESUMES:
        return "resume"
    return "finalize"


# ---------------------------------------------------------------------------
# Rule E and the active run, from the transcript (DESIGN 2.1, case 5)
# ---------------------------------------------------------------------------

RECOVERY_SOURCE_TOOL = "main_session_restart_recovery"


def _history_user_turns(messages: list) -> list:
    """[(run_id, provenance sourceTool)] of the admitted user turns, in order."""
    out = []
    for m in messages or []:
        run = _history_user_run_id(m)
        if run:
            out.append((run, (m.get("provenance") or {}).get("sourceTool")))
    return out


def recovery_source_run(messages: list, run_id: str) -> str | None:
    """Rule E: the run a restart-recovery run recovers, the newest non-recovery
    turn before it (main-session-restart-recovery-CPJjd8da.mjs:441). Else None."""
    turns = _history_user_turns(messages)
    for i, (run, tool) in enumerate(turns):
        if run == run_id:
            if tool != RECOVERY_SOURCE_TOOL:
                return None
            return next((r for r, t in reversed(turns[:i]) if t != RECOVERY_SOURCE_TOOL), None)
    return None


def run_message_id(session_key: str, chat_id: str, run_id: str, messages: list | None = None) -> str | None:
    """The message `run_id` writes into: its source run's for a recovery (rule E)."""
    source = recovery_source_run(messages, run_id) if messages else None
    return turn_message_id(session_key, source or run_id, chat_id)


# ---------------------------------------------------------------------------
# Cron wakes: one run id for every wake into a session (ELI-103)
# ---------------------------------------------------------------------------
# The cron executor runs a wake with runId = the session's sessionId
# (run-executor.runtime-ro-4Z0fM.mjs:499), so the wake is found by its own
# `[cron:<jobId> <name>]` user turn: the newest committed at or before the
# event's `ts`. Its closing `cli-assistant:<sessionId>` message is deduplicated
# by key, so only the first wake gets one: never end a wake from it.

# 2026.10.2+ marks the wake turn by cron provenance instead and runs it under
# its own run id: an ordinary agent turn.

_CRON_PROMPT_RE = re.compile(r"^\[cron:(?P<job>[^\s\]]+)[\s\]]")


def _cron_turn_job(m: dict) -> str | None:
    """The cron job a wake turn names (provenance, else prompt header), else None."""
    prov = m.get("provenance") if isinstance(m.get("provenance"), dict) else None
    if prov:
        if (prov.get("kind"), prov.get("sourceTool")) != ("internal_system", "cron"):
            return None
        hit = _CRON_PROMPT_RE.match(str(prov.get("sourcePromptPrefix") or ""))
        if prov.get("jobId") or hit:
            return prov.get("jobId") or hit.group("job")
    hit = _CRON_PROMPT_RE.match(((_history_item(m) or {}).get("text") or "").lstrip())
    return hit.group("job") if hit else None


def wake_turns(messages: list) -> list:
    """[{key, at, job, shared_run}] of the cron wake turns, in order.
    `shared_run`: the wake runs under the session's id (9.3, ELI-103)."""
    out = []
    for m in messages or []:
        if not isinstance(m, dict):
            continue
        key = _history_user_run_id({**m, "role": "user"} if _is_forwarded_turn(m) else m)
        if not key or parse_pipe_run_id(key):
            continue
        job = _cron_turn_job(m)
        if not job:
            continue
        meta = m.get("__openclaw") if isinstance(m.get("__openclaw"), dict) else {}
        at = meta.get("recordTimestampMs") or m.get("timestamp")
        out.append({"key": key, "at": at if isinstance(at, (int, float)) else None,
                    "job": job, "shared_run": not m.get("provenance")})
    return out


def _shared_wake_turns(messages: list) -> list:
    """Wake turns running under the session's id: the only ones a sessionId event can belong to."""
    return [w for w in wake_turns(messages) if w["shared_run"]]


def wake_turn_at(messages: list, at_ms: float, bound=frozenset()) -> dict | None:
    """The wake whose event was emitted at `at_ms`, not already `bound`. None
    while its turn is not committed yet (embedded-agent-DNQn_PMM.mjs:5891)."""
    for turn in reversed(_shared_wake_turns(messages)):
        if turn["at"] is not None and turn["at"] <= at_ms:
            return None if turn["key"] in bound else turn
    return None


def wake_turn_of_run(messages: list, job: str, start_ms: float, bound=frozenset()) -> dict | None:
    """The wake turn job `job`'s run started at `start_ms` wrote, or None while
    not committed yet."""
    for turn in reversed(_shared_wake_turns(messages)):
        if turn["job"] == job and turn["at"] is not None and turn["at"] >= start_ms:
            return None if turn["key"] in bound else turn
    return None


def wake_span(messages: list, start_ms: float, end_ms: float) -> list:
    """A wake's assistant messages: those between its turn's commit and its
    terminal, minus user turns queued meanwhile."""
    out = []
    for m in messages or []:
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        ts = m.get("timestamp")
        if isinstance(ts, (int, float)) and start_ms <= ts <= end_ms:
            out.append(m)
    return out


# --- thinking --------------------------------------------------------------
# Shared by the Thinking filter and the Pipe so both use one ranking and clamp.
# No imports or extra names: it lands in the Pipe's flat namespace, where a
# helper could shadow a Pipe name. Filter-only helpers go in thinking_filter.

# Mirrors the Gateway's table. Clamp only downward: less thinking is safe,
# more costs money.
LEVEL_RANKS = {
    "off": 0,
    "minimal": 10,
    "low": 20,
    "medium": 30,
    "adaptive": 30,
    "high": 40,
    "xhigh": 60,
    "max": 70,
    "ultra": 80,
}

# Means "send no level": keep the agent's own. "off" is an explicit level.
UNSET = "default"

# Used until the Pipe writes a ladder cache. Every known provider has these.
FALLBACK_LEVELS = ["off", "minimal", "low", "medium", "high"]

LADDER_CACHE_NAME = "thinking-ladders.json"

# The Gateway's rejection lists labels, not ids. The binary profile labels
# `low` as "on".
LEVEL_LABEL_ALIASES = {"on": "low"}

# Anchors of the Gateway's validation error, all required and in order:
#   Thinking level "high" is not supported for claude-cli/claude-opus-5. Use one of: off.
_REJECT_HEAD = 'Thinking level "'
_REJECT_MID = '" is not supported for '
_REJECT_TAIL = ". Use one of: "


def parse_thinking_rejection(text):
    """Parse the Gateway's level rejection into the model's real ladder.

    `sessions.describe` builds its ladder without the model catalog, so it
    over-reports levels; only the send path's rejection is accurate.
    Returns None, or `{"level", "model", "levels"}`; `levels` may be empty, so
    check for None. No `re`, since the filter shares this fragment.
    """
    if not text:
        return None
    head = text.find(_REJECT_HEAD)
    if head < 0:
        return None
    level_start = head + len(_REJECT_HEAD)
    mid = text.find(_REJECT_MID, level_start)
    if mid < 0:
        return None
    tail = text.find(_REJECT_TAIL, mid)
    if tail < 0:
        return None

    level = text[level_start:mid].strip().lower()
    model = text[mid + len(_REJECT_MID):tail].strip()
    if not level or not model or " " in model:
        # A model ref has no space, so this is not the real rejection.
        return None

    listed = text[tail + len(_REJECT_TAIL):]
    stop = listed.find(".")
    if stop >= 0:
        listed = listed[:stop]
    levels = []
    for token in listed.split(","):
        name = token.strip().lower()
        name = LEVEL_LABEL_ALIASES.get(name, name)
        if name in LEVEL_RANKS and name not in levels:
            levels.append(name)
    levels.sort(key=lambda lv: LEVEL_RANKS[lv])
    return {"level": level, "model": model, "levels": levels}


def clamp_to_ladder(level, ladder):
    """Fit a level to a model's ladder. Returns (level, note to show or None).

    Clamps down to the nearest supported rank, else to the lowest one.
    """
    if not level or level == UNSET:
        return None, None
    if not ladder:
        # Unknown ladder: let the Gateway rule rather than drop the user's pick.
        return level, None
    if level in ladder:
        return level, None

    want = LEVEL_RANKS.get(level)
    if want is None:
        return None, f"Unknown thinking level {level!r}, ignoring it."

    ranked_ladder = [lv for lv in ladder if lv in LEVEL_RANKS]
    if not ranked_ladder:
        return None, "This model reported no recognized thinking levels; ignoring the selection."

    at_or_below = [lv for lv in ranked_ladder if LEVEL_RANKS[lv] <= want]
    if at_or_below:
        best = max(at_or_below, key=lambda lv: LEVEL_RANKS[lv])
    else:
        best = min(ranked_ladder, key=lambda lv: LEVEL_RANKS[lv])
    return best, (
        f"This model does not support thinking level {level!r}, "
        f"using {best!r} instead."
    )


# --- media -----------------------------------------------------------------


MEDIA_DIR = "/tmp/openclaw-pipe-media"
MEDIA_BASE_URL = "http://localhost:18791"

_file_server_started = False

_MEDIA_TRIGGER = "MEDIA:"
_MEDIA_FNAME_RE = re.compile(r"\.[A-Za-z0-9]{1,8}$")


def _looks_like_media_filename(fname: str) -> bool:
    """Whether fname has an extension, so prose like "the MEDIA: fix" stays text."""
    return bool(_MEDIA_FNAME_RE.search(fname))


def _advance_media_buffer(pending: str, delta: str, ctx: str = "") -> tuple[str, str]:
    """Feed a delta; return (text_to_yield_now, new_pending).

    A directive can split across deltas, so hold from "MEDIA:" (or a partial
    prefix) until whitespace ends the filename, or until an open backtick
    run is decided (ELI-111). `ctx`: text already shown in this item.
    """
    candidate = pending + delta
    _directives, hold = _media_scan(candidate, ctx, final=False)
    if hold is None:
        return candidate, ""
    return candidate[:hold], candidate[hold:]


def _take_media_fname(after_prefix: str) -> tuple[str, str]:
    """Split text after "MEDIA:" into (filename, rest).

    A filename also ends at the next "MEDIA:" (ELI-76). A glued copy of the
    same directive is a re-delivered tail and is dropped.
    """
    token = after_prefix.split()[0] if after_prefix else ""
    fname = token.split(_MEDIA_TRIGGER, 1)[0]
    rest = after_prefix[len(fname):]
    glued = _MEDIA_TRIGGER + fname
    while fname and rest.startswith(glued):
        after = rest[len(glued):]
        if after and not after[0].isspace() and not after.startswith(_MEDIA_TRIGGER):
            break  # a different, longer filename that merely starts the same
        rest = after
    return fname, rest


# Directives in code stay text (ELI-107, ELI-111): fenced blocks (CommonMark
# 4.5) and code spans (6.1). An unclosed backtick run is literal, known only
# when its paragraph ends. Indented code is not tracked (list lines indent).
_BLOCK_START_RE = re.compile(r"^ {0,3}(#{1,6}(\s|$)|[-+*](\s|$)|\d{1,9}[.)](\s|$))")


def _media_code_ranges(text: str, ctx: str = "", final: bool = True):
    """(code ranges of `text`, offset where code state is undecided or None).

    `ctx` precedes `text`; `final`: nothing follows `text`."""
    full, base = ctx + text, len(ctx)
    ranges, open_at = [], None
    fence_step = globals().get("_fence_step")

    def spans(start, end, last):
        """Code spans of full[start:end]; `last`: the paragraph may go on."""
        nonlocal open_at
        i = start
        while i < end:
            c = full[i]
            if c == "\\" and i + 1 < end and full[i + 1] == "`":
                i += 2
                continue
            if c != "`":
                i += 1
                continue
            j = i
            while j < end and full[j] == "`":
                j += 1
            k, close = j, None
            while k < end and close is None:
                if full[k] != "`":
                    k += 1
                    continue
                r = k
                while r < end and full[r] == "`":
                    r += 1
                if r - k == j - i and not (last and r == end):
                    close = r
                k = r
            if close is not None:
                ranges.append((i, close))
                i = close
                continue
            if last and open_at is None:
                open_at = i
            i = j

    fence, para, pos = "", None, 0
    lines = full.split("\n")
    for n, line in enumerate(lines):
        end = pos + len(line)
        complete = final or n < len(lines) - 1
        if fence or (complete and fence_step and fence_step(line, "")):
            if para is not None:
                spans(para, pos, False)
                para = None
            ranges.append((pos, min(end + 1, len(full))))
            if complete and fence_step:
                fence = fence_step(line, fence)
        elif complete and not line.strip():
            if para is not None:
                spans(para, pos, False)
                para = None
        else:
            if para is not None and _BLOCK_START_RE.match(line):
                spans(para, pos, False)
                para = None
            if para is None:
                para = pos
        pos = end + 1
    if para is not None:
        spans(para, len(full), not final)
    shifted = [(max(a, base) - base, b - base) for a, b in ranges if b > base]
    if open_at is not None:
        open_at = max(open_at, base) - base
    return shifted, open_at


def _media_scan(text: str, ctx: str = "", final: bool = True):
    """(directives as (start, end, filename) outside code, hold offset or None).

    `ctx` precedes `text`; `final`: nothing follows `text`."""
    ranges, open_at = _media_code_ranges(text, ctx, final)

    def in_code(i):
        return any(a <= i < b for a, b in ranges)
    directives, hold, i = [], None, 0
    while True:
        idx = text.find(_MEDIA_TRIGGER, i)
        if idx < 0:
            break
        i = idx + len(_MEDIA_TRIGGER)
        if in_code(idx):
            continue
        after = text[i:]
        stripped = after.strip()
        fname, rest = _take_media_fname(stripped)
        end = i + (len(after) - len(after.lstrip())) + len(stripped) - len(rest)
        # The line break after it depends on what follows (ELI-113).
        complete = final or bool(text[end:].strip())
        if not complete or (open_at is not None and idx >= open_at
                            and _looks_like_media_filename(fname)):
            hold = idx
            break
        if fname and _looks_like_media_filename(fname):
            directives.append((idx, end, fname))
            i = end
    if hold is None and not final:
        for n in range(min(len(_MEDIA_TRIGGER) - 1, len(text)), 0, -1):
            if text.endswith(_MEDIA_TRIGGER[:n]) and not in_code(len(text) - n):
                hold = len(text) - n
                break
    return directives, hold


def _replace_media(text: str, directives, replacement) -> str:
    """Replace each directive with `replacement(filename)`, text after it on
    a new line. A chunk's trailing line break is left alone (ELI-113)."""
    out, pos = "", 0
    for start, end, fname in directives:
        rest = text[end:]
        shown = replacement(fname)
        # A directive taken out (ELI-328) leaves no line of its own.
        out += text[pos:start] + shown + ("\n" if rest.strip() and shown else "")
        pos = end + len(rest) - len(rest.lstrip())
    return out + text[pos:]


def _resolve_media(text, base_url=None, ctx="", file_server=True):
    """Turn every MEDIA: directive outside code (ELI-111) into an image link.

    A bare filename links to the file server at `base_url`. With the file
    server off (`file_server` False) nothing serves that link, so the line
    becomes a plain error instead of an image that never loads; a URL
    directive needs no server and stays an image either way."""
    if base_url is None:
        base_url = MEDIA_BASE_URL
    directives, _hold = _media_scan(text, ctx)
    if not directives:
        return text, False

    def shown(fname):
        if _is_media_url(fname):
            return f"![{os.path.basename(fname)}]({fname})"
        if file_server:
            # A URL, not base64: base64 breaks OWUI's streaming parser.
            return f"![{fname}]({base_url.rstrip('/')}/{fname})"
        return f"_(a file could not be uploaded: {fname})_"
    return _replace_media(text, directives, shown), True


def _is_media_url(fname: str) -> bool:
    return fname.startswith(("https://", "http://"))


def _is_gateway_media_name(fname: str) -> bool:
    """A path directive: the Gateway stores that file as an `image` block
    (ELI-328); the Pipe cannot read the path."""
    return "/" in fname and not _is_media_url(fname)


def _event_media_urls(data) -> list[str]:
    """An assistant event's `mediaUrls`. The Gateway's own runtime moves
    `MEDIA:` lines here; claude-cli keeps them in the text (ELI-328)."""
    urls = data.get("mediaUrls") if isinstance(data, dict) else None
    return [u.strip() for u in urls if isinstance(u, str) and u.strip()] if isinstance(urls, list) else []


def _take_gateway_media(text: str, ctx: str = "") -> tuple[str, list[str]]:
    """(`text` without path directives, their paths). The images come later
    from the run's stored blocks (`_gateway_images_text`)."""
    directives, _hold = _media_scan(text, ctx)
    paths = [d for d in directives if _is_gateway_media_name(d[2])]
    if not paths:
        return text, []
    return _replace_media(text, paths, lambda _fname: ""), [fname for _s, _e, fname in paths]


def _extract_request_bearer(__request__):
    """The OWUI request's Bearer token, or None."""
    if not __request__:
        return None
    headers = getattr(__request__, "headers", None)
    if not headers:
        return None
    auth = headers.get("authorization") or headers.get("Authorization")
    if auth and auth.lower().startswith("bearer "):
        return auth.split(" ", 1)[1].strip()
    return None


def _multipart_body(field_name, file_path, filename, mime):
    boundary = "----openclawowui" + uuid.uuid4().hex
    with open(file_path, "rb") as f:
        raw = f.read()
    head = (
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="{field_name}"; '
        f'filename="{filename}"\r\n'
        f"Content-Type: {mime}\r\n\r\n"
    ).encode()
    tail = f"\r\n--{boundary}--\r\n".encode()
    return boundary, head + raw + tail


def _upload_owui_file(file_path, base_url, token):
    """Upload one file to the OWUI Files API; return the file object."""
    if not token:
        raise RuntimeError("missing OWUI bearer token")
    filename = os.path.basename(file_path)
    mime = mimetypes.guess_type(filename)[0] or "application/octet-stream"
    boundary, body = _multipart_body("file", file_path, filename, mime)
    req = urllib.request.Request(
        f"{base_url.rstrip('/')}/api/v1/files/?process=false",
        data=body,
        headers={
            "Authorization": f"Bearer {token}",
            "Accept": "application/json",
            "Content-Type": f"multipart/form-data; boundary={boundary}",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.loads(resp.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "replace")[:300]
        raise RuntimeError(f"OWUI file upload failed: {exc.code} {detail}") from exc


async def _resolve_media_via_owui(
    text,
    *,
    base_url,
    token,
    __event_emitter__,
    ctx="",
):
    """Upload every MEDIA: file to OWUI and attach it to the message.

    If any one cannot be uploaded, return handled=False so the fallback
    resolves all of them the same way.
    """
    directives, _hold = _media_scan(text, ctx)
    if not directives:
        return text, False
    for _start, _end, fname in directives:
        if ".." in fname or "/" in fname or not os.path.isfile(os.path.join(MEDIA_DIR, fname)):
            return text, False

    shown = {}
    for _start, _end, fname in directives:
        if fname in shown:
            continue
        # Off the event loop: this blocking call goes to OWUI's own API, which
        # cannot answer while its loop is blocked (self-deadlock).
        fpath = os.path.join(MEDIA_DIR, fname)
        file_obj = await asyncio.to_thread(_upload_owui_file, fpath, base_url, token)
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "files",
                    "data": {"files": [file_obj]},
                }
            )

        file_id = file_obj.get("id")
        mime = file_obj.get("meta", {}).get("content_type") or mimetypes.guess_type(fname)[0] or ""
        content_url = f"/api/v1/files/{file_id}/content" if file_id else ""
        if content_url and mime.startswith("image/"):
            shown[fname] = f"![{fname}]({content_url})"
        elif content_url:
            shown[fname] = f"[{fname}]({content_url})"
        else:
            shown[fname] = f"`{fname}`"
    return _replace_media(text, directives, shown.__getitem__), True


async def _resolve_media_text(text, *, valves, __request__=None, __event_emitter__=None, ctx=""):
    """Resolve MEDIA: directives via OWUI Files, else the file server.

    Pass only text whose filenames are complete (see `_advance_media_buffer`).
    """
    handled = False
    resolved = text
    if valves.USE_OWUI_FILES:
        token = _extract_request_bearer(__request__) or valves.OWUI_API_KEY
        try:
            resolved, handled = await _resolve_media_via_owui(
                text,
                base_url=valves.OWUI_BASE_URL,
                token=token,
                __event_emitter__=__event_emitter__,
                ctx=ctx,
            )
        except Exception as ex:
            pipe_log(f"  OWUI file upload failed; falling back: {ex}")
    if not handled:
        resolved, handled = _resolve_media(
            text, base_url=valves.FILE_SERVER_BASE_URL, ctx=ctx, file_server=valves.ENABLE_FILE_SERVER)
        if handled and not valves.ENABLE_FILE_SERVER and resolved != text:
            pipe_log("  MEDIA: file not uploaded to OWUI and the file server is off; the reply says so")
    return resolved, handled


# Gateway route for `image` blocks. It needs the Gateway token, which the
# browser lacks, so the Pipe fetches it (ELI-322).
_GATEWAY_MEDIA_PREFIX = "/api/chat/media/outgoing/"
_GATEWAY_MEDIA_MAX_BYTES = 50 * 1024 * 1024
_SAFE_FNAME_RE = re.compile(r"[^A-Za-z0-9._-]+")


def _gateway_image_blocks(message) -> list[dict]:
    """A message's `image` blocks on the Gateway media route, in order."""
    content = message.get("content") if isinstance(message, dict) else None
    if not isinstance(content, list):
        return []
    return [
        block for block in content
        if isinstance(block, dict) and block.get("type") == "image"
        and isinstance(block.get("url"), str) and block["url"].startswith(_GATEWAY_MEDIA_PREFIX)
    ]


def _is_run_assistant_message(message, run_id: str) -> bool:
    """Whether `message` is a stored assistant message of run `run_id`.

    Includes the media message the Gateway appends, keyed
    `<run id>:assistant-media[:n]` with no `runId` (2026.10.10,
    appendInjectedAssistantMessageToTranscript)."""
    if not isinstance(message, dict) or message.get("role") != "assistant" or not run_id:
        return False
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    if run_id in (meta.get("runId"), message.get("runId")):
        return True
    media_key = f"{run_id}:assistant-media"
    return any(isinstance(key, str) and (key == media_key or key.startswith(media_key + ":"))
               for key in (meta.get("idempotencyKey"), message.get("idempotencyKey")))


def _history_image_blocks_for_run(history: dict, run_id: str) -> list[dict]:
    """One run's Gateway image blocks in `chat.history`. The live final has
    only text; images are stored after it (ELI-322)."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return []
    blocks = []
    for message in messages:
        if _is_run_assistant_message(message, run_id):
            blocks += _gateway_image_blocks(message)
    return blocks


def _history_media_errors_for_run(history: dict, run_id: str) -> list[str]:
    """File names from one run's `attachment_error` blocks (e.g. `file-not-found`)."""
    labels = []
    for message in (history or {}).get("messages") or []:
        if not _is_run_assistant_message(message, run_id):
            continue
        for block in message.get("content") if isinstance(message.get("content"), list) else []:
            attachment = block.get("attachment") if isinstance(block, dict) else None
            if block.get("type") == "attachment_error" and isinstance(attachment, dict):
                labels.append(str(attachment.get("label") or ""))
    return labels


def _unstored_gateway_media(paths, blocks: int, errors: list[str]) -> list[str]:
    """Names in `paths` with no stored image: those in `errors`, then the
    rest beyond the first `blocks`."""
    names = [os.path.basename(p) for p in paths]
    failed = [n for n in names if n in {os.path.basename(e) for e in errors if e}]
    rest = [n for n in names if n not in failed]
    return failed + rest[max(0, blocks):]


def _gateway_image_fname(block: dict) -> str:
    """A unique safe file name for an image block."""
    stem = os.path.splitext(os.path.basename(str(block.get("alt") or "")))[0]
    stem = _SAFE_FNAME_RE.sub("-", stem).strip("-.")[:60] or "image"
    ext = mimetypes.guess_extension(block.get("mimeType") or "") or ".png"
    return f"{stem}-{uuid.uuid4().hex[:8]}{ext}"


def _fetch_gateway_media(gateway_url: str, token: str, path: str) -> bytes:
    """GET one media path from the Gateway with its token."""
    host, port, tls = _parse_gateway_url(gateway_url)
    req = urllib.request.Request(
        f"{'https' if tls else 'http'}://{host}:{port}{path}",
        headers={"Authorization": f"Bearer {token}"},
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        raw = resp.read(_GATEWAY_MEDIA_MAX_BYTES + 1)
    if len(raw) > _GATEWAY_MEDIA_MAX_BYTES:
        raise RuntimeError(f"media over {_GATEWAY_MEDIA_MAX_BYTES} bytes")
    return raw


async def _gateway_images_text(blocks, *, valves, __request__=None, __event_emitter__=None,
                               missing=()) -> str:
    """Fetch Gateway image blocks and show them as MEDIA: directives.

    Failed fetches and `missing` files are named, never dropped silently."""
    lines = [f"_(an image could not be loaded: {name})_" for name in missing]
    for block in blocks:
        fname = _gateway_image_fname(block)
        try:
            raw = await asyncio.to_thread(
                _fetch_gateway_media, valves.GATEWAY_URL, valves.GATEWAY_TOKEN, block["url"])
            os.makedirs(MEDIA_DIR, exist_ok=True)
            with open(os.path.join(MEDIA_DIR, fname), "wb") as f:
                f.write(raw)
        except Exception as ex:
            pipe_log(f"  gateway image fetch failed for {block['url']}: {ex!r}")
            lines.append(f"_(an image could not be loaded: {block.get('alt') or 'image'})_")
            continue
        lines.append(f"MEDIA:{fname}")
    if not lines:
        return ""
    text = "\n\n" + "\n\n".join(lines) + "\n"
    resolved, _handled = await _resolve_media_text(
        text, valves=valves, __request__=__request__, __event_emitter__=__event_emitter__)
    return resolved


# OWUI reloads a function into a new module with no teardown, so the old
# file server keeps the port. It is stashed on `open_webui.socket.main`, which
# is never reloaded, so the next deploy can shut it down first.
_STALE_FILE_SERVER_ATTR = "_openclaw_file_server_v1"


def _reap_stale_file_server() -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    stale = getattr(_owui_socket_main, _STALE_FILE_SERVER_ATTR, None)
    if stale is None:
        return
    try:
        stale.shutdown()
        stale.server_close()
        setattr(_owui_socket_main, _STALE_FILE_SERVER_ATTR, None)
        pipe_log("  reaped stale file server from a previous deploy")
    except Exception as ex:
        pipe_log(f"  failed to reap stale file server (non-fatal): {ex}")


def _stop_file_server() -> None:
    """ENABLE_FILE_SERVER is off: close the port a server of this load or of
    an earlier deploy still holds. Only starting a server reaps the old one,
    and with the valve off none starts, so a deploy that turned it off would
    leave the port open until Open WebUI restarted."""
    global _file_server_started
    _reap_stale_file_server()
    _file_server_started = False


def _remember_file_server(server) -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    setattr(_owui_socket_main, _STALE_FILE_SERVER_ATTR, server)


def _upload_dest(directory: str, raw_path: str) -> str | None:
    """Where an upload to `raw_path` (the request path) is written: a file
    directly inside `directory`, after symlinks resolve. None to refuse it."""
    name = raw_path.strip("/").split("?")[0]
    root = os.path.realpath(directory)
    dest = os.path.realpath(os.path.join(root, name))
    # Resolved, then prefixed (the check CodeQL's py/path-injection
    # recognises); a direct child only, so "", ".", ".." and "a/b" fail too.
    if not dest.startswith(root + os.sep) or os.path.dirname(dest) != root:
        return None
    return dest


def _start_file_server(port=18791):
    """Start the media file server, once per process."""
    global _file_server_started
    if _file_server_started:
        return
    _reap_stale_file_server()
    directory = "/tmp/openclaw-pipe-media"
    os.makedirs(directory, exist_ok=True)
    Path(directory, "health").write_text("ok")

    class _Handler(SimpleHTTPRequestHandler):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, directory=directory, **kwargs)

        def end_headers(self):
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Cache-Control", "no-cache")
            super().end_headers()

        def _handle_upload(self):
            length = int(self.headers.get("Content-Length", 0))
            if length == 0:
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b"empty")
                return
            body = self.rfile.read(length)
            dest = _upload_dest(directory, self.path)
            if dest is None:
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b"bad path")
                return
            with open(dest, "wb") as f:
                f.write(body)
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.end_headers()
            self.wfile.write(f"ok:{os.path.basename(dest)}".encode())

        def do_PUT(self):
            self._handle_upload()

        def do_POST(self):
            self._handle_upload()


    try:
        server = HTTPServer(("0.0.0.0", port), _Handler)
        _remember_file_server(server)
        threading.Thread(target=server.serve_forever, daemon=True).start()
        _file_server_started = True
    except OSError:
        pass


# --- images ----------------------------------------------------------------

# Re-encoding a photo that is over the cap: libjpeg quality 85 keeps text on a
# photographed menu or sign readable at a fraction of a phone camera's size.
_FIT_JPEG_QUALITY = 85
# JPEG size grows with the pixel count, so each try scales both sides by the
# square root of (cap / size), a little under it so one try usually lands.
_FIT_SCALE_MARGIN = 0.95
# libjpeg refuses an image with a side above this (`JPEG_MAX_DIMENSION` in
# jpeglib.h), so a longer side is cut down before the first encode.
_JPEG_MAX_DIMENSION = 65500
# Characters base64 decoding skips: they are not part of the payload's size.
_BASE64_WHITESPACE = " \t\r\n"
# `chat.send` attachment type of an image (the same value gateway.py sends).
_IMAGE_ATTACHMENT_TYPE = "image"


# One fit at a time: each holds the whole photo decoded plus a converted and a
# resized copy, so the memory spent is one photo's, however many are sent.
_image_fit_lock = asyncio.Lock()


class ImageTooLargeError(Exception):
    """An image over the Gateway's cap that could not be made to fit. `str()`
    is the sentence the user sees."""


def _base64_decoded_size(data: str) -> int:
    """Decoded byte count of a base64 string, without decoding it."""
    data = data.strip()
    chars = len(data) - sum(data.count(c) for c in _BASE64_WHITESPACE)
    return chars * 3 // 4 - (len(data) - len(data.rstrip("=")))


def _images_over_cap(attachments: list, max_bytes: int) -> bool:
    return any(a.get("type") == _IMAGE_ATTACHMENT_TYPE
               and _base64_decoded_size(a.get("content") or "") > max_bytes
               for a in attachments)


def _shrink_to_jpeg(raw: bytes, max_bytes: int, PIL) -> bytes | None:
    """`raw` as a JPEG of at most `max_bytes`, EXIF orientation applied; None
    when even a 1x1 image is too big."""
    Image, ImageOps = PIL
    img = ImageOps.exif_transpose(Image.open(io.BytesIO(raw)))
    if img.mode in ("RGBA", "LA", "P"):
        # JPEG has no alpha: put a transparent screenshot on white.
        rgba = img.convert("RGBA")
        img = Image.new("RGB", rgba.size, "white")
        img.paste(rgba, mask=rgba.getchannel("A"))
    elif img.mode not in ("RGB", "L"):
        img = img.convert("RGB")
    longest = max(img.size)
    if longest > _JPEG_MAX_DIMENSION:
        scale = _JPEG_MAX_DIMENSION / longest
        img = img.resize((max(1, int(img.width * scale)), max(1, int(img.height * scale))),
                         Image.LANCZOS)
    out = io.BytesIO()
    img.save(out, "JPEG", quality=_FIT_JPEG_QUALITY, optimize=True)
    while out.tell() > max_bytes:
        scale = min(_FIT_SCALE_MARGIN, (max_bytes / out.tell()) ** 0.5 * _FIT_SCALE_MARGIN)
        size = (max(1, int(img.width * scale)), max(1, int(img.height * scale)))
        if size == (img.width, img.height):  # already 1x1: nothing left to shrink
            return None
        img = img.resize(size, Image.LANCZOS)
        out = io.BytesIO()
        img.save(out, "JPEG", quality=_FIT_JPEG_QUALITY, optimize=True)
    return out.getvalue()


def _load_pil():
    """(Image, ImageOps) from Pillow, or None where it is not installed."""
    try:
        from PIL import Image, ImageOps
    except ImportError:
        return None
    return Image, ImageOps


def _fit_image_attachments(attachments: list, max_bytes: int) -> list:
    """`attachments` with every image over `max_bytes` (the Gateway's cap,
    decoded bytes) re-encoded as a JPEG that fits. Images under it are passed
    on untouched. Raises `ImageTooLargeError` when one cannot be made to fit."""
    out = []
    for a in attachments:
        content = a.get("content") or ""
        size = _base64_decoded_size(content)
        if not _images_over_cap([a], max_bytes):
            out.append(a)
            continue
        mb, cap_mb = size / 1048576, max_bytes / 1048576
        too_big = (f"**Couldn't send the image:** it is {mb:.1f} MB and the "
                   f"Gateway accepts images up to {cap_mb:.1f} MB")
        lib = _load_pil()
        if lib is None:
            raise ImageTooLargeError(
                f"{too_big}, and this server can't make it smaller (Pillow is "
                "not installed). Please send a smaller photo or a screenshot.")
        try:
            small = _shrink_to_jpeg(base64.b64decode(content), max_bytes, lib)
        except Exception as e:  # not an image Pillow can read
            pipe_log(f"image fit: {a.get('fileName')}: {e}")
            small = None
        if small is None:
            raise ImageTooLargeError(
                f"{too_big}, and it couldn't be made small enough. Please send "
                "a smaller photo or a screenshot.")
        pipe_log(f"image fit: {a.get('fileName')} {size} -> {len(small)} bytes "
                 f"(cap {max_bytes})")
        stem = (a.get("fileName") or "image").rsplit(".", 1)[0]
        out.append({**a, "mimeType": "image/jpeg", "fileName": f"{stem}.jpg",
                    "content": base64.b64encode(small).decode("ascii")})
    return out


# --- emit ------------------------------------------------------------------

async def _emit_status(__event_emitter__, description, *, done=False):
    """Send an OWUI status event when the current pipe call supports events."""
    if not __event_emitter__:
        return
    await __event_emitter__(
        {"type": "status", "data": {"description": description, "done": done}}
    )


# Claude Code's sub-agent tool; a background one keeps the run open until its
# report is in (ELI-163).
_AGENT_TOOL_NAME = "Agent"
_AGENT_LAUNCHED_PREFIX = "Async agent launched"


def _is_agent_tool(name) -> bool:
    """Claude Code's `Agent`, in any case: the Gateway lowercases some tool names."""
    return (name or "").strip().lower() == _AGENT_TOOL_NAME.lower()


def _is_background_agent_launch(name, result_text, is_error=False) -> bool:
    return (not is_error and _is_agent_tool(name)
            and (result_text or "").strip().startswith(_AGENT_LAUNCHED_PREFIX))


def _background_agents_line(n: int) -> str:
    """The status row of a reply a background agent holds open."""
    return f"Waiting on {n} background agent{'' if n == 1 else 's'}"


# Live view ids go into the URL as they are.
_LIVE_VIEW_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")


# Words before the real command: keywords, wrappers. `FOO=1 cmd` is skipped too.
_SHELL_LEAD_WORDS = frozenset({"do", "then", "else", "elif", "if", "while", "until", "!", "{", "(",
                               "time", "env", "nohup", "setsid", "sudo", "exec"})
_SHELL_WRAPPER_WITH_ARG = frozenset({"timeout"})   # `timeout 60 cmd`: one more word to skip
_ENV_ASSIGNMENT = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")
_HEREDOC = re.compile(r"<<(-?)[ \t]*(?:'([^'\n]+)'|\"([^\"\n]+)\"|\\?([A-Za-z0-9_.-]+))")


def _command_position(segment: str) -> str:
    """`segment` from its command on: leading keywords, wrappers, their options
    and `VAR=value` assignments skipped. "" when nothing is left."""
    words = segment.split()
    i = 0
    while i < len(words):
        w = words[i]
        if w in _SHELL_LEAD_WORDS or _ENV_ASSIGNMENT.match(w):
            i += 1
        elif w in _SHELL_WRAPPER_WITH_ARG:
            i += 2
        elif i and words[i - 1] in _SHELL_LEAD_WORDS and w.startswith("-"):
            i += 1   # an option of a wrapper: `sudo -E`, `env -i`
        else:
            break
    return " ".join(words[i:])


def _command_segments(command: str) -> list[str]:
    """The commands a shell line runs, each from its command word on. Quoted
    text and heredoc bodies are dropped, so a browser word in a string is no command."""
    segments: list[str] = []
    cur: list[str] = []
    pending: list[tuple[str, bool]] = []   # heredocs whose bodies start after this line
    quote = ""
    i, n = 0, len(command)

    def cut():
        segment = _command_position("".join(cur))
        cur.clear()
        if segment:
            segments.append(segment)

    while i < n:
        ch = command[i]
        if quote:
            if ch == "\\" and quote == '"':
                i += 2
                continue
            if ch == quote:
                cur.append(quote * 2)
                quote = ""
            i += 1
            continue
        if ch == "\\":
            i += 2
            continue
        if ch in "'\"":
            quote = ch
            i += 1
            continue
        if ch == "<" and command.startswith("<<", i) and not command.startswith("<<<", i):
            m = _HEREDOC.match(command, i)
            if m:
                pending.append((m.group(2) or m.group(3) or m.group(4), m.group(1) == "-"))
                i = m.end()
                continue
        if ch == "\n":
            cut()
            i += 1
            while pending:
                delim, strip = pending.pop(0)
                while i < n:
                    end = command.find("\n", i)
                    line = command[i:n if end < 0 else end]
                    i = n if end < 0 else end + 1
                    if (line.lstrip("\t") if strip else line) == delim:
                        break
            continue
        if ch in ";|`" or command.startswith("$(", i) or ch in "()":
            cut()
            i += 2 if command.startswith(("||", "$("), i) else 1
            continue
        if ch == "&":
            redirect = (cur and cur[-1][-1:] in "<>") or command.startswith("&>", i)
            if not redirect:
                cut()
                i += 2 if command.startswith("&&", i) else 1
                continue
        cur.append(ch)
        i += 1
    cut()
    return segments


def _tool_command(args_str) -> str:
    """The `command` argument of a JSON tool call, else ""."""
    try:
        args = json.loads(args_str or "")
    except (TypeError, ValueError):
        return ""
    command = args.get("command") if isinstance(args, dict) else None
    return command if isinstance(command, str) else ""


def _live_view_url(valves, *, chat_id, message_id, user_id, email, tool_name, args_str):
    """The live view embed URL for a call that really drives a browser, or None.
    Only the tool name and the commands are matched, and only an http(s) URL is
    returned: Open WebUI renders any other embed string as HTML."""
    template = (getattr(valves, "LIVE_VIEW_URL", "") or "").strip()
    if not template or not re.match(r"^https?://", template, re.I):
        return None
    if not all(isinstance(v, str) and _LIVE_VIEW_ID.match(v) for v in (chat_id, message_id)):
        return None
    users = _parse_owner_users(getattr(valves, "LIVE_VIEW_USERS", "") or "")
    if users and not _is_owner_user(users, user_id, email):
        return None
    try:
        tools = re.compile(getattr(valves, "LIVE_VIEW_TOOLS", "") or r"(?!)", re.I)
    except re.error:
        return None
    command = _tool_command(args_str)
    if not any(tools.search(c) for c in [tool_name or "", *(_command_segments(command) if command else [])]):
        return None
    return template.replace("{chat_id}", chat_id).replace("{message_id}", message_id)


def _fmt_tokens(n) -> str:
    """Compact token count: 115212 -> '115k', 1000000 -> '1.0m'."""
    try:
        n = int(n)
    except (TypeError, ValueError):
        return "?"
    if n >= 1_000_000:
        return f"{n / 1_000_000:.1f}m"
    if n >= 1_000:
        return f"{n // 1_000}k"
    return str(n)


def _format_goal_line(goal: dict) -> str:
    """Mirror the TUI footer's goal phrasing (see docs/tools/goal.md)."""
    status = goal.get("status")
    tokens_used = goal.get("tokensUsed")
    budget = goal.get("tokenBudget")
    used_fmt = _fmt_tokens(tokens_used) if tokens_used is not None else "?"
    if status == "active":
        if budget:
            return f"🎯 Pursuing goal ({used_fmt}/{_fmt_tokens(budget)})"
        objective = (goal.get("objective") or "").strip()
        if len(objective) > 40:
            objective = objective[:39] + "…"
        return f"🎯 Pursuing goal: {objective}" if objective else "🎯 Pursuing goal"
    if status == "paused":
        return "🎯 Goal paused (/goal resume)"
    if status == "blocked":
        return "🎯 Goal blocked (/goal resume)"
    if status == "usage_limited":
        return "🎯 Goal hit usage limits (/goal resume)"
    if status == "budget_limited":
        return f"🎯 Goal unmet ({used_fmt}/{_fmt_tokens(budget)})"
    if status == "complete":
        return f"🎯 Goal achieved ({used_fmt})"
    return ""


def _window_bit(w: dict) -> str | None:
    used = w.get("usedPercent")
    if used is None:
        return None
    return f"{w.get('label')} {round(100 - used)}% left"


def _relative_time(reset_at_ms) -> str | None:
    """Compact relative countdown: '22m', '4h07m', '3d07h'. None if unknown/past."""
    if not reset_at_ms:
        return None
    delta_s = int((reset_at_ms - time.time() * 1000) / 1000)
    if delta_s <= 0:
        return None
    days, rem = divmod(delta_s, 86400)
    hours, rem = divmod(rem, 3600)
    minutes = rem // 60
    if days:
        return f"{days}d{hours:02d}h"
    if hours:
        return f"{hours}h{minutes:02d}m"
    return f"{minutes}m"


def _window_reset_line(w: dict) -> str | None:
    """Detail line for one rate-limit window with a known reset time, e.g.
    '⏱ 5h 18% left (resets in 22m)'."""
    bit = _window_bit(w)
    rel = _relative_time(w.get("resetAt"))
    if not bit or not rel:
        return None
    return f"⏱ {bit} (resets in {rel})"


async def _build_usage_status_lines(conn, session_key, timeout: float = 5,
                                    run_usage: dict | None = None) -> list[str]:
    """Best-effort final status lines: context fill with the primary window,
    a reset line per window, and the goal. One fact per line, since OWUI clamps
    each status row to one line; the thin line goes last since OWUI shows only
    the last one. Errors are swallowed so the reply is never affected.

    `run_usage`: the run's own usage gives the context fill, since OpenClaw
    2026.10 writes a first reply's totals to the row only after the run (ELI-177).
    """
    describe_task = asyncio.ensure_future(
        conn.send_request("sessions.describe", dict(key=session_key), timeout=timeout)
    )
    usage_task = asyncio.ensure_future(conn.send_request("usage.status", {}, timeout=timeout))

    context_bit = None
    goal_line = None
    provider = None
    try:
        desc = await describe_task
        session_row = (desc or {}).get("session") or {}
        provider = session_row.get("modelProvider")
        context_tokens = session_row.get("contextTokens")
        total_tokens = _usage_prompt_tokens(run_usage) or session_row.get("totalTokens")
        if context_tokens and total_tokens is not None:
            pct = round(total_tokens / context_tokens * 100, 1)
            context_bit = f"🧠 {_fmt_tokens(total_tokens)}/{_fmt_tokens(context_tokens)} ({pct:g}%)"
        goal = session_row.get("goal")
        if goal:
            goal_line = _format_goal_line(goal) or None
    except Exception:
        pass

    primary_bit = None
    reset_lines = []
    try:
        usage = await usage_task
        if provider:
            for p in (usage or {}).get("providers", []):
                if p.get("provider") != provider:
                    continue
                windows = p.get("windows") or []
                bits = [b for b in (_window_bit(w) for w in windows) if b]
                if bits:
                    primary_bit = f"⏱ {bits[0]}"
                elif p.get("summary"):
                    primary_bit = f"⏱ {p['summary']}"
                # The primary window gets its reset line here too.
                reset_lines = [
                    line for line in (_window_reset_line(w) for w in windows) if line
                ]
                break
    except Exception:
        pass

    context_and_primary = " · ".join(bit for bit in (context_bit, primary_bit) if bit) or None

    return [line for line in (goal_line, *reset_lines, context_and_primary) if line]


async def _emit_message_snapshot(__event_emitter__, content):
    """Write `content` to the stored reply with a `replace` event. Open WebUI
    0.12 writes it even while `done: false`, and its end-of-reply save
    overwrites it (ELI-160 slice 8).
    """
    if not __event_emitter__ or not content:
        return
    await __event_emitter__(
        {"type": "replace", "data": {"content": content}}
    )


async def _live_output(request, chat_id: str | None, message_id: str | None) -> list | None:
    """Open WebUI's live copy of a streaming reply's `output`, or None.
    A chat read spanning the end-of-reply save gets neither copy nor output
    (ELI-267); at the end of the Pipe's stream the copy holds the whole reply."""
    if request is None or not chat_id or not message_id:
        return None
    try:
        from open_webui.tasks import get_response_streams_by_chat_id
        streams = await get_response_streams_by_chat_id(
            getattr(request.app.state, "redis", None), chat_id)
    except Exception as ex:
        pipe_log(f"  live output of {message_id[:8]}...: {ex!r}")
        return None
    output = next((s.get("output") for s in streams if s.get("message_id") == message_id), None)
    return copy.deepcopy(output) if output else None


# --- composer --------------------------------------------------------------

# ---------------------------------------------------------------------------
# Composer "Status" button.
#
# OWUI 0.12 has no hook for composer buttons, so an `execute` event installs
# one. Chat.svelte runs it only if its chat_id is the shown chat and its
# message_id is in that tab's history. The snippet is idempotent and
# versioned, keeps the button alive with a debounced MutationObserver, shows
# it only on chats of this Pipe's models, and on click POSTs to the Status
# Action. It also takes over the toolbar's "OpenClaw Status" button, since
# OWUI's handler uploads and saves the whole chat (8 s on a 14 MB chat).
# The button moves out of the chip row when it does not fit, as that row
# scrolls (OWUI 0.13's Model controls button narrows it on phones).
#
# Delivered by the Status Action, at each Pipe turn, and by the composer
# watcher when a socket opens a Pipe chat. The watcher targets the latest
# *user* message: OWUI writes the targeted message back after running the
# code, and a user message never streams, so no reply gets clobbered.
# ---------------------------------------------------------------------------

_COMPOSER_BUTTON_VERSION = "11"

# Status Action id (install_action.py FUNCTION_ID) and the default Pipe id;
# a Pipe under another id adds its own prefixes.
_COMPOSER_ACTION_ID = "openclaw_status_action"
_COMPOSER_DEFAULT_MODEL_PREFIX = "openclaw_gateway."

# The Thinking filter chip's alt text (install_filter.py); the button follows it.
_COMPOSER_THINKING_CHIP_LABEL = "OpenClaw Thinking"

_COMPOSER_BUTTON_JS_TEMPLATE = r"""
(function () {
  const CFG = __OPENCLAW_COMPOSER_CONFIG__;
  const KEY = '__openclawComposerBtn';
  try {
    const prev = window[KEY];
    if (prev && prev.version === CFG.version) {
      if (typeof prev.configure === 'function') prev.configure(CFG);
      return;
    }
    if (prev && typeof prev.teardown === 'function') {
      try { prev.teardown(); } catch (e) { /* the old copy is going away anyway */ }
    }
  } catch (e) {
    console.warn('[openclaw-composer] guard failed', e);
    return;
  }

  const BTN_ID = 'openclaw-composer-status-button';
  // A chat that is not OpenClaw is looked at again after this long (its model
  // can be switched); an OpenClaw chat stays OpenClaw for the page lifetime.
  const NEGATIVE_TTL_MS = 600000;
  // Re-inserting the button more often than this means something keeps
  // removing it (a layout this snippet does not understand): give up.
  const LOOP_LIMIT = 20;
  const LOOP_WINDOW_MS = 10000;
  // A crab claw (ELI-231): an open pincer with a tooth on each finger and a
  // wrist, in Heroicons' outline style (24x24, round caps), for "Claw".
  const CLAW_PATH = 'M6.3 14.6C4.6 11.7 5.7 7.1 8.7 4.6C10.8 2.8 13.4 2.3 15.6 3.1C14.3 3.7 13.4 4.4 13 5.3L13.9 6.5L12 6.9C11.6 7.5 11.3 8.1 11.2 8.7C11.1 11 12.7 12.9 15.1 12.7C16.4 12.5 17.3 11.9 17.8 11.1L17.1 10L18.6 9.7C18.6 9.2 18.6 8.7 18.5 8.2C20.5 10.2 20.6 13.4 18.9 15.8C17.1 18.3 14.2 18.8 11.6 17.8C9.5 17 7.5 16.1 6.3 14.6ZM7.8 16L5.4 19.6L9.1 21.1L11 17.6';

  const state = {
    prefixes: [],
    // Informational only: the Action does not use it for the status path.
    sessionId: null,
    cache: {},
    // chat id -> its model, from the deliveries.
    models: {},
    inflight: {},
    observer: null,
    timer: null,
    busy: false,
    inserts: [],
    // The window width at which the button last did not fit in the chip row;
    // up to that width it sits in the left group instead.
    narrowAt: 0,
    resizeObserver: null,
    watched: null,
    warned: {},
    dead: false,
  };

  function warnOnce(tag, err) {
    if (state.warned[tag]) return;
    state.warned[tag] = true;
    try { console.warn('[openclaw-composer] ' + tag, err); } catch (e) { /* no console */ }
  }

  function configure(cfg) {
    (cfg.modelPrefixes || []).forEach(function (p) {
      if (typeof p === 'string' && p && state.prefixes.indexOf(p) === -1) state.prefixes.push(p);
    });
    if (cfg.sessionId) state.sessionId = cfg.sessionId;
    // A delivery names the chat it was sent for, and is only ever sent for
    // an OpenClaw chat, so that chat needs no lookup.
    if (typeof cfg.chatId === 'string' && cfg.chatId) {
      state.cache[cfg.chatId] = { ok: true, vouched: true, at: Date.now() };
      if (typeof cfg.chatModel === 'string' && cfg.chatModel) state.models[cfg.chatId] = cfg.chatModel;
    }
    schedule();
  }

  function token() {
    try { return localStorage.getItem('token') || ''; } catch (e) { return ''; }
  }

  function currentChatId() {
    const m = /^\/c\/([^\/?#]+)\/?$/.exec(location.pathname);
    if (!m) return null;
    const id = decodeURIComponent(m[1]);
    // Temporary chats are never saved, so there is nothing to look up.
    if (id.indexOf('local:') === 0) return null;
    return id;
  }

  function isOpenclawModel(id) {
    return typeof id === 'string' && state.prefixes.some(function (p) { return id.indexOf(p) === 0; });
  }

  function chatModel(chat) {
    const c = (chat && chat.chat) || {};
    const candidates = Array.isArray(c.models) ? c.models.slice() : [];
    const h = c.history || {};
    const cur = h.messages && h.currentId ? h.messages[h.currentId] : null;
    if (cur && cur.model) candidates.push(cur.model);
    for (let i = 0; i < candidates.length; i++) {
      if (isOpenclawModel(candidates[i])) return candidates[i];
    }
    return null;
  }

  // Latest user message on the current branch, else the current leaf. The
  // Action's dialog events target this id, and a user message never streams,
  // so a dialog opened mid-reply cannot race the reply's own updates.
  function targetMessageId(chat) {
    const h = ((chat && chat.chat) || {}).history || {};
    const msgs = h.messages || {};
    let id = h.currentId;
    for (let i = 0; id && i < 500; i++) {
      const m = msgs[id];
      if (!m) break;
      if (m.role === 'user') return id;
      id = m.parentId;
    }
    return h.currentId || null;
  }

  // The message a toolbar button belongs to: Open WebUI renders each message
  // in a `message-<id>` element.
  function messageIdOf(el) {
    const m = el && el.closest('[id^="message-"]');
    return m ? m.id.slice('message-'.length) : null;
  }

  // The chat's own messages on screen. A side chat's panel (Open WebUI 0.13.2)
  // renders its messages after them, in its own container.
  function chatMessages(sel) {
    return (document.getElementById('messages-container') || document).querySelectorAll(sel);
  }

  // The latest user message on screen: the current branch's, as rendered.
  function latestUserMessageId() {
    const users = chatMessages('.chat-user');
    return users.length ? messageIdOf(users[users.length - 1]) : null;
  }

  function postAction(body) {
    return fetch('/api/chat/actions/' + CFG.actionId, {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + token(),
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (r && !r.ok) {
        return r.json().catch(function () { return {}; }).then(function (j) {
          throw new Error((j && j.detail) || ('HTTP ' + r.status));
        });
      }
    });
  }

  // The model a reply was written by, from its avatar: Open WebUI renders it
  // as `/models/model/profile/image?id=<model id>` inside the message.
  function modelOfMessage(el) {
    const img = el && el.querySelector('img[src*="/models/model/profile/image?id="]');
    if (!img) return null;
    try {
      const id = new URL(img.getAttribute('src'), location.origin).searchParams.get('id');
      return isOpenclawModel(id) ? id : null;
    } catch (e) {
      return null;
    }
  }

  // The newest reply's model on screen.
  function latestReplyModel() {
    const replies = chatMessages('.chat-assistant');
    const el = replies.length ? replies[replies.length - 1].closest('[id^="message-"]') : null;
    return modelOfMessage(el);
  }

  // The body from what the page has, or null when it lacks the model or a
  // message (then the chat is read). `model`: the page's own reading of it,
  // for a chat no delivery has named yet.
  function bodyFromPage(chatId, messageId, model) {
    model = state.models[chatId] || model;
    if (!model || !messageId) return null;
    return { model: model, chat_id: chatId, id: messageId, session_id: state.sessionId || 'openclaw-composer' };
  }

  function fetchChat(chatId) {
    return fetch('/api/v1/chats/' + encodeURIComponent(chatId), {
      headers: { 'Authorization': 'Bearer ' + token() },
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
  }

  function classify(chatId) {
    if (state.inflight[chatId]) return;
    state.inflight[chatId] = true;
    fetchChat(chatId).then(function (chat) {
      const prev = state.cache[chatId];
      if (prev && prev.vouched) return;
      state.cache[chatId] = { ok: !!chatModel(chat), at: Date.now() };
    }, function () {
      const prev = state.cache[chatId];
      if (prev && prev.vouched) return;
      state.cache[chatId] = { ok: false, at: Date.now() };
    }).then(function () {
      delete state.inflight[chatId];
      schedule();
    });
  }

  function toast(text) {
    try {
      const dark = document.documentElement.classList.contains('dark');
      const el = document.createElement('div');
      el.setAttribute('role', 'status');
      el.textContent = text;
      el.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);'
        + 'z-index:10001;max-width:min(420px,90vw);padding:10px 14px;border-radius:12px;'
        + 'font-size:13px;line-height:1.4;box-shadow:0 4px 16px rgba(0,0,0,0.18);';
      el.style.background = dark ? '#1f2937' : '#ffffff';
      el.style.color = dark ? '#f3f4f6' : '#111827';
      el.style.border = '1px solid ' + (dark ? '#374151' : '#e5e7eb');
      document.body.appendChild(el);
      setTimeout(function () { el.remove(); }, 4000);
    } catch (e) {
      warnOnce('toast failed', text);
    }
  }

  // The POST body the Status Action receives. Same shape as the dialog's own
  // Compact button, minus `mode`, so the Action takes its normal status path.
  function actionBody(chatId, chat) {
    let model = chatModel(chat);
    const c = (chat && chat.chat) || {};
    const entry = state.cache[chatId];
    if (!model && entry && entry.vouched && Array.isArray(c.models) && typeof c.models[0] === 'string') {
      // A workspace model built on an OpenClaw model: its id has none of the
      // Pipe's prefixes, but the Pipe itself vouched for this chat.
      model = c.models[0];
    }
    const messageId = targetMessageId(chat);
    if (!model || !messageId) return null;
    return {
      model: model,
      chat_id: chatId,
      id: messageId,
      session_id: state.sessionId || 'openclaw-composer',
    };
  }

  function openStatus(btn) {
    if (state.busy) return;
    const chatId = currentChatId();
    if (!chatId) return;
    state.busy = true;
    btn.style.opacity = '0.6';
    const known = bodyFromPage(chatId, latestUserMessageId(), latestReplyModel());
    (known ? Promise.resolve(known) : fetchChat(chatId).then(function (chat) {
      return actionBody(chatId, chat);
    })).then(function (body) {
      if (!body) throw new Error('this chat has no OpenClaw message yet');
      return postAction(body);
    }).catch(function (err) {
      console.warn('[openclaw-composer] status failed', err);
      toast('OpenClaw status: ' + ((err && err.message) || err));
    }).then(function () {
      state.busy = false;
      btn.style.opacity = '';
    });
  }

  // Capture phase, so it runs before Open WebUI's own click handler on the
  // button and can stop it.
  function onToolbarClick(e) {
    const btn = e.target && e.target.closest && e.target.closest('button[aria-label="OpenClaw Status"]');
    const chatId = btn ? currentChatId() : null;
    const message = btn ? btn.closest('[id^="message-"]') : null;
    const body = chatId ? bodyFromPage(chatId, messageIdOf(btn), modelOfMessage(message)) : null;
    if (!body) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    postAction(body).catch(function (err) {
      console.warn('[openclaw-composer] status failed', err);
      toast('OpenClaw status: ' + ((err && err.message) || err));
    });
  }

  function makeButton() {
    const b = document.createElement('button');
    b.type = 'button';
    b.id = BTN_ID;
    // Shown as "Claw" (ELI-202); the aria-label keeps its old name, which the
    // page scripts and the tests find the button by.
    b.title = 'Claw';
    b.setAttribute('aria-label', 'OpenClaw status');
    b.dataset.openclawVersion = CFG.version;
    b.className = 'p-[0.375rem] flex gap-1 items-center text-sm rounded-full '
      + 'transition-colors duration-300 focus:outline-hidden shrink-0 '
      + 'bg-transparent text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800';
    b.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
      + 'stroke-width="1.75" stroke="currentColor" aria-hidden="true" class="size-4">'
      + '<path stroke-linecap="round" stroke-linejoin="round" d="' + CLAW_PATH + '"/></svg>'
      // Icon-only below `sm`, like Open WebUI's own composer chips: at phone
      // width the chip row's overflow cut the label to "Stat" (ELI-123). The
      // title and aria-label still name it. Both classes ship in Open WebUI's CSS.
      + '<span class="pr-0.5 hidden sm:inline">Claw</span>';
    b.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      openStatus(b);
    });
    return b;
  }

  // {parent, after}: insert right after `after` inside `parent`, or at the end
  // of `parent` when `after` is null. null when no known anchor is on screen.
  // The composer's button row: [left group: More (+), and up to Open WebUI
  // 0.13.0 Integrations] [chip row, scrolls] [model, send]. 0.13.1 moved
  // Integrations into the + menu, so the row is found from the + button and
  // known by its shape. A channel's composer keeps its + inside the row's
  // flex-1 group: that is not a chat composer.
  function composerRow() {
    const integ = document.getElementById('input-menu-button')
      || document.getElementById('integration-menu-button');
    const form = integ ? integ.closest('form') : null;
    const row = integ ? integ.closest('div.justify-between') : null;
    if (!form || !row || !form.contains(row)) return null;
    const chips = row.querySelector(':scope > div.flex-1');
    if (chips && chips.contains(integ)) return null;
    return { integ: integ, form: form, row: row, chips: chips };
  }

  // The left group, which never scrolls: the row's child holding Integrations.
  function leftSlot(c) {
    let g = c.integ;
    while (g && g.parentElement !== c.row) g = g.parentElement;
    return g && g !== c.chips ? { parent: g, after: null, left: true } : null;
  }

  // {parent, after}: insert right after `after` inside `parent`, or at the end
  // of `parent` when `after` is null. null when no known anchor is on screen.
  function findSlot() {
    const c = composerRow();
    if (!c) return null;
    if (state.narrowAt && window.innerWidth <= state.narrowAt) return leftSlot(c);
    const imgs = c.form.querySelectorAll('img[alt]');
    for (let i = 0; i < imgs.length; i++) {
      if (imgs[i].getAttribute('alt') !== CFG.thinkingChipLabel) continue;
      const chip = imgs[i].closest('button');
      const wrap = chip ? chip.parentElement : null;
      if (wrap && wrap.parentElement && c.form.contains(wrap.parentElement)) {
        return { parent: wrap.parentElement, after: wrap };
      }
    }
    // The chip is only rendered while the filter is on. Fall back to the end
    // of the chip group the composer always renders next to it.
    const groups = c.chips ? c.chips.querySelectorAll(':scope > div.shrink-0') : [];
    if (groups.length) return { parent: groups[groups.length - 1], after: null };
    return null;
  }

  // Placed in the chip row but cut off by its scroll box: from now on, up to
  // this width, the left group.
  function checkFits(btn) {
    const c = composerRow();
    if (!c || !c.chips || typeof btn.getBoundingClientRect !== 'function') return;
    let a = btn.parentElement;
    while (a && a !== c.chips) a = a.parentElement;
    if (!a) return;
    const r = btn.getBoundingClientRect();
    const box = c.chips.getBoundingClientRect();
    if (r.width === 0) return;
    if (r.left < box.left - 0.5 || r.right > box.right + 0.5) {
      state.narrowAt = window.innerWidth;
      // Now, not on the next ensure(): a clipped button must not stay on
      // screen for a debounce.
      const s = leftSlot(c);
      if (s) s.parent.appendChild(btn);
      return;
    }
    watchChips(c.chips, btn);
  }

  // The chip row can get narrower without a childList change (the model's
  // name fills in, a font loads): check again whenever its size changes.
  function watchChips(chips, btn) {
    if (typeof ResizeObserver !== 'function') return;
    if (!state.resizeObserver) {
      state.resizeObserver = new ResizeObserver(function () {
        const b = document.getElementById(BTN_ID);
        if (b) checkFits(b);
      });
    }
    if (state.watched === chips) return;
    state.resizeObserver.disconnect();
    state.resizeObserver.observe(chips);
    state.resizeObserver.observe(btn);
    state.watched = chips;
  }

  // Wider than where the button stopped fitting: try the chip row again.
  // Narrower: ensure() checks the fit. Moves a width change causes are not
  // the composer fighting the button, so they don't count toward LOOP_LIMIT.
  function onResize() {
    if (state.narrowAt && window.innerWidth > state.narrowAt) {
      state.narrowAt = 0;
      state.inserts = [];
    }
    schedule();
  }

  function removeAll() {
    const all = document.querySelectorAll('#' + BTN_ID);
    for (let i = 0; i < all.length; i++) all[i].remove();
  }

  function ensure() {
    if (state.dead) return;
    const chatId = currentChatId();
    let show = false;
    if (chatId) {
      const c = state.cache[chatId];
      if (!c || (!c.ok && Date.now() - c.at > NEGATIVE_TTL_MS)) classify(chatId);
      show = !!(c && c.ok);
    }
    const slot = show ? findSlot() : null;
    if (!slot) {
      removeAll();
      return;
    }
    const all = document.querySelectorAll('#' + BTN_ID);
    let btn = all.length ? all[0] : null;
    for (let i = 1; i < all.length; i++) all[i].remove();
    if (btn && btn.dataset.openclawVersion !== CFG.version) {
      btn.remove();
      btn = null;
    }
    const placed = btn && (slot.after
      ? slot.after.nextElementSibling === btn
      : slot.parent.lastElementChild === btn);
    if (placed) {
      checkFits(btn);
      return;
    }
    const now = Date.now();
    state.inserts = state.inserts.filter(function (t) { return now - t < LOOP_WINDOW_MS; });
    state.inserts.push(now);
    if (state.inserts.length > LOOP_LIMIT) {
      warnOnce('the composer keeps removing the button; giving up until reload', null);
      teardown();
      state.dead = true;
      return;
    }
    if (!btn) btn = makeButton();
    if (slot.after) slot.after.insertAdjacentElement('afterend', btn);
    else slot.parent.appendChild(btn);
    checkFits(btn);
  }

  function schedule() {
    if (state.timer || state.dead) return;
    state.timer = setTimeout(function () {
      state.timer = null;
      try { ensure(); } catch (e) { warnOnce('ensure failed', e); }
    }, 150);
  }

  function teardown() {
    if (state.observer) state.observer.disconnect();
    state.observer = null;
    if (state.timer) clearTimeout(state.timer);
    state.timer = null;
    window.removeEventListener('popstate', schedule);
    window.removeEventListener('resize', onResize);
    if (state.resizeObserver) state.resizeObserver.disconnect();
    state.resizeObserver = null;
    state.watched = null;
    document.removeEventListener('click', onToolbarClick, true);
    try { removeAll(); } catch (e) { /* page is going away */ }
  }

  try {
    window[KEY] = {
      version: CFG.version,
      configure: configure,
      teardown: teardown,
      ensure: ensure,
      // For live checks from the console; not used by the page.
      debug: function () {
        const chatId = currentChatId();
        return {
          version: CFG.version, chatId: chatId, prefixes: state.prefixes.slice(),
          cached: chatId ? state.cache[chatId] || null : null, dead: state.dead,
          slot: !!findSlot(), narrowAt: state.narrowAt, buttons: document.querySelectorAll('#' + BTN_ID).length,
          inserts: state.inserts.length,
        };
      },
      actionBody: actionBody,
      openStatus: openStatus,
    };
    state.observer = new MutationObserver(schedule);
    state.observer.observe(document.body, { childList: true, subtree: true });
    window.addEventListener('popstate', schedule);
    window.addEventListener('resize', onResize);
    document.addEventListener('click', onToolbarClick, true);
    configure(CFG);
  } catch (e) {
    warnOnce('install failed', e);
  }
})();
"""


def _composer_own_function_id():
    """Function id from the module name `function_<id>_<32 hex>`, or None."""
    m = re.match(r"^function_(.+)_[0-9a-f]{32}$", globals().get("__name__") or "")
    return m.group(1) if m else None


def _composer_model_prefixes(model_id=None, own_id=None) -> list:
    """Model-id prefixes that count as OpenClaw chats."""
    prefixes = [_COMPOSER_DEFAULT_MODEL_PREFIX]
    extra = []
    if isinstance(own_id, str) and own_id:
        extra.append(own_id + ".")
    if isinstance(model_id, str) and "." in model_id:
        extra.append(model_id.split(".", 1)[0] + ".")
    for p in extra:
        if p not in prefixes:
            prefixes.append(p)
    return prefixes


def _render_composer_button_js(*, session_id=None, model_prefixes=None, chat_id=None,
                               chat_model=None) -> str:
    """The snippet with its config as one JSON literal, `<` escaped so it
    cannot close a script tag. `chat_model` is sent only with `chat_id`."""
    config = {
        "version": _COMPOSER_BUTTON_VERSION,
        "actionId": _COMPOSER_ACTION_ID,
        "modelPrefixes": list(model_prefixes or [_COMPOSER_DEFAULT_MODEL_PREFIX]),
        "sessionId": session_id if isinstance(session_id, str) and session_id else None,
        "chatId": chat_id if isinstance(chat_id, str) and chat_id else None,
        "chatModel": chat_model if chat_id and isinstance(chat_model, str) and chat_model else None,
        "thinkingChipLabel": _COMPOSER_THINKING_CHIP_LABEL,
    }
    payload = json.dumps(config).replace("<", "\\u003c")
    return _COMPOSER_BUTTON_JS_TEMPLATE.replace("__OPENCLAW_COMPOSER_CONFIG__", payload)


async def _emit_composer_button(__event_emitter__, *, session_id=None, model_id=None,
                                chat_id=None, model_prefixes=None, chat_model=None) -> bool:
    """Emit the snippet; returns False rather than raise, so it never fails a turn."""
    if not __event_emitter__:
        return False
    try:
        code = _render_composer_button_js(
            session_id=session_id,
            model_prefixes=model_prefixes or _composer_model_prefixes(model_id),
            chat_id=chat_id,
            chat_model=chat_model,
        )
        await __event_emitter__({"type": "execute", "data": {"code": code}})
        return True
    except Exception as ex:
        pipe_log(f"[composer] could not emit the status button: {ex}")
        return False


# --- composer_watch --------------------------------------------------------
#
# Pipe only (the Action artifact does not include this fragment).


# ---------------------------------------------------------------------------
# (c) Composer watcher: push the snippet when a tab opens an OpenClaw chat.
#
# Open WebUI 0.12 has no hook on a tab's `events:chat` join, so this polls
# SESSION_POOL[sid]["chat_ids"] (socket/main.py). It sends with `sio.call` to
# that one socket: Chat.svelte acks `execute` only after running it and drops
# it (no ack) until the chat's history is loaded, so no ack means retry.
# ---------------------------------------------------------------------------

# Until the snippet lands, a Status click takes Open WebUI's slow path (it saves
# the whole chat), so poll fast. SESSION_POOL is in memory.
_COMPOSER_WATCH_INTERVAL_S = 0.5
_COMPOSER_WATCH_SETTLE_S = 0.5
_COMPOSER_WATCH_ACK_TIMEOUT_S = 4.0
_COMPOSER_WATCH_RETRY_S = 3.0
_COMPOSER_WATCH_ATTEMPTS = 3
_COMPOSER_WATCH_LIVENESS_S = 30.0

# Kept on `open_webui.socket.main` (see `_STALE_CONN_ATTR` in gateway.py) so a
# redeploy can cancel the old watcher. One slot per Pipe function id.
_COMPOSER_WATCH_ATTR = "_openclaw_composer_watcher_v1"


def _composer_watch_slot(function_id) -> str:
    """The attribute on OWUI's socket module holding `function_id`'s watcher."""
    return f"{_COMPOSER_WATCH_ATTR}_{function_id}" if function_id else _COMPOSER_WATCH_ATTR

_composer_watcher_task = None


async def _composer_chat_head(user_id, current_id, message) -> dict:
    """{"user_id", "message_id", "model"} of a chat: `message_id` is the snippet's
    targetMessageId(), `model` the newest assistant message's."""
    target, model, message_id = None, None, current_id
    for _ in range(500):
        if not message_id:
            break
        row = await message(message_id)
        if row is None:
            break
        role, parent_id, model_id = row
        if role == "assistant" and model is None:
            model = model_id
        if role == "user" and target is None:
            target = message_id
        if target is not None and model is not None:
            break
        message_id = parent_id
    return {"user_id": user_id, "message_id": target or current_id, "model": model}


class _ComposerWatcher:
    def __init__(self, valves_getter, prefixes_getter, function_id=None):
        self.valves_getter = valves_getter
        self.prefixes_getter = prefixes_getter
        self.function_id = function_id
        # (sid, chat_id) -> {"next": monotonic time, "attempts": int, "done": bool}
        self._pairs: dict = {}

    def enabled(self) -> bool:
        try:
            return bool(getattr(self.valves_getter(), "COMPOSER_STATUS_BUTTON", True))
        except Exception:
            return False

    @staticmethod
    def _session_pool_batches():
        import open_webui.socket.main as _owui_socket_main
        getter = getattr(_owui_socket_main, "get_session_pool_batches", None)
        if getter is not None:
            return getter()
        pool = getattr(_owui_socket_main, "SESSION_POOL", None) or {}
        return [list(pool.items())]

    @staticmethod
    async def _chat_head(chat_id):
        """`_composer_chat_head` from the DB, one `chat_message` row per step.
        Reading the chat itself builds it all in Python, about 14x its JSON (ELI-115)."""
        from sqlalchemy import select
        from open_webui.internal.db import get_async_db_context
        from open_webui.models.chats import Chat
        from open_webui.models.chat_messages import ChatMessage

        async with get_async_db_context() as db:
            row = (await db.execute(select(Chat.user_id, Chat.current_message_id)
                                    .where(Chat.id == chat_id))).first()
            if row is None:
                return None

            async def message(message_id):
                return (await db.execute(
                    select(ChatMessage.role, ChatMessage.parent_id, ChatMessage.model_id)
                    .where(ChatMessage.id == f"{chat_id}-{message_id}"))).first()
            return await _composer_chat_head(row[0], row[1], message)

    @staticmethod
    async def _call_sid(sid, payload) -> bool:
        """True when the tab acked, i.e. actually ran the snippet."""
        from open_webui.socket.main import sio
        try:
            await sio.call("events", payload, to=sid, timeout=_COMPOSER_WATCH_ACK_TIMEOUT_S)
            return True
        except Exception:
            return False

    async def function_state(self) -> str:
        """"active", "inactive", "gone" or "unknown" for this Pipe function."""
        if not self.function_id:
            return "unknown"
        try:
            from open_webui.models.functions import Functions
            fn = Functions.get_function_by_id(self.function_id)
            if asyncio.iscoroutine(fn):
                fn = await fn
        except Exception:
            return "unknown"
        if fn is None:
            return "gone"
        return "active" if getattr(fn, "is_active", True) else "inactive"

    async def tick(self, now=None):
        if not self.enabled():
            for key in self._pairs:
                _chat_tab_left(*key)
            self._pairs.clear()
            return 0
        now = time.monotonic() if now is None else now
        live = set()
        due = []
        for batch in self._session_pool_batches():
            for sid, session in batch:
                if not isinstance(session, dict):
                    continue
                user_id = session.get("id")
                for chat_id in session.get("chat_ids") or []:
                    key = (sid, chat_id)
                    live.add(key)
                    st = self._pairs.get(key)
                    if st is None:
                        self._pairs[key] = {"next": now + _COMPOSER_WATCH_SETTLE_S,
                                            "attempts": 0, "done": False}
                        continue
                    if st["done"] or now < st["next"]:
                        continue
                    st["attempts"] += 1
                    due.append((key, user_id))
        for key in [k for k in self._pairs if k not in live]:
            del self._pairs[key]
            _chat_tab_left(*key)
        if not due:
            return 0

        results = await asyncio.gather(
            *(self._push(sid, chat_id, user_id) for (sid, chat_id), user_id in due),
            return_exceptions=True,
        )
        pushed = 0
        for ((sid, chat_id), _user_id), result in zip(due, results):
            st = self._pairs.get((sid, chat_id))
            if isinstance(result, BaseException):
                pipe_log(f"[composer] push to {str(sid)[:8]} failed: {result}")
                result = "retry"
            if result == "acked":
                pushed += 1
                # The tab shows the chat: an ask_user card can go there (askuser.py).
                _chat_tab_ready(sid, chat_id)
            if st is None:
                continue
            if result == "retry" and st["attempts"] < _COMPOSER_WATCH_ATTEMPTS:
                st["next"] = now + _COMPOSER_WATCH_RETRY_S
            else:
                st["done"] = True
        return pushed

    async def _push(self, sid, chat_id, user_id) -> str:
        """"acked" (the tab ran it), "skip" (not ours to push), or "retry"."""
        if not user_id:
            return "skip"
        head = await self._chat_head(chat_id)
        if head is None or head["user_id"] != user_id:
            return "skip"
        prefixes = self.prefixes_getter()
        model = head["model"]
        if not (isinstance(model, str) and any(model.startswith(p) for p in prefixes)):
            return "skip"
        message_id = head["message_id"]
        if not message_id:
            return "skip"
        # The intent and auto-send hooks ride along: a tab opened after a turn
        # writer started must still answer its cancel query (ELI-100 case 8).
        code = (_page_hooks_js(chat_id, _auto_send_on(self.valves_getter()))
                + _render_composer_button_js(session_id=sid, model_prefixes=prefixes, chat_id=chat_id,
                                             chat_model=model))
        acked = await self._call_sid(sid, {
            "chat_id": chat_id,
            "message_id": message_id,
            "data": {"type": "execute", "data": {"code": code}},
        })
        return "acked" if acked else "retry"

    async def run(self):
        _CHAT_TABS_TRACKED[0] = True
        last_error = None
        next_liveness = 0.0
        state = "unknown"
        while True:
            try:
                now = time.monotonic()
                if now >= next_liveness:
                    next_liveness = now + _COMPOSER_WATCH_LIVENESS_S
                    state = await self.function_state()
                    if state == "gone":
                        pipe_log("[composer] Pipe function deleted; watcher stops")
                        _CHAT_TABS_TRACKED[0] = False
                        return
                if state != "inactive":
                    await self.tick()
                last_error = None
            except asyncio.CancelledError:
                raise
            except Exception as ex:
                if str(ex) != last_error:
                    last_error = str(ex)
                    pipe_log(f"[composer] watcher tick failed: {ex}")
            await asyncio.sleep(_COMPOSER_WATCH_INTERVAL_S)


_composer_known_prefixes = [_COMPOSER_DEFAULT_MODEL_PREFIX]


def _composer_note_model(model_id=None) -> list:
    """Remember the Pipe's function id and served model prefixes, so chats are
    recognised under a non-default id. Returns the known prefixes."""
    for p in _composer_model_prefixes(model_id, own_id=_composer_own_function_id()):
        if p not in _composer_known_prefixes:
            _composer_known_prefixes.append(p)
    return list(_composer_known_prefixes)


def _ensure_composer_watcher(valves_getter):
    """Start the watcher once per deploy inside Open WebUI, cancelling a
    previous deploy's. Returns the task, or None."""
    global _composer_watcher_task
    try:
        if not bool(getattr(valves_getter(), "COMPOSER_STATUS_BUTTON", True)):
            return None
        if _composer_watcher_task is not None and not _composer_watcher_task.done():
            return _composer_watcher_task
        try:
            import open_webui.socket.main as _owui_socket_main
        except Exception:
            return None
        _composer_note_model()
        function_id = _composer_own_function_id()
        slot = _composer_watch_slot(function_id)
        stale = getattr(_owui_socket_main, slot, None)
        if stale is not None and stale is not _composer_watcher_task:
            try:
                stale.cancel()
            except Exception:
                pass
        watcher = _ComposerWatcher(valves_getter, lambda: list(_composer_known_prefixes),
                                   function_id=function_id)
        _composer_watcher_task = asyncio.get_running_loop().create_task(watcher.run())
        setattr(_owui_socket_main, slot, _composer_watcher_task)
        return _composer_watcher_task
    except Exception as ex:
        pipe_log(f"[composer] could not start the watcher: {ex}")
        return None


# --- askuser ---------------------------------------------------------------

_USER_INPUT_TRIGGER_PREFIXES = ("Codex needs input:", "OpenClaw needs input:")


def _is_user_input_prompt(text: str) -> bool:
    """Return True for OpenClaw/Codex blocking user-input prompts."""
    normalized = (text or "").lstrip()
    return any(normalized.startswith(p) for p in _USER_INPUT_TRIGGER_PREFIXES)


def _could_be_user_input_prefix(normalized_text: str) -> bool:
    """True while `normalized_text` could still become (or is) a trigger phrase.
    Streaming delivers the phrase a few characters at a time, so a single delta
    never matches alone.
    """
    if not normalized_text:
        return True
    return any(
        normalized_text.startswith(p) or p.startswith(normalized_text)
        for p in _USER_INPUT_TRIGGER_PREFIXES
    )


# CommonMark 4.5: a fence is 3+ backticks or tildes, indented up to 3 spaces;
# only an equal-or-longer run of the same character closes it.
_FENCE_OPEN_RE = re.compile(r"^ {0,3}(`{3,}|~{3,})(.*)$")
_FENCE_CLOSE_RE = re.compile(r"^ {0,3}(`{3,}|~{3,})[ \t]*$")


def _fence_of(state) -> str:
    """A fence state as the open fence's run ("" when none). `True` is a
    backtick fence of unknown length (older callers passed a bool)."""
    if state is True:
        return "```"
    return state or ""


def _fence_step(line: str, fence: str) -> str:
    """The fence state after `line` when `fence` was open before it."""
    if fence:
        m = _FENCE_CLOSE_RE.match(line)
        if m and m.group(1)[0] == fence[0] and len(m.group(1)) >= len(fence):
            return ""
        return fence
    m = _FENCE_OPEN_RE.match(line)
    if m and not (m.group(1)[0] == "`" and "`" in m.group(2)):
        return m.group(1)
    return ""


def _fence_open_after(text: str, in_fence=False) -> str:
    """The fence run open at the end of `text` ("" when none)."""
    fence = _fence_of(in_fence)
    for line in (text or "").split("\n"):
        fence = _fence_step(line, fence)
    return fence


def _marker_line_index(text: str, in_fence=False):
    """Index of the first line that opens a needs-input block, else None.
    Every line is checked: a provider can deliver the whole reply as one chunk.
    A line inside a fenced code block is a quote, not a prompt (ELI-107).
    """
    start, fence = 0, _fence_of(in_fence)
    while True:
        nl = text.find("\n", start)
        line = text[start:] if nl == -1 else text[start:nl]
        before, fence = fence, _fence_step(line, fence)
        if not before and not fence and _is_user_input_prompt(line):
            return start
        if nl == -1:
            return None
        start = nl + 1


def _advance_input_prompt_buffer(pending: str, delta: str,
                                 in_fence=False, at_line_start=True) -> tuple[str, str]:
    """Feed an assistant delta into the needs-input buffer; returns
    `(text_to_yield_now, new_pending)`. A trigger counts only at a line start,
    and deltas need not split at lines, so after divergence only the text after
    the last newline is held again.

    `in_fence`: nothing in a fence is held (ELI-107). `at_line_start`: when
    False, the first line of `delta` opens no prompt (ELI-147).
    """
    candidate = pending + delta
    if not (pending or at_line_start):
        nl = candidate.find("\n")
        if nl == -1:
            return candidate, ""
        head = candidate[:nl + 1]
        flush, held = _advance_input_prompt_buffer("", candidate[nl + 1:],
                                                   _fence_open_after(head, in_fence))
        return head + flush, held
    if not in_fence and _could_be_user_input_prefix(candidate.lstrip()):
        return "", candidate
    # The whole reply may arrive at once: flush up to the marker, hold the rest.
    marker_at = _marker_line_index(candidate, in_fence)
    if marker_at is not None:
        return candidate[:marker_at], candidate[marker_at:]
    idx = candidate.rfind("\n")
    if idx == -1:
        return candidate, ""
    before, after = candidate[: idx + 1], candidate[idx + 1 :]
    if after and not _fence_open_after(before, in_fence) and _could_be_user_input_prefix(after.lstrip()):
        return before, after
    return before + after, ""


def _strip_input_marker_line(text: str) -> str:
    """Drop a leading needs-input marker and keep the prompt after it, including
    a question on the marker line (ELI-151). Card, modal and text fallback all
    split the prompt here, so no fallback leaks the raw directive.
    """
    if not text:
        return text
    stripped = text.lstrip()
    lead_ws = text[: len(text) - len(stripped)]
    for prefix in _USER_INPUT_TRIGGER_PREFIXES:
        if stripped.startswith(prefix):
            rest = stripped[len(prefix):].lstrip(" \t\r")
            if rest.startswith("\n"):
                rest = rest.lstrip("\n")
            return lead_ws + rest
    return text


def _strip_needs_input_lines(text: str) -> str:
    """Drop every needs-input directive outside a fence, keeping its question
    (ELI-151); a fenced quote stays as written (ELI-107)."""
    if not text:
        return text
    out, fence, skip_blank = [], "", False
    for line in text.split("\n"):
        before, fence = fence, _fence_step(line, fence)
        if not before and not fence and _is_user_input_prompt(line):
            line = _strip_input_marker_line(line)
            skip_blank = not line.strip()
            if skip_blank:
                continue
        if skip_blank and not line.strip():
            continue
        skip_blank = False
        out.append(line)
    return "\n".join(out)


def _truncate_at_repeated_marker(text: str) -> str:
    """Keep only the first needs-input block: an agent once glued a second
    copy onto the last option, doubling the dialog's buttons.
    """
    if not text:
        return text
    first_end = -1
    for prefix in _USER_INPUT_TRIGGER_PREFIXES:
        i = text.find(prefix)
        if i != -1 and (first_end == -1 or i + len(prefix) < first_end):
            first_end = i + len(prefix)
    if first_end == -1:
        return text
    nxt = -1
    for prefix in _USER_INPUT_TRIGGER_PREFIXES:
        i = text.find(prefix, first_end)
        if i != -1 and (nxt == -1 or i < nxt):
            nxt = i
    return text[:nxt].rstrip() if nxt != -1 else text


def _dedupe_options(options):
    """Drop repeated option labels, keeping first-seen order."""
    seen, out = set(), []
    for opt in options:
        key = opt.strip().lower()
        if key and key not in seen:
            seen.add(key)
            out.append(opt)
    return out


def _extract_numbered_options(prompt_text: str) -> list[tuple[str, str]]:
    """[(index_str, label), ...] for lines like "1. foo" / "2) bar", else []."""
    pattern = re.compile(r"(?m)^\s*(\d+)[.)]\s+(.+)$")
    return [(m.group(1), m.group(2).strip()) for m in pattern.finditer(prompt_text or "")]


# What the Ask User block shows for a secret's answer.
SECRET_ANSWER_SHOWN = "•••• (secret entered)"
# Sent once when the secret's dialog got no answer: the reply tells the user
# not to type it into the chat.
SECRET_NOT_RECEIVED_FOR_AGENT = (
    "[Open WebUI] No answer: the masked dialog for the secret you asked for was not "
    "answered, so nothing was received. Do not ask for it in the chat, which stores "
    "what the user types. Use masked credential entry, or ask again when the user "
    "has this chat open."
)
# Sent when the user cancels the secret's dialog (ELI-189); also shown in the block.
SECRET_CANCELLED_FOR_AGENT = (
    "[Open WebUI] Cancelled: the user closed the masked dialog for the secret you "
    "asked for without entering it, so nothing was received. Do not ask for it in "
    "the chat, which stores what the user types."
)
SECRET_CANCELLED_SHOWN = "Cancelled (nothing entered)"

_MULTI_MARKERS = (
    "(multiselect)", "(multi-select)", "(multi)", "[multiselect]", "[multi]",
    "select all that apply", "choose all that apply", "check all that apply",
    "בחר כמה", "בחירה מרובה", "אפשר לבחור כמה", "בחר את כל",
    "اختر كل ما ينطبق", "اختيار متعدد", "يمكنك اختيار أكثر من",
)


def _parse_text_prompt(prompt_text: str) -> dict:
    """`title`, `message`, `secret`, `confirm`, `options` and `multi` of a
    text needs-input prompt."""
    prompt_text = _truncate_at_repeated_marker(prompt_text or "")
    # A question on the marker line stays (ELI-151).
    lines = [line.strip() for line in _strip_input_marker_line(prompt_text).splitlines()]
    lines = [line for line in lines if line]

    title = "OpenClaw needs input"
    if lines and len(lines[0]) <= 80 and not re.match(r"^\d+\.", lines[0]):
        title = lines[0]
        lines = lines[1:]
    message = "\n".join(lines).strip() or "Please answer so the run can continue."
    text_lower = prompt_text.lower()

    multi = any(m in text_lower for m in _MULTI_MARKERS)
    if multi:
        for mk in _MULTI_MARKERS:
            title = re.sub(re.escape(mk), "", title, flags=re.IGNORECASE).strip()
            message = re.sub(re.escape(mk), "", message, flags=re.IGNORECASE).strip()
        title = title or "OpenClaw needs input"
        message = message or "Please answer so the run can continue."

    # Yes/no only when clearly binary: free text turned into yes/no loses the answer.
    has_options = bool(re.search(r"(?m)^\s*\d+[.)]\s", prompt_text))
    yn_markers = ("(y/n)", "[y/n]", "y/n?", "yes/no", "(yes/no)", "כן/לא", "כן / לא", "نعم/لا", "نعم / لا")
    confirm_verbs = (
        "confirm", "proceed", "overwrite", "are you sure", "do you want",
        "delete", "remove", "בטוח", "האם", "هل تريد",
    )
    # "؟" is the Arabic question mark.
    ends_question = message.rstrip().endswith(("?", "؟")) or title.rstrip().endswith(("?", "؟"))
    # A secret unless it is clearly a choice and nothing asks for the value: a
    # choice that merely mentions a password keeps its answers (ELI-196). Kept
    # specific: a bare "key" matches "monkey".
    mentions_secret = any(
        marker in text_lower for marker in ("secret", "password", "api key", "token"))
    asks_for_value = "may show your reply" in text_lower or bool(re.search(
        r"\b(enter|paste|provide|type|send|give|share|input)\b[^.?!\n]{0,40}?"
        r"(secret|password|api key|token)", text_lower))
    yes_no = any(m in text_lower for m in yn_markers)
    is_choice = yes_no or len(_extract_numbered_options(prompt_text)) >= 2
    secret = asks_for_value or (mentions_secret and not is_choice)
    confirm = not secret and not has_options and (
        yes_no or (any(w in text_lower for w in confirm_verbs) and ends_question)
    )
    options = [] if secret or confirm else _dedupe_options(
        [label for _, label in _extract_numbered_options(prompt_text)])
    return {
        "title": title,
        "message": message,
        "secret": secret,
        "confirm": confirm,
        "options": options if len(options) >= 2 else [],
        "multi": multi,
    }


def _is_secret_prompt(prompt_text: str) -> bool:
    return not _parse_ask_user_json(prompt_text) and _parse_text_prompt(prompt_text)["secret"]


def _secret_not_received_text(prompt_text: str) -> str:
    """The reply's closing text for a secret nobody entered. Never the agent's
    question: an answer typed into the chat is stored there."""
    title = _parse_text_prompt(prompt_text)["title"]
    return (f"**{title}**: not received. A secret is entered only in its masked dialog, "
            "never in the chat, which keeps what you type. To enter it, open this chat "
            "in a tab and ask the agent to try again: the dialog shows again.")


def _masked_input_payload(title: str, message: str, placeholder: str = "Type your answer") -> dict:
    """OWUI's input dialog with a masked field (`<input type="password">`)."""
    return {"type": "input", "data": {
        "title": title,
        "message": message,
        "placeholder": placeholder,
        "type": "password",
    }}


def _secret_input_payload(prompt_text: str) -> dict:
    """OWUI's masked input dialog for a secret: the card has no masked field."""
    fields = _parse_text_prompt(prompt_text)
    return _masked_input_payload(fields["title"], fields["message"])


_OPTION_DESCRIPTION_SEPARATORS = (" - ", " – ", " — ")

# OWUI clamps a request:user_input call to 60..240s and removes the card on
# timeout. An unanswered card ends the reply with the question as text (ELI-142).
_NATIVE_CARD_TIMEOUT_MS = 240_000


def _split_option_description(text: str) -> tuple[str, str]:
    """"Postgres - robust, needs a server" -> ("Postgres", "robust, needs a server")."""
    for sep in _OPTION_DESCRIPTION_SEPARATORS:
        label, found, description = text.partition(sep)
        if found and label.strip() and description.strip():
            return label.strip(), description.strip()
    return text.strip(), ""


def _parse_ask_user_json(prompt_text: str) -> list[dict] | None:
    """Questions from a JSON needs-input body (optionally fenced), shaped like
    OWUI's ask_user arguments, or None for the text form.
    """
    body = _strip_input_marker_line(_truncate_at_repeated_marker(prompt_text or "")).strip()
    fence = re.match(r"^```[a-zA-Z]*\s*\n(.*?)\n?```\s*$", body, re.DOTALL)
    if fence:
        body = fence.group(1).strip()
    if not body.startswith("{"):
        return None
    try:
        parsed = json.loads(body)
    except ValueError:
        return None
    raw_questions = parsed.get("questions") if isinstance(parsed, dict) else None
    if not isinstance(raw_questions, list) or not raw_questions:
        return None

    allow_other = parsed.get("allow_other", True) is not False
    questions, seen_ids = [], set()
    for index, raw in enumerate(raw_questions):
        if not isinstance(raw, dict):
            continue
        text = str(raw.get("question") or "").strip()
        if not text:
            continue
        qid = str(raw.get("id") or "").strip()[:64] or f"q{index + 1}"
        while qid in seen_ids:
            qid = f"{qid}_{index + 1}"
        seen_ids.add(qid)
        options, seen_labels = [], set()
        for opt in raw.get("options") or []:
            if isinstance(opt, dict):
                label = str(opt.get("label") or "").strip()
                description = str(opt.get("description") or "").strip()
            else:
                label, description = _split_option_description(str(opt))
            if label and label.lower() not in seen_labels:
                seen_labels.add(label.lower())
                options.append({"label": label[:80], "description": description[:240]})
        questions.append({
            "id": qid,
            "header": str(raw.get("header") or "").strip()[:48] or f"Question {index + 1}",
            "question": text[:500],
            "options": options,
            # A question with no options is free text, so it must accept typing.
            "allow_other": not options or raw.get("allow_other", allow_other) is not False,
        })
    return questions or None


def _ask_user_fallback_text(prompt_text: str) -> str:
    """An unanswered prompt as the reply's closing text: the JSON form reads as
    its questions and options, not raw JSON (ELI-142)."""
    questions = _parse_ask_user_json(prompt_text)
    if not questions and _is_secret_prompt(prompt_text):
        return _secret_not_received_text(prompt_text)
    if not questions:
        return _strip_input_marker_line(prompt_text)
    numbered = len(questions) > 1
    lines = []
    for n, q in enumerate(questions, 1):
        auto_header = re.fullmatch(r"Question \d+", q["header"])
        line = q["question"] if auto_header else f"**{q['header']}**: {q['question']}"
        lines.append(f"{n}. {line}" if numbered else line)
        for opt in q["options"]:
            label = f"{opt['label']} - {opt['description']}" if opt["description"] else opt["label"]
            lines.append(("   - " if numbered else "- ") + label)
    return "\n".join(lines) + "\n\n_Answer in your next message._"


# The card picks one option per question, so a multi-select question takes
# typed numbers; its labels ride under this key to map the answer back.
_MULTI_CHOICES_KEY = "openclaw_choices"


def _native_ask_user_payload(prompt_text: str) -> dict | None:
    """OWUI's native `request:user_input` card for a prompt, or None for a
    secret (the card has no masked input).
    """
    questions = _parse_ask_user_json(prompt_text)
    if questions is None:
        fields = _parse_text_prompt(prompt_text)
        if fields["secret"]:
            return None
        question = {
            "id": "answer",
            "header": fields["title"],
            "question": fields["message"],
            "options": [],
            "allow_other": True,
        }
        # The numbered list moves into `options`, or one line for a multi-select.
        message = re.sub(r"(?m)^\s*\d+[.)]\s+.*$\n?", "", fields["message"]).strip()
        if fields["confirm"]:
            question["options"] = [
                {"label": "Yes", "description": ""},
                {"label": "No", "description": ""},
            ]
            question["allow_other"] = False
        elif fields["options"] and fields["multi"]:
            listed = " · ".join(f"{n}. {label}" for n, label in enumerate(fields["options"], 1))
            question["question"] = (f"{message or fields['title']} {listed}. "
                                    "Type the numbers you pick, like 1, 3")
            question[_MULTI_CHOICES_KEY] = list(fields["options"])
        elif fields["options"]:
            for label in fields["options"]:
                label, description = _split_option_description(label)
                question["options"].append({"label": label, "description": description})
            question["question"] = message or fields["title"]
        questions = [question]
    return {
        "type": "request:user_input",
        "data": {
            "questions": questions,
            "allow_other": True,
            "timeout_ms": _NATIVE_CARD_TIMEOUT_MS,
        },
    }


def _map_multi_answer(text: str, choices: list[str]) -> str:
    """A typed multi-select answer ("1,3", "Cheese, 1") as the chosen options,
    comma-joined; anything else is the answer as typed.
    """
    text = (text or "").strip()
    picked = _picked_choices(text, choices)
    return ", ".join(picked) if picked else text


def _picked_choices(text: str, choices: list[str]) -> list[str] | None:
    """The options a typed multi-select answer names, or None."""
    by_name = {}
    for choice in choices:
        by_name.setdefault(choice.lower(), choice)
        by_name.setdefault(_split_option_description(choice)[0].lower(), choice)
    picked = []
    for part in re.split(r"[,;،]", (text or "").strip()):
        part = part.strip()
        if not part:
            continue
        if part.lower() in by_name:
            names = [by_name[part.lower()]]
        elif re.fullmatch(r"\d+(\s+\d+)*", part):
            numbers = [int(n) for n in part.split()]
            if not all(1 <= n <= len(choices) for n in numbers):
                return None
            names = [choices[n - 1] for n in numbers]
        else:
            return None
        picked += [name for name in names if name not in picked]
    return picked or None


def _format_native_answers(questions: list[dict], answers: dict) -> str:
    """The card's {question_id: answer} as the text sent to the agent: the bare
    answer for one question, "Header: answer" lines for several.
    """
    lines = []
    for question in questions:
        answer = answers.get(question["id"]) if isinstance(answers, dict) else None
        if not isinstance(answer, dict):
            continue
        if answer.get("type") == "other":
            text = str(answer.get("text") or "").strip()
        else:
            text = str(answer.get("label") or "").strip()
        labels = [o["label"] for o in question.get("options", [])]
        if labels == ["Yes", "No"] and text in labels:
            text = text.lower()
        if question.get(_MULTI_CHOICES_KEY):
            text = _map_multi_answer(text, question[_MULTI_CHOICES_KEY])
        if text:
            lines.append((question.get("header") or question["id"], text))
    if not lines:
        return ""
    if len(questions) == 1:
        return lines[0][1]
    return "\n".join(f"{header}: {text}" for header, text in lines)


async def _call_on_chat_tab(
    owui_user_id: str, owui_chat_id: str | None, owui_message_id: str | None, payload: dict,
    timeout_s: float,
):
    """Show `payload` on a socket viewing the chat, or None when there is none.
    Sent as OWUI's get_event_call does, closing with request:interaction:done."""
    try:
        from open_webui.socket.main import sio, SESSION_POOL
    except Exception as ex:
        pipe_log(f"  question on the chat's tab unavailable (not running inside OWUI process?): {ex}")
        return None
    sid = _live_session_id_for_user(owui_user_id, SESSION_POOL, owui_chat_id)
    if not sid:
        return None
    pipe_log(f"  question: showing it on session {sid[:8]}...")
    card = payload.get("type") == "request:user_input"
    interaction_id = str(uuid.uuid4())
    if card:
        payload = {**payload, "data": {**payload["data"], "interaction_id": interaction_id}}
    try:
        return await sio.call(
            "events",
            {"chat_id": owui_chat_id, "message_id": owui_message_id, "data": payload},
            to=sid,
            timeout=timeout_s,
        )
    except Exception as ex:
        return {"error": f"Event call timed out: {ex!r}"}
    finally:
        if card:
            try:
                await sio.emit(
                    "events",
                    {
                        "chat_id": owui_chat_id,
                        "message_id": owui_message_id,
                        "data": {
                            "type": "request:interaction:done",
                            "data": {"interaction_id": interaction_id},
                        },
                    },
                    to=sid,
                )
            except Exception:
                pass


async def _ask_where_the_chat_is(
    __event_call__,
    payload: dict,
    timeout_s: float,
    *,
    grace_s: float = 0,
    owui_user_id: str | None,
    owui_chat_id: str | None,
    owui_message_id: str | None,
    poll_interval_s: float,
    owui_session_id: str | None,
):
    """Ask on the turn's own socket, else once on a tab viewing the chat. Never
    re-shown after a timeout: that keeps a reply open with nothing on screen
    (ELI-142)."""
    response = await _event_call_while_session_lives(
        __event_call__, payload, owui_session_id, timeout_s + grace_s, poll_interval_s
    )
    if owui_user_id and isinstance(response, dict) and "disconnected" in str(response.get("error", "")):
        response = await _call_on_chat_tab(owui_user_id, owui_chat_id, owui_message_id, payload, timeout_s)
    return response


def _unanswered(response) -> str:
    if response is None:
        return "no tab views the chat"
    if isinstance(response, dict):
        return str(response.get("error") or response.get("status"))[:80]
    return repr(response)[:80]


async def _ask_user_native_card(
    __event_call__,
    payload: dict,
    *,
    owui_user_id: str | None,
    owui_chat_id: str | None,
    owui_message_id: str | None,
    poll_interval_s: float,
    owui_session_id: str | None = None,
) -> str | None:
    """Ask once through OWUI's native card. Only an answer or a cancel proves it
    was seen; anything else returns None and the reply ends with the question
    as text (ELI-107).
    """
    response = await _ask_where_the_chat_is(
        __event_call__, payload, payload["data"]["timeout_ms"] / 1000, grace_s=15,
        owui_user_id=owui_user_id, owui_chat_id=owui_chat_id, owui_message_id=owui_message_id,
        poll_interval_s=poll_interval_s, owui_session_id=owui_session_id,
    )
    if isinstance(response, dict) and response.get("status") == "answered":
        return _format_native_answers(payload["data"]["questions"], response.get("answers") or {}) or None
    pipe_log(f"  question card not answered ({_unanswered(response)}); the question ends the reply as text")
    return None


async def _ask_user_secret(
    __event_call__,
    prompt_text: str,
    *,
    timeout_s: float,
    owui_user_id: str | None,
    owui_chat_id: str | None,
    owui_message_id: str | None,
    poll_interval_s: float,
    owui_session_id: str | None = None,
) -> str | None:
    """Ask for a secret in OWUI's masked dialog. OWUI puts no timeout on it, so
    `timeout_s` ends the wait."""
    try:
        response = await _ask_where_the_chat_is(
            __event_call__, _secret_input_payload(prompt_text), timeout_s,
            owui_user_id=owui_user_id, owui_chat_id=owui_chat_id, owui_message_id=owui_message_id,
            poll_interval_s=poll_interval_s, owui_session_id=owui_session_id,
        )
    except asyncio.TimeoutError:
        response = {"error": f"no answer in {timeout_s:g} s"}
    if response is False:
        # The dialog's Cancel (EventConfirmDialog resolves False), not a "no".
        pipe_log("  secret dialog cancelled by the user")
        return SECRET_CANCELLED_FOR_AGENT
    answer = _normalize_event_call_response(response)
    if not answer:
        pipe_log(f"  secret dialog not answered ({_unanswered(response)}); the question ends the reply as text")
    return answer or None


def _ask_user_detail_block(prompt_text: str, answer: str) -> str:
    """An answered ask-user prompt as an "Ask User" `<details type="tool_calls">`
    block: OWUI has no Q&A type, and tool_calls renders collapsible.
    """
    json_questions = _parse_ask_user_json(prompt_text)
    if SECRET_NOT_RECEIVED_FOR_AGENT in answer:
        return "\n" + _secret_not_received_text(prompt_text) + "\n"
    if SECRET_CANCELLED_FOR_AGENT in answer:
        answer = SECRET_CANCELLED_SHOWN
    elif _is_secret_prompt(prompt_text):
        # The block is stored in Open WebUI's database.
        answer = SECRET_ANSWER_SHOWN
    if json_questions:
        question_display = "\n\n".join(
            f"{q['header']}\n{q['question']}" for q in json_questions
        )
    else:
        fields = _parse_text_prompt(prompt_text)
        question_display = f"{fields['title']}\n{fields['message']}"
    args_str = json.dumps({"question": question_display})
    call_id = f"ask-user-{uuid.uuid4().hex[:12]}"
    return (
        '\n<details type="tool_calls" done="true" '
        f'id="{html.escape(call_id)}" '
        'name="Ask User" '
        f'arguments="{html.escape(args_str[:3000])}" '
        f'result="{html.escape(answer[:8000])}" '
        'meta="" files="[]" embeds="[]">'
        '\n<summary>❓ Ask User</summary>\n</details>\n'
    )


@dataclass
class UserInputResult:
    """Outcome of answering a needs-input prompt via an OWUI modal.
    handled=False: the caller shows the text as a fallback. new_run_id: the
    answer started a new run to follow; None means the run went on in place.
    """

    handled: bool
    new_run_id: str | None = None
    prompt_text: str | None = None
    answer: str | None = None
    # The answer run's consumer queue, registered before its send.
    queue: object = None


def _normalize_event_call_response(response) -> str:
    """Text from common OWUI __event_call__ return shapes, else empty string."""
    if response is None:
        return ""
    # Confirmation modals resolve to a bare bool; bool is an int, so check it first.
    if isinstance(response, bool):
        return "yes" if response else "no"
    if isinstance(response, str):
        return response.strip()
    if isinstance(response, dict):
        if "error" in response:
            return ""
        for key in ("value", "text", "content", "message", "response"):
            value = response.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        value = response.get("option")
        if isinstance(value, str) and value.strip():
            return value.strip()
        if response.get("confirmed") is True:
            return "yes"
        if response.get("confirmed") is False:
            return "no"
    return ""


def _live_session_id_for_user(user_id: str, session_pool, chat_id: str | None = None) -> str | None:
    """A connected OWUI session_id of `user_id` (newest first), or None.
    With `chat_id`, only a socket viewing that chat: the user's first socket may
    be another tab where the card never shows (ELI-58). An OWUI without
    `chat_ids` gets any socket.
    """
    mine = [(sid, s) for sid, s in list(session_pool.items()) if s and s.get("id") == user_id]
    if chat_id and any("chat_ids" in s for _sid, s in mine):
        viewing = [sid for sid, s in mine if chat_id in (s.get("chat_ids") or [])]
        return viewing[-1] if viewing else None
    return mine[0][0] if mine else None


async def _event_call_while_session_lives(__event_call__, payload: dict, session_id: str | None,
                                          timeout_s: float, poll_interval_s: float):
    """`__event_call__(payload)`, given up once its socket leaves SESSION_POOL:
    OWUI answers a gone socket only at its own timeout, up to 240 s (ELI-58)."""
    call = asyncio.ensure_future(asyncio.wait_for(__event_call__(payload), timeout=timeout_s))
    try:
        from open_webui.socket.main import SESSION_POOL
    except Exception:
        SESSION_POOL = None
    if not session_id or SESSION_POOL is None:
        return await call
    while True:
        done, _ = await asyncio.wait({call}, timeout=poll_interval_s)
        if done:
            return call.result()
        if session_id not in SESSION_POOL:
            call.cancel()
            pipe_log(f"  question card: session {session_id[:8]}... is gone; showing it on the user's tab")
            return {"error": "Client session disconnected."}


async def _ask_user_input_modal(
    __event_call__,
    prompt_text: str,
    *,
    timeout_s: float = _NATIVE_CARD_TIMEOUT_MS / 1000,
    owui_user_id: str | None = None,
    owui_chat_id: str | None = None,
    owui_message_id: str | None = None,
    poll_interval_s: float = 5,
    owui_session_id: str | None = None,
) -> str | None:
    """Ask a needs-input prompt in the chat's tab: the question card, or the
    masked dialog for a secret. None when unanswered."""
    if not __event_call__ or not _is_user_input_prompt(prompt_text):
        return None
    native_payload = _native_ask_user_payload(prompt_text)
    if native_payload is not None:
        return await _ask_user_native_card(
            __event_call__,
            native_payload,
            owui_user_id=owui_user_id,
            owui_chat_id=owui_chat_id,
            owui_message_id=owui_message_id,
            poll_interval_s=poll_interval_s,
            owui_session_id=owui_session_id,
        )
    return await _ask_user_secret(
        __event_call__,
        prompt_text,
        timeout_s=timeout_s,
        owui_user_id=owui_user_id,
        owui_chat_id=owui_chat_id,
        owui_message_id=owui_message_id,
        poll_interval_s=poll_interval_s,
        owui_session_id=owui_session_id,
    )


# ---------------------------------------------------------------------------
# Secret requests from the Gateway (ELI-96)
# ---------------------------------------------------------------------------
# The `secrets` tool's request is a Gateway question with one store-bound
# question {questionId: "secret_value", isSecret: true, secretStore}.
# `question.resolve` makes the Gateway itself store the value and answer the
# agent "stored" (2026.10.10-beta.1 dist: secrets-tool-f-CystZd.mjs:1253,
# question-CtUDaC2R.mjs:289-370).
#
# Asked like the ask-user secret (ELI-148). The typed value goes straight into
# question.resolve and is never yielded, emitted, persisted or logged. Whether
# a run can use it is Gateway config (secrets.egressProxy, ELI-97).

SECRET_REQUEST_METHODS = ("question.resolve",)
SECRET_REQUEST_EVENTS = ("question.requested", "question.resolved")
# question id -> the task asking for it
_SECRET_REQUESTS: dict = {}
# session key -> the reply streaming its run, which asks its Gateway questions
_SECRET_ASKERS: dict = {}


def _secret_requests_offered(conn) -> bool:
    """The Gateway offers what a secret request needs: its question events
    and `question.resolve` (hello-ok features)."""
    methods = getattr(conn, "gateway_methods", None) or ()
    events = getattr(conn, "gateway_events", None) or ()
    return all(m in methods for m in SECRET_REQUEST_METHODS) and all(e in events for e in SECRET_REQUEST_EVENTS)


def _secret_request_question(record) -> dict | None:
    """The store-bound secret question of a `question.requested` record."""
    if not isinstance(record, dict):
        return None
    questions = record.get("questions") or []
    if len(questions) != 1 or not isinstance(questions[0], dict):
        return None
    question = questions[0]
    store = question.get("secretStore")
    if not question.get("isSecret") or not isinstance(store, dict) or not store.get("name") \
            or not question.get("questionId"):
        return None
    return question


def _secret_request_payload(question: dict) -> dict:
    """The masked dialog for a secret request, from its metadata only."""
    store = question["secretStore"]
    lines = [str(store.get("reason") or "The agent asks for a secret.")]
    hosts = store.get("allowedHosts") or []
    lines.append("Allowed hosts: " + (", ".join(hosts) if hosts
                                       else "none (usable only as a config SecretRef)"))
    lines.append("It goes straight to OpenClaw's secret store, not into this chat.")
    return _masked_input_payload(f"Secret: {store['name']}", "\n\n".join(lines),
                                 placeholder=f"Paste {store['name']}")


def _secret_asker_join(turn) -> None:
    _SECRET_ASKERS[turn.session_key] = turn


def _secret_asker_leave(turn) -> None:
    if _SECRET_ASKERS.get(getattr(turn, "session_key", None)) is turn:
        del _SECRET_ASKERS[turn.session_key]


def secret_request_seen(conn, record) -> bool:
    """`question.requested`: ask a secret request made in an Open WebUI chat.
    False otherwise, or when the Gateway lacks the question protocol."""
    question = _secret_request_question(record)
    if question is None or record.get("status", "pending") != "pending" or not record.get("id"):
        return False
    if not _secret_requests_offered(conn):
        return False
    parsed = conn.parse_owui_session_key(record.get("sessionKey") or "")
    if not parsed or record["id"] in _SECRET_REQUESTS:
        return False
    _SECRET_REQUESTS[record["id"]] = spawn_background(
        _answer_secret_request(conn, record, question, *parsed))
    return True


def secret_request_resolved(payload) -> None:
    """`question.resolved`: the dialog's wait ends; a later answer is dropped."""
    task = _SECRET_REQUESTS.pop((payload or {}).get("id"), None)
    if task is not None:
        task.cancel()


GUEST_SECRET_NOTE = "_The agent asked for the secret `{name}`. That needs the owner; it is not available here._"


async def _cancel_guest_secret_request(conn, record: dict, name: str) -> None:
    """Cancel a secret request from a guest's chat and note it in the run's reply (ELI-229)."""
    qid = record["id"]
    # Out of the registry first: `question.resolved` follows the answer right
    # away, and `secret_request_resolved` would cancel this task.
    if _SECRET_REQUESTS.get(qid) is asyncio.current_task():
        del _SECRET_REQUESTS[qid]
    try:
        result = await conn.send_request("question.resolve", {"id": qid, "cancel": True,
                                                               "resolvedBy": "openwebui"}, timeout=30)
        shown = str((result or {}).get("status"))
    except Exception as ex:
        shown = f"not cancelled ({type(ex).__name__})"
    pipe_log(f"  secret request: {name} in a chat of a user not in OWNER_USERS: {shown}")
    payload = {"sessionKey": record.get("sessionKey") or "", "stream": PIPE_NOTE_STREAM,
               "data": {"id": f"{_NOTE_ITEM_PREFIX}secret_{qid}", "text": GUEST_SECRET_NOTE.format(name=name)}}
    if record.get("runId"):
        payload["runId"] = record["runId"]
    await conn.dispatch_run_event({"type": "event", "event": "agent", "payload": payload})


async def _answer_secret_request(conn, record: dict, question: dict, user_id: str, chat_id: str) -> None:
    qid, name = record["id"], question["secretStore"]["name"]
    timeout_s = max(1.0, (record.get("expiresAtMs") or 0) / 1000 - time.time())
    payload = _secret_request_payload(question)
    if not await _sender_is_owner(conn, record.get("sessionKey") or ""):
        # The store is the owner's: a guest's chat cannot write it, and a
        # pending request answered in the Control UI would hand the owner's
        # secret to a run the guest reads (ELI-229).
        await _cancel_guest_secret_request(conn, record, name)
        return
    turn = _SECRET_ASKERS.get(record.get("sessionKey"))
    pipe_log(f"  secret request: {name} in chat {chat_id[:8]}... (question {qid[:8]}...)")
    try:
        if turn is not None:
            ask = _ask_where_the_chat_is(
                turn.__event_call__, payload, timeout_s,
                owui_user_id=user_id, owui_chat_id=chat_id, owui_message_id=turn.owui_message_id,
                poll_interval_s=5, owui_session_id=(turn.__metadata__ or {}).get("session_id"))
        else:
            ask = _call_on_chat_tab(user_id, chat_id, None, payload, timeout_s)
        response = await asyncio.wait_for(ask, timeout_s)
    except asyncio.TimeoutError:
        response = None
    if _SECRET_REQUESTS.get(qid) is not asyncio.current_task():
        return
    del _SECRET_REQUESTS[qid]
    if response is None:
        # The Gateway expires it and the agent hears "No credential arrived".
        pipe_log(f"  secret request: {name} not answered in Open WebUI")
        return
    # A cancelled dialog answers False.
    value = response.strip() if isinstance(response, str) else ""
    params = ({"id": qid, "answers": {"answers": {question["questionId"]: [value]}},
               "resolvedBy": "openwebui"} if value
              else {"id": qid, "cancel": True, "resolvedBy": "openwebui"})
    value = response = None
    try:
        result = await conn.send_request("question.resolve", params, timeout=30)
        shown = "stored" if (result or {}).get("status") == "answered" else str((result or {}).get("status"))
    except Exception as ex:
        shown = f"not stored ({type(ex).__name__})"
    finally:
        params = None
    pipe_log(f"  secret request: {name} {shown}")
    if turn is not None and turn.__event_emitter__:
        try:
            await turn.__event_emitter__({"type": "notification", "data": {
                "type": "success" if shown == "stored" else "info", "content": f"{name}: {shown}"}})
        except Exception:
            pass


# ---------------------------------------------------------------------------
# The agent's ask_user tool (ELI-216)
# ---------------------------------------------------------------------------
# `ask_user` registers a Gateway question (`question.requested`, up to three
# questions) and waits on `question.waitAnswer` (2026.10.5 dist:
# ask-user-tool-*.mjs). A Gateway client chat gets no prompt of its own, so
# the run used to wait out the 15 minute timeout.
#
# Asked in Open WebUI's card on the newest tab that loaded the chat, moving to
# newer tabs. The card has no timeout: Open WebUI answers its timeout as a
# Cancel. "Loaded" is the composer watcher's ack: a tab cancels a card at once
# while it does not show the chat, which must not read as the user's Cancel.

# question id -> the task asking it
_AGENT_QUESTIONS: dict = {}


def _agent_question_payload(record, timeout_ms: int | None) -> dict | None:
    """Open WebUI's card for an ask_user question record, or None (a secret,
    no questions)."""
    questions = record.get("questions") if isinstance(record, dict) else None
    if not isinstance(questions, list) or not questions:
        return None
    card = []
    for index, raw in enumerate(questions):
        if not isinstance(raw, dict) or raw.get("isSecret") or raw.get("secretStore"):
            return None
        qid, text = str(raw.get("questionId") or ""), str(raw.get("question") or "").strip()
        if not qid or not text:
            return None
        options = [{"label": str(o.get("label") or "").strip(),
                    "description": str(o.get("description") or "").strip()}
                   for o in raw.get("options") or [] if isinstance(o, dict) and o.get("label")]
        question = {
            "id": qid,
            "header": str(raw.get("header") or "").strip() or f"Question {index + 1}",
            "question": text,
            "options": options,
            "allow_other": not options or raw.get("isOther") is not False,
        }
        if raw.get("multiSelect") and options:
            # The card picks one option, so picks are typed as numbers.
            listed = " · ".join(f"{n}. {o['label']}" for n, o in enumerate(options, 1))
            question.update(question=f"{text} {listed}. Type the numbers you pick, like 1, 3",
                            options=[], allow_other=True)
            question[_MULTI_CHOICES_KEY] = [o["label"] for o in options]
        card.append(question)
    return {"type": "request:user_input",
            "data": {"questions": card, "allow_other": True, "timeout_ms": timeout_ms}}


def _agent_question_answers(questions: list[dict], answers) -> dict:
    """The card's answers as question.resolve's {questionId: [values]}."""
    out = {}
    for question in questions:
        answer = answers.get(question["id"]) if isinstance(answers, dict) else None
        if not isinstance(answer, dict):
            continue
        key = "text" if answer.get("type") == "other" else "label"
        text = str(answer.get(key) or "").strip()
        if not text:
            continue
        choices = question.get(_MULTI_CHOICES_KEY)
        out[question["id"]] = (_picked_choices(text, choices) or [text]) if choices else [text]
    return out


def agent_question_seen(conn, record) -> bool:
    """`question.requested`: ask an ask_user question from an Open WebUI chat."""
    if not isinstance(record, dict) or record.get("status", "pending") != "pending" \
            or not record.get("id") or record["id"] in _AGENT_QUESTIONS:
        return False
    if _agent_question_payload(record, None) is None:
        return False
    parsed = conn.parse_owui_session_key(record.get("sessionKey") or "")
    if not parsed:
        return False
    _AGENT_QUESTIONS[record["id"]] = spawn_background(_answer_agent_question(conn, record, *parsed))
    return True


def _open_writer_message_id(conn, chat_id: str, session_key: str) -> str | None:
    """The reply a turn writer streams the session's run into (agent-started runs)."""
    for writer in list(getattr(conn, "_turn_writers", {}).values()):
        if writer.chat_id == chat_id and writer.session_key == session_key and not writer.closed:
            return writer.message_id
    return None


# chat id -> the sockets that have loaded the chat, oldest first
_READY_CHAT_TABS: dict = {}
# chat id -> events set when one more socket has loaded it
_CHAT_TAB_WAITERS: dict = {}
# Whether the composer watcher feeds _READY_CHAT_TABS (on by default).
_CHAT_TABS_TRACKED = [False]
# Without the watcher, how often a question with no tab looks for one.
_UNTRACKED_TAB_POLL_S = 5.0


def _chat_tab_ready(sid, chat_id) -> None:
    """The composer watcher: socket `sid` shows chat `chat_id` loaded."""
    tabs = _READY_CHAT_TABS.setdefault(chat_id, [])
    if sid in tabs:
        tabs.remove(sid)
    tabs.append(sid)
    for event in list(_CHAT_TAB_WAITERS.get(chat_id, ())):
        event.set()


def _chat_tab_left(sid, chat_id) -> None:
    """The composer watcher: socket `sid` no longer shows chat `chat_id`."""
    tabs = _READY_CHAT_TABS.get(chat_id)
    if tabs and sid in tabs:
        tabs.remove(sid)
        if not tabs:
            del _READY_CHAT_TABS[chat_id]


def _views_chat(session_pool, sid, user_id, chat_id) -> bool:
    session = session_pool.get(sid) if sid else None
    return bool(session) and session.get("id") == user_id and (
        "chat_ids" not in session or chat_id in (session.get("chat_ids") or []))


def _temporary_chat_socket(session_pool, chat_id: str) -> tuple[str, str] | None:
    """(socket, chat id) for a temporary chat whose socket is connected: its id
    (`temporary:<socket id>[:<uuid>]`) names the socket, in mixed case. The
    session key the id came from is in lower case (`_owui_session_key`), and a
    side chat's panel takes events for its exact id only."""
    for prefix in TEMPORARY_CHAT_ID_PREFIXES:
        if chat_id.startswith(prefix):
            named, sep, rest = chat_id[len(prefix):].partition(":")
            sid = next((s for s in list(session_pool) if s.lower() == named.lower()), None)
            return (sid, f"{prefix}{sid}{sep}{rest}") if sid else None
    return None


def _shows_chat(session_pool, sid, user_id, chat_id, parent_id=None) -> bool:
    """`sid` shows the chat: it loaded it as its page, or it is the tab that
    asked from a side chat's panel. A panel never joins its own chat, so the
    socket has no record of it: a temporary side chat (Open WebUI 0.13.0) is
    shown by the tab that asked, a saved one (0.13.1+) while that tab shows the
    chat it was opened from (`parent_id`). The page cancels a card for a saved
    chat it does not show, so without its parent the tab is not used."""
    if _views_chat(session_pool, sid, user_id, chat_id):
        return True
    session = session_pool.get(sid) if sid else None
    if not session or session.get("id") != user_id:
        return False
    return _is_temporary_chat(chat_id) or (
        parent_id is not None and parent_id in (session.get("chat_ids") or []))


async def _side_chat_parent(chat_id: str) -> str | None:
    """The chat a saved side chat was opened from (its `originalChatId`), if any."""
    if _is_temporary_chat(chat_id):
        return None
    try:
        return await _owui_history_rows(chat_id).origin()
    except Exception as ex:
        pipe_log(f"  ask_user: the parent of chat {chat_id[:8]}... not read: {ex!r}")
        return None


def _agent_card_tab(session_pool, user_id, chat_id, own_sid, parent_id=None) -> str | None:
    """The socket to show an ask_user card on, or None while no tab can."""
    for sid in reversed(_READY_CHAT_TABS.get(chat_id, [])):
        if _views_chat(session_pool, sid, user_id, chat_id):
            return sid
    if _shows_chat(session_pool, own_sid, user_id, chat_id, parent_id):
        return own_sid
    if not _CHAT_TABS_TRACKED[0]:
        return _live_session_id_for_user(user_id, session_pool, chat_id)
    return None


@contextlib.contextmanager
def _chat_tab_signal(chat_id):
    """An event set when one more socket loads the chat."""
    event = asyncio.Event()
    _CHAT_TAB_WAITERS.setdefault(chat_id, set()).add(event)
    try:
        yield event
    finally:
        waiters = _CHAT_TAB_WAITERS.get(chat_id)
        if waiters is not None:
            waiters.discard(event)
            if not waiters:
                del _CHAT_TAB_WAITERS[chat_id]


async def _card_on_tab(sio, session_pool, sid, user_id, chat_id, message_id, payload, deadline,
                       parent_id=None):
    """Show the card on `sid`: (response, None), (None, "moved") when a newer
    tab loads the chat or `sid` leaves it, or (None, None) at the deadline."""
    # Shown in a side chat's panel: when the tab opens the chat as its page, the
    # panel is gone, so the card goes again to the page.
    panel = not _views_chat(session_pool, sid, user_id, chat_id)
    interaction_id = str(uuid.uuid4())
    data = {**payload["data"], "interaction_id": interaction_id}
    event = {"chat_id": chat_id, "message_id": message_id, "data": {**payload, "data": data}}
    if panel:
        # The tab's page answers `cancelled` at once to a card for a chat it does
        # not show, before the panel takes it (Open WebUI 0.13.2 Chat.svelte:1544);
        # the page skips the user's own shared events (Chat.svelte:1528), the panel does not.
        event = {**event, "shared": True, "user_id": user_id}
    pipe_log(f"  ask_user: showing the card on session {sid[:8]}...")
    with _chat_tab_signal(chat_id) as newer:
        call = asyncio.ensure_future(sio.call(
            "events", event, to=sid, timeout=max(1.0, deadline - time.time())))
        try:
            while True:
                left = deadline - time.time()
                if left <= 0:
                    return None, None
                tab_change = asyncio.ensure_future(newer.wait())
                try:
                    # Wake often enough to notice a gone socket: Open WebUI
                    # keeps a call to one open.
                    done, _ = await asyncio.wait({call, tab_change}, timeout=min(left, 5.0),
                                                 return_when=asyncio.FIRST_COMPLETED)
                finally:
                    tab_change.cancel()
                if call in done:
                    try:
                        response = call.result()
                    except Exception as ex:
                        pipe_log(f"  ask_user: the card on {sid[:8]}... failed: {ex!r}")
                        return None, "moved"
                    if not _shows_chat(session_pool, sid, user_id, chat_id, parent_id):
                        return None, "moved"
                    return response, None
                newer.clear()
                if _agent_card_tab(session_pool, user_id, chat_id, sid, parent_id) != sid \
                        or not _shows_chat(session_pool, sid, user_id, chat_id, parent_id) \
                        or (panel and _views_chat(session_pool, sid, user_id, chat_id)):
                    return None, "moved"
        finally:
            call.cancel()
            try:
                await sio.emit("events", {"chat_id": chat_id, "message_id": message_id, "data": {
                    "type": "request:interaction:done", "data": {"interaction_id": interaction_id}}},
                    to=sid)
            except Exception:
                pass


async def _ask_agent_card(user_id, chat_id, message_id, own_sid, payload, deadline):
    """The card's response from whichever tab has the chat, or None at the deadline."""
    try:
        from open_webui.socket.main import sio, SESSION_POOL
    except Exception as ex:
        pipe_log(f"  ask_user: no Open WebUI sockets here: {ex}")
        return None
    temporary = _temporary_chat_socket(SESSION_POOL, chat_id)
    if temporary is not None:
        # Also with no live turn (a writer's reply): the chat's own socket shows it.
        own_sid, chat_id = own_sid or temporary[0], temporary[1]
    parent_id = await _side_chat_parent(chat_id)
    while (left := deadline - time.time()) > 0:
        sid = _agent_card_tab(SESSION_POOL, user_id, chat_id, own_sid, parent_id)
        if sid is None:
            with _chat_tab_signal(chat_id) as ready:
                wait = left if _CHAT_TABS_TRACKED[0] else min(left, _UNTRACKED_TAB_POLL_S)
                try:
                    await asyncio.wait_for(ready.wait(), wait)
                except asyncio.TimeoutError:
                    pass
            continue
        response, moved = await _card_on_tab(sio, SESSION_POOL, sid, user_id, chat_id,
                                             message_id, payload, deadline, parent_id)
        if moved:
            if sid == own_sid:
                own_sid = None
            continue
        return response
    return None


async def _answer_agent_question(conn, record: dict, user_id: str, chat_id: str) -> None:
    qid, key = record["id"], record.get("sessionKey") or ""
    deadline = (record.get("expiresAtMs") or 0) / 1000 or time.time() + 900
    payload = _agent_question_payload(record, None)
    questions = payload["data"]["questions"]
    turn = _SECRET_ASKERS.get(key)
    message_id = turn.owui_message_id if turn is not None else _open_writer_message_id(conn, chat_id, key)
    own_sid = (turn.__metadata__ or {}).get("session_id") if turn is not None else None
    if not message_id:
        # Open WebUI cancels a card for a message the tab lacks: left to the Control UI.
        _AGENT_QUESTIONS.pop(qid, None)
        pipe_log(f"  ask_user: no reply in chat {chat_id[:8]}... streams the run; left to the Control UI")
        return
    pipe_log(f"  ask_user: {len(questions)} question(s) in chat {chat_id[:8]}... (question {qid[:12]}...)")
    response = await _ask_agent_card(user_id, chat_id, message_id, own_sid, payload, deadline)
    if _AGENT_QUESTIONS.get(qid) is not asyncio.current_task():
        return
    del _AGENT_QUESTIONS[qid]
    if response is None:
        pipe_log("  ask_user: not answered before the question expired")
        return
    answers = (_agent_question_answers(questions, response.get("answers"))
               if isinstance(response, dict) and response.get("status") == "answered" else {})
    if answers:
        params = {"id": qid, "answers": {"answers": answers}, "resolvedBy": "openwebui"}
    else:
        pipe_log("  ask_user: the card was cancelled")
        params = {"id": qid, "cancel": True, "resolvedBy": "openwebui"}
    try:
        result = await conn.send_request("question.resolve", params, timeout=30)
        shown = str((result or {}).get("status"))
    except Exception as ex:
        shown = f"not resolved ({type(ex).__name__})"
    pipe_log(f"  ask_user: {shown}")


def question_requested(conn, record) -> bool:
    """`question.requested`: a secret request or an ask_user question."""
    return secret_request_seen(conn, record) or agent_question_seen(conn, record)


def question_resolved(payload) -> None:
    """`question.resolved`: the pending wait ends; a later answer is dropped."""
    secret_request_resolved(payload)
    task = _AGENT_QUESTIONS.pop((payload or {}).get("id"), None)
    if task is not None:
        task.cancel()


# --- approvals -------------------------------------------------------------

# Plugin approvals: a `before_tool_call` hook answering `requireApproval`.
# The Gateway offers `plugin.approval.request` only to a client with
# operator.admin/approvals scope and the "plugin-approvals" cap
# (`canDeliverApprovals`); without one, a webchat turn's tool call fails with
# "no approval route". The owner answers in the ask_user question card.
# Only sessions this copy owns (by AGENT_ID) are handled. Guest chats and
# channel threads are denied at once, so the turn does not stall until the
# timeout (up to 10 min). Sub-agent sessions are left to the Control UI.

PLUGIN_APPROVAL_METHODS = ("plugin.approval.resolve",)
PLUGIN_APPROVAL_EVENTS = ("plugin.approval.requested", "plugin.approval.resolved")
# Deny first: OWUI tags the first option "Recommended".
PLUGIN_APPROVAL_CHOICES = (("deny", "Deny"), ("allow-once", "Allow once"), ("allow-always", "Always allow"))
_PLUGIN_APPROVAL_QID = "approval"
GUEST_APPROVAL_NOTE = "_The agent asked to use `{tool}`. That needs the owner's approval; it was denied here._"
_PLUGIN_APPROVAL_DETAIL_CHARS = 600
# approval id -> the task asking it
_PLUGIN_APPROVALS: dict = {}


def _plugin_approvals_offered(conn) -> bool:
    """Whether hello-ok lists the approval events and resolve method."""
    methods = getattr(conn, "gateway_methods", None) or ()
    events = getattr(conn, "gateway_events", None) or ()
    return all(m in methods for m in PLUGIN_APPROVAL_METHODS) and all(e in events for e in PLUGIN_APPROVAL_EVENTS)


def _plugin_approval_decisions(request: dict) -> list[str]:
    """Allowed decisions, deny always first (the Gateway adds deny too)."""
    known = [d for d, _ in PLUGIN_APPROVAL_CHOICES]
    raw = request.get("allowedDecisions") if isinstance(request, dict) else None
    allowed = [d for d in known if isinstance(raw, list) and d in raw] or known
    return ["deny"] + [d for d in allowed if d != "deny"]


def _plugin_approval_payload(record) -> dict | None:
    """OWUI question card for a `plugin.approval.requested` record, or None."""
    request = record.get("request") if isinstance(record, dict) else None
    if not isinstance(request, dict):
        return None
    title = str(request.get("title") or "").strip() or "Approval needed"
    text = str(request.get("description") or "").strip() or "Allow this action?"
    facts = []
    if request.get("toolName"):
        facts.append(f"Tool: {request['toolName']}")
    if request.get("pluginId"):
        facts.append(f"Plugin: {request['pluginId']}")
    if request.get("severity") == "critical":
        facts.append("Severity: critical")
    if facts:
        text = f"{text} ({', '.join(facts)})"
    detail = str(request.get("detail") or "").strip()
    if detail:
        text = f"{text}\n\n{detail[:_PLUGIN_APPROVAL_DETAIL_CHARS]}"
    labels = dict(PLUGIN_APPROVAL_CHOICES)
    options = [{"label": labels[d], "description": ""} for d in _plugin_approval_decisions(request)]
    question = {"id": _PLUGIN_APPROVAL_QID, "header": title, "question": text,
                "options": options, "allow_other": False}
    return {"type": "request:user_input",
            "data": {"questions": [question], "allow_other": False, "timeout_ms": None}}


def _plugin_approval_decision(response, allowed: list[str]) -> str:
    """The decision the card's answer names; anything else denies."""
    if isinstance(response, dict) and response.get("status") == "answered":
        answer = (response.get("answers") or {}).get(_PLUGIN_APPROVAL_QID)
        label = str((answer or {}).get("label") or "").strip() if isinstance(answer, dict) else ""
        for decision, shown in PLUGIN_APPROVAL_CHOICES:
            if shown == label and decision in allowed:
                return decision
    return "deny"


def _plugin_approval_session(conn, key: str) -> tuple | None:
    """("chat", user id, chat id), ("channel",), or None if not this copy's."""
    parsed = conn.parse_owui_session_key(key or "")   # matches AGENT_ID
    if parsed:
        return ("chat", *parsed)
    agent_id = getattr(conn._valves(), "AGENT_ID", None)
    m = _CHANNEL_KEY_RE.match(key or "")
    if agent_id and m and m.group(1) == agent_id:
        return ("channel",)
    return None


def plugin_approval_requested(conn, record) -> bool:
    """Ask or deny an approval in a session this copy owns; False otherwise."""
    if not isinstance(record, dict) or not record.get("id") or record["id"] in _PLUGIN_APPROVALS:
        return False
    if _plugin_approval_payload(record) is None or not _plugin_approvals_offered(conn):
        return False
    session = _plugin_approval_session(conn, (record.get("request") or {}).get("sessionKey") or "")
    if not session:
        return False
    _PLUGIN_APPROVALS[record["id"]] = spawn_background(_answer_plugin_approval(conn, record, *session))
    return True


def plugin_approval_resolved(payload) -> None:
    """Answered elsewhere, expired or cancelled: end the card's wait."""
    task = _PLUGIN_APPROVALS.pop((payload or {}).get("id"), None)
    if task is not None:
        pipe_log(f"  plugin approval: resolved elsewhere ({(payload or {}).get('decision')} by "
                 f"{(payload or {}).get('resolvedBy')})")
        task.cancel()


async def _resolve_plugin_approval(conn, approval_id: str, decision: str) -> str:
    try:
        await conn.send_request("plugin.approval.resolve", {"id": approval_id, "decision": decision},
                                timeout=30)
        return decision
    except Exception as ex:
        return f"not resolved ({type(ex).__name__}: {str(ex)[:120]})"


async def _deny_plugin_approval(conn, record: dict, tool: str, why: str, note: str | None) -> None:
    """Deny at once; with `note`, say so in the asking run's reply."""
    approval_id, request = record["id"], record.get("request") or {}
    # Unregister first: `plugin.approval.resolved` would cancel this task.
    if _PLUGIN_APPROVALS.get(approval_id) is asyncio.current_task():
        del _PLUGIN_APPROVALS[approval_id]
    shown = await _resolve_plugin_approval(conn, approval_id, "deny")
    pipe_log(f"  plugin approval: {tool} in {why}: {shown}")
    if note is None:
        return
    payload = {"sessionKey": request.get("sessionKey") or "", "stream": PIPE_NOTE_STREAM,
               "data": {"id": f"{_NOTE_ITEM_PREFIX}approval_{approval_id}", "text": note.format(tool=tool)}}
    if request.get("runId"):
        payload["runId"] = request["runId"]
    await conn.dispatch_run_event({"type": "event", "event": "agent", "payload": payload})


async def _answer_plugin_approval(conn, record: dict, kind: str, user_id: str = "", chat_id: str = "") -> None:
    approval_id, request = record["id"], record.get("request") or {}
    key = request.get("sessionKey") or ""
    tool = str(request.get("toolName") or request.get("title") or "a tool")
    if kind == "channel":
        await _deny_plugin_approval(conn, record, tool, "a channel thread (no card there)", None)
        return
    if not await _sender_is_owner(conn, key):
        await _deny_plugin_approval(conn, record, tool, "a chat of a user not in OWNER_USERS",
                                    GUEST_APPROVAL_NOTE)
        return
    deadline = (record.get("expiresAtMs") or 0) / 1000 or time.time() + 120
    payload = _plugin_approval_payload(record)
    turn = _SECRET_ASKERS.get(key)
    message_id = turn.owui_message_id if turn is not None else _open_writer_message_id(conn, chat_id, key)
    own_sid = (turn.__metadata__ or {}).get("session_id") if turn is not None else None
    if not message_id:
        # A card needs its reply message. Left to the Control UI.
        _PLUGIN_APPROVALS.pop(approval_id, None)
        pipe_log(f"  plugin approval: no reply in chat {chat_id[:8]}... streams the run; left to the Control UI")
        return
    pipe_log(f"  plugin approval: {tool} in chat {chat_id[:8]}... (approval {approval_id[:16]}...)")
    response = await _ask_agent_card(user_id, chat_id, message_id, own_sid, payload, deadline)
    if _PLUGIN_APPROVALS.get(approval_id) is not asyncio.current_task():
        return
    del _PLUGIN_APPROVALS[approval_id]
    if response is None:
        # The Gateway's timeout ends it and tells the agent.
        pipe_log("  plugin approval: not answered before it expired")
        return
    decision = _plugin_approval_decision(response, _plugin_approval_decisions(request))
    pipe_log(f"  plugin approval: {await _resolve_plugin_approval(conn, approval_id, decision)}")


# --- gateway ---------------------------------------------------------------
GATEWAY_SCOPES = ["operator.admin", "operator.read", "operator.write"]
# For users not in OWNER_USERS. Without operator.admin the Gateway does not
# record their turns as the owner's, so owner-only tools are withheld. Not a
# sandbox: tools the Gateway allows non-owner turns stay available.
RESTRICTED_SCOPES = ["operator.read", "operator.write"]
# The Gateway prunes a silently paired device when another silent client with
# the same client id, mode and displayName pairs while it has no open socket.
# A displayName of its own keeps other local "webchat" clients from evicting it.
# The name carries the first characters of the device id (`_display_name`), so
# two installs on one Gateway do not share a name either. The main identity
# needs one too: on a local Gateway it is approved silently like any loopback
# client, and a connect without a name clears the stored one, so the Pipe and the
# Status Action (same identity, same device id) always send the same name.
MAIN_DISPLAY_NAME = "owui-pipe"
RESTRICTED_DISPLAY_NAME = "owui-pipe-restricted"
DISPLAY_NAME_ID_CHARS = 8


def _display_name(base: str, ident: dict | None) -> str:
    """`base` plus the start of the device id, e.g. owui-pipe-e769bc48; `base` alone without an id."""
    device_id = (ident or {}).get("id") or ""
    return f"{base}-{device_id[:DISPLAY_NAME_ID_CHARS]}" if device_id else base


def _parse_owner_users(raw: str) -> frozenset:
    """OWNER_USERS as a set of lowercase user ids and emails."""
    return frozenset(p.strip().lower() for p in (raw or "").split(",") if p.strip())


def _is_owner_user(owners: frozenset, user_id, email) -> bool:
    """An empty list makes everyone an owner (the behaviour before the valve)."""
    if not owners:
        return True
    return any(v and str(v).strip().lower() in owners for v in (user_id, email))


# Run requests go out only through `_run_request`, which picks the connection:
# the sender's scopes decide whether the turn counts as the owner's.
RUN_SEND, RUN_ABORT, RUN_PATCH = "chat.send", "chat.abort", "sessions.patch"
# chat.send fields the Gateway accepts only from an operator.admin connection.
# See `_non_owner_send_params`.
ADMIN_ONLY_SEND_FIELDS = (
    "systemInputProvenance",
    "systemProvenanceReceipt",
    "suppressCommandInterpretation",
    "originatingChannel",
    "originatingTo",
    "originatingAccountId",
    "originatingThreadId",
)
_OWUI_KEY_USER = re.compile(r"^agent:[^:]+:openwebui-([0-9a-fA-F-]{36})-")
# A user's or a saved chat's id: a UUID, joined in the session key by a dash.
_UUID_LEN = len("2d206eab-acac-4945-bd2f-7e8b6365de8c")
_KEY_PART_SEP = "-"
# A temporary chat's id in a session key (a side chat's on Open WebUI 0.13.0):
# `temporary:<socket id>[:<uuid>]`, or the legacy `local:` one, then the
# column's `-m<n>` if any (open_webui/utils/chat_id.py).
_OWUI_TEMPORARY_CHAT_ID = re.compile(r"((?:temporary|local):[^:]+?(?::[0-9a-f-]{36})?)(?:-m\d+)?")
# An Open WebUI channel thread's session (channels.py).
_CHANNEL_KEY_RE = re.compile(r"^agent:([^:]+):openwebui:channel:([^:]+):thread:([^:]+)$")


# ---------------------------------------------------------------------------
# Custom exceptions
# ---------------------------------------------------------------------------

class GatewayError(Exception):
    """Handshake failure or refused request. `error` is the Gateway's error
    shape ({code, message, details, retryable, retryAfterMs}) when sent."""

    def __init__(self, message: str = "", error: dict | None = None):
        super().__init__(message)
        self.error = error or {}


_GATEWAY_CONNECT_TIMEOUT_S = 10.0

# websockets' 1 MiB default closes the whole connection (1009) on a bigger
# frame, and a long `chat.history` or one large tool result exceeds it.
# Bounded so a runaway frame can't exhaust Open WebUI's memory.
GATEWAY_WS_MAX_SIZE = 64 * 1024 * 1024


def _explain_connect_rejection(message: str, *, device_id: str | None = None) -> str:
    """Turn the Gateway's terse connect rejection into an actionable message."""
    lowered = message.lower()
    if "pairing" in lowered or "not approved" in lowered:
        ident = f"\n\nThis device's id is `{device_id}`." if device_id else ""
        return (
            "This Open WebUI instance is not an approved device on the OpenClaw "
            "Gateway yet.\n\nOn the Gateway host, run:\n\n"
            "    openclaw devices list\n"
            "    openclaw devices approve <request-id>\n"
            f"{ident}\n\nThen send your message again."
        )
    if any(k in lowered for k in ("unauthor", "invalid token", "forbidden", "bad token")):
        return (
            f"The Gateway rejected the credentials ({message}). Check the "
            "GATEWAY_TOKEN valve in Open WebUI under Admin Panel > Functions > "
            "OpenClaw Gateway > valves; it must match `gateway.auth.token` in "
            "your OpenClaw config."
        )
    return message


def _parse_gateway_url(raw: str) -> tuple[str, int, bool]:
    """Parse the GATEWAY_URL valve into (host, port, tls).

    Users paste full URLs, so a scheme is accepted; ``wss``/``https`` set tls.
    Anything unparseable raises GatewayError naming the valve, never a bare
    ValueError that would escape pipe()'s handler.
    """
    value = (raw or "").strip()
    if not value:
        raise GatewayError(
            "The GATEWAY_URL valve is empty. Set it to your OpenClaw Gateway "
            "as host:port, for example localhost:18789."
        )
    tls = False
    if "://" in value:
        scheme, _, value = value.partition("://")
        if scheme.lower() not in ("ws", "wss", "http", "https"):
            raise GatewayError(
                f"GATEWAY_URL has an unsupported scheme '{scheme}://'. Use a "
                "bare host:port, for example localhost:18789."
            )
        tls = scheme.lower() in ("wss", "https")
    default_port = "443" if tls else "18789"
    value = value.split("/", 1)[0].split("?", 1)[0]

    if value.startswith("["):
        # Keep the brackets: websockets needs them in the URL.
        addr, sep, rest = value.partition("]")
        if not sep:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} is missing a closing ']' on the IPv6 "
                "address. Expected [address]:port, for example [::1]:18789."
            )
        inner = addr[1:]
        # A bracketed non-IPv6 value makes websockets raise a bare ValueError
        # that escapes every handler, so reject it here.
        try:
            ipaddress.IPv6Address(inner)
        except ValueError:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} has {inner!r} in brackets, but brackets "
                "are only for IPv6 literals. Use a plain host:port such as "
                f"{inner}:18789, or bracket an actual IPv6 address like "
                "[::1]:18789."
            )
        host = addr + "]"
        port_str = rest[1:] if rest.startswith(":") else (rest or default_port)
    elif value.count(":") > 1:
        try:
            ipaddress.IPv6Address(value)
        except ValueError:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} has more than one ':' and is not an IPv6 "
                "address, so the port is ambiguous. Expected host:port, for "
                "example localhost:18789."
            )
        # rpartition(":") would read "::1" as host ":" on port 1.
        raise GatewayError(
            f"GATEWAY_URL {raw!r} is an IPv6 address. Wrap it in brackets so "
            "the port is unambiguous, for example [::1]:18789."
        )
    else:
        host, sep, port_str = value.rpartition(":")
        if not sep:
            host, port_str = value, default_port

    if not host or host == "[]":
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has no host. Expected host:port, "
            "for example localhost:18789."
        )
    if not (port_str.isascii() and port_str.isdigit()):
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has a non-numeric port {port_str!r}. "
            "Expected host:port, for example localhost:18789."
        )
    port = int(port_str)
    if not 1 <= port <= 65535:
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has port {port}, which is outside 1-65535. "
            "The OpenClaw Gateway default is 18789."
        )
    return host, port, tls


# Budget for reading back an interrupted turn's tail. `chat.history` honors
# maxChars per message (schema max 500000) up to a 128 KiB per-message byte
# cap; 50000 chars stays under that cap even for 2-byte scripts like Hebrew.
RECOVERY_HISTORY_LIMIT = 40
RECOVERY_HISTORY_MAX_CHARS = 50000


def _event_frame(payload: dict) -> dict:
    """Wrap a routed payload as a frame for an inline reply. A `chat` event
    has a state and no stream; anything else is `agent`."""
    event = "chat" if "state" in payload and "stream" not in payload else "agent"
    return {"type": "event", "event": event, "payload": payload}


def _history_item(message) -> dict | None:
    """Flatten one `chat.history` message to {role, text}, text blocks only."""
    if not isinstance(message, dict):
        return None
    content = message.get("content")
    if isinstance(content, str):
        text = content
    elif isinstance(content, list):
        text = "".join(
            str(block.get("text") or "")
            for block in content
            if isinstance(block, dict) and block.get("type") == "text"
        )
    else:
        text = str(message.get("text") or "")
    return {"role": message.get("role"), "text": text}


def _history_recovery_text(history: dict, user_text: str) -> str | None:
    """The assistant text saved after this user message in `chat.history`."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    return _recovery_text_from_items([_history_item(m) for m in messages], user_text)


def _recovery_user_text_matches(item_text: str, user_text: str) -> bool:
    """True if a stored user message is this turn's, verbatim or behind the
    Gateway's metadata envelope."""
    return item_text == user_text or item_text.endswith("\n" + user_text)


def _recovery_text_from_items(items, user_text: str) -> str | None:
    """The LAST non-empty assistant item after the last user item matching
    `user_text`. Last because a tool-using turn stores several assistant
    messages and the first is only a preamble."""
    if not isinstance(items, list):
        return None

    normalized_user_text = (user_text or "").strip()
    if not normalized_user_text:
        return None

    last_matching_user_index = None
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            continue
        if item.get("role") != "user":
            continue
        if _recovery_user_text_matches(
            str(item.get("text", "")).strip(), normalized_user_text
        ):
            last_matching_user_index = idx

    if last_matching_user_index is None:
        return None

    found = None
    for item in items[last_matching_user_index + 1:]:
        if not isinstance(item, dict):
            continue
        text = str(item.get("text", "")).strip()
        if item.get("role") == "user" and text:
            break  # the next turn; tool results are user items with no text
        if item.get("role") == "assistant" and text:
            found = text
    return found


async def _recover_turn_text(conn, session_key: str, user_text: str) -> str | None:
    """Read back a turn's text from `chat.history` after the stream was lost (ELI-74)."""
    try:
        history = await conn.session_history(session_key)
    except Exception as ex:
        pipe_log(f"  history recovery failed: {ex}")
        return None
    text = _history_recovery_text(history, user_text)
    if not text:
        pipe_log("  history recovery found no reply")
    return text


def _owui_session_key(agent_id: str, user_id: str, chat_id: str, column: int = 0) -> str:
    """The chat's session key. Column n > 0 is one model of a multi-model
    chat (ELI-329). In lower case, as the Gateway stores it and names it in its
    events: a temporary chat's id carries its socket's id, which has upper case,
    and a key in another case would never match its run's events."""
    key = f"agent:{agent_id}:openwebui-{user_id}-{chat_id}".lower()
    return f"{key}-m{column}" if column else key


def _session_thinking_ladder(desc: dict) -> list | None:
    """Thinking levels the session's CURRENT model supports, from a
    `sessions.describe` response.

    `thinkingLevels` ids are authoritative. `thinkingOptions` holds display
    labels, which break clamping (ELI-85); it is only a fallback. None means
    "unknown, pass through", unlike [] ("supports nothing").
    """
    row = (desc or {}).get("session") or {}
    levels = row.get("thinkingLevels")
    if isinstance(levels, list) and levels:
        out = [str(lv.get("id")) for lv in levels
               if isinstance(lv, dict) and lv.get("id")]
        if out:
            return out
    opts = row.get("thinkingOptions")
    if isinstance(opts, list) and opts:
        return [str(x).strip().lower() for x in opts]
    return None


def _session_model_key(row) -> str | None:
    """`provider/model` for a `sessions.describe` row, or None. Matches the
    Gateway's rejection text so both ladder sources share a cache key."""
    row = row or {}
    provider = str(row.get("modelProvider") or "").strip()
    model = str(row.get("model") or "").strip()
    if not provider or not model:
        return None
    return f"{provider}/{model}"


def _ladder_cache_path(state_dir: str = "") -> str:
    return os.path.join(_state_dir(state_dir), LADDER_CACHE_NAME)


# Guards the ladder cache's read-merge-write: Pipe and Status Action threads
# in one OWUI process would otherwise drop each other's updates.
_LADDER_CACHE_LOCK = threading.Lock()


def _record_thinking_ladder(levels, model_key=None, authoritative=False,
                             state_dir: str = "") -> bool:
    """Fold a ladder into the cache, as a union and per model.

    `levels` (union) feeds the Thinking filter dropdown, which OWUI cannot
    vary per model. `models[key]` is what sends clamp against. An
    `authoritative` ladder (stated in a Gateway rejection) is never
    overwritten by a describe-observed one, which can be the generic profile.
    Best-effort; returns False only when the write failed.
    """
    known = [lv for lv in (levels or []) if lv in LEVEL_RANKS]
    path = _ladder_cache_path(state_dir)

    with _LADDER_CACHE_LOCK:
        current = _read_json_file(path) or {}

        have = current.get("levels")
        have = [x for x in have if x in LEVEL_RANKS] if isinstance(have, list) else []
        merged = sorted(set(have) | set(known), key=lambda lv: (LEVEL_RANKS[lv], lv))

        models = current.get("models")
        models = dict(models) if isinstance(models, dict) else {}
        model_changed = False
        if model_key:
            prior = models.get(model_key)
            prior = prior if isinstance(prior, dict) else {}
            if prior.get("source") == "gateway" and not authoritative:
                pass
            else:
                entry = {
                    "levels": known,
                    "source": "gateway" if authoritative else "describe",
                    "updated": int(time.time()),
                }
                if (prior.get("levels") != entry["levels"]
                        or prior.get("source") != entry["source"]):
                    models[model_key] = entry
                    model_changed = True

        if merged == have and not model_changed:
            return True
        payload = {"levels": merged, "updated": int(time.time())}
        if models:
            payload["models"] = models
        if not _write_json_file(path, payload):
            return False
    if merged != have:
        pipe_log(f"thinking ladder cache updated: {merged}")
    if model_changed:
        pipe_log(
            f"thinking ladder for {model_key}: {known} "
            f"({'stated by gateway' if authoritative else 'observed'})"
        )
    return True


def _read_model_thinking_ladder(model_key, state_dir: str = ""):
    """The exact ladder for one model, or None if unknown (empty counts as unknown)."""
    if not model_key:
        return None
    cache = _read_json_file(_ladder_cache_path(state_dir)) or {}
    models = cache.get("models")
    if not isinstance(models, dict):
        return None
    entry = models.get(model_key)
    if not isinstance(entry, dict):
        return None
    levels = entry.get("levels")
    if not isinstance(levels, list):
        return None
    known = [lv for lv in levels if lv in LEVEL_RANKS]
    return known or None


def _owui_chat_send_params(
    session_key: str,
    message: str,
    idempotency_key: str,
    owui_chat_id: str | None,
    owui_user_id: str | None,
    attachments: list | None = None,
    thinking: str | None = None,
) -> dict:
    params = dict(
        sessionKey=session_key,
        message=message,
        idempotencyKey=idempotency_key,
    )
    if attachments:
        params["attachments"] = attachments
    # Absent means "agent default", unlike any value, "off" included.
    if thinking:
        params["thinking"] = thinking
    if owui_chat_id:
        metadata = {
            "chat_id": owui_chat_id,
            "source": "openwebui",
        }
        if owui_user_id and owui_user_id != "unknown":
            metadata["user_id"] = owui_user_id
        params["systemProvenanceReceipt"] = "\n".join([
            "Conversation info (untrusted metadata):",
            "```json",
            json.dumps(metadata, ensure_ascii=False, indent=2),
            "```",
        ])
    return params


def _resolved_model_key(patch_resp: dict) -> str | None:
    resolved = patch_resp.get("resolved", {})
    provider = resolved.get("modelProvider")
    model = resolved.get("model")
    if provider and model:
        return f"{provider}/{model}"
    return None


# Runtime provider namespaces. sessions.patch reports the vendor instead
# ("claude-cli/x" resolves to "anthropic/x"), so the post-patch check must
# treat them as equal.
_RUNTIME_PROVIDER_NAMESPACES = {"claude-cli", "google-gemini-cli", "codex-cli"}


def _model_patch_matches(model_override: str | None, patch_resp: dict) -> bool:
    if model_override is None:
        return True
    if _resolved_model_key(patch_resp) == model_override:
        return True
    if "/" in model_override:
        want_provider, want_model = model_override.split("/", 1)
        got_model = patch_resp.get("resolved", {}).get("model")
        if want_provider in _RUNTIME_PROVIDER_NAMESPACES and want_model == got_model:
            return True
    return False


def _coerce_text(value) -> str:
    """Extract text from common stream payload shapes."""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        for key in ("delta", "text", "content", "message"):
            text = _coerce_text(value.get(key))
            if text:
                return text
        return ""
    if isinstance(value, list):
        parts = [_coerce_text(item) for item in value]
        return "".join(part for part in parts if part)
    return ""


def _content_has_image(raw_content) -> bool:
    """True if an OWUI message's block-list `content` has an image_url block."""
    if not isinstance(raw_content, list):
        return False
    return any(
        isinstance(block, dict) and block.get("type") == "image_url"
        for block in raw_content
    )


# Used only when hello-ok has no `policy.attachments.maxImageBytes`: the
# Gateway's own cap, openclaw packages/media-core/src/constants.ts:2
# (MAX_IMAGE_BYTES). chat.send refuses a bigger decoded image outright.
GATEWAY_IMAGE_BYTES_FALLBACK = 6 * 1024 * 1024

def _hello_max_image_bytes(hello_ok: dict) -> int:
    """The image cap hello-ok advertises, else the Gateway's built-in one."""
    policy = hello_ok.get("policy")
    attachments = policy.get("attachments") if isinstance(policy, dict) else None
    cap = attachments.get("maxImageBytes") if isinstance(attachments, dict) else None
    # `True` is an int in Python: it is not a byte count.
    if isinstance(cap, int) and not isinstance(cap, bool) and cap > 0:
        return cap
    return GATEWAY_IMAGE_BYTES_FALLBACK


_DATA_URL_RE = re.compile(r"^data:([^;,]*)(?:;[^,]*)?,(.*)$", re.DOTALL)


def _extract_image_attachments(raw_content) -> list:
    """Inline images from OWUI `content` blocks as `chat.send` attachments.
    OWUI only sends base64 data URIs; anything else is skipped."""
    if not isinstance(raw_content, list):
        return []
    attachments = []
    for idx, block in enumerate(raw_content):
        if not (isinstance(block, dict) and block.get("type") == "image_url"):
            continue
        image_url = block.get("image_url")
        url = image_url.get("url") if isinstance(image_url, dict) else None
        if not isinstance(url, str):
            continue
        match = _DATA_URL_RE.match(url.strip())
        if not match or ";base64" not in url.split(",", 1)[0]:
            continue
        mime = match.group(1) or "image/png"
        ext = mimetypes.guess_extension(mime) or ".png"
        attachments.append({
            "type": "image",
            "mimeType": mime,
            "fileName": f"image-{idx + 1}{ext}",
            "content": match.group(2),
        })
    return attachments


def _numbered_attachments(attachments: list, *, combined: bool) -> list:
    """Renumber images of several combined messages so names don't collide."""
    if not combined:
        return attachments
    out = []
    for n, a in enumerate(attachments, 1):
        ext = mimetypes.guess_extension(a.get("mimeType") or "") or ".png"
        out.append({**a, "fileName": f"image-{n}{ext}"})
    return out


def _item_assistant_text(data: dict) -> str:
    """Return visible assistant text carried by item/preamble events."""
    kind = str(data.get("kind", "")).strip().lower()
    if kind not in ("assistant", "message", "output", "preamble"):
        return ""
    for key in ("delta", "text", "content", "message"):
        text = _coerce_text(data.get(key)).strip()
        if text:
            return text
    return ""


# Queue item `_GatewayConnection._mark_event_gap` puts where events were lost.
_GAP_MARKER_TYPE = "_pipe_gap"
# Put in every run queue when a reconnect lands on a new Gateway process: the
# run's owner (DESIGN 2.7) is then decided from its row.
_RESTART_MARKER_TYPE = "_pipe_restart"
# A session row for its inline replies: `{"type", "row", "resync", "read_at"}`.
# A run's own settle row ends its reply even if the final event was lost.
# `resync` (after a reconnect or gap): an idle session means every admitted
# run is over. An idle row counts only if read after the run was admitted.
_ROW_MARKER_TYPE = "_pipe_row"
# A later message was steered into this run (2026.10.10+): `{"type", "into"}`.
# The reply ends there; the rest goes to the steered message's reply.
_STEERED_MARKER_TYPE = "_pipe_steered"
# Turn pump queue items (`writer._turn_pump_loop`).
_PUMP_EVENT = "event"
_PUMP_STEERED_IN = "steered_in"
_CHAT_FINAL = "final"
_PHASE_END = "end"


def _settle_ref(run_id: str) -> dict | None:
    """The reply of a Pipe reply run, as `_settle_steered_replies` takes it;
    None for any other run."""
    pipe = parse_pipe_run_id(run_id)
    if not pipe or pipe["kind"] != PIPE_RUN_REPLY:
        return None
    return {"chat_id": pipe["chat"], "message_id": pipe["message"], "request_task_id": None,
            "span_run": run_id}


def steers_mid_run_messages(version) -> bool:
    """True for a 2026.10.10+ Gateway, which steers mid-run messages into the
    run (claude-cli included). An unknown version counts as older."""
    m = re.match(r"\s*(\d{4})\.(\d{1,2})\.(\d{1,3})", str(version or ""))
    return bool(m) and tuple(int(g) for g in m.groups()) >= (2026, 10, 10)


# Tail length that anchors a cumulative text with a hole in it. Long enough
# that a match is never a coincidence of a short phrase.
_WHOLE_TEXT_ANCHOR_CHARS = 200
_MIN_WHOLE_TEXT_ANCHOR_CHARS = 64
_LINE_BREAKS_RE = re.compile(r"\n+")


def _one_break(text: str) -> str:
    """Collapse line-break runs: a claude-cli closer joins messages with one
    newline where the stream used two (ELI-219)."""
    return _LINE_BREAKS_RE.sub("\n", text)


def _item_delta_text(item_text: str, last_item_text: str, assistant_stream_text: str) -> str:
    """The new text an `item` event adds beyond what was already shown. Some
    items echo the complete final text, which must not be shown twice."""
    baseline = last_item_text or assistant_stream_text
    if not baseline:
        return item_text
    if item_text == baseline:
        return ""
    if item_text.startswith(baseline):
        return item_text[len(baseline):]
    if _one_break(item_text) == _one_break(baseline):
        return ""
    if last_item_text and item_text.endswith("\n" + last_item_text):
        # A claude-cli closer ending with the item already shown (ELI-219);
        # that item can be too short for the anchors below.
        return ""
    # Cumulative text with a hole (events lost in a reconnect): only what
    # follows the known tail is new. The hole is filled by the transcript
    # rebuild (ELI-147). Shorter anchors too: the hole may sit in the longest.
    for n in (_WHOLE_TEXT_ANCHOR_CHARS, 128, _MIN_WHOLE_TEXT_ANCHOR_CHARS):
        anchor = baseline[-n:]
        if len(anchor) < _MIN_WHOLE_TEXT_ANCHOR_CHARS:
            break
        pos = item_text.rfind(anchor)
        if pos >= 0:
            return item_text[pos + len(anchor):]
    return item_text


def _suppress_already_shown(delta: str, visible_message_text: str) -> str:
    """Safety net: drop `delta` if it is already the tail of the visible text.
    `_item_delta_text`'s baseline can drift from `visible_message_text`."""
    if delta and visible_message_text.endswith(delta):
        return ""
    return delta


def _attr(value: str) -> str:
    """Escape a tool card HTML attribute value. Newlines become `&#10;`: OWUI
    parses these attributes with a non-dotAll regex and silently drops a
    value containing a literal newline."""
    return (
        html.escape(value)
        .replace("\r\n", "&#10;")
        .replace("\n", "&#10;")
        .replace("\r", "&#10;")
    )


# `output_index` past the end of Open WebUI's output list. Without one the
# chat tab splices the item in before the last one (ELI-122).
_OUTPUT_APPEND_INDEX = 1 << 30


def _tool_call_started_event(name: str, tool_call_id: str, args_str: str) -> dict:
    """Announce a tool call as a Responses-API output item (live spinner).

    A yielded `response.*` dict lands in OWUI's backend output list, so the
    card stays mutable, unlike yielded markdown. The id goes in `id` and
    `call_id` is deliberately absent: OWUI replaces an added item sharing
    either with one it holds, so the matching `function_call_output` would
    replace this item. Consumers read `call_id or id`.
    """
    return {
        "type": "response.output_item.added",
        "output_index": _OUTPUT_APPEND_INDEX,
        "item": {
            "type": "function_call",
            "id": tool_call_id,
            "name": name,
            "arguments": args_str[:3000],
            "status": "in_progress",
        },
    }


# A Pipe note in a reply (ELI-197), carried as a run event of this made-up
# stream so the live reply and a turn writer render it alike. Its id is
# stable per note, so the same note again replaces it.
PIPE_NOTE_STREAM = "pipe_note"
_NOTE_ITEM_PREFIX = "msg_note_"
# A tool result's takeover link (CONTROL_LINK_PATTERN), as a note (ELI-318).
CONTROL_LINK_NOTE = ("**[Take control ↗]({link})**: the agent is waiting for you to do a step in "
                     "its browser. It opens in a new tab; press End there when you are done.")

# The Gateway's context compaction as a reply note (ELI-283). A size shows
# only when the Gateway sends `tokensBefore`; the session's `totalTokens` is
# stale by then and no stand-in.
COMPACTION_STREAM = "compaction"
COMPACTING_NOTE = "🧹 _Compacting context…_"
COMPACTION_FAILED_NOTE = "🧹 _Context compaction did not complete: the conversation goes on uncompacted._"
COMPACTION_SKIPPED_NOTE = "🧹 _Context compaction skipped: nothing to compact yet._"
COMPACTION_STOPPED_NOTE = "🧹 _Context compaction stopped._"
COMPACTED_BODY = ("Older messages in this conversation were summarized to free up the model's "
                  "context. The agent continues from that summary plus the most recent messages; "
                  "everything stays visible here.")


def _compacted_note(tokens_before) -> str:
    was = f" · was ~{_fmt_tokens(tokens_before)} tokens" if isinstance(tokens_before, int) \
        and tokens_before > 0 else ""
    return (f"<details>\n<summary>🧹 Context compacted{was}</summary>\n\n"
            f"{COMPACTED_BODY}\n</details>")


def _tool_call_result_event(tool_call_id: str, result_str: str) -> dict:
    """Complete a tool call announced by `_tool_call_started_event`. This item
    keeps `call_id`; see the started event for why that one does not."""
    return {
        "type": "response.output_item.added",
        "output_index": _OUTPUT_APPEND_INDEX,
        "item": {
            "type": "function_call_output",
            "id": f"fco_{tool_call_id}",
            "call_id": tool_call_id,
            "output": [{"type": "output_text", "text": result_str[:8000]}],
            "status": "completed",
        },
    }


def _tool_result_text(result) -> str:
    """The text a tool card shows for a tool event's `result`. An envelope's
    `details` is metadata, not output, and is left out (ELI-121)."""
    if isinstance(result, str):
        return result
    blocks = result.get("content") if isinstance(result, dict) else result
    if not isinstance(blocks, list):
        return json.dumps(result)
    lines = []
    for block in blocks:
        kind = block.get("type") if isinstance(block, dict) else None
        if kind == "text" and isinstance(block.get("text"), str):
            lines.append(block["text"])
        elif kind == "image":
            lines.append(f"[{block.get('mimeType') or 'an'} image]")
        else:
            lines.append(block if isinstance(block, str) else json.dumps(block))
    return "\n".join(lines)


TOOL_ERROR_MARK = "❌"
# What a call the run ended without answering shows as its output.
TOOL_NO_RESULT_NOTE = "(no result -- the run ended first)"

# A sub-agent title fits one phone line; the Status Action uses it too (ELI-155).
SUBAGENT_TITLE_MAX = 60
_FIRST_SENTENCE_RE = re.compile(r"(?<=[.!?])\s|\n")
# How much of a sub-agent's task its spawn card shows as input.
SPAWN_TASK_LINES = 3
SPAWN_TASK_CHARS = 300


def _short_title(text: str) -> str:
    """The first sentence of `text`, cut on a word to SUBAGENT_TITLE_MAX."""
    first = _FIRST_SENTENCE_RE.split(text.strip(), 1)[0].strip()
    if len(first) <= SUBAGENT_TITLE_MAX:
        return first
    cut = first[:SUBAGENT_TITLE_MAX - 1]
    space = cut.rfind(" ")
    if space >= SUBAGENT_TITLE_MAX // 2:
        cut = cut[:space]
    return cut.rstrip(" ,;:(") + "…"


def _is_spawn_tool(name: str) -> bool:
    """`sessions_spawn`, bare or as a claude-cli MCP tool name."""
    return name == "sessions_spawn" or (name.startswith("mcp__")
                                        and name.endswith("__sessions_spawn"))


def _json_object(text: str) -> dict:
    try:
        value = json.loads(text)
    except (TypeError, ValueError):
        return {}
    return value if isinstance(value, dict) else {}


def _spawn_title(args: dict) -> str:
    """A sub-agent's name: its spawn label, else its task's first sentence."""
    task = str(args.get("task") or "").strip()
    return str(args.get("label") or "").strip() or (_short_title(task) if task else "Sub-agent")


def _spawn_task_head(task: str) -> str:
    """The first SPAWN_TASK_LINES lines of a task, at most SPAWN_TASK_CHARS."""
    lines = [line for line in task.strip().splitlines() if line.strip()]
    head = "\n".join(lines[:SPAWN_TASK_LINES])
    if len(head) > SPAWN_TASK_CHARS:
        head = head[:SPAWN_TASK_CHARS - 1].rsplit(" ", 1)[0].rstrip(" ,;:(") + "…"
    elif len(lines) > SPAWN_TASK_LINES:
        head += "\n…"
    return head


# Deferred-tool wrappers: `tool_call` on OpenClaw 2026.10.1-10.4,
# `dispatch_action` from 10.10. The target is also reported as a nested call.
DEFERRED_CALL_TOOLS = ("dispatch_action", "tool_call")


def _is_nested_tool_call(data: dict, known: "set | dict") -> bool:
    """A deferred-tool wrapper's target call. It gets no card of its own."""
    if data.get("parentToolCallId"):
        return True
    tcid = str(data.get("toolCallId") or "")
    parts = tcid.split(":")
    return len(parts) > 2 and parts[0] == "tool_call" and parts[1] in known


OPENCLAW_MCP_PREFIX = "mcp__openclaw__"


def _bare_tool_name(name: str) -> str:
    """Strip `mcp__openclaw__`: live events drop it but claude-cli's imported
    transcript keeps it, so rebuilt cards would be titled differently."""
    return name[len(OPENCLAW_MCP_PREFIX):] if name.startswith(OPENCLAW_MCP_PREFIX) else name


def _deferred_call_view(name: str, args_str: str) -> tuple[str, str] | None:
    """A deferred-tool wrapper call as (target name, target args), else None."""
    if _bare_tool_name(name) not in DEFERRED_CALL_TOOLS:
        return None
    args = _json_object(args_str)
    target = args.get("id") if isinstance(args.get("id"), str) else args.get("name")
    if not isinstance(target, str) or not target.strip():
        return None
    inner = args.get("args")
    if not isinstance(inner, dict):  # a flattened call: the target's arguments beside `id`
        inner = {k: v for k, v in args.items() if k not in ("id", "name")}
    return target.strip().rsplit(":", 1)[-1], json.dumps(inner)


def _deferred_call_result_text(result_str: str) -> str:
    """The target's result inside a wrapper's envelope, else the text as is."""
    envelope = _json_object(result_str)
    if not isinstance(envelope.get("tool"), dict) or "result" not in envelope:
        return result_str
    return _tool_result_text(envelope["result"])


def _tool_card_view(name: str, args_str: str) -> tuple[str, str]:
    """A tool card's title and input. A spawn card shows the sub-agent's
    title and its task's head (ELI-155)."""
    name = _bare_tool_name(name)
    if not _is_spawn_tool(name):
        return name, args_str
    args = _json_object(args_str)
    task = str(args.get("task") or "")
    return f"🤖 {_spawn_title(args)}", json.dumps({"task": _spawn_task_head(task)} if task.strip() else {})


def _spawn_result_view(args_str: str, result_str: str) -> tuple[str, bool]:
    """A spawn's JSON receipt as one line, and whether the spawn failed."""
    receipt = _json_object(result_str)
    status = receipt.get("status")
    if not isinstance(status, str):
        return result_str, False
    if status == "accepted":
        return f"Started: {_spawn_title(_json_object(args_str))}", False
    error = str(receipt.get("error") or "").strip()
    return f"Not started ({status})" + (f": {error}" if error else ""), True


def _spawned_child(payload: dict):
    """(parent key, child key, run id or None) of an accepted spawn's result
    event, else None. A deferred wrapper's envelope is read too."""
    data = payload.get("data") or {}
    if payload.get("stream") != "tool" or data.get("phase") != "result" or data.get("isError") is True:
        return None
    parent = payload.get("sessionKey")
    text = _tool_result_text(data.get("result", {}))
    name = _bare_tool_name(data.get("name") or "")
    if _is_spawn_tool(name):
        receipt = _json_object(text)
    elif name in DEFERRED_CALL_TOOLS:
        receipt = _json_object(_deferred_call_result_text(text))
    else:
        return None
    child = receipt.get("childSessionKey")
    if receipt.get("status") != "accepted" or not isinstance(child, str) or not child or not parent:
        return None
    run_id = receipt.get("runId")
    return parent, child, run_id if isinstance(run_id, str) and run_id else None


def _spawn_call_args(payload: dict) -> dict | None:
    """A spawn call's arguments from its start event (wrapped or not), else None."""
    data = payload.get("data") or {}
    if payload.get("stream") != "tool" or data.get("phase") != "start":
        return None
    name, args_str = _bare_tool_name(data.get("name") or ""), json.dumps(data.get("args") or {})
    view = _deferred_call_view(name, args_str)
    if view:
        name, args_str = view
    return _json_object(args_str) if _is_spawn_tool(name) else None


def _tool_call_error_relabel_event(name: str, tool_call_id: str, args_str: str) -> dict:
    """Re-announce a failed call's item with status "failed" and ❌ in its name.

    OWUI draws the red X only for status "failed" (ELI-278). Re-sending the
    start event with the same id replaces the item in both OWUI reducers, so
    it works live on any card; `response.name.done` does not (ELI-124).
    """
    event = _tool_call_started_event(f"{name} {TOOL_ERROR_MARK}", tool_call_id, args_str)
    event["item"]["status"] = "failed"
    return event


def _tool_error_banner(result_str: str) -> str:
    """Prefix a failed tool's Output with an explicit failure line."""
    return f"{TOOL_ERROR_MARK} tool call failed\n\n{result_str}"


def _render_tool_result_block(name: str, tool_call_id: str, args_str: str,
                              result_str: str, meta) -> str:
    """Render a finished tool call as OWUI's markdown `tool_calls` card, for
    paths with no live protocol channel."""
    return (
        '\n<details type="tool_calls" done="true" '
        f'id="{_attr(tool_call_id)}" '
        f'name="{_attr(name)}" '
        f'arguments="{_attr(args_str[:3000])}" '
        f'result="{_attr(result_str[:8000])}" '
        f'meta="{_attr(str(meta)[:500])}" '
        'files="[]" embeds="[]">'
        f'\n<summary>{html.escape(name)}</summary>\n</details>\n'
    )


class _TurnRenderer:
    """Rebuild a run's visible content (text, tool cards, Pipe notes) from its
    Gateway events, as the inline reply renders it. The turn writer uses it to
    finish a message whose inline reply ended early (ELI-100). It holds raw
    run text; MEDIA and ask-user rewrites come from `note_turn_rewrite`.
    """

    def __init__(self):
        self.visible_text = ""
        # As OWUI 0.12 stores a reply: `text` is `content`, `output` the
        # Responses items. A card baked into `content` is no card (ELI-92).
        self.text = ""
        self.output: list[dict] = []
        self._assistant_stream_text = ""
        # A steered message's answer is a new `itemId` in the same run.
        self._assistant_item_id: str | None = None
        self._last_item_text = ""
        self._active_tool_args: dict[str, str] = {}
        # A result may carry no tool name (claude-cli's `tool_result`).
        self._active_tool_names: dict[str, str] = {}
        self._tool_items: dict[str, dict] = {}
        self._tool_results: set[str] = set()
        # A new run continuing the message needs the message break; the
        # Gateway only inserts it inside one run.
        self.run_boundary = False
        # A possible silent sentinel at a message start (`_add_text`).
        self._held = ""
        # The run's reply was a silent sentinel alone, not lost text.
        self.silenced = False
        self._compactions = 0
        self._compaction_note_id: str | None = None
        self._compaction_before = None

    @property
    def received(self) -> str:
        """All the run text that arrived, shown or not: the dedup baseline."""
        return self._assistant_stream_text

    @property
    def last_item(self) -> str:
        """The last item event's text, the baseline for the next one."""
        return self._last_item_text

    def seed(self, run_text: dict | None) -> None:
        """Take another reply's dedup baselines for the run it showed."""
        if run_text:
            self._assistant_stream_text = run_text.get("received", "")
            self._last_item_text = run_text.get("item", "")

    def drop_shown(self, shown: str) -> bool:
        """Drop the leading `shown` part another message already holds
        (ELI-147). False, changing nothing, if the text doesn't start with it."""
        if not self.text.startswith(shown):
            return False
        cut, pos, kept = len(shown), 0, []
        for item in self.output:
            if item.get("type") == "message":
                text = item["content"][0]["text"]
                start, pos = pos, pos + len(text)
                if pos <= cut:
                    continue
                if start < cut:
                    item = copy.deepcopy(item)
                    item["content"][0]["text"] = text[cut - start:]
            elif pos < cut:
                continue
            kept.append(item)
        self.output, self.text = kept, self.text[cut:]
        self.visible_text = self.text
        return True

    def _mark_new_reply(self, item_id) -> None:
        """A new `itemId` after a message starts a second reply in the run,
        which needs a break or the two run together (ELI-271). Notes are
        looked past."""
        if not isinstance(item_id, str) or not item_id:
            return
        previous, self._assistant_item_id = self._assistant_item_id, item_id
        last = next((i for i in reversed(self.output)
                     if not str(i.get("id", "")).startswith(_NOTE_ITEM_PREFIX)), None)
        if previous and previous != item_id and last is not None and last.get("type") == "message":
            self.run_boundary = True

    def _add(self, chunk: str) -> None:
        if chunk:
            self.visible_text += chunk

    def _add_text(self, chunk: str) -> str:
        """Append `chunk`; returns it as added. A leading silent sentinel is
        held: followed by more text it is dropped (ELI-219), alone it stays out
        (`flush`)."""
        if not chunk:
            return ""
        last = self.output[-1] if self.output else None
        if last is None or last.get("type") != "message" or not last["content"][0]["text"]:
            pending = self._held + chunk
            lead = pending.lstrip()
            if any(s.startswith(lead) for s in _SILENT_SENTINELS):
                self._held = pending
                return ""
            self._held = ""
            for s in _SILENT_SENTINELS:
                if lead.startswith(s) and lead[len(s):len(s) + 1].isspace():
                    pipe_log(f"  dropped a leading {s} before the run's text")
                    pending = lead[len(s):].lstrip()
                    break
            chunk = pending
        return self._append_text(chunk)

    def flush(self) -> str:
        """Release held text unless it is a sentinel; returns it as added."""
        held, self._held = self._held, ""
        if held.strip() in _SILENT_SENTINELS:
            self.silenced = True
        if not held.strip() or held.strip() in _SILENT_SENTINELS:
            return ""
        return self._append_text(held)

    def _append_text(self, chunk: str) -> str:
        if not chunk:
            return ""
        if self.run_boundary:
            self.run_boundary = False
            chunk = _message_boundary_separator(self.text, chunk) + chunk
        self._add(chunk)
        self.text += chunk
        last = self.output[-1] if self.output else None
        if (last is None or last.get("type") != "message"
                or str(last.get("id", "")).startswith(_NOTE_ITEM_PREFIX)):
            last = {
                "type": "message",
                "id": f"msg_{uuid.uuid4().hex[:24]}",
                "status": "in_progress",
                "role": "assistant",
                "content": [{"type": "output_text", "text": ""}],
            }
            self.output.append(last)
        last["content"][0]["text"] += chunk
        return chunk

    def _compaction_note(self, run_id: str, data: dict) -> dict | None:
        """The note a compaction event makes; its end replaces its start. The
        id is deterministic so every renderer of the run names it alike."""
        phase = data.get("phase")
        if phase not in ("start", "end"):
            return None
        nid = self._compaction_note_id
        if nid is None:
            self._compactions += 1
            tag = hashlib.sha1(run_id.encode()).hexdigest()[:8]
            nid = f"{_NOTE_ITEM_PREFIX}compaction_{tag}_{self._compactions}"
            self._compaction_before = None
        if phase == "start":
            self._compaction_note_id = nid
            self._compaction_before = data.get("tokensBefore")
            return {"id": nid, "text": COMPACTING_NOTE}
        self._compaction_note_id = None
        if data.get("completed") is True:
            return {"id": nid, "text": _compacted_note(self._compaction_before)}
        return {"id": nid, "text": {"skipped": COMPACTION_SKIPPED_NOTE,
                                    "aborted": COMPACTION_STOPPED_NOTE}.get(data.get("outcome"),
                                                                           COMPACTION_FAILED_NOTE)}

    def _tool_item(self, name: str, tcid: str, args_str: str, events: list) -> dict:
        """The call's card, opened on first sight (start or result)."""
        item = self._tool_items.get(tcid)
        if item is None:
            event = _tool_call_started_event(name, tcid, args_str)
            item = copy.deepcopy(event["item"])
            self._tool_items[tcid] = item
            self.output.append(item)
            events.append(event)
        return item

    def _unanswered(self, note: str) -> list[dict]:
        """A result event for every call with no result yet, saying `note`."""
        return [_tool_call_result_event(tcid, note) for tcid in self._tool_items
                if tcid not in self._tool_results]

    def close_open_calls(self, note: str) -> list[dict]:
        """Answer every open call with `note`. OWUI would execute an unanswered
        streamed `function_call` itself, and stored it spins forever."""
        events = self._unanswered(note)
        for event in events:
            self._tool_results.add(event["item"]["call_id"])
            self.output.append(copy.deepcopy(event["item"]))
        return events

    def finished_output(self) -> list[dict]:
        """`output` as stored after the run: open calls closed, items completed."""
        out = copy.deepcopy(self.output)
        out += [e["item"] for e in self._unanswered(TOOL_NO_RESULT_NOTE)]
        for item in out:
            if item.get("status") == "in_progress":
                item["status"] = "completed"
        return out

    def feed(self, payload: dict) -> list:
        """Feed one event. Returns what it added for a live stream: text (str)
        and Responses card events, so inline and writer match (ELI-147)."""
        events: list = []
        data = payload.get("data", {}) or {}
        stream = payload.get("stream")
        name = data.get("name", "")
        phase = data.get("phase", "")
        if stream == "assistant":
            raw_delta = data.get("delta")
            if raw_delta:
                delta = raw_delta
            else:
                raw_text = data.get("text") or ""
                delta = (
                    _item_delta_text(raw_text, "", self._assistant_stream_text)
                    if raw_text else ""
                )
                if raw_text and not delta:
                    pipe_log("  suppressed duplicate catch-all assistant text")
                delta = _suppress_already_shown(delta, self.visible_text)
            if delta:
                if (
                    "Sender (untrusted metadata)" in delta
                    or "UnTrustedMetadata" in delta
                ):
                    pipe_log("  filtered metadata block")
                    return events
                self._assistant_stream_text += delta
                self._mark_new_reply(data.get("itemId"))
                events.append(self._add_text(delta))

        if stream == "item":
            item_text = _item_assistant_text(data)
            if item_text:
                item_delta = _item_delta_text(
                    item_text, self._last_item_text, self._assistant_stream_text
                )
                self._last_item_text = item_text
                item_delta = _suppress_already_shown(item_delta, self.visible_text)
                if item_delta:
                    events.append(self._add_text(item_delta))

        if stream == COMPACTION_STREAM:
            note = self._compaction_note(payload.get("runId") or "", data)
            if note is None:
                return events
            events.append(self.flush())
            stream, data = PIPE_NOTE_STREAM, note

        if stream == PIPE_NOTE_STREAM:
            nid, text = data.get("id"), data.get("text")
            if nid and text:
                item = {"type": "message", "id": nid, "status": "completed", "role": "assistant",
                        "content": [{"type": "output_text", "text": text}]}
                at = next((n for n, i in enumerate(self.output) if i.get("id") == nid), None)
                if at is None:
                    self.output.append(item)
                else:
                    self.output[at] = item
                events.append({"type": "response.output_item.added",
                               "output_index": _OUTPUT_APPEND_INDEX, "item": copy.deepcopy(item)})
            return events

        if stream == "tool":
            tcid = data.get("toolCallId", "")
            if _is_nested_tool_call(data, self._active_tool_names.keys() | self._tool_results):
                return events
            if phase == "start":
                if tcid:
                    events.append(self.flush())
                    args_str = json.dumps(data.get("args", {}))
                    self._active_tool_args[tcid] = args_str
                    self._active_tool_names[tcid] = name
                    card_name, card_args = _tool_card_view(*(_deferred_call_view(name, args_str)
                                                             or (name, args_str)))
                    self._tool_item(card_name, tcid, card_args, events)
            elif phase == "result":
                if tcid and tcid in self._tool_results:
                    return events
                result = data.get("result", {})
                result_str = _tool_result_text(result)
                args_str = self._active_tool_args.pop(tcid, None) or json.dumps(
                    data.get("args", {})
                )
                name = self._active_tool_names.pop(tcid, None) or name
                deferred = _deferred_call_view(name, args_str)
                if deferred:
                    name, args_str = deferred
                    result_str = _deferred_call_result_text(result_str)
                failed = data.get("isError") is True
                if _is_spawn_tool(name) and not failed:
                    result_str, failed = _spawn_result_view(args_str, result_str)
                card_name, card_args = _tool_card_view(name, args_str)
                self._add(_render_tool_result_block(
                    card_name, tcid, card_args, result_str, data.get("meta", "")
                ))
                if tcid:
                    self._tool_results.add(tcid)
                    item = self._tool_item(card_name, tcid, card_args, events)
                    item["status"] = "failed" if failed else "completed"
                    if failed:
                        item["name"] = f"{card_name} {TOOL_ERROR_MARK}"
                        events.append(_tool_call_error_relabel_event(card_name, tcid, card_args))
                        result_str = _tool_error_banner(result_str)
                    event = _tool_call_result_event(tcid, result_str)
                    self.output.append(copy.deepcopy(event["item"]))
                    events.append(event)
        return events


# ---------------------------------------------------------------------------
# Persistent Gateway Connection (singleton)
# ---------------------------------------------------------------------------

# State shared by every `_GatewayConnection` in the process. A redeploy execs
# a new module with no teardown of the old one, so the bookkeeping lives on
# OWUI's stable `open_webui.socket.main` module.
_SHARED_STATE_ATTR = "_openclaw_gateway_shared_state_v1"


def _shared_gateway_state() -> dict | None:
    """The process-global bookkeeping dicts, or None outside OWUI (tests)."""
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return None
    state = getattr(_owui_socket_main, _SHARED_STATE_ATTR, None)
    if state is None:
        state = {}
        setattr(_owui_socket_main, _SHARED_STATE_ATTR, state)
    # Per key: the dict outlives redeploys, so new keys must be backfilled.
    state.setdefault("delivered_live", {})
    state.setdefault("claimed_runs", {})
    state.setdefault("chat_write_locks", {})
    state.setdefault("turn_rewrites", {})
    return state


# Streaming replies for the Status Action (ELI-186): {(chat_id, message_id):
# _TurnRenderer}. OWUI saves tool cards only at the reply's end. Lives on
# OWUI's stable module so the separate Action module sees it.
_LIVE_REPLIES_ATTR = "_openclaw_live_replies_v1"
_live_replies_local: dict = {}


def _live_replies() -> dict:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return _live_replies_local
    replies = getattr(_owui_socket_main, _LIVE_REPLIES_ATTR, None)
    if replies is None:
        replies = {}
        setattr(_owui_socket_main, _LIVE_REPLIES_ATTR, replies)
    return replies


def _live_reply_output(chat_id, message_id):
    """A copy of a running reply's output so far, or None."""
    renderer = _live_replies().get((chat_id, message_id))
    output = getattr(renderer, "output", None)
    return copy.deepcopy(output) if isinstance(output, list) else None


class _RunQueue(asyncio.Queue):
    """A run's bounded event queue: a slow reader applies backpressure
    instead of losing text. Control markers bypass the bound, since the
    receive loop must never wait or raise on them."""

    def put_control(self, item) -> None:
        bound, self._maxsize = self._maxsize, 0
        try:
            self.put_nowait(item)
        finally:
            self._maxsize = bound

    def take_all(self) -> list:
        """Everything queued now, in order, without waiting."""
        items = []
        while not self.empty():
            items.append(self.get_nowait())
        return items


def _feeds_writer(consumer: "_Consumer") -> bool:
    """`consumer`'s queues go to a turn writer's pump (`_WriterQueue`)."""
    return bool(consumer.queues) and all(isinstance(q, _WriterQueue) for q in consumer.queues)


def _pump_baselines(pump) -> dict | None:
    """Dedup baselines of a writer pump's run, counting unwritten events."""
    writer = pump.writer
    renderer = writer.renderer if writer is not None else (pump.handover or {}).get("renderer")
    if not isinstance(renderer, _TurnRenderer):
        return None
    shadow = copy.deepcopy(renderer)
    for kind, item in list(pump.queue._queue):
        if kind == _PUMP_EVENT and item:
            shadow.feed(item)
    return {"received": shadow.received, "stream": shadow.received, "item": shadow.last_item}


class _WriterQueue(_RunQueue):
    """Forwards a run's events into a turn writer's pump when the writer owns
    the steered message's reply. Other markers stay here; the writer ends
    from the transcript at the settle."""

    def __init__(self, pump):
        super().__init__()
        self.pump = pump

    def put_nowait(self, item) -> None:
        if not isinstance(item, dict):
            return
        if item.get("_steered"):
            self.pump.queue.put_nowait((_PUMP_STEERED_IN, item["_steered"]))
        elif item.get("type") == _PUMP_EVENT:
            self.pump.queue.put_nowait((_PUMP_EVENT, item.get("payload") or {}))


# Open WebUI's uvicorn Server, kept while it serves (see `owui_shutting_down`).
_UVICORN_SERVER = None


def remember_owui_server() -> None:
    """Keep a reference to the uvicorn Server running Open WebUI. Taken early
    from the SIGTERM handler: uvicorn restores old handlers before cancelling
    tasks."""
    global _UVICORN_SERVER
    if _UVICORN_SERVER is not None:
        return
    try:
        server = getattr(signal.getsignal(signal.SIGTERM), "__self__", None)
    except (ValueError, TypeError):
        return
    if server is not None and hasattr(server, "should_exit"):
        _UVICORN_SERVER = server


def owui_shutting_down() -> bool:
    """True once Open WebUI got SIGTERM/SIGINT. Shutdown cancels replies like
    a Stop does, so this tells them apart (ELI-94)."""
    remember_owui_server()
    return bool(getattr(_UVICORN_SERVER, "should_exit", False))


remember_owui_server()


@dataclass
class _Consumer:
    """An active run consumer; its queues receive the run's events."""
    session_key: str
    run_id: str
    queues: list[asyncio.Queue] = field(default_factory=list)
    # Sent more than a lone `chat` final, so it was not steered elsewhere.
    started: bool = False
    ended: bool = False
    # Its message was steered into run `steered_into`; its own events are
    # dropped. Tracked since a socket drop can lose its lone final.
    steered: bool = False
    steered_into: str = ""
    # Writer pumps that showed this run before a steer took it (`_turn_next_run`).
    held: list = field(default_factory=list)


# Hooks the Pipe build registers; all None in the Status Action build, whose
# connection only makes requests (ELI-149).
# Turn writer entry points (writer.py's `_TurnHooks`).
_TURNS = None
# `question.*` handlers (askuser.py, ELI-96). Only the live turn-writing
# connection asks, so a question is asked once; `question.resolved` also
# reaches a retired one so pre-deploy questions still get cancelled.
_QUESTION_HOOKS = None
# `chat.metadata.changed` handler (slash_prompts.py).
_SLASH_PROMPTS_HOOK = None
# `plugin.approval.*` handlers (approvals.py), gated like `_QUESTION_HOOKS`.
_APPROVAL_HOOKS = None
PLUGIN_APPROVAL_CAP = "plugin-approvals"


class _GatewayConnection:
    """Persistent WebSocket connection to the Gateway: dispatches events to
    per-run queues and reconnects with backoff."""

    # Every connect names the device (`_display_name`). A build without this
    # flag connects nameless, which wipes the name the Gateway stored (a
    # nameless silent record can be pruned); `_retire_stale_connection` keeps
    # such a build from reconnecting.
    sends_display_name = True

    def __init__(self, valves_ref, writes_turns: bool = True, scopes: list | None = None,
                 identity_name: str = "identity", requests_only: bool = False,
                 display_name: str = MAIN_DISPLAY_NAME):
        self._valves = valves_ref
        # A RESTRICTED_SCOPES connection has its own device identity and only
        # sends requests (no subscriptions); see `_run_request`.
        self.scopes = list(GATEWAY_SCOPES if scopes is None else scopes)
        self._identity_name = identity_name
        self.requests_only = requests_only
        self._display_name = display_name
        self._ws: websockets.WebSocketClientProtocol | None = None
        # Last opened endpoint. A connection replaced by a valve change keeps
        # dialling its old one (`_pinned_endpoint`).
        self._endpoint: tuple[str, int, bool] | None = None
        self._pinned_endpoint: tuple[str, int, bool] | None = None
        self._event_loop_task: asyncio.Task | None = None
        self._init_lock = asyncio.Lock()

        self._ident: dict | None = None
        self._device_token: str | None = None

        self._pending_reqs: dict[str, asyncio.Future] = {}

        # Keyed by f"{session_key}:{run_id}".
        self._consumers: dict[str, _Consumer] = {}

        # `session_send_lock` (ELI-56).
        self._session_send_locks: dict[str, asyncio.Lock] = {}
        # A retired connection stays up for open send sections: closing it
        # would leave a waiter with no settle push (ELI-172).
        self._open_send_sections = 0
        # Per session, replies in `send_section` that may combine with a later
        # message, oldest first.
        self._send_waiters: dict[str, list] = {}

        # Parked cancelled turns (`park_cancelled_turn`). An immediate
        # chat.abort would also kill every subagent the turn spawned.
        self._pending_cancel_aborts: dict[str, dict] = {}

        # {session_key: (model, ts)} and `model_patch_lock`s (ELI-59), per worker.
        self._model_patch_cache: dict[str, tuple[str | None, float]] = {}
        self._model_patch_locks: dict[str, asyncio.Lock] = {}

        # Last thinking-clamp note per session, so it is shown once.
        self._thinking_note_shown: dict[str, str] = {}

        self._reconnect_attempt = 0
        self._max_backoff = 30  # seconds
        # A turn asks the event loop to reconnect now and awaits the outcome;
        # the loop is the socket's only reader (ELI-176).
        self._reconnect_now = asyncio.Event()
        self._reconnect_waiters: list = []
        # While turns wait on a refusing Gateway, retry at the first backoff step.
        self._turns_awaiting_gateway = 0
        # hello-ok's `policy.tickIntervalMs`; like the Gateway's own client,
        # drop a socket silent for twice that.
        self._tick_interval_s = 30.0
        self._stopped = False
        # A newer deploy took over (`retire()`): serve existing runs only,
        # write no turns, never reconnect once they end.
        self._retired = False
        # A message whose writer is gone can be taken over (DESIGN 2.3).
        self.writer_id = turn_writer_id()
        self.writes_turns = writes_turns and _TURNS is not None
        self._turn_pumps: dict = {}     # (session_key, run_id) -> _RunPump
        self._turn_writers: dict = {}   # (chat_id, message_id) -> _TurnWriter
        self._turn_skip_runs: dict = {}  # (session_key, run_id) of heartbeat runs
        # Agent-run events not yet known to be no heartbeat (`_turn_kind_known`).
        self._turn_unkinded: dict = {}
        self._turn_kinded: dict = {}
        # (child session, child run) -> a sub-agent's result
        self._child_results: dict = {}
        # session_key -> run id of a message-less inline reply awaiting its
        # interrupted run's owner
        self._awaiting_owner: dict = {}
        self._session_ids: dict = {}     # session_key -> sessionId (a cron wake's run id)
        self._wake_turns_bound: dict = {}  # session_key -> wake turn keys given a message
        # session_key -> [{job, start, end}] cron runs heard (`note_cron_event`)
        self._cron_runs: dict = {}
        self._turn_resolve_lock = asyncio.Lock()
        self._frame_seq: int | None = None
        self._stop_notice_seen = False  # `shutdown` without restartExpectedMs on this socket
        self._shutdown_seen = False     # any `shutdown` on this socket
        # Bumped on every connect.
        self.connection_epoch = 0
        # A reconnect is not a restart: `hello-ok.server.bootId` names the
        # Gateway process, and only a new one means its runs are gone.
        # Counting reconnects would send bogus resume turns.
        self.gateway_boot_id: str | None = None
        self.gateway_restarts = 0
        self.gateway_version: str | None = None   # hello-ok.server.version
        # hello-ok.policy.attachments.maxImageBytes: chat.send refuses an
        # image bigger than this (decoded bytes), so bigger ones are shrunk.
        self.gateway_max_image_bytes = GATEWAY_IMAGE_BYTES_FALLBACK
        # hello-ok.features, checked instead of version numbers.
        self.gateway_methods: frozenset = frozenset()
        self.gateway_events: frozenset = frozenset()

        self._next_req_id = 1

        # Inside OWUI these dicts are shared by every connection in the
        # process (`_shared_gateway_state`); in tests each gets its own.
        _shared = _shared_gateway_state()

        # Stubs the startup reconcile finished, so none is finalized twice.
        self._claimed_runs: dict[str, bool] = (
            _shared["claimed_runs"] if _shared is not None else {}
        )

        # `_delivered_live`: "session_key:run_id" of finals shown to a live
        # tab. A retried final is caught by identity, never by text.
        # `_held_for_live`: events of a continuing run that arrived before
        # its still-streaming reply registered; never a turn writer's.
        self._held_for_live: dict[tuple[str, str], list] = {}
        self.unreachable_held_drains = 0
        self._delivered_live: dict[str, float] = (
            _shared["delivered_live"] if _shared is not None else {}
        )

        # Model and thinking level of each session's last send (`steers_into_active_run`).
        self.sent_settings: dict[str, tuple] = {}
        # "<session>:<run>" -> "aborted" / "error" for a run that ended without an answer.
        self.runs_failed: dict[str, str] = {}

        # Per-chat locks for non-writer read-modify-write paths (stub reconcile).
        self._chat_write_locks: dict[str, asyncio.Lock] = (
            _shared["chat_write_locks"] if _shared is not None else {}
        )

        # For a run a live pipe() renders into a known message: its target
        # (chat_id, message_id) and a shadow `_TurnRenderer`, so a turn writer
        # can finish the same message if the inline turn ends first
        # (DESIGN 2.6). Instance-local: a zombie never registers a target.
        self._run_targets: dict[str, dict] = {}
        self._run_renderers: dict[str, "_TurnRenderer"] = {}
        # `note_reply_sent` (ELI-82), by "session_key:message_id".
        self._sent_replies: dict[str, dict] = {}
        # "chat_id:message_id" -> [(raw, shown)] MEDIA and ask-user rewrites
        # the inline reply made; a takeover writer repeats them. Shared across
        # deploys.
        self._turn_rewrites: dict[str, list] = (
            _shared["turn_rewrites"] if _shared is not None else {}
        )

        # Transcript subscriptions, renewed after each connect. A tool event
        # can arrive twice (initiator and subscriber); `_tool_events_seen`
        # keeps the first.
        self._message_subscriptions: set[str] = set()
        # Runs active at the last subscribe (DESIGN 2.1), whose start push
        # this socket never got. An empty list means "active, ids not given":
        # the Gateway omits activeRunIds for claude-cli runs.
        self.active_run_snapshot: dict[str, list[str]] = {}
        self._subscriptions_stale = False
        # Waiter Events per session: `sessions.changed` (ELI-88), transcript
        # appends (ELI-164), and child session changes (ELI-260).
        self._session_change_waiters: dict[str, asyncio.Event] = {}
        self._session_message_waiters: dict[str, asyncio.Event] = {}
        self._session_child_waiters: dict[str, asyncio.Event] = {}
        # Each run's assistant messages as `session.message` pushes them (ELI-381):
        # its usage line and images come from these, not a `chat.history` read.
        # Pushes can be lost in a socket gap, and a rewrite comes with no
        # message: the counts tell a reader its run's messages may be incomplete.
        self._run_messages: dict[tuple, list] = {}
        self.message_gaps = 0
        self.message_rewrites: dict[str, int] = {}
        # The Gateway's `cron` event (a job added, changed, removed, started
        # or finished), or a socket gap: the waiter, and a count readers keep
        # to tell a cached job list is old.
        # `cron_epoch` names this connection, so a revision never matches
        # another connection's, the Pipe's and the Action's classes included.
        self._cron_waiter: asyncio.Event | None = None
        self.cron_epoch = uuid.uuid4().hex
        self.cron_revision = 0
        self._tool_events_seen: dict[tuple, bool] = {}
        # A waiting command returns its "Take control" link on every poll.
        self._control_links_shown: dict[tuple, bool] = {}
        # Spawn call args awaiting their result, for the child index.
        self._spawn_args: dict[tuple, dict] = {}
        # Child key -> its spawn's run; children whose error is recorded.
        self._spawn_runs: dict[str, str] = {}
        self._child_errors_read: set[str] = set()

    async def _subscribe_all(self) -> None:
        """Renew the session index and transcript subscriptions."""
        try:
            # The Gateway registers for pushes, THEN lists, so a run is in
            # this snapshot or its start push follows.
            resp = await self.send_request("sessions.subscribe", {"activeOnly": True}, timeout=15)
        except Exception as ex:
            pipe_log(f"  sessions.subscribe failed: {ex}")
        else:
            self._note_active_snapshot(((resp or {}).get("list") or {}).get("sessions") or [])
            self._stop_notice_seen = False
            self._shutdown_seen = False
        # Also after a failed subscribe: the turn resync reads rows with sessions.list,
        # and the reads it skipped while the socket was coming back are owed now
        # (ELI-369). A socket that dropped again leaves it to that reconnect's hello.
        if _TURNS:
            spawn_background(_TURNS.after_hello(self))
        for key in list(self._message_subscriptions):
            await self._subscribe_messages(key)
        # A waiter that read state before subscribing could miss a settle.
        self._wake_session_waiters()

    def _note_active_snapshot(self, rows: list) -> None:
        """Keep the active runs of OWUI sessions from a subscribe snapshot."""
        snap = {}
        for row in rows:
            key = str(row.get("key") or "")
            runs = [r for r in (row.get("activeRunIds") or []) if r]
            if (runs or row.get("hasActiveRun")) and self.parse_owui_session_key(key):
                snap[key] = runs
        self.active_run_snapshot = snap
        if snap:
            pipe_log(f"  subscribe snapshot: {len(snap)} OWUI session(s) with an active run")

    async def _subscribe_messages(self, session_key: str) -> bool:
        try:
            # A just-started Gateway refuses it while preparing the agent.
            await _send_when_prepared(
                self, "sessions.messages.subscribe", {"key": session_key}, timeout=15
            )
            return True
        except Exception as ex:
            pipe_log(f"  sessions.messages.subscribe {session_key[-36:]} failed: {ex}")
            return False

    async def ensure_message_subscription(self, session_key: str) -> None:
        """Subscribe to `session.tool` for `session_key`. Only the run's
        initiating socket gets tool events as `agent` events (ELI-92)."""
        if not session_key or session_key in self._message_subscriptions:
            return
        self._message_subscriptions.add(session_key)
        if not await self._subscribe_messages(session_key):
            self._message_subscriptions.discard(session_key)

    def _first_tool_event(self, payload: dict) -> bool:
        """False for a tool event already dispatched via the other path."""
        data = payload.get("data") or {}
        tcid = data.get("toolCallId")
        phase = data.get("phase")
        if not tcid or phase not in ("start", "result"):
            return True
        key = (payload.get("sessionKey"), tcid, phase)
        if key in self._tool_events_seen:
            return False
        self._tool_events_seen[key] = True
        if len(self._tool_events_seen) > 4000:
            for stale in list(self._tool_events_seen)[:2000]:
                self._tool_events_seen.pop(stale, None)
        return True

    def _control_link_note(self, payload: dict) -> dict | None:
        """A "Take control" note for a tool result matching CONTROL_LINK_PATTERN
        (ELI-318), once per link and chat. Takeover pages refuse framing, so
        the link goes in the reply text."""
        data = payload.get("data") or {}
        session = payload.get("sessionKey") or ""
        if payload.get("stream") != "tool" or data.get("phase") != "result" or not payload.get("runId"):
            return None
        pattern = (getattr(self._valves(), "CONTROL_LINK_PATTERN", "") or "").strip()
        if not pattern or not self.parse_owui_session_key(session):
            return None
        try:
            found = re.search(pattern, _tool_result_text(data.get("result", {})))
        except re.error as ex:
            pipe_log(f"  CONTROL_LINK_PATTERN is not a valid regular expression: {ex}")
            return None
        link = found.group(0).strip() if found else ""
        if not re.fullmatch(r"https?://[^\s()<>\[\]]+", link) or (session, link) in self._control_links_shown:
            return None
        self._control_links_shown[(session, link)] = True
        if len(self._control_links_shown) > 2000:
            for stale in list(self._control_links_shown)[:1000]:
                self._control_links_shown.pop(stale, None)
        pipe_log(f"  control link added: {link}")
        nid = f"{_NOTE_ITEM_PREFIX}control_{hashlib.sha256(link.encode()).hexdigest()[:12]}"
        return {"sessionKey": session, "runId": payload["runId"], "stream": PIPE_NOTE_STREAM,
                "data": {"id": nid, "text": CONTROL_LINK_NOTE.format(link=link)}}

    def _spawn_seen(self, payload: dict):
        """(parent, child, task, run fields) of an accepted spawn result, else
        None. Task and label come from the start event; the receipt has
        neither. Run fields keep a deleted child's row (ELI-276)."""
        data = payload.get("data") or {}
        call = (payload.get("sessionKey"), data.get("toolCallId"))
        args = _spawn_call_args(payload)
        if args is not None:
            self._spawn_args[call] = args
            if len(self._spawn_args) > 200:
                for stale in list(self._spawn_args)[:100]:
                    self._spawn_args.pop(stale, None)
            return None
        if data.get("phase") != "result":
            return None
        args = self._spawn_args.pop(call, None) or {}
        spawned = _spawned_child(payload)
        if not spawned:
            return None
        parent, child, run_id = spawned
        task = str(args.get("task") or "").strip() or None
        label = str(args.get("label") or "").strip()
        run = {"runId": run_id, **({"label": label} if label else {})} if run_id else None
        return parent, child, task, run

    def session_change_event(self, session_key: str) -> asyncio.Event:
        """An Event set by the next `sessions.changed` for `session_key` or a
        socket gap. Take it BEFORE reading the state so no change slips
        between the read and the wait."""
        ev = self._session_change_waiters.get(session_key)
        if ev is None:
            ev = self._session_change_waiters[session_key] = asyncio.Event()
        return ev

    def cron_event(self) -> asyncio.Event:
        """An Event set by the next `cron` event or a socket gap. Take it
        BEFORE reading the jobs so no change slips between the read and the wait."""
        if self._cron_waiter is None:
            self._cron_waiter = asyncio.Event()
        return self._cron_waiter

    def _on_cron_changed(self) -> None:
        self.cron_revision += 1
        waiter, self._cron_waiter = self._cron_waiter, None
        if waiter is not None:
            waiter.set()

    def _wake_session_waiters(self, session_key: str | None = None) -> None:
        if session_key is None:
            self._on_cron_changed()     # a gap may have lost a `cron` event too
        keys = [session_key] if session_key else list(self._session_change_waiters)
        for key in keys:
            ev = self._session_change_waiters.pop(key, None)
            if ev is not None:
                ev.set()
        if session_key is None:
            # A gap or a fresh subscription: an append may be among the lost.
            self.message_gaps += 1
            for key in list(self._session_message_waiters):
                self._session_message_waiters.pop(key).set()
            for key in list(self._session_child_waiters):
                self._session_child_waiters.pop(key).set()

    def session_child_event(self, session_key: str) -> asyncio.Event:
        """Like `session_change_event`, for a child session of `session_key`."""
        ev = self._session_child_waiters.get(session_key)
        if ev is None:
            ev = self._session_child_waiters[session_key] = asyncio.Event()
        return ev

    def session_message_event(self, session_key: str) -> asyncio.Event:
        """Like `session_change_event`, for a transcript change: an append, a
        `sessions.changed` with phase `message` (a rewrite), or a gap."""
        ev = self._session_message_waiters.get(session_key)
        if ev is None:
            ev = self._session_message_waiters[session_key] = asyncio.Event()
        return ev

    def _wake_message_waiter(self, session_key: str) -> None:
        ev = self._session_message_waiters.pop(session_key, None)
        if ev is not None:
            ev.set()

    async def read_until_stored(self, session_key: str, read, have, max_wait_s: float, empty=None):
        """`read(fresh)` until `have(result)`, re-reading after each
        transcript change. Returns (last result, whether `have` held).
        `max_wait_s` bounds the whole wait; a read's own error is raised."""
        loop = asyncio.get_running_loop()
        deadline = loop.time() + max_wait_s
        bound = object()

        async def within(coro):
            # `asyncio.wait` doesn't raise, so a read's own TimeoutError still propagates.
            task = asyncio.ensure_future(coro)
            left = deadline - loop.time()
            if left > 0:
                await asyncio.wait({task}, timeout=left)
            if not task.done():
                task.cancel()
                return bound
            return task.result()

        got = await within(read(False))
        if got is bound:
            return empty, False
        if have(got):
            return got, True
        while True:
            if await within(self.ensure_message_subscription(session_key)) is bound:
                return got, False
            changed = self.session_message_event(session_key)
            fresh = await within(read(True))
            if fresh is bound:
                return got, False
            got = fresh
            if have(got):
                return got, True
            if await within(changed.wait()) is bound:
                return got, False

    def _note_run_message(self, key: str, payload: dict) -> None:
        """Keep a pushed assistant message's digest under each run it belongs to,
        for a run a reply follows only: one nobody reads (a wake's, say) is not kept.
        A reply's consumer is registered before its run starts."""
        message = payload.get("message")
        if not key or not isinstance(message, dict) or message.get("role") != _ASSISTANT_ROLE:
            return
        digest = _run_message_digest(message)
        for run_id in _transcript_run_ids(message) | ({payload["runId"]} if payload.get("runId") else set()):
            if self._reply_follows(key, run_id):
                self._run_messages.setdefault((key, run_id), []).append(digest)

    def _reply_follows(self, session_key: str, run_id: str) -> bool:
        """A reply streams the run, or continues it (a message steered into it)."""
        return any(c.session_key == session_key and (c.run_id == run_id or (c.steered and c.steered_into == run_id))
                   for c in self._consumers.values())

    def _drop_unfollowed_runs(self, session_key: str) -> None:
        """The session went idle: drop what no reply reads any more (a reply
        parked and never claimed, say)."""
        for key in [k for k in self._run_messages if k[0] == session_key and not self._reply_follows(*k)]:
            del self._run_messages[key]

    def subscribed_to_messages(self, session_key: str) -> bool:
        """Whether this connection gets the session's `session.message` pushes."""
        return session_key in self._message_subscriptions

    def run_transcript(self, session_key: str, run_id: str) -> dict:
        """The run's pushed assistant messages, shaped like `chat.history`."""
        return {"messages": list(self._run_messages.get((session_key, run_id), ()))}

    def forget_run_transcript(self, session_key: str, run_id: str) -> None:
        """A reply ended: drop its run's messages unless another reply continues the run."""
        if not self._reply_follows(session_key, run_id):
            self._run_messages.pop((session_key, run_id), None)

    def transcript_mark(self, session_key: str) -> tuple:
        """Compare marks taken before and after a run: a difference means a
        push may be missing from its messages (a socket gap or a rewrite)."""
        return self.message_gaps, self.message_rewrites.get(session_key, 0)

    def _note_run_failed(self, payload: dict) -> None:
        """Record an aborted or failed run (no answer is stored) and wake its
        transcript waiters (`_await_steered_answer`)."""
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        how = payload.get("state") if payload.get("state") in ("aborted", "error") else (
            "error" if payload.get("stream") == "lifecycle" and data.get("phase") == "error" else None)
        sess, run = payload.get("sessionKey"), payload.get("runId")
        if not (how and sess and run):
            return
        self.runs_failed[f"{sess}:{run}"] = how
        if len(self.runs_failed) > 2000:
            for stale in list(self.runs_failed)[:1000]:
                self.runs_failed.pop(stale, None)
        self._wake_message_waiter(sess)

    def _on_session_message(self, payload: dict) -> None:
        key = payload.get("sessionKey") or ""
        self._note_run_message(key, payload)
        self._wake_message_waiter(key)
        if key and isinstance(payload.get("message"), dict):
            self._on_user_message_committed(key, payload["message"])
        if _TURNS and key:
            _TURNS.session_message(self, key)

    def _on_shutdown(self, payload: dict) -> None:
        """DESIGN 2.7 F4: sent before the Gateway aborts runs. Without
        restartExpectedMs it is a stop, whose aborted runs are never recovered."""
        self._shutdown_seen = True
        if payload.get("restartExpectedMs") is None:
            self._stop_notice_seen = True

    def _on_sessions_changed(self, payload: dict) -> None:
        """A session row changed: wake its waiters, and subscribe a just
        started OWUI session's transcript before its first tool call."""
        key = payload.get("sessionKey") or payload.get("key") or ""
        self.note_session_id(key, payload.get("sessionId"))
        if key:
            # On any change: 2026.10.10 announces a cron wake's idle with
            # `status: done` and no `hasActiveRun` (`reason: cron-binding`).
            self._wake_session_waiters(key)
            if "hasActiveRun" in payload:
                self.row_to_consumers(key, payload)
            if payload.get("hasActiveRun") is False:
                self._drop_unfollowed_runs(key)
        if key and payload.get("phase") == "message":
            # A rewrite, not an append: no `session.message` follows.
            self.message_rewrites[key] = self.message_rewrites.get(key, 0) + 1
            self._wake_message_waiter(key)
        parent = payload.get("spawnedBy") or payload.get("parentSessionKey")
        if parent and parent != key:
            ev = self._session_child_waiters.pop(parent, None)
            if ev is not None:
                ev.set()
            if key and _subagent_ended(payload) and self.parse_owui_session_key(parent):
                spawn_background(self._record_child_end(parent, key, {**payload, "key": key}))
        if _TURNS and key and payload.get("hasActiveRun") is False:
            _TURNS.settled(self, key, payload)
        if (payload.get("hasActiveRun") and key
                and key not in self._message_subscriptions
                and self.parse_owui_session_key(key)):
            spawn_background(self.ensure_message_subscription(key))

    async def _record_child_end(self, parent: str, child: str, row: dict) -> None:
        """Keep a chat's child as it ended for the Status dialog, since a
        cleanup "delete" child vanishes (ELI-276). A failed run's own error is
        read too: the row's `lastRunError` is a canned summary (ELI-277)."""
        loop = asyncio.get_running_loop()
        await loop.run_in_executor(None, functools.partial(_subagent_remember, parent, rows=[row]))
        if row.get("status") not in ("failed", "timeout") or child in self._child_errors_read:
            return
        run_id = self._spawn_runs.get(child) or ((await loop.run_in_executor(
            None, _subagent_runs, parent)).get(child) or {}).get("runId")
        if not run_id:
            return
        try:
            ended = await self.send_request("agent.wait", {"runId": run_id, "timeoutMs": 0}, timeout=5)
        except Exception as ex:
            pipe_log(f"[subagents] agent.wait {run_id} failed: {ex}")
            return
        if (ended or {}).get("status") == "timeout":
            return   # not over on the run's side yet: the next push asks again
        self._child_errors_read.add(child)
        if len(self._child_errors_read) > 2000:
            self._child_errors_read.clear()
        error = (ended or {}).get("error")
        if isinstance(error, str) and error.strip():
            await loop.run_in_executor(None, functools.partial(
                _subagent_remember, parent, runs={child: {"error": error.strip()[:2000]}}))

    def row_to_consumers(self, session_key: str, row: dict, resync: bool = False,
                         read_at: float | None = None, outside_loop: bool = False) -> None:
        """Hand `row` to every inline reply of `session_key`. `outside_loop`:
        not called by the receive loop, so the row queues behind earlier
        events, one task per queue."""
        marker = {"type": _ROW_MARKER_TYPE, "row": row, "resync": resync,
                  "read_at": time.monotonic() if read_at is None else read_at}
        for key, consumer in list(self._consumers.items()):
            if key.startswith(f"{session_key}:"):
                for q in consumer.queues:
                    if outside_loop:
                        spawn_background(q.put(dict(marker)))
                    else:
                        q.put_control(dict(marker))

    async def push_row(self, session_key: str) -> None:
        """Read the session's row now and hand it to its inline replies."""
        try:
            lst = await self.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  row read for {session_key[-12:]} failed: {ex!r}")
            return
        row = next((r for r in (lst.get("sessions") or []) if r.get("key") == session_key), None)
        if row is not None:
            self.row_to_consumers(session_key, row, outside_loop=True)

    def stop_awaiting_owner(self, session_key: str, run_id: str) -> None:
        """The reply decided: the agent runs held for it go on (`_release_held`)."""
        if self._awaiting_owner.get(session_key) == run_id:
            del self._awaiting_owner[session_key]
            self._release_held(session_key)

    def note_cron_event(self, payload: dict) -> None:
        """Record a cron run into a session from a `cron` event. Needed because
        a short one-shot wake leaves `cron.list` before its events are judged
        (ELI-181)."""
        job = payload.get("job") if isinstance(payload.get("job"), dict) else {}
        target, job_id, start = job.get("sessionTarget"), payload.get("jobId"), payload.get("runAtMs")
        if not (job_id and isinstance(start, (int, float))):
            return
        run = next((r for runs in self._cron_runs.values() for r in runs
                    if r["job"] == job_id and r["start"] == start), None)
        if run is None:
            if payload.get("action") != "started" or not (
                    isinstance(target, str) and target.startswith("session:")):
                return
            runs = self._cron_runs.setdefault(target[len("session:"):], [])
            run = {"job": job_id, "start": start, "end": None}
            runs.append(run)
            del runs[:-20]
        if payload.get("action") == "finished" and isinstance(payload.get("durationMs"), (int, float)):
            run["end"] = start + payload["durationMs"]

    def cron_run_at(self, session_key: str, at_ms: float) -> dict | None:
        """The newest recorded cron run into `session_key` covering `at_ms`."""
        for run in reversed(self._cron_runs.get(session_key) or []):
            if run["start"] <= at_ms and (run["end"] is None or at_ms <= run["end"]):
                return run
        return None

    def note_session_id(self, session_key: str, session_id) -> None:
        if session_key and isinstance(session_id, str) and session_id:
            self._session_ids[session_key] = session_id

    async def session_id_for(self, session_key: str) -> str | None:
        """The session's sessionId, also every cron wake's run id. Read from
        the row when no event carried it yet."""
        known = self._session_ids.get(session_key)
        if known:
            return known
        try:
            lst = await self.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  sessionId read for {session_key[-12:]} failed: {ex!r}")
            return None
        for row in lst.get("sessions") or []:
            self.note_session_id(row.get("key") or "", row.get("sessionId"))
        return self._session_ids.get(session_key)

    def register_run_target(self, session_key: str, run_id: str,
                            chat_id: str | None, message_id: str | None,
                            thinking: str | None = None,
                            request_task_id: str | None = None,
                            span_run: str | None = None,
                            steer_pending: bool = False,
                            before: list | None = None) -> None:
        """Record that this run streams into an OWUI message and start its
        shadow `_TurnRenderer`. `request_task_id`: OWUI's request task, which
        a handover write waits for. `span_run`, `steer_pending` and `before`
        describe steered replies (`_settle_steered_replies`)."""
        if not (chat_id and message_id and run_id):
            return
        key = f"{session_key}:{run_id}"
        self._run_targets[key] = {"chat_id": chat_id, "message_id": message_id,
                                  "thinking": thinking, "request_task_id": request_task_id,
                                  "span_run": span_run, "steer_pending": steer_pending,
                                  "before": list(before or [])}
        self._run_renderers[key] = _TurnRenderer()
        # Bound memory for runs that never end.
        if len(self._run_targets) > 100:
            for stale in list(self._run_targets)[:50]:
                self._run_targets.pop(stale, None)
                self._run_renderers.pop(stale, None)

    def handover_of(self, session_key: str, run_id: str, thinking: str | None = None) -> dict:
        """What a turn writer takes over from a run's request (DESIGN 2.6)."""
        key = f"{session_key}:{run_id}"
        target = self._run_targets[key]
        return {"message_id": target["message_id"], "renderer": self._run_renderers.get(key),
                "thinking": thinking or target.get("thinking"), "shown": target.get("shown", ""),
                "request_task_id": target.get("request_task_id"),
                "steer_pending": bool(target.get("steer_pending"))}

    def unregister_run_target(self, session_key: str, run_id: str) -> None:
        key = f"{session_key}:{run_id}"
        self._run_targets.pop(key, None)
        self._run_renderers.pop(key, None)

    def note_reply_sent(self, session_key: str, message_id: str | None,
                        run_id: str, text: str) -> None:
        """Record the run a reply sent, so a repeat call follows it instead of
        resending (ELI-82)."""
        if not (message_id and run_id):
            return
        self._sent_replies[f"{session_key}:{message_id}"] = {"run_id": run_id, "text": text}
        if len(self._sent_replies) > 100:
            for stale in list(self._sent_replies)[:50]:
                self._sent_replies.pop(stale, None)

    def reply_sent(self, session_key: str, message_id: str | None) -> dict | None:
        """{run_id, text} that `note_reply_sent` recorded for this reply."""
        return self._sent_replies.get(f"{session_key}:{message_id}") if message_id else None

    def continue_run_target(self, session_key: str, run_id: str, next_run_id: str,
                            shown: bool = True) -> None:
        """Move the target and renderer to the next run (an ask-user answer).
        `shown` marks the old run delivered; False moves the target only."""
        key = f"{session_key}:{run_id}"
        target = self._run_targets.pop(key, None)
        renderer = self._run_renderers.pop(key, None)
        if shown:
            self.mark_delivered_live(session_key, run_id)
        if target is None:
            return
        nkey = f"{session_key}:{next_run_id}"
        self._run_targets[nkey] = target
        self._run_renderers[nkey] = renderer if renderer is not None else _TurnRenderer()

    def note_turn_rewrite(self, chat_id: str | None, message_id: str | None,
                          raw: str, shown: str) -> None:
        """Record that the inline reply showed `shown` for `raw`, so a
        takeover writer does the same."""
        if not (chat_id and message_id and raw) or raw == shown:
            return
        key = f"{chat_id}:{message_id}"
        rewrites = self._turn_rewrites.setdefault(key, [])
        if (raw, shown) not in rewrites:
            rewrites.append((raw, shown))
        if len(self._turn_rewrites) > 200:
            for stale in list(self._turn_rewrites)[:100]:
                self._turn_rewrites.pop(stale, None)

    def turn_rewrites(self, chat_id: str, message_id: str) -> list:
        return list(self._turn_rewrites.get(f"{chat_id}:{message_id}") or [])

    def _chat_write_lock(self, chat_id: str) -> asyncio.Lock:
        """The process-wide lock for read-modify-writes into `chat_id`."""
        lock = self._chat_write_locks.get(chat_id)
        if lock is None:
            lock = asyncio.Lock()
            self._chat_write_locks[chat_id] = lock
        return lock

    # ── Public API ──────────────────────────────────────────────────

    @property
    def reconnecting(self) -> bool:
        """The event loop is bringing a dropped socket back; requests fail until then."""
        return (self._ws is None and not self._stopped and self._event_loop_task is not None
                and not self._event_loop_task.done())

    def endpoint_moved(self) -> bool:
        """GATEWAY_URL now names another endpoint (`_replace_moved_connection`).
        An unparseable valve counts as moved, so the new attempt names it."""
        if self._endpoint is None:
            return False
        try:
            return _parse_gateway_url(self._valves().GATEWAY_URL) != self._endpoint
        except GatewayError:
            return True

    async def ensure_connected(self):
        """Ensure the WS connection is up; connect/reconnect if needed."""
        if self._ws and self._event_loop_task and not self._event_loop_task.done():
            return
        if self._retired and not self._serving():
            # Revived retired connections pile up as orphans running old code.
            raise GatewayError(
                "gateway connection retired: a newer deploy of the pipe owns it now"
            )
        if self._event_loop_task and not self._event_loop_task.done() and not self._stopped:
            # A socket opened here would go unread until the loop's backoff
            # ends (ELI-176), so make the loop try now.
            await self._await_reconnect()
            return
        async with self._init_lock:
            if self._ws and self._event_loop_task and not self._event_loop_task.done():
                return
            self._stopped = False
            await self._connect_once_started()
            if not self._event_loop_task or self._event_loop_task.done():
                self._event_loop_task = asyncio.create_task(self._event_loop())

    async def _await_reconnect(self):
        """Await the event loop's reconnect outcome (ELI-176). A refusal means
        a restarting Gateway, so wait up to GATEWAY_DOWN_WAIT_S; other
        failures raise at once."""
        deadline = time.monotonic() + GATEWAY_DOWN_WAIT_S
        refusal = None
        self._turns_awaiting_gateway += 1
        try:
            self._reconnect_now.set()
            while True:
                waiter = asyncio.get_running_loop().create_future()
                self._reconnect_waiters.append(waiter)
                # The loop's first attempt is made at once; later ones at its first step.
                await asyncio.wait({waiter, self._event_loop_task},
                                   timeout=None if refusal is None else max(0, deadline - time.monotonic()),
                                   return_when=asyncio.FIRST_COMPLETED)
                if not waiter.done():
                    waiter.cancel()
                    if self._event_loop_task.done():
                        raise GatewayError("gateway connection stopped while reconnecting")
                    raise refusal
                error = waiter.result()
                if error is None:
                    return
                error = error if isinstance(error, GatewayError) else GatewayError(str(error))
                if not _gateway_refused(error) or time.monotonic() >= deadline:
                    raise error
                if refusal is None:
                    pipe_log("  the Gateway refuses connections (down or restarting); the message "
                             f"waits for the reconnect, up to {GATEWAY_DOWN_WAIT_S} s")
                refusal = error
        finally:
            self._turns_awaiting_gateway -= 1

    async def send_request(self, method: str, params: dict, timeout: float = 10) -> dict:
        """Send a request and wait for the response."""
        # None while reconnecting; raise a readable error, not AttributeError.
        if self._ws is None:
            raise GatewayError("gateway connection not ready (reconnecting)")
        req_id = str(self._next_req_id)
        self._next_req_id += 1
        fut = asyncio.get_running_loop().create_future()
        self._pending_reqs[req_id] = fut

        try:
            await self._ws.send(json.dumps(dict(
                type="req", id=req_id, method=method, params=params
            )))
            return await asyncio.wait_for(fut, timeout=timeout)
        finally:
            self._pending_reqs.pop(req_id, None)

    def session_send_lock(self, session_key: str) -> asyncio.Lock:
        """Per-session lock around queue release, chat.send and run registration."""
        return self._session_send_locks.setdefault(session_key, asyncio.Lock())

    @contextlib.asynccontextmanager
    async def send_section(self, session_key: str):
        """`session_send_lock`, keeping this connection up until the section
        ends even if retired: the settle it waits for is pushed only to this
        socket (ELI-172)."""
        self._open_send_sections += 1
        try:
            async with self.session_send_lock(session_key):
                yield
        finally:
            self._open_send_sections -= 1
            self._close_if_retired_and_idle()

    def send_waiters(self, session_key: str) -> list:
        """Replies waiting to send, oldest first. Messages queued behind one
        run go out together as one turn."""
        return self._send_waiters.setdefault(session_key, [])

    def drop_send_waiter(self, session_key: str, waiter) -> None:
        waiters = self._send_waiters.get(session_key)
        if waiters and waiter in waiters:
            waiters.remove(waiter)
            if not waiters:
                del self._send_waiters[session_key]

    MODEL_PATCH_CACHE_TTL_S = 60.0

    def model_patch_lock(self, session_key: str) -> asyncio.Lock:
        """Per-session lock so a message burst issues one sessions.patch (ELI-59)."""
        return self._model_patch_locks.setdefault(session_key, asyncio.Lock())

    def model_patch_cached(self, session_key: str, model: str | None) -> bool:
        """True if `model` was applied within the TTL, so the patch can be
        skipped (ELI-59). The TTL bounds drift from external model changes."""
        entry = self._model_patch_cache.get(session_key)
        if entry is None:
            return False
        cached_model, ts = entry
        return cached_model == model and (time.time() - ts) < self.MODEL_PATCH_CACHE_TTL_S

    def record_model_patched(self, session_key: str, model: str | None) -> None:
        """Record a successful sessions.patch for the cache (ELI-59)."""
        self._model_patch_cache[session_key] = (model, time.time())

    def should_announce_thinking_note(self, session_key: str, note: str) -> bool:
        """True the first time a given clamp note applies to a session. A
        picked level stays picked, so repeating it on every answer is noise.
        Per connection on purpose, never persisted."""
        if not note:
            return False
        if self._thinking_note_shown.get(session_key) == note:
            return False
        self._thinking_note_shown[session_key] = note
        return True

    def invalidate_model_patch(self, session_key: str) -> None:
        """Drop the cached model after a patch failure (ELI-59)."""
        self._model_patch_cache.pop(session_key, None)

    def register_consumer(self, session_key: str, run_id: str) -> asyncio.Queue:
        """Attach a new event queue to the (session, run) consumer."""
        key = f"{session_key}:{run_id}"
        consumer = self._consumers.get(key)
        if consumer is None:
            consumer = _Consumer(session_key=session_key, run_id=run_id)
            self._consumers[key] = consumer
            pipe_log(f"  registered consumer: {key[:60]}...")
        q = _RunQueue(maxsize=500)
        consumer.queues.append(q)
        for ev in self._held_for_live.pop((session_key, run_id), []):
            q.put_nowait(_event_frame(ev))  # the run's first events, held for this reply
        return q

    def unregister_consumer(self, session_key: str, run_id: str, queue: asyncio.Queue | None = None):
        """Remove one queue, or the whole consumer when `queue` is None."""
        key = f"{session_key}:{run_id}"
        consumer = self._consumers.get(key)
        if consumer is None:
            return
        if queue:
            try:
                consumer.queues.remove(queue)
            except ValueError:
                pass
        if not consumer.queues or queue is None:
            del self._consumers[key]
            for other in [k for k, c in self._consumers.items()
                          if c.session_key == session_key and c.steered and c.steered_into == run_id]:
                del self._consumers[other]
            self._release_held(session_key)
            # Its run may never have started (`has_reply`): waiters re-read.
            self._wake_session_waiters(session_key)
        pipe_log(f"  unregistered consumer: {key[:60]}...")
        self._close_if_retired_and_idle()

    def has_reply(self, session_key: str) -> bool:
        """Whether a reply here streams a run of `session_key`, including
        before the Gateway has the run (ELI-260)."""
        return any(c.session_key == session_key and not getattr(c, "steered", False)
                   for c in self._consumers.values())

    def _serving(self) -> bool:
        """Work a retired connection still owes (ELI-172)."""
        return (any(not getattr(c, "steered", False) for c in self._consumers.values())
                or bool(self._open_send_sections))

    def _close_if_retired_and_idle(self) -> None:
        if self._retired and not self._serving():
            pipe_log("  retired gateway connection: last run finished, closing")
            spawn_background(self.disconnect())

    def live_reply_owns(self, session_key: str, run_id: str) -> bool:
        """True when `run_id` continues a message a live inline reply still
        streams; its events wait for that reply, not a second writer."""
        parsed = parse_pipe_run_id(run_id)
        waiting = self._awaiting_owner.get(session_key)
        if waiting and parsed is None and run_id != waiting:
            # Any agent run may be the Gateway's recovery of it (rule E).
            return True
        if parsed is None or parsed["kind"] == "reply":
            return False
        for c in list(self._consumers.values()):
            other = parse_pipe_run_id(c.run_id) if c.session_key == session_key else None
            if (other and c.run_id != run_id and other["chat"] == parsed["chat"]
                    and other["message"] == parsed["message"]):
                return True
        return False

    def hold_for_live(self, session_key: str, run_id: str, payload: dict) -> None:
        held = self._held_for_live.setdefault((session_key, run_id), [])
        if len(held) < 500:
            held.append(payload)

    def _release_held(self, session_key: str) -> None:
        """A reply ended: drain the runs held for it in the background, unless a
        new reply registers for them first (`register_consumer`)."""
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            return  # no loop, no events to route (a sync teardown)
        for (sess, run) in list(self._held_for_live):
            if sess == session_key:
                async def drain(sess=sess, run=run):
                    self.drain_held(sess, run)
                spawn_background(drain())

    def drain_held(self, session_key: str, run_id: str) -> None:
        """Route a run's held events in order, synchronously so nothing else
        for the run can come between them."""
        if self.live_reply_owns(session_key, run_id):
            return
        held = self._held_for_live.pop((session_key, run_id), None)
        if not held:
            return
        consumer = self._consumers.get(f"{session_key}:{run_id}")
        if consumer is not None:
            # Unreachable (`register_consumer` takes them first); logged if it breaks.
            self.unreachable_held_drains += 1
            pipe_log(f"  ERROR unreachable: {len(held)} held event(s) for an already-registered "
                     f"consumer of {run_id[:24]}... (count {self.unreachable_held_drains})")
            for q in consumer.queues:
                for ev in held:
                    q.put_control(_event_frame(ev))
            return
        pipe_log(f"  {len(held)} held event(s) of {run_id[:24]}... released to the turn writer")
        for ev in held:
            _TURNS.route_now(self, ev)  # only the turn writer holds events

    def mark_delivered_live(self, session_key: str, run_id: str):
        """Record that a live tab got this run's final, so a late event never
        reopens its message (`_turn_route_now`)."""
        key = f"{session_key}:{run_id}"
        self._delivered_live[key] = time.time()
        if len(self._delivered_live) > 500:
            oldest_first = sorted(self._delivered_live.items(), key=lambda kv: kv[1])
            for stale_key, _ in oldest_first[:250]:
                self._delivered_live.pop(stale_key, None)

    def was_delivered_live(self, session_key: str, run_id: str) -> bool:
        return f"{session_key}:{run_id}" in self._delivered_live

    def active_run_id_for_session(self, session_key: str) -> str | None:
        """Return the sole active run id for a session, if one is registered."""
        matches = [
            consumer.run_id for consumer in self._consumers.values()
            if consumer.session_key == session_key
        ]
        if len(matches) == 1:
            return matches[0]
        return None

    def user_turn_run_active(self, session_key: str, chat_id: str) -> bool:
        """The session's one active run is a Pipe reply run in `chat_id`, the
        only kind the Gateway steers into. Into any other it falls back to its
        follow-up queue, where on 2026.10.10-beta.1 the send never runs."""
        # Started only: a message waiting to be steered has a consumer too.
        runs = {c.run_id for c in self._consumers.values()
                if c.session_key == session_key and c.started and not (c.ended or c.steered)}
        runs |= {run for (s, run), pump in getattr(self, "_turn_pumps", {}).items()
                 if s == session_key and pump.started and not pump.terminal.is_set()}
        parsed = parse_pipe_run_id(next(iter(runs))) if len(runs) == 1 else None
        return bool(parsed and parsed["kind"] == "reply" and parsed["chat"] == chat_id)

    def parse_owui_session_key(self, session_key: str) -> tuple[str, str] | None:
        """(user_id, chat_id) of a key `_owui_session_key` built, else None.
        Split by position: the user's id is a UUID, containing dashes; so is a
        saved chat's, and a temporary chat's is `temporary:<socket id>[:<uuid>]`."""
        agent_id = getattr(self._valves(), "AGENT_ID", None)
        if not agent_id:
            return None
        prefix = f"agent:{agent_id}:openwebui-".lower()   # as `_owui_session_key` builds it
        if not session_key.startswith(prefix):
            return None
        after = session_key[len(prefix):]
        user_id, sep, chat = after[:_UUID_LEN], after[_UUID_LEN:_UUID_LEN + 1], after[_UUID_LEN + 1:]
        if len(user_id) < _UUID_LEN or sep != _KEY_PART_SEP or not chat:
            return None
        temporary = _OWUI_TEMPORARY_CHAT_ID.fullmatch(chat)
        if temporary:
            return user_id, temporary.group(1)
        return (user_id, chat[:_UUID_LEN]) if len(chat) >= _UUID_LEN else None

    async def dispatch_run_event(self, msg: dict) -> None:
        """Route one run event (or Pipe note, ELI-197): shadow render, then
        live reply or turn writer. A takeover link adds a note (ELI-318)."""
        payload = msg.get("payload", {})
        if payload.get("stream") == "tool" and not self._first_tool_event(payload):
            return
        await self._dispatch_run_event(msg)
        note = self._control_link_note(payload)
        if note is not None:
            await self._dispatch_run_event({"type": "event", "event": "agent", "payload": note})

    async def _dispatch_run_event(self, msg: dict) -> None:
        payload = msg.get("payload", {})
        self._note_run_failed(payload)
        spawned = self._spawn_seen(payload) if payload.get("stream") == "tool" else None
        if spawned:
            # The Status dialog's child index (state.py), off the loop.
            parent, child, task, run = spawned
            if run:
                self._spawn_runs[child] = run["runId"]
                if len(self._spawn_runs) > 2000:
                    for stale in list(self._spawn_runs)[:1000]:
                        self._spawn_runs.pop(stale, None)
            asyncio.get_running_loop().run_in_executor(None, functools.partial(
                _subagent_remember, parent, keys=[child], tasks={child: task} if task else None,
                runs={child: run} if run else None))

        # Shadow render, live consumer or not: a takeover writer starts from it.
        _evt_sess = payload.get("sessionKey", "")
        _evt_run = payload.get("runId", "")
        if _evt_sess and _evt_run:
            _renderer = self._run_renderers.get(f"{_evt_sess}:{_evt_run}")
            if _renderer is not None:
                try:
                    _renderer.feed(payload)
                except Exception as ex:
                    pipe_log(f"  shadow renderer feed failed: {ex}")

        if _TURNS and _evt_sess and _evt_run:
            _TURNS.next_run(self, payload)
        consumers = self.consumers_for_event(payload)

        # ELI-100: a run no live request consumes is a turn.
        if not consumers and _TURNS and _TURNS.route_now(self, payload):
            return

        if consumers and not self._note_run_event(msg, consumers[0]):
            return
        if consumers:
            if not payload.get("runId"):
                pipe_log("  dispatched session-only event to sole consumer")
            if payload.get("state") == "final" and payload.get("sessionKey") and payload.get("runId"):
                self.mark_delivered_live(payload["sessionKey"], payload["runId"])
                self.unregister_run_target(payload["sessionKey"], payload["runId"])
            for q in consumers[0].queues:
                await q.put(msg)
            return

        if payload.get("sessionKey") and not payload.get("runId"):
            pipe_log("  dropped ambiguous or unmatched session-only event")

    def _note_run_event(self, msg: dict, consumer: _Consumer) -> bool:
        """Track whether `consumer`'s run started, ended or was steered. False
        drops the event. A first event that is a message-less `chat` final
        means it was steered and the commit did not switch it (`_steer`)."""
        payload = msg.get("payload") or {}
        terminal = (payload.get("state") in ("final", "error", "aborted")
                    or (payload.get("stream") == "lifecycle"
                        and (payload.get("data") or {}).get("phase") in ("end", "error")))
        if consumer.steered:
            if terminal:
                self._consumers.pop(f"{consumer.session_key}:{consumer.run_id}", None)
            return False
        if (not consumer.started and msg.get("event") == "chat"
                and payload.get("state") == "final" and not payload.get("message")
                and steers_mid_run_messages(self.gateway_version) and self._steer(consumer)):
            self._consumers.pop(f"{consumer.session_key}:{consumer.run_id}", None)
            return False
        consumer.started = True
        consumer.ended = consumer.ended or terminal
        if terminal and (payload.get("state") == _CHAT_FINAL
                         or (payload.get("data") or {}).get("phase") == _PHASE_END):
            # Its writers end at the next run's first event if no settle comes first.
            for p in [*consumer.held, *(q.pump for q in consumer.queues if isinstance(q, _WriterQueue))]:
                p.ended_clean = consumer.run_id
        if consumer.ended and _feeds_writer(consumer):
            # A turn writer shows the rest (`_steer_handed_over`) and ends at the
            # settle; late events open nothing. Its pump learns the run ended, so
            # a message committed before the settle is no steer into it.
            pump = self._turn_pumps.get((consumer.session_key, consumer.run_id))
            if pump is not None:
                pump.terminal.set()
            self.mark_delivered_live(consumer.session_key, consumer.run_id)
            self.unregister_run_target(consumer.session_key, consumer.run_id)
            self._consumers.pop(f"{consumer.session_key}:{consumer.run_id}", None)
            self._wake_session_waiters(consumer.session_key)
            self._close_if_retired_and_idle()
            return False
        return True

    def _on_user_message_committed(self, session_key: str, message: dict) -> None:
        """A user message was committed. On 2026.10.10+ a commit naming a
        steer target applies the steer from here. The Gateway publishes the
        target in a second commit, once the runtime took the message in
        (`confirmSteerTargetRunIdForPersistence`), with no order to the
        run's events or to later messages' commits: it can come after the
        run ended."""
        idem = str((message.get("__openclaw") or {}).get("idempotencyKey") or "")
        if not (message.get("role") == "user" and idem.endswith(":user")
                and steers_mid_run_messages(self.gateway_version)):
            return
        # A queued (not steered) message is committed with no target.
        into = (message.get("__openclaw") or {}).get("steerTargetRunId")
        if not into:
            return
        run_id = idem[:-len(":user")]
        consumer = self._consumers.get(f"{session_key}:{run_id}")
        if consumer is not None and consumer.steered:
            return
        if consumer is None:
            steered = self._steer_handed_over(session_key, run_id)
            if steered is None:
                return  # no reply of ours waits for it
        else:
            # Started: its lone final came first, with no running run to steer into.
            steered = None if consumer.started else consumer
        if steered is not None and self._steer(steered, into=into):
            return
        # Its reply still takes its part of the run: from the transcript.
        pipe_log(f"  steer of run {run_id[:24]}... into {into[:24]}... not applied: that run is not "
                 "the session's running run; its replies settle from the transcript")
        refs = [_settle_ref(r) for r in (into, run_id)]
        if _TURNS and all(refs):
            spawn_background(_TURNS.settle_steered_replies(self, session_key, refs))

    def _steer_handed_over(self, session_key: str, run_id: str) -> _Consumer | None:
        """A consumer feeding the turn writer that took over a reply still
        waiting to be steered (`_WriterQueue`), else None."""
        pump = getattr(self, "_turn_pumps", {}).get((session_key, run_id))
        if pump is None or pump.started or not (pump.handover or {}).get("steer_pending"):
            return None
        return _Consumer(session_key=session_key, run_id=run_id, queues=[_WriterQueue(pump)])

    def _steer(self, consumer: _Consumer, into: str | None = None) -> bool:
        """Send the session's active run's events from here on to the reply of
        `consumer`'s message, which was steered into it. The previous reply
        ends at this point; the steered one gets the run and its dedup
        baselines. False with no single active run, or not `into`."""
        sess = consumer.session_key
        active = [c for c in self._consumers.values()
                  if c.session_key == sess and c is not consumer and c.started
                  and not (c.ended or c.steered)]
        pumps = [(run, pump) for (s, run), pump in getattr(self, "_turn_pumps", {}).items()
                 if s == sess and pump.started and not pump.wake and not pump.terminal.is_set()]
        if len(active) == 1:
            run = active[0]
            if into and run.run_id != into:
                return False
            if _feeds_writer(run):
                # The writer has the baselines; it stays open until the settle.
                fed = run.queues[0].pump
                writer = fed.writer
                # Its own run's span (a steered message's answer), after the
                # replies the run was split into before it.
                own = next((r for (s, r), p in self._turn_pumps.items() if s == sess and p is fed), run.run_id)
                prior = dict(fed.steered_earlier or {})
                before = [*(prior.pop("before", None) or []), *([prior] if prior else [])]
                earlier = writer and {"chat_id": writer.chat_id, "message_id": writer.message_id,
                                      "request_task_id": None, "span_run": own, "before": before}
                run_text = _pump_baselines(fed)
                run.held.append(fed)
            else:
                earlier = self._run_targets.get(f"{sess}:{run.run_id}")
                earlier = earlier and {k: earlier.get(k) for k in ("chat_id", "message_id", "request_task_id")} | {
                    "span_run": earlier.get("span_run") or run.run_id, "before": earlier.get("before") or []}
                shadow = self._run_renderers.get(f"{sess}:{run.run_id}")
                run_text = ({"received": shadow.received, "stream": shadow.received,
                             "item": shadow.last_item} if shadow is not None else None)
            for q in run.queues:
                q.put_control({"type": _STEERED_MARKER_TYPE, "into": consumer.run_id})
            run.queues = list(consumer.queues)
            run_id = run.run_id
        elif not active and len(pumps) == 1:
            run_id, pump = pumps[0]
            if into and run_id != into:
                return False
            writer = pump.writer
            earlier = writer and {"chat_id": writer.chat_id, "message_id": writer.message_id,
                                  "request_task_id": None, "span_run": run_id}
            run_text = asyncio.get_running_loop().create_future()
            if _feeds_writer(consumer):
                # The old writer ends at the settle from the transcript, which
                # covers event gaps. Baselines now: its pump may be busy.
                run_text = _pump_baselines(pump)
                # The next steer into this run carries the replies before it.
                consumer.queues[0].pump.steered_earlier = earlier
            else:
                pump.queue.put_nowait(("steered", run_text))
            self._consumers[f"{sess}:{run_id}"] = _Consumer(
                session_key=sess, run_id=run_id, queues=list(consumer.queues), started=True,
                held=[pump] if _feeds_writer(consumer) else [])
        else:
            return False
        consumer.steered, consumer.steered_into = True, run_id
        for q in consumer.queues:
            q.put_control({"type": _STEERED_MARKER_TYPE, "_steered": {
                "run": run_id, "run_text": run_text, "earlier": earlier}})
        pipe_log(f"  run {consumer.run_id[:24]}... steered into {run_id[:24]}...; "
                 "its reply continues that run")
        return True

    def consumers_for_event(self, payload: dict) -> list[_Consumer]:
        """Return consumers that should receive a Gateway event payload."""
        evt_session = payload.get("sessionKey", "")
        evt_run_id = payload.get("runId", "")
        if evt_session and evt_run_id:
            consumer = self._consumers.get(f"{evt_session}:{evt_run_id}")
            return [consumer] if consumer else []
        if evt_session and not evt_run_id:
            matches = [
                consumer for consumer in self._consumers.values()
                if consumer.session_key == evt_session and not consumer.steered
            ]
            return matches if len(matches) == 1 else []
        return []

    async def session_history(self, session_key: str,
                              limit: int = RECOVERY_HISTORY_LIMIT,
                              max_chars: int = RECOVERY_HISTORY_MAX_CHARS,
                              timeout: float = 10) -> dict:
        """Recent messages, normalized by `_transcript_roles` and
        `_transcript_commit_order`."""
        hist = await self.send_request(
            "chat.history",
            dict(sessionKey=session_key, limit=limit, maxChars=max_chars),
            timeout=timeout
        )
        if isinstance(hist, dict) and isinstance(hist.get("messages"), list):
            hist["messages"] = _transcript_commit_order(_transcript_roles(hist["messages"]))
        return hist

    async def abort(self, session_key: str, run_id: str):
        """Send chat.abort for an active run."""
        try:
            await _run_request(self, RUN_ABORT, dict(sessionKey=session_key, runId=run_id),
                               wait=False)
            pipe_log(f"  sent chat.abort for run {run_id[:20]}...")
        except Exception as e:
            pipe_log(f"  abort send failed: {e}")

    async def _abort_cancelled_run(self, session_key: str, run_id: str,
                                   send_stop: bool) -> None:
        await self.abort(session_key, run_id)
        if send_stop:
            pipe_log("Generator cancelled -- sending /stop fallback")
            await self.send_stop(session_key)

    def park_cancelled_turn(self, session_key: str, run_id: str | None,
                            queue: asyncio.Queue | None, carried: list[str],
                            grace_s: float, send_stop: bool,
                            run_text: dict | None = None, settle=None,
                            reply: dict | None = None,
                            waiting: list | None = None,
                            attachments: list | None = None) -> None:
        """Park a cancelled reply's unfinished business for the next message.

        OWUI cancels the same way for Stop and Send now, so the turn is parked
        and decided after. The run keeps going and `queue` buffers its events;
        `carried`/`attachments` are accepted but unsent messages; `run_text`
        holds dedup baselines, since closing events repeat the whole text;
        `waiting` replies are ended by the claimer or a release (ELI-188).
        `settle` asks the browser which button it was, in a background task
        (ELI-95); without it `grace_s` decides. Unclaimed, the run is aborted.

        Synchronous on purpose: it runs on the cancel path, where an await can
        be interrupted. An OWUI shutdown is no Stop: the run keeps going for
        the next process's reconcile (ELI-90, ELI-94).
        """
        if owui_shutting_down():
            if queue is not None:
                self.unregister_consumer(session_key, run_id, queue=queue)
            pipe_log(f"  Open WebUI is shutting down: run {str(run_id)[:20]}... keeps going "
                     f"({len(carried)} unsent message(s) dropped)")
            return
        previous = self._pending_cancel_aborts.pop(session_key, None)
        if previous is not None:
            if previous["task"] is not None:
                previous["task"].cancel()
            previous["resolved"].set()
            carried = list(previous["carried"]) + list(carried)
            attachments = list(previous["attachments"]) + list(attachments or [])
            waiting = list(previous["waiting"]) + [
                r for r in (waiting or []) if r not in previous["waiting"]]
            if previous["queue"] is not None and previous["queue"] is not queue:
                self.unregister_consumer(
                    session_key, previous["run_id"], queue=previous["queue"])
            if previous["run_id"] and previous["run_id"] != run_id:
                spawn_background(self._abort_cancelled_run(
                    session_key, previous["run_id"], previous["send_stop"]))
        if run_id:
            # The run's tail belongs to the claimer, never the stopped message.
            # A reply still waiting to be steered keeps `steer_pending`.
            target = self._run_targets.get(f"{session_key}:{run_id}") or {}
            if reply is not None and target.get("steer_pending"):
                reply = {**reply, "steer_pending": True}
            self.unregister_run_target(session_key, run_id)
            self.mark_delivered_live(session_key, run_id)

        entry = {"run_id": run_id, "queue": queue, "carried": list(carried),
                 "attachments": list(attachments or []),
                 "send_stop": send_stop, "task": None,
                 "resolved": asyncio.Event(), "run_text": run_text, "reply": reply,
                 "waiting": list(waiting or [])}

        def _release() -> None:
            # Read from the entry: `_keep_in_own_message` may have cleared it.
            if entry["queue"] is not None:
                self.unregister_consumer(session_key, entry["run_id"], queue=entry["queue"])
            if entry["carried"]:
                pipe_log(f"  stopped: dropping {len(entry['carried'])} unsent "
                         "message(s)")
                if _TURNS is not None:
                    _TURNS.end_unsent_replies(self, entry["waiting"], sent=False)
            if entry["run_id"]:
                spawn_background(
                    self._abort_cancelled_run(session_key, entry["run_id"], send_stop))

        entry["release"] = _release
        if grace_s <= 0:
            _release()
            return
        self._pending_cancel_aborts[session_key] = entry
        self._arm_parked_timer(session_key, entry, grace_s)
        if settle is None:
            entry["resolved"].set()
            return

        async def _settle() -> None:
            try:
                await settle()
            finally:
                entry["resolved"].set()
        spawn_background(_settle())

    def _arm_parked_timer(self, session_key: str, entry: dict,
                          wait_s: float) -> None:
        if entry["task"] is not None:
            entry["task"].cancel()

        async def _fire():
            await asyncio.sleep(wait_s)
            if self._pending_cancel_aborts.get(session_key) is not entry:
                return
            if entry.get("claiming"):
                # A follow-up is waiting: only an explicit Stop releases it now.
                return
            self._pending_cancel_aborts.pop(session_key, None)
            entry["resolved"].set()
            pipe_log(f"  no new message within {wait_s:g}s of the cancel: "
                     f"stopping run {str(entry['run_id'])[:20]}...")
            entry["release"]()

        entry["task"] = spawn_background(_fire())

    def settle_parked_turn(self, session_key: str, run_id: str | None,
                           intent: str | None, hold_s: float) -> None:
        """Apply the browser's answer about the cancel: "stop" stops now,
        "send_now" holds the run up to `hold_s` for the follow-up, anything
        else keeps the fallback timer."""
        entry = self._pending_cancel_aborts.get(session_key)
        if entry is None or entry["run_id"] != run_id:
            return
        if intent == "stop":
            self._pending_cancel_aborts.pop(session_key, None)
            if entry["task"] is not None:
                entry["task"].cancel()
            pipe_log(f"  cancel was a Stop: stopping run {str(run_id)[:20]}... now")
            entry["release"]()
        elif intent == "send_now":
            # The follow-up claims the run, not this answer: a writer opened now
            # would be overwritten by OWUI's own cancel handling.
            pipe_log(f"  cancel was a Send now: holding run {str(run_id)[:20]}... "
                     f"for the follow-up message (up to {hold_s:g}s)")
            self._arm_parked_timer(session_key, entry, hold_s)
        else:
            pipe_log("  cancel intent unknown (no page hook or no answer): "
                     "keeping the fallback window")
        entry["resolved"].set()

    def _keep_in_own_message(self, session_key: str, entry: dict) -> bool:
        """Hand a parked run to a turn writer in the message it was cancelled
        in, with the buffered events (ELI-158). False with no message or run."""
        reply, run_id, queue = entry.get("reply"), entry["run_id"], entry["queue"]
        if not reply or not run_id or not _TURNS:
            return False
        taken = queue.take_all() if queue is not None else []
        events = [m.get("payload") or {} for m in taken if m.get("type") == "event"]
        # Undo parking's delivered mark so events reach the writer.
        delivered = self._delivered_live.pop(f"{session_key}:{run_id}", None)
        if not _TURNS.hand_over(self, session_key, run_id,
                                reply={**reply, "events": events, "no_resume": True}):
            for m in taken:
                queue.put_control(m)
            if delivered is not None:
                self._delivered_live[f"{session_key}:{run_id}"] = delivered
            return False
        if queue is not None:
            self.unregister_consumer(session_key, run_id, queue=queue)
        entry.update(run_id=None, queue=None, reply=None, run_text=None)
        return True

    async def claim_cancelled_turn(self, session_key: str) -> dict | None:
        """Take over the turn `park_cancelled_turn` parked, if any.

        Waits for the page's cancel answer, so a Stop still in flight is
        honored; that query has its own bound (ELI-95). The caller then owns
        the returned run, queue, carried messages and waiting replies.
        """
        entry = self._pending_cancel_aborts.get(session_key)
        if entry is None:
            return None
        if not entry["resolved"].is_set():
            entry["claiming"] = True
            await entry["resolved"].wait()
        entry = self._pending_cancel_aborts.pop(session_key, None)
        if entry is None:
            return None
        if entry["task"] is not None:
            entry["task"].cancel()
        # The run stays in its own message; the new reply takes only the messages.
        self._keep_in_own_message(session_key, entry)
        return {"run_id": entry["run_id"], "queue": entry["queue"],
                "carried": list(entry["carried"]),
                "attachments": list(entry["attachments"]),
                "waiting": list(entry["waiting"]),
                "run_text": entry.get("run_text")}

    def seed_run_renderer(self, session_key: str, run_id: str,
                          queue: asyncio.Queue,
                          run_text: dict | None = None) -> None:
        """Bring a new shadow renderer level with an adopted run: its dedup
        baselines plus the events already waiting in `queue`."""
        key = f"{session_key}:{run_id}"
        renderer = self._run_renderers.get(key)
        if renderer is None:
            return
        renderer.seed(run_text)
        # A takeover writer rebuilds from after what earlier replies showed (ELI-147).
        self._run_targets[key]["shown"] = (run_text or {}).get("stream", "")
        for msg in list(getattr(queue, "_queue", ())):
            try:
                renderer.feed(msg.get("payload", {}))
            except Exception as ex:
                pipe_log(f"  shadow renderer seed failed: {ex}")

    async def send_stop(self, session_key: str):
        """Send the stronger /stop command for runtimes where chat.abort is incomplete."""
        try:
            resp = await _run_request(
                self, RUN_SEND,
                dict(
                    sessionKey=session_key,
                    message="/stop",
                    deliver=False,
                    idempotencyKey=f"stop-{uuid.uuid4()}",
                ),
                timeout=10,
            )
            pipe_log(f"  sent /stop fallback: {resp}")
        except asyncio.TimeoutError:
            pipe_log("  /stop fallback timed out")
        except Exception as e:
            pipe_log(f"  /stop fallback failed: {e}")

    def _connect_caps(self) -> list:
        """Connect caps. "plugin-approvals" makes the Gateway count this as a
        client that shows approvals, so only the admin turn-writing one sends it."""
        caps = ["tool-events"]
        if _APPROVAL_HOOKS and self.writes_turns and "operator.admin" in self.scopes:
            caps.append(PLUGIN_APPROVAL_CAP)
        return caps

    @property
    def handles_hooks(self) -> bool:
        """Whether this connection hands hook events to the Pipe. Every client
        gets its own copy, so only the live turn writer does (ELI-341)."""
        return self.writes_turns and not self._retired

    async def retire(self):
        """Step down for a newer deploy's connection. Existing consumers and
        waiting sends (ELI-172) are still served; then it closes for good."""
        self._retired = True
        _retire_turn_writer(self.writer_id)
        for writer in list(self._turn_writers.values()):
            writer.release()
        for pump in list(self._turn_pumps.values()):
            pump.queue.put_nowait(("retired", None))
        if self._serving():
            pipe_log(
                f"  retired gateway connection: serving {len(self._consumers)} "
                f"in-flight run(s) and {self._open_send_sections} queued message(s) before closing"
            )
            return
        await self.disconnect()

    async def disconnect(self):
        """Gracefully close the connection."""
        self._stopped = True
        if self._event_loop_task:
            self._event_loop_task.cancel()
            try:
                await self._event_loop_task
            except asyncio.CancelledError:
                pass
            self._event_loop_task = None
        if self._ws:
            try:
                await self._ws.close()
            except Exception:
                pass
            self._ws = None
        # No reply reads this connection's run messages any more.
        self._run_messages.clear()
        # A follow waiting on this connection reads again, through a live one.
        self._on_cron_changed()

    # ── Internal ────────────────────────────────────────────────────

    def _mark_event_gap(self) -> None:
        """Put a gap marker into every run queue. The Gateway has no event
        replay; a reply reading it hands over to the turn writer's transcript
        rebuild (ELI-147)."""
        n = 0
        for consumer in list(self._consumers.values()):
            for q in consumer.queues:
                q.put_control({"type": _GAP_MARKER_TYPE})
                n += 1
        if n:
            pipe_log(f"  marked an event gap in {n} run queue(s)")
        self._wake_session_waiters()

    def _mark_gateway_restart(self) -> None:
        """Tell every live reply that its run's Gateway process is gone."""
        for consumer in list(self._consumers.values()):
            for q in consumer.queues:
                q.put_control({"type": _RESTART_MARKER_TYPE})

    def _note_gateway_boot(self, boot_id: str | None) -> None:
        """Count a Gateway restart only when its boot id changes."""
        first = self.connection_epoch <= 1
        if self.gateway_boot_id is not None and boot_id != self.gateway_boot_id:
            self.gateway_restarts += 1
            pipe_log(f"  Gateway restarted (bootId {self.gateway_boot_id[:8]} -> {str(boot_id)[:8]})")
            self._mark_gateway_restart()
        elif not first:
            pipe_log(f"  reconnected to the same Gateway (bootId {str(boot_id)[:8]}); runs continue")
        self.gateway_boot_id = boot_id

    async def _connect_and_start(self):
        """Connect, handshake, and start the event loop task."""
        valves = self._valves()
        host, port, tls = self._pinned_endpoint or _parse_gateway_url(valves.GATEWAY_URL)
        ws_url = f"{'wss' if tls else 'ws'}://{host}:{port}"
        token = valves.GATEWAY_TOKEN

        if not token:
            raise GatewayError(
                "The GATEWAY_TOKEN valve is empty. Set it in Open WebUI under "
                "Admin Panel > Functions > OpenClaw Gateway > valves. The value "
                "is `gateway.auth.token` in your OpenClaw config."
            )

        self._ensure_identity(valves)

        pipe_log(f"Connecting to {ws_url}")
        # Every failure becomes GatewayError: pipe() catches only that.
        try:
            ws = await asyncio.wait_for(
                websockets.connect(ws_url, ping_interval=None,
                                   max_size=GATEWAY_WS_MAX_SIZE),
                timeout=_GATEWAY_CONNECT_TIMEOUT_S,
            )
        except asyncio.TimeoutError:
            raise GatewayError(
                f"No response from the OpenClaw Gateway at {host}:{port} within "
                f"{_GATEWAY_CONNECT_TIMEOUT_S:.0f}s. Check the GATEWAY_URL valve, "
                "and that the Open WebUI backend can reach that host (Open WebUI "
                "resolves it, not your browser)."
            )
        except (OSError, ValueError, websockets.exceptions.WebSocketException) as ex:
            # WebSocketException is not an OSError (a non-Gateway answering).
            # A refused connect is marked: a reconnecting turn waits through it.
            raise GatewayError(
                f"Could not connect to the OpenClaw Gateway at {host}:{port} "
                f"({type(ex).__name__}: {ex}). Is the Gateway running, and is "
                "the GATEWAY_URL valve pointing at it?"
                + (_container_loopback_hint(host, port, tls) if _refused_connect(ex) else ""),
                error={"code": GATEWAY_REFUSED_CODE} if _refused_connect(ex) else None,
            )

        challenge = json.loads(await asyncio.wait_for(ws.recv(), 10))
        if challenge.get("event") != "connect.challenge":
            raise GatewayError("Bad handshake -- expected connect.challenge")

        c = challenge["payload"]
        signed = _sign_challenge(self._ident, c["nonce"], c["ts"], token_str=token,
                                 scopes=self.scopes)

        auth = dict(token=token)
        if self._device_token:
            auth["deviceToken"] = self._device_token

        await ws.send(json.dumps(dict(
            type="req", id="1", method="connect", params=dict(
                minProtocol=4, maxProtocol=4,
                client=dict(id="webchat", version="1",
                            platform="linux", mode="cli",
                            displayName=_display_name(self._display_name, self._ident)),
                role="operator",
                scopes=self.scopes,
                auth=auth,
                device=signed,
                locale="en-US",
                userAgent="openclaw-owui-pipe/1.0",
                caps=self._connect_caps()
            )
        )))

        resp = await _connect_response(ws, "1")
        if not resp.get("ok"):
            err = resp.get("error")
            pipe_log(f"  connect rejected: {json.dumps(err)[:500]}")
            raise GatewayError(
                _explain_connect_rejection(
                    str((err or {}).get("message", "connect failed")),
                    device_id=(self._ident or {}).get("id"),
                ),
                error=err if isinstance(err, dict) else None,
            )

        hello_ok = resp.get("payload", {})
        if hello_ok.get("auth", {}).get("deviceToken"):
            self._device_token = hello_ok["auth"]["deviceToken"]
            self._save_device_token(valves)
            pipe_log(f"Device token captured: {self._device_token[:20]}...")

        self._ws = ws
        self._endpoint = (host, port, tls)
        self._frame_seq = None  # frame seq counts per socket
        tick_ms = (hello_ok.get("policy") or {}).get("tickIntervalMs")
        if isinstance(tick_ms, (int, float)) and tick_ms > 0:
            self._tick_interval_s = tick_ms / 1000
        self._reconnect_attempt = 0
        self.connection_epoch += 1
        self._thinking_note_shown.clear()
        self.gateway_version = (hello_ok.get("server") or {}).get("version")
        self.gateway_max_image_bytes = _hello_max_image_bytes(hello_ok)
        features = hello_ok.get("features") or {}
        self.gateway_methods = frozenset(features.get("methods") or ())
        self.gateway_events = frozenset(features.get("events") or ())
        self._note_gateway_boot((hello_ok.get("server") or {}).get("bootId"))
        pipe_log(
            f"Connected to Gateway (persistent) [epoch {self.connection_epoch}]"
        )
        # The event loop renews subscriptions: their responses need it reading.
        # Never spawn the event loop here; `_reconnect` calls this from inside it.
        self._subscriptions_stale = not self.requests_only

    def _identity_path(self, valves):
        return os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), f"{self._identity_name}.json")

    def _device_token_path(self, valves):
        suffix = self._identity_name[len("identity"):]
        return os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), f"device-token{suffix}.json")

    def _load_device_token(self, valves):
        if self._device_token:
            return
        data = _read_json_file(self._device_token_path(valves))
        if isinstance(data, dict) and data.get("deviceToken"):
            self._device_token = data["deviceToken"]
            pipe_log("Using persisted device token")

    def _save_device_token(self, valves):
        if not self._device_token:
            return
        _write_json_file(
            self._device_token_path(valves),
            {"deviceToken": self._device_token, "deviceId": self._ident.get("id")},
        )

    def _ensure_identity(self, valves):
        """Load the device identity: state-dir file, then the DEVICE_IDENTITY
        valve, else generate once and persist."""
        if self._ident:
            return
        identity_path = self._identity_path(valves)
        ident = _read_json_file(identity_path)
        if ident and ident.get("id") and ident.get("privateKey"):
            self._ident = ident
            pipe_log(f"Using device identity from {identity_path}")
            self._load_device_token(valves)
            return

        # The valve is the main identity only.
        if self._identity_name == "identity" and getattr(valves, "DEVICE_IDENTITY", ""):
            ident = _parse_device_identity(valves.DEVICE_IDENTITY)
            if ident and ident.get("id") and ident.get("privateKey"):
                self._ident = ident
                _write_json_file(identity_path, ident)
                pipe_log("Using device identity from valve and persisted it to state dir")
                self._load_device_token(valves)
                return
            pipe_log("Failed to parse DEVICE_IDENTITY valve; generating new identity")

        self._ident = _generate_device_identity()
        _write_json_file(identity_path, self._ident)
        pipe_log(f"Generated new device identity and saved it to {identity_path}")
        if self._identity_name != "identity":
            return
        print(
            f"DEVICE_IDENTITY={json.dumps(self._ident, separators=(',',':'))}",
            flush=True
        )

    async def _event_loop(self):
        """Read and dispatch WS messages. The ONLY caller of `recv()`; it
        reconnects in place, since a second loop task would race on recv."""
        while not self._stopped:
            try:
                if self._ws is None:
                    await self._reconnect()
                    continue
                if self._subscriptions_stale:
                    self._subscriptions_stale = False
                    spawn_background(self._subscribe_all())
                msg = json.loads(await asyncio.wait_for(self._ws.recv(),
                                                        timeout=2 * self._tick_interval_s))

                # The Gateway silently skips `seq` for dropIfSlow events it
                # dropped on a slow client; treat a skip like a reconnect gap.
                _seq = msg.get("seq")
                if msg.get("type") == "event" and isinstance(_seq, int):
                    if self._frame_seq is not None and _seq != self._frame_seq + 1:
                        pipe_log(f"  frame seq gap: expected {self._frame_seq + 1}, got {_seq}")
                        self._mark_event_gap()
                        if _TURNS:
                            spawn_background(_TURNS.resync(self))
                    self._frame_seq = _seq

                if msg.get("type") == "res":
                    req_id = msg.get("id")
                    fut = self._pending_reqs.get(req_id)
                    if fut and not fut.done():
                        if msg.get("ok") is False:
                            err = msg.get("error", {})
                            fut.set_exception(
                                GatewayError(
                                    err.get("message")
                                    or err.get("code")
                                    or "request failed",
                                    error=err if isinstance(err, dict) else None,
                                )
                            )
                        else:
                            fut.set_result(msg.get("payload", {}))
                    continue

                if msg.get("event") == "tick" or msg.get("payload", {}).get("isHeartbeat"):
                    if _TURNS:
                        _TURNS.note_heartbeat(self, msg.get("payload") or {})
                    continue

                # Tool events come as `agent` to the run's starter and as
                # `session.tool` to subscribers (ELI-92); one path, first wins.
                if msg.get("type") == "event" and msg.get("event") == "sessions.changed":
                    self._on_sessions_changed(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "chat.metadata.changed":
                    if _SLASH_PROMPTS_HOOK and self.handles_hooks:
                        _SLASH_PROMPTS_HOOK(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "shutdown":
                    self._on_shutdown(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "question.requested":
                    if _QUESTION_HOOKS and self.handles_hooks:
                        _QUESTION_HOOKS[0](self, msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "question.resolved":
                    # Retired connections too: a pre-deploy question lives in
                    # the old module. Each registry pops its own ids.
                    if _QUESTION_HOOKS and self.writes_turns:
                        _QUESTION_HOOKS[1](msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "plugin.approval.requested":
                    if _APPROVAL_HOOKS and self.handles_hooks:
                        _APPROVAL_HOOKS[0](self, msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "plugin.approval.resolved":
                    # Retired connections too, as for `question.resolved`.
                    if _APPROVAL_HOOKS and self.writes_turns:
                        _APPROVAL_HOOKS[1](msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "session.message":
                    self._on_session_message(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "session.tool":
                    # Same payload as an `agent` tool event, so same path.
                    p = msg.get("payload") or {}
                    msg = {"type": "event", "event": "agent", "payload": {
                        k: p[k] for k in ("runId", "sessionKey", "sessionId", "stream",
                                          "data", "seq", "ts") if k in p}}
                if msg.get("type") == "event" and msg.get("event") == "cron":
                    self.note_cron_event(msg.get("payload") or {})
                    self._on_cron_changed()
                    continue
                if msg.get("type") != "event" or \
                   msg.get("event") not in ("agent", "chat"):
                    continue

                await self.dispatch_run_event(msg)

            except asyncio.TimeoutError:
                # No tick for two intervals: a half-open socket.
                pipe_log(f"  tick timeout: no frame for {2 * self._tick_interval_s:.0f}s, "
                         "reconnecting")
                transport = getattr(self._ws, "transport", None)
                if transport is not None:
                    transport.abort()
                self._ws = None
                self._mark_event_gap()
            except websockets.exceptions.ConnectionClosed as e:
                pipe_log(f"WS disconnected -- reconnecting... ({_close_detail(e)})")
                self._ws = None
                self._mark_event_gap()
            except asyncio.CancelledError:
                break
            except Exception as e:
                pipe_log(f"Event loop error: {e!r}")
                self._ws = None
                try:
                    self._mark_event_gap()
                except Exception as ex:  # the loop outlives any one failure
                    pipe_log(f"  event gap marking failed: {ex!r}")

    async def _connect_once_started(self):
        """`_connect_and_start`, retrying while a just-started Gateway refuses
        with reason "startup-sidecars", after the wait it names, up to
        STARTUP_REFUSAL_WAIT_S."""
        deadline = time.monotonic() + STARTUP_REFUSAL_WAIT_S
        told = False
        while True:
            try:
                return await self._connect_and_start()
            except GatewayError as ex:
                retry_ms = _gateway_starting_retry_ms(ex)
                if retry_ms is None or self._stopped or time.monotonic() + retry_ms / 1000 > deadline:
                    raise
                if not told:
                    told = True
                    pipe_log(f"  the Gateway is starting; connecting again as it asks (every {retry_ms} ms)")
                await asyncio.sleep(retry_ms / 1000)

    async def _reconnect(self):
        """Reconnect with backoff, in place inside `_event_loop`. Must never
        spawn another `_event_loop` task."""
        while not self._stopped:
            self._reconnect_attempt += 1
            delay = 1 if self._turns_awaiting_gateway else min(2 ** (self._reconnect_attempt - 1),
                                                               self._max_backoff)
            pipe_log(f"  reconnect in {delay}s (attempt {self._reconnect_attempt})")
            try:
                # A turn waiting for the connection ends the wait (ensure_connected).
                await asyncio.wait_for(self._reconnect_now.wait(), delay)
                pipe_log("  reconnecting now: a message is waiting for the connection")
            except asyncio.TimeoutError:
                pass
            self._reconnect_now.clear()
            if self._stopped:
                self._answer_reconnect_waiters(GatewayError("gateway connection stopped"))
                return
            try:
                await self._connect_once_started()
                self._answer_reconnect_waiters(None)
                return
            except Exception as e:
                pipe_log(f"  reconnect failed: {e}")
                self._ws = None
                self._answer_reconnect_waiters(e)

    def _answer_reconnect_waiters(self, error) -> None:
        """Hand a reconnect attempt's outcome to the turns waiting on it."""
        waiters, self._reconnect_waiters = self._reconnect_waiters, []
        self._reconnect_now.clear()   # asked during this attempt: it is the answer
        for waiter in waiters:
            if not waiter.done():
                waiter.set_result(error)


# Protocol sentinels for "no user-visible reply" (docs/tools/subagents.md),
# never shown in a chat.
_SILENT_SENTINELS = {"ANNOUNCE_SKIP", "NO_REPLY", "no_reply"}


# How far back to look for a run's closing message; later runs may follow it.
RUN_TEXT_HISTORY_LIMIT = 60
# For rebuilding a whole run: each tool call is a message of its own.
RUN_HISTORY_LIMIT = 600


def _idempotency_keys(message) -> tuple[str, str]:
    """A message's `idempotencyKey`, top level and under `__openclaw`."""
    if not isinstance(message, dict):
        return "", ""
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    return str(message.get("idempotencyKey") or ""), str(meta.get("idempotencyKey") or "")


_ASSISTANT_ROLE = "assistant"
# What a reply reads from its run's messages: the usage, image and
# attachment_error blocks (ELI-322, ELI-328), and the keys that name the run.
_DIGEST_BLOCK_TYPES = ("image", "attachment_error")
_DIGEST_FIELDS = ("role", "usage", "runId", "idempotencyKey")
_DIGEST_META_FIELDS = ("runId", "idempotencyKey")


def _run_message_digest(message: dict) -> dict:
    """The part of a stored message a reply reads, not its text or tool calls."""
    digest = {k: message[k] for k in _DIGEST_FIELDS if k in message}
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    digest["__openclaw"] = {k: meta[k] for k in _DIGEST_META_FIELDS if k in meta}
    content = message.get("content")
    digest["content"] = [b for b in content if isinstance(b, dict) and b.get("type") in _DIGEST_BLOCK_TYPES] \
        if isinstance(content, list) else []
    return digest
_CLI_ASSISTANT_KEY_PREFIX = "cli-assistant:"
_ASSISTANT_MEDIA_KEY_PART = ":assistant-media"


def _transcript_run_ids(message: dict) -> set[str]:
    """The runs a stored message belongs to: its `runId`, a CLI reply's
    `cli-assistant:<run>` key, or the media message's `<run>:assistant-media[:n]`
    key (which has no `runId`, 2026.10.10)."""
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    ids = {str(meta.get("runId") or ""), str(message.get("runId") or "")}
    for key in _idempotency_keys(message):
        if key.startswith(_CLI_ASSISTANT_KEY_PREFIX):
            ids.add(key[len(_CLI_ASSISTANT_KEY_PREFIX):])
        elif _ASSISTANT_MEDIA_KEY_PART in key:
            ids.add(key.split(_ASSISTANT_MEDIA_KEY_PART, 1)[0])
    ids.discard("")
    return ids


def _history_text_for_run(history: dict, run_id: str) -> tuple[bool, str | None]:
    """(found, text) of a run's closing message, by its `cli-assistant:<runId>`
    key. text is None when the run ended silent."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id:
        return False, None
    wanted = {run_id, f"cli-assistant:{run_id}"}
    for message in reversed(messages):
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        if not set(_idempotency_keys(message)) & wanted:
            continue
        text = ((_history_item(message) or {}).get("text") or "").strip()
        if not text:
            fallback = message.get("openclawStreamFallback")
            if isinstance(fallback, dict):
                text = str(fallback.get("replacementText") or "").strip()
        return True, (text if text and text not in _SILENT_SENTINELS else None)
    return False, None


def _usage_prompt_tokens(usage) -> int | None:
    """The context a model call filled, as OpenClaw's
    `deriveContextPromptTokens` counts it, or None."""
    if not isinstance(usage, dict):
        return None
    context = usage.get("contextUsage") if isinstance(usage.get("contextUsage"), dict) else {}
    if context.get("state") == "unavailable":
        return None
    if context.get("state") == "available":
        prompt = context.get("promptTokens")
        return prompt if isinstance(prompt, (int, float)) and prompt > 0 else None
    nums = {k: usage.get(k) if isinstance(usage.get(k), (int, float)) else 0
            for k in ("input", "cacheRead", "cacheWrite", "output")}
    prompt = nums["input"] + nums["cacheRead"] + nums["cacheWrite"]
    if prompt > 0:
        return prompt
    total = usage.get("totalTokens", usage.get("total"))
    if isinstance(total, (int, float)) and total - nums["output"] > 0:
        return total - nums["output"]
    return None


def _history_usage_for_run(history: dict, run_id: str) -> dict | None:
    """The `usage` of one run's last model call in `chat.history`, or None."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id:
        return None
    wanted = {run_id, f"cli-assistant:{run_id}"}
    for message in reversed(messages):
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
        ids = {*_idempotency_keys(message), str(meta.get("runId") or ""), str(message.get("runId") or "")}
        if ids & wanted and _usage_prompt_tokens(message.get("usage")):
            return message["usage"]
    return None


def _history_latest_prompt_tokens(history: dict) -> int | None:
    """Prompt tokens of the newest assistant message reporting a usage."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    for message in reversed(messages):
        if isinstance(message, dict) and message.get("role") == "assistant":
            prompt = _usage_prompt_tokens(message.get("usage"))
            if prompt:
                return prompt
    return None


def _history_renderer(messages: list) -> "_TurnRenderer":
    """A `_TurnRenderer` fed from `chat.history` instead of live events (ELI-88/90/92)."""
    r = _TurnRenderer()
    for payload in _history_events(messages):
        r.feed(payload)
    r.flush()
    return r


def _history_events(messages: list):
    """`chat.history` messages as the live events that wrote them: the one
    transcript parser (ELI-147). Handles both shapes: claude-cli imports
    (`toolcall`/`tool_result` blocks) and the Gateway's own runtime
    (`toolCall` blocks plus `toolResult` messages).

    A claude-cli closer repeats its run's text, so it counts only when the
    run carried none, and in place. Text after a tool call gets the live
    stream's separator (`sawToolUseSinceText`). A `message` tool send's
    duplicate record is shown once (ELI-324)."""
    text = ""                 # what the events so far said
    sent_by_tool: set[str] = set()   # texts the agent's `message` tool already delivered
    run_text = False          # this run carried text before its closer
    tool_since_text = False   # the Gateway's `sawToolUseSinceText`
    reply_ended = False       # a reply of this run ended since the last text
    for message in messages:
        if not isinstance(message, dict):
            continue
        role = message.get("role")
        if role == "toolResult" and message.get("toolCallId"):
            yield _history_tool_result(message["toolCallId"], message.get("toolName"),
                                       message.get("content"), message.get("isError"))
            continue
        if _is_closing_message(message):
            closing = ((_history_item(message) or {}).get("text") or "").strip()
            if not run_text and closing and closing not in _SILENT_SENTINELS:
                delta = _message_boundary_separator(text, closing) + closing
                text, tool_since_text = text + delta, False
                yield {"stream": "assistant", "data": {"delta": delta}}
            run_text = False
            continue
        content = message.get("content")
        if isinstance(content, str):
            content = [{"type": "text", "text": content}]
        for block in content if isinstance(content, list) else []:
            if not isinstance(block, dict):
                continue
            kind = block.get("type")
            if kind == "text" and block.get("text") and role == "assistant":
                if _is_message_tool_mirror(message):
                    sent_by_tool.add(block["text"].strip())
                elif block["text"].strip() in sent_by_tool:
                    continue
                lead = (_message_boundary_separator(text, block["text"])
                        if tool_since_text or reply_ended else "")
                text, tool_since_text, reply_ended = text + lead + block["text"], False, False
                run_text = run_text or bool(block["text"].strip())
                yield {"stream": "assistant", "data": {"delta": lead + block["text"]}}
            elif kind in ("toolcall", "toolCall") and block.get("id") and role == "assistant":
                tool_since_text = True
                yield {"stream": "tool", "data": {
                    "phase": "start", "name": block.get("name", ""),
                    "toolCallId": block["id"], "args": block.get("arguments") or {}}}
            elif kind == "tool_result" and block.get("tool_use_id"):
                yield _history_tool_result(block["tool_use_id"], block.get("name"),
                                           block.get("content"), block.get("is_error"))
        # More text after a native reply ended answers a steered message (ELI-271).
        reply_ended = reply_ended or bool(_run_closed_by(message))


def _history_tool_result(tool_call_id: str, name, content, is_error) -> dict:
    return {"stream": "tool", "data": {
        "phase": "result", "name": name or "", "toolCallId": tool_call_id,
        "result": "" if content is None else content, "isError": is_error is True}}


def _message_boundary_separator(previous: str, nxt: str) -> str:
    """The newlines the Gateway inserts between two claude-cli assistant
    messages (`missingMessageBoundarySeparator`): enough for a blank line."""
    if not previous:
        return ""
    trailing = len(previous[-2:]) - len(previous[-2:].rstrip("\n"))
    leading = len(nxt[:2]) - len(nxt[:2].lstrip("\n"))
    return "\n" * max(0, 2 - trailing - leading)


def _is_message_tool_mirror(message) -> bool:
    """The transcript copy of a `message` tool send (`<runId>:message-tool:...`)."""
    return any(":message-tool:" in k for k in _idempotency_keys(message))


def _is_closing_message(message) -> bool:
    """A run's closing assistant message (`cli-assistant:<runId>`)."""
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return False
    return any(k.startswith("cli-assistant:") for k in _idempotency_keys(message))


def _run_closed_by(message) -> str | None:
    """The run a message closes, or None: claude-cli's `cli-assistant:<runId>`,
    or a native run's assistant message that did not stop for a tool call."""
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return None
    key = next((k for k in _idempotency_keys(message) if k.startswith("cli-assistant:")), "")
    if key:
        return key[len("cli-assistant:"):]
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    if meta.get("runId") and message.get("stopReason") not in (None, "toolUse"):
        return str(meta["runId"])
    return None


def _deepest_leaf_id(messages: dict, start_id: str | None) -> str | None:
    """Walk `childrenIds` (newest child) from `start_id` to the leaf.

    OWUI's `history.currentId` is only a view pointer and can point at an
    ancestor; anchoring there would create a sibling variant group.
    """
    node_id = start_id
    seen: set[str] = set()
    for _ in range(10_000):
        if not node_id or node_id in seen:
            break
        seen.add(node_id)
        node = messages.get(node_id) or {}
        children = node.get("childrenIds") or []
        if not children:
            break
        node_id = children[-1]
    return node_id


def _is_forwarded_turn(message) -> bool:
    """A forwarded user turn, which `chat.history` shows as role "assistant"
    since OpenClaw 2026.10.2 (`hasForwardedMessageProvenance`)."""
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return False
    key = next((k for k in _idempotency_keys(message) if k), "")
    prov = message.get("provenance") if isinstance(message.get("provenance"), dict) else {}
    forwarded = ((prov.get("kind"), prov.get("sourceTool")) == ("inter_session", "sessions_send")
                 or (prov.get("kind"), prov.get("sourceTool")) == ("internal_system", "cron"))
    return key.endswith(":user") and len(key) > 5 and forwarded


def _transcript_roles(messages: list) -> list:
    """Put forwarded user turns back in role "user" (GH #24, OpenClaw 2026.10.2+)."""
    return [{**m, "role": "user"} if _is_forwarded_turn(m) else m for m in messages]


def _transcript_commit_order(messages: list) -> list:
    """Move each sent user message to where its run took it in.

    The Gateway stores a message when sent, but claude-cli takes it in later,
    so messages written meanwhile would read as its answer. Its commit time
    (`recordTimestampMs`) is the boundary; its imported copy stays right
    after it. Processed from the last one back.
    """
    out = list(messages)
    for message in reversed([m for m in messages if _committed_after_sent(m) is not None]):
        at = out.index(message)
        committed = _committed_after_sent(message)
        end = at + 1
        while end < len(out) and _commit_ms(out[end]) is not None and (
                _commit_ms(out[end]) < committed
                or (_commit_ms(out[end]) == committed and not _history_user_run_id(out[end]))):
            end += 1
        own = [i for i in range(at + 1, end) if _copy_of(out[i], message)]
        end = own[-1] if own else end
        out.insert(end - 1, out.pop(at))
    return out


def _commit_ms(message) -> float | None:
    """When `message` joined the run: a sent message's commit, else its time."""
    if not isinstance(message, dict):
        return None
    committed = _committed_after_sent(message)
    at = message.get("timestamp")
    return committed if committed is not None else (at if isinstance(at, (int, float)) else None)


def _committed_after_sent(message) -> float | None:
    """A sent message's `recordTimestampMs`, if later than its timestamp."""
    if not _history_user_run_id(message):
        return None
    committed, sent = (message.get("__openclaw") or {}).get("recordTimestampMs"), message.get("timestamp")
    if not isinstance(committed, (int, float)) or not isinstance(sent, (int, float)) or committed <= sent:
        return None
    return committed


def _copy_of(message, sent: dict) -> bool:
    """`message` is the CLI runtime's imported copy of `sent`."""
    if not isinstance(message, dict) or message.get("role") != "user" or _history_user_run_id(message):
        return False
    text = (_history_item(sent) or {}).get("text", "").strip()
    return bool(text) and (_history_item(message) or {}).get("text", "").strip().endswith(text)


def _history_user_run_id(message) -> str | None:
    """The run a `chat.send` user message (`<runId>:user`) started, else None."""
    if not isinstance(message, dict) or message.get("role") != "user":
        return None
    key = next((k for k in _idempotency_keys(message) if k), "")
    return key[:-len(":user")] if key.endswith(":user") and len(key) > 5 else None


# Read-only shim (ELI-100): pre-ELI-100 messages embed a task id as an HTML
# comment, so old messages still open straight into that task's drawer.
_SUBAGENT_TASK_ID_MARKER_RE = re.compile(r"<!--\s*openclaw:taskId=([^\s>]+?)\s*-->")


_gateway_connection: _GatewayConnection | None = None
_gateway_init_lock = asyncio.Lock()

# Stashed on OWUI's stable `open_webui.socket.main` so the next deploy (a new
# module, no teardown hook) can find and retire this one.
_STALE_CONN_ATTR = "_openclaw_gateway_connection_v1"


def _function_module_prefix(module_name: str) -> str:
    """`function_<id>_<hex>` -> `function_<id>`, OWUI 0.12's per-load module
    name, so older loads of this Function are told from the Status Action."""
    head, sep, tail = module_name.rpartition("_")
    if sep and len(tail) == 32 and all(c in "0123456789abcdef" for c in tail):
        return head
    return module_name


def _orphaned_gateway_connections(current) -> list:
    """Live `_GatewayConnection`s of OLDER loads of this Function, found on
    the heap: the stash names only the previous one."""
    import gc
    prefix = _function_module_prefix(__name__)
    if not prefix.startswith("function_"):
        return []
    found = []
    for obj in gc.get_objects():
        cls = type(obj)
        if cls.__name__ != "_GatewayConnection" or obj is current:
            continue
        mod = getattr(cls, "__module__", "") or ""
        if mod == __name__ or _function_module_prefix(mod) != prefix:
            continue
        found.append(obj)
    return found


def _end_replies_of(stale) -> None:
    """A pinned connection's socket is gone while replies still read it. No
    event can reach them now, it has no turn writer to hand them to
    (`_hand_over_run` refuses a retired connection) and the successor leaves a
    run alone while `_served_by_retired` finds its consumer, so each would stay
    generating for good. Each reply gets its run's own end signal and its
    consumer is unregistered: it finishes with what it showed, and this load's
    turn writer writes the rest of the run into the same message (ELI-150)."""
    for consumer in list(getattr(stale, "_consumers", {}).values()):
        end = _event_frame({"sessionKey": consumer.session_key, "runId": consumer.run_id,
                            "stream": "lifecycle", "data": {"phase": "end"}})
        for queue in list(consumer.queues):
            put = getattr(queue, "put_control", queue.put_nowait)
            put(end)
            stale.unregister_consumer(consumer.session_key, consumer.run_id, queue=queue)


def _pin_shut(stale) -> None:
    """Keep an older build's connection from connecting again, but keep its
    open socket read. The connection's own event loop is that socket's only
    reader: it answers the Gateway's pings and carries the runs the connection
    still serves. It ends when the socket drops (a dial is then the only thing
    left to do) or when the connection closes itself once idle
    (`_close_if_retired_and_idle`). Setting `_stopped` here would end the old
    loop after its current `recv()` and leave the socket open and unread, a
    CLOSE-WAIT socket per pin (ELI-369). The old code cannot be changed, so its
    entry points are replaced from this side.

    It admits no new work: `ensure_connected` refuses even with the socket
    open (a retired producer of the old build, such as its channel watcher,
    would otherwise start a run here). When the socket is gone the replies
    still reading it are ended (`_end_replies_of`)."""
    def _refusal() -> GatewayError:
        return GatewayError("gateway connection retired by a newer deploy")

    def _gone() -> GatewayError:
        stale._stopped = True       # a dial was wanted: nothing is left to read
        _end_replies_of(stale)
        answer = getattr(stale, "_answer_reconnect_waiters", None)
        error = _refusal()
        if answer is not None:
            answer(error)
        return error

    async def _ensure_connected(*_a, **_k):
        ws, task = getattr(stale, "_ws", None), getattr(stale, "_event_loop_task", None)
        if ws is not None and task is not None and not task.done():
            raise _refusal()
        raise _gone()

    async def _connect_and_start(*_a, **_k):
        raise _gone()

    async def _reconnect(*_a, **_k):
        _gone()

    stale.ensure_connected = _ensure_connected
    stale._connect_and_start = _connect_and_start
    stale._reconnect = _reconnect


async def _retire_stale_connection(stale) -> None:
    retire = getattr(stale, "retire", None)
    if retire is not None:
        await asyncio.wait_for(retire(), timeout=5)
        if not getattr(stale, "sends_display_name", False):
            # It still serves its runs, but a reconnect by its old code would
            # connect nameless on the shared device and wipe the stored name.
            _pin_shut(stale)
        return
    # Pre-`retire()` build: it serves no run past this, so it closes now; pin
    # its entry points shut so it can't revive.
    stale._stopped = True
    _pin_shut(stale)
    await asyncio.wait_for(stale.disconnect(), timeout=5)


# Earlier loads' connections this load retired. One may still stream a reply
# (`retire`); its run's events reach this load's connection too (ELI-150).
_retired_connections: list = []


def _served_by_retired(payload: dict) -> bool:
    _retired_connections[:] = [c for c in _retired_connections if getattr(c, "_consumers", None)]
    return any(c.consumers_for_event(payload) for c in _retired_connections)


async def _reap_stale_gateway_connection() -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    stale_conns = []
    stale = getattr(_owui_socket_main, _STALE_CONN_ATTR, None)
    if stale is not None and stale is not _gateway_connection:
        stale_conns.append(stale)
    try:
        for obj in _orphaned_gateway_connections(_gateway_connection):
            if not any(obj is s for s in stale_conns):
                stale_conns.append(obj)
    except Exception as ex:
        pipe_log(f"  orphan scan failed (non-fatal): {ex}")
    for conn in stale_conns:
        try:
            await _retire_stale_connection(conn)
            _retired_connections.append(conn)
            pipe_log(
                "  reaped stale gateway connection from a previous deploy "
                f"({type(conn).__module__})"
            )
        except Exception as ex:
            pipe_log(f"  failed to reap stale gateway connection (non-fatal): {ex}")


def _remember_gateway_connection(conn: _GatewayConnection) -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    setattr(_owui_socket_main, _STALE_CONN_ATTR, conn)


async def _replace_moved_connection(old: _GatewayConnection, make) -> _GatewayConnection:
    """Connect `make()` to the new GATEWAY_URL, then retire `old` (pinned to
    its endpoint). Retiring only after success keeps a mistyped valve from
    breaking the working connection."""
    new = make()
    await new.ensure_connected()
    old._pinned_endpoint = old._endpoint
    try:
        await _retire_stale_connection(old)
        _retired_connections.append(old)
    except Exception as ex:
        pipe_log(f"  failed to retire the connection to the old Gateway endpoint (non-fatal): {ex}")
    pipe_log(f"  GATEWAY_URL changed: now connected to {new._endpoint[0]}:{new._endpoint[1]}"
             f"{' (TLS)' if new._endpoint[2] else ''}")
    return new


async def _get_gateway_connection(valves_getter) -> _GatewayConnection:
    """Get or create the singleton Gateway connection."""
    global _gateway_connection
    conn = _gateway_connection
    if conn is not None and not conn.endpoint_moved():
        await conn.ensure_connected()
        return conn
    async with _gateway_init_lock:
        conn = _gateway_connection
        if conn is None:
            await _reap_stale_gateway_connection()
            conn = _GatewayConnection(valves_getter)
            await conn.ensure_connected()
        elif not conn.endpoint_moved():
            await conn.ensure_connected()
            return conn
        else:
            conn = await _replace_moved_connection(conn, lambda: _GatewayConnection(valves_getter))
        _gateway_connection = conn
        _remember_gateway_connection(conn)
        return conn


# ---------------------------------------------------------------------------
# Owner users (OWNER_USERS valve)
# ---------------------------------------------------------------------------
# Turns sent by the main (operator.admin) connection are the owner's. Run
# requests for non-owner chats go over a RESTRICTED_SCOPES connection; reading
# and rendering stay on the main one, the only writer into OWUI (ELI-100).

_restricted_connection: "_GatewayConnection | None" = None
_restricted_init_lock = asyncio.Lock()


def _new_restricted_connection(valves_getter) -> "_GatewayConnection":
    return _GatewayConnection(valves_getter, writes_turns=False, scopes=RESTRICTED_SCOPES,
                              identity_name="identity-restricted", requests_only=True,
                              display_name=RESTRICTED_DISPLAY_NAME)


async def _get_restricted_connection(valves_getter) -> "_GatewayConnection":
    """The connection for non-owner users' run requests."""
    global _restricted_connection
    async with _restricted_init_lock:
        conn = _restricted_connection
        if conn is None:
            conn = _new_restricted_connection(valves_getter)
            await conn.ensure_connected()
        elif conn.endpoint_moved():
            conn = await _replace_moved_connection(conn, lambda: _new_restricted_connection(valves_getter))
        else:
            await conn.ensure_connected()
        _restricted_connection = conn
        return conn


async def _owui_call(fn, *args):
    out = fn(*args)
    return await out if asyncio.iscoroutine(out) else out


async def _owner_users_setting(conn) -> "str | None":
    """OWNER_USERS, or None when unreadable. The Status Action reads it from
    the Pipe function's saved valves."""
    valves_getter = getattr(conn, "_valves", None)
    raw = getattr(valves_getter() if callable(valves_getter) else None, "OWNER_USERS", None)
    if isinstance(raw, str):
        return raw
    try:
        from open_webui.models.functions import Functions
    except ImportError:
        return ""  # not inside Open WebUI: there is no valve to set
    try:
        found = ""
        for fn in await _owui_call(Functions.get_functions_by_type, "pipe") or []:
            saved = await _owui_call(Functions.get_function_valves_by_id, fn.id) or {}
            if isinstance(saved, dict) and saved.get("OWNER_USERS"):
                found = ",".join(x for x in (found, saved["OWNER_USERS"]) if x)
        return found
    except Exception as ex:
        pipe_log(f"  owner users: could not read the Pipe's valves ({ex!r}); treating as not owner")
        return None


async def _user_email(user_id: str) -> "str | None":
    try:
        from open_webui.models.users import Users
        user = await _owui_call(Users.get_user_by_id, user_id)
        return getattr(user, "email", None) if user else None
    except Exception:
        return None


async def _sender_is_owner(conn, session_key: str) -> bool:
    """Whether a run request for `session_key` may go out as the owner's.
    Undecidable means not the owner's."""
    raw = await _owner_users_setting(conn)
    if raw is None:
        return False
    owners = _parse_owner_users(raw)
    if not owners:
        return True
    if _CHANNEL_KEY_RE.match(session_key or ""):
        # Shared thread: always restricted, so its tool list stays stable.
        return False
    m = _OWUI_KEY_USER.match(session_key or "")
    if not m:
        return False
    user_id = m.group(1)
    if user_id.lower() in owners:
        return True
    return _is_owner_user(owners, user_id, await _user_email(user_id))


# The Gateway reads a message as a command ("/stop", "/model x") when its trimmed
# text starts with this (its chat.send handler).
GATEWAY_COMMAND_PREFIX = "/"


def _is_gateway_command(message: str) -> bool:
    """Whether the Gateway reads `message` as a command rather than a prompt."""
    return message.lstrip().startswith(GATEWAY_COMMAND_PREFIX)


# The commands that start the session afresh (the Gateway's RESET_COMMAND_RE).
GATEWAY_RESET_COMMAND_RE = re.compile(r"^/(new|reset)(?:\s|$)", re.IGNORECASE)


def _is_gateway_reset(message: str) -> bool:
    """Whether `message` is a command that gives the session a fresh start."""
    return bool(GATEWAY_RESET_COMMAND_RE.match(message.strip()))


def _close_frame_text(frame) -> str:
    return f"{frame.code} {frame.reason!r}" if frame is not None else "none"


def _close_detail(e) -> str:
    """Both close frames of a closed connection (ELI-369). websockets reports
    code 1006 whenever no frame came back, also when this side failed the
    connection itself (1009 a frame over max_size, 1007 a text frame not
    UTF-8): only the frame it sent names that. The code itself is left out:
    it is the received frame's, or 1006 when none came, and websockets 13+
    deprecates reading it."""
    return (f"sent {_close_frame_text(getattr(e, 'sent', None))}, "
            f"received {_close_frame_text(getattr(e, 'rcvd', None))}")


def _non_owner_send_params(params: dict) -> dict:
    """A chat.send for the restricted connection: admin-only fields dropped,
    the metadata receipt prepended to the message as the Gateway would. A
    command ("/stop") stays as typed, since commands are read from raw text."""
    dropped = [f for f in ADMIN_ONLY_SEND_FIELDS if f in params]
    if not dropped:
        return params
    out = {k: v for k, v in params.items() if k not in dropped}
    receipt = params.get("systemProvenanceReceipt")
    message = out.get("message") or ""
    moved = isinstance(receipt, str) and bool(receipt) and not _is_gateway_command(message)
    if moved:
        out["message"] = "\n\n".join(p for p in (receipt, message) if p)
    pipe_log(f"  non-owner chat.send: left out admin-only fields {dropped}"
             + ("; metadata block moved into the message" if moved else ""))
    return out


async def _run_request(conn, method: str, params: dict, *, timeout: float = 10,
                       owner: "bool | None" = None, wait: bool = True,
                       started: "float | None" = None):
    """Send a run request on `conn` for an owner, else on the restricted
    connection. `owner` overrides the session-key decision; `started`
    (monotonic) is an earlier send's, whose wait budget this one shares."""
    if owner is None:
        owner = await _sender_is_owner(conn, params.get("sessionKey") or params.get("key") or "")
    target = conn if owner else await _get_restricted_connection(conn._valves)
    if not owner and method == RUN_SEND:
        params = _non_owner_send_params(params)
    if not wait:
        await target._ws.send(json.dumps(dict(type="req", id="abort" if method == RUN_ABORT
                                              else f"run-{uuid.uuid4().hex[:8]}",
                                              method=method, params=params)))
        return None
    return await _send_when_prepared(target, method, params, timeout=timeout, started=started)


async def _send_when_prepared(conn, method: str, params: dict, *, timeout: float = 10,
                              started: "float | None" = None):
    """`conn.send_request`, resent while the Gateway is still preparing the
    agent (up to STARTUP_REFUSAL_WAIT_S), or on any other retryable refusal
    (up to RETRYABLE_REFUSAL_WAIT_S): 2026.10.5 refuses sessions.patch that
    way right after preparation, naming no reason."""
    started = time.monotonic() if started is None else started
    deadline = started + STARTUP_REFUSAL_WAIT_S
    told = set()
    while True:
        try:
            return await conn.send_request(method, params, timeout=timeout)
        except GatewayError as ex:
            retry_ms, why = _startup_refusal_retry_ms(ex), "preparing"
            if retry_ms is None:
                retry_ms, why = _retryable_refusal_retry_ms(ex), "retryable"
                if retry_ms is not None and "retryable-since" not in told:
                    told.add("retryable-since")
                    retryable_deadline = time.monotonic() + RETRYABLE_REFUSAL_WAIT_S
            if retry_ms is None or time.monotonic() + retry_ms / 1000 > (
                    deadline if why == "preparing" else min(deadline, retryable_deadline)):
                raise
            if why not in told:
                told.add(why)
                pipe_log(f"  {method}: the Gateway is still preparing the agent after its start; "
                         f"sending again as it asks (every {retry_ms} ms, up to {STARTUP_REFUSAL_WAIT_S} s)"
                         if why == "preparing" else
                         f"  {method}: refused as retryable ({ex}); sending again in {retry_ms} ms, "
                         f"up to {RETRYABLE_REFUSAL_WAIT_S} s")
            await asyncio.sleep(retry_ms / 1000)


# A just-started Gateway (2026.10.5+) refuses runs with this details.code
# until the agent's database is prepared. The refusal is not cached by
# idempotency key, so the same request is resent; no event marks the end.
STARTUP_REFUSAL_CODE = "agent-database-inspection-pending"
STARTUP_REFUSAL_WAIT_S = 300
RETRYABLE_REFUSAL_WAIT_S = 30
# Wait for a restarting Gateway that refuses connections.
GATEWAY_DOWN_WAIT_S = 120
GATEWAY_REFUSED_CODE = "connection-refused"


async def _connect_response(ws, req_id: str, timeout: float = 10) -> dict:
    """The first `res` frame with our connect id; other frames are skipped."""
    deadline = time.monotonic() + timeout
    while True:
        frame = json.loads(await asyncio.wait_for(ws.recv(), max(0, deadline - time.monotonic())))
        if frame.get("type") == "res" and frame.get("id") == req_id:
            return frame
        pipe_log(f"  frame before the connect response, skipped: type={frame.get('type')!r} "
                 f"event={frame.get('event')!r} id={frame.get('id')!r}")


_LOOPBACK_HOSTS = frozenset({"localhost", "127.0.0.1", "::1", "[::1]"})


def _in_container() -> bool:
    """Open WebUI runs in a Docker or Podman container."""
    return os.path.exists("/.dockerenv") or os.path.exists("/run/.containerenv")


def _container_loopback_hint(host: str, port: int, tls: bool = False) -> str:
    """A hint for a refused loopback address inside a container, where
    localhost is the container itself."""
    if host not in _LOOPBACK_HOSTS and not host.startswith("127."):
        return ""
    if not _in_container():
        return ""
    where = (" Open WebUI runs in a container here. Unless it uses host networking "
             f"(--network host, where this refusal means nothing listens on {host}:{port}), "
             f"{host} inside it is the container itself, not the machine the Gateway runs on.")
    if tls:
        # host.docker.internal would not match the proxy's certificate.
        return (where + " A wss:// address names the TLS proxy: point GATEWAY_URL at a "
                "host name its certificate covers and that the container can reach, with "
                "the proxy listening there.")
    return (where + f" Point GATEWAY_URL at the host (host.docker.internal:{port}, started with "
            "--add-host=host.docker.internal:host-gateway, or the host's LAN address) "
            "and have the Gateway listen there: gateway.bind lan in the OpenClaw config "
            "listens on every interface, so firewall the port on a host the internet can "
            "reach. A Gateway behind tailscale serve keeps its loopback bind: set "
            "GATEWAY_URL to its wss:// address instead.")


def _refused_connect(ex) -> bool:
    """Every resolved address refused the connect. asyncio merges differing
    errors into one "Multiple exceptions:" OSError."""
    if isinstance(ex, ConnectionRefusedError):
        return True
    text = str(ex)
    return (isinstance(ex, OSError) and text.startswith("Multiple exceptions:")
            and text.count("[Errno") == text.count(f"[Errno {errno.ECONNREFUSED}]"))


def _gateway_refused(ex) -> bool:
    """A connect the Gateway's host refused: nothing listens on the port."""
    return isinstance(ex, GatewayError) and ex.error.get("code") == GATEWAY_REFUSED_CODE


def _gateway_starting_retry_ms(ex: GatewayError) -> int | None:
    """Retry wait for a "startup-sidecars" connect refusal, bounded like
    OpenClaw's `resolveGatewayStartupRetryAfterMs`."""
    err = getattr(ex, "error", None) or {}
    details = err.get("details") if isinstance(err.get("details"), dict) else {}
    if err.get("code") != "UNAVAILABLE" or err.get("retryable") is not True \
            or details.get("reason") != "startup-sidecars":
        return None
    retry = err.get("retryAfterMs")
    retry = int(retry) if isinstance(retry, (int, float)) else 500
    return min(max(retry, 100), 2000)


def _startup_refusal_retry_ms(ex: GatewayError) -> int | None:
    """Retry wait for a STARTUP_REFUSAL_CODE refusal, else None."""
    err = getattr(ex, "error", None) or {}
    details = err.get("details") if isinstance(err.get("details"), dict) else {}
    if not err.get("retryable") or details.get("code") != STARTUP_REFUSAL_CODE:
        return None
    retry = err.get("retryAfterMs")
    return int(retry) if isinstance(retry, (int, float)) and retry > 0 else 250


def _retryable_refusal_retry_ms(ex: GatewayError) -> int | None:
    """Retry wait for any other UNAVAILABLE + retryable refusal, else None."""
    err = getattr(ex, "error", None) or {}
    if err.get("code") != "UNAVAILABLE" or err.get("retryable") is not True:
        return None
    retry = err.get("retryAfterMs")
    return int(retry) if isinstance(retry, (int, float)) and retry > 0 else 250


# ELI-359: OpenClaw 2026.10.5 commits a `chat.send` to the session's pending
# inputs, then refuses to publish it when another write lands on the agent
# database in between (session-accessor-BHpQ2Hsr.mjs:542, e.g. the startup
# sub-agent recovery). UNAVAILABLE, not retryable, and the input never runs:
# its key is refused from then on ("Pending input ownership ended; submit a new
# turn"), a new key runs once. Checked with a forced fault on 2026.10.5.
UNPUBLISHED_INPUT_ERROR = "Pending input authority changed before publication"
# The Gateway's error code for a request it could not serve now.
UNAVAILABLE_CODE = "UNAVAILABLE"


def is_unpublished_input(ex: Exception) -> bool:
    """A `chat.send` refused as committed but never published (ELI-359)."""
    err = getattr(ex, "error", None) or {}
    return (isinstance(ex, GatewayError) and err.get("code") == UNAVAILABLE_CODE
            and UNPUBLISHED_INPUT_ERROR in str(err.get("message") or ex))


# `sessions.list` returns at most 100 rows without a `limit`, and has no
# filter by key: `search` is a substring match.
_SESSIONS_PAGE = 500          # rows asked for per page of a full read
_SESSION_READ_LIMIT = 10      # rows asked for when one session is named


async def _list_all_sessions(conn, *, timeout: float = 30, **filters) -> dict:
    """Every `sessions.list` row for `filters`, read page by page."""
    rows: list = []
    while True:
        resp = await conn.send_request(
            "sessions.list", {**filters, "limit": _SESSIONS_PAGE, "offset": len(rows)}, timeout=timeout)
        page = resp.get("sessions") or []
        rows.extend(page)
        total = resp.get("totalCount")
        if not page or (total is not None and len(rows) >= total) or (total is None and len(page) < _SESSIONS_PAGE):
            return {"sessions": rows, "totalCount": total if total is not None else len(rows)}


# --- errors ----------------------------------------------------------------

# ---------------------------------------------------------------------------
# What the user sees when a run or a send fails (S13)
#
# The Gateway's error string is a developer's line ("prepared reply dispatch
# runtime owner was not published for main"), the same for every user. The user
# gets one plain sentence in the language of their own message, and the raw
# text stays one click away in a collapsed block for whoever debugs it.
# ---------------------------------------------------------------------------

ERROR_SEND = "send"              # chat.send was refused or failed
ERROR_RUN = "run"                # the run ended in an error
ERROR_TIMEOUT = "timeout"        # the Gateway did not answer in time
ERROR_UNFINISHED = "unfinished"  # the run ended without a reply or a reason
ERROR_DETAILS = "details"        # the summary of the collapsed raw text

LANG_EN = "en"
LANG_HE = "he"

# The Hebrew block of Unicode: its letters and points.
_HEBREW_FIRST, _HEBREW_LAST = "֐", "׿"
_URL_RE = re.compile(r"https?://\S+")
_BACKTICKS_RE = re.compile(r"`+")
# A code fence is at least this many backticks.
_MIN_FENCE = 3

_ERROR_TEXT = {
    LANG_EN: {
        ERROR_SEND: "**Your message couldn't be sent.** Please try sending it again.",
        ERROR_RUN: "**Something went wrong while answering.** Please try again.",
        ERROR_TIMEOUT: ("**The assistant took too long to respond.** This is usually "
                        "temporary: please send your message again."),
        ERROR_UNFINISHED: "**The reply didn't finish.** Please send your message again.",
        ERROR_DETAILS: "Technical details",
    },
    LANG_HE: {
        ERROR_SEND: "**לא הצלחתי לשלוח את ההודעה.** אפשר לנסות לשלוח אותה שוב.",
        ERROR_RUN: "**משהו השתבש בזמן שעניתי.** אפשר לנסות שוב.",
        ERROR_TIMEOUT: ("**לא קיבלתי תשובה בזמן.** זה בדרך כלל חולף, "
                        "אפשר לשלוח את ההודעה שוב."),
        ERROR_UNFINISHED: "**התשובה לא הסתיימה.** אפשר לשלוח את ההודעה שוב.",
        ERROR_DETAILS: "פרטים טכניים",
    },
}


def _message_language(text) -> str:
    """`LANG_HE` when more words of `text` have Hebrew letters than Latin ones
    (links left out), else `LANG_EN`: the script of the message picks the
    language, no setting. Words, not letters, so one long foreign name in a
    Hebrew sentence does not outweigh it."""
    hebrew = latin = 0
    for word in _URL_RE.sub("", str(text or "")).split():
        if any(_HEBREW_FIRST <= c <= _HEBREW_LAST for c in word):
            hebrew += 1
        elif any(c.isascii() and c.isalpha() for c in word):
            latin += 1
    return LANG_HE if hebrew > latin else LANG_EN


def _fenced(raw: str) -> str:
    """`raw` as a code block that no backticks inside it can close."""
    longest = max((len(m) for m in _BACKTICKS_RE.findall(raw)), default=0)
    fence = "`" * max(_MIN_FENCE, longest + 1)
    return f"{fence}\n{raw}\n{fence}"


def _plain_error(kind: str, raw, user_text="") -> str:
    """The sentence for an error of `kind`, in the language of `user_text`,
    followed by `raw` (the Gateway's own text) in a collapsed block."""
    text = _ERROR_TEXT[_message_language(user_text)]
    raw = str(raw or "").strip()
    if not raw:
        return text[kind]
    return (f"{text[kind]}\n\n<details>\n<summary>{text[ERROR_DETAILS]}</summary>\n\n"
            f"{_fenced(raw)}\n\n</details>")


# --- writer ----------------------------------------------------------------

# ---------------------------------------------------------------------------
# The turn writer (ELI-100, docs/design/agent-turns.md 2.3-2.5)
# ---------------------------------------------------------------------------
# One writer per run rendered outside a live `pipe()` request. It owns one
# message and registers with Open WebUI's task registry so the page shows the
# chat as generating and its Stop button reaches it.


# Opens tried at a run's end while Open WebUI's DB is locked (ELI-167). Each
# waits out sqlite's busy_timeout (5 s), so 6 is about 30 s.
OPEN_AT_END_LOCKED_TRIES = 6
# M's final write waits this long for the handed-over request to end.
FINAL_STATUS_REQUEST_WAIT_S = 30
# A cancel's tail on a reply's status lines: "Stopped" from `park`, then the
# empty closing line.
_CANCEL_STATUS_TAIL = ("Stopped", "")


def _final_status_history(history: list | None, lines: list, stopped: bool) -> tuple[list, list]:
    """M's final status lines (cancel tail dropped) and the ones it adds."""
    kept = [h for h in (history or []) if isinstance(h, dict)]
    while kept and kept[-1].get("done") is not False and kept[-1].get("description") in _CANCEL_STATUS_TAIL:
        kept.pop()
    if stopped:
        new = [{"description": "Stopped", "done": True}]
    else:
        new = [{"description": line, "done": True} for line in lines] or [{"description": "", "done": True}]
    return kept + new, new


# Message meta: the user's Stop ended this reply. Nothing adds to it afterwards
# (`_reconcile_chat_ended_runs`). An Open WebUI shutdown cancels a reply the
# same way, but its run goes on (ELI-94).
STOPPED_META = "openclaw_stopped"


async def _mark_stopped(chat_id: str, message_id: str, request=None) -> None:
    """Mark the reply stopped before any `done: true` save, so no restart finds
    it finished and unmarked. Marked again after `request`'s own save."""
    await _write_stop_mark(chat_id, message_id)
    if request is not None and not request.done():
        async def after_request():
            await asyncio.wait({request})
            await _write_stop_mark(chat_id, message_id)
        spawn_background(after_request())


async def _write_stop_mark(chat_id: str, message_id: str) -> None:
    try:
        await _set_turn_meta(chat_id, message_id, {STOPPED_META: True})
    except Exception as ex:
        pipe_log(f"  reply {message_id[:8]}...: marking it stopped failed: {ex!r}")


def _ended_by_stop(message: dict) -> bool:
    return bool((message.get("meta") or {}).get(STOPPED_META))


def _db_locked(ex: BaseException) -> bool:
    """sqlite's `database is locked`, raw or wrapped by SQLAlchemy."""
    seen = set()
    while ex is not None and id(ex) not in seen:
        seen.add(id(ex))
        if "database is locked" in str(ex):
            return True
        ex = ex.__cause__ or ex.__context__
    return False


async def _set_turn_meta(chat_id: str, message_id: str, meta: dict) -> bool:
    """Merge `meta` into message `message_id` under the chat's row lock, never
    cut short by a cancel (ELI-205)."""
    return await _uncancellable(_set_turn_meta_now(chat_id, message_id, meta))


async def _set_turn_meta_now(chat_id: str, message_id: str, meta: dict) -> bool:
    from open_webui.models.chats import Chats
    from sqlalchemy.orm.attributes import flag_modified

    async with Chats._chat_transaction(chat_id) as (db, chat):
        if chat is None:
            return False
        data = chat.chat or {}
        history = data.get("history") or {}
        msg = (history.get("messages") or {}).get(message_id)
        if msg is None:
            return False
        msg["meta"] = {**(msg.get("meta") or {}), **meta}
        chat.chat = {**data, "history": history}
        flag_modified(chat, "chat")
        return True


async def _introduce_turn_message(chat_id: str, user_id: str, messages: dict, current_id: str | None,
                                  message_id: str | None = None) -> None:
    """Show a newly claimed message in every open tab via the shared
    `chat:messages` event, as Open WebUI does for its own turns."""
    from open_webui.socket.main import sio

    await sio.emit("events", {
        "chat_id": chat_id, "message_id": message_id or current_id, "user_id": user_id, "shared": True,
        "data": {"type": "chat:messages", "data": {"messages": messages, "currentId": current_id}},
    }, room=f"chat:{chat_id}")


def _turn_message_patch(message_id: str, parent: str | None, message: dict) -> dict:
    """The `chat:messages` nodes for `message`. The parent gets only the link:
    the page merges childrenIds as a set and keeps its other fields."""
    nodes = {message_id: message}
    if parent:
        nodes[parent] = {"id": parent, "childrenIds": [message_id]}
    return nodes


def _owui_redis():
    """Open WebUI's redis client, or None in a single-process install."""
    app = getattr(sys.modules.get("open_webui.main"), "app", None)
    return getattr(getattr(app, "state", None), "redis", None)


async def _save_response_stream(task_id, chat_id, message_id, text: str, output: list) -> None:
    """Open WebUI's mid-turn copy of a message. 0.12.3 dropped the `content`
    argument (the GET rebuilds text from `output`)."""
    import inspect
    from open_webui.tasks import save_response_stream

    if "content" in inspect.signature(save_response_stream).parameters:
        await save_response_stream(_owui_redis(), task_id, chat_id, message_id, text, output)
    else:
        await save_response_stream(_owui_redis(), task_id, chat_id, message_id, output)


async def _clear_response_stream(task_id: str | None) -> None:
    """Drop the mid-turn copy once the row is saved whole."""
    if not task_id:
        return
    try:
        from open_webui.tasks import clear_response_stream

        await clear_response_stream(_owui_redis(), task_id)
    except Exception as ex:
        pipe_log(f"  turn writer: clearing the response stream failed: {ex!r}")


# Open WebUI's event names are a closed catalog, so consumers tell the Pipe's
# `chat.finished` from the middleware's by `source`.
CHAT_FINISHED_SOURCE = "openclaw-pipe"
# Meta key so a reply is published once however many paths finish it.
CHAT_FINISHED_META = "openclaw_chat_finished"


async def _claim_chat_finished(chat_id: str, message_id: str) -> dict | None:
    """The message if saved whole and not yet published, marked published
    under the row lock (a request can run twice, in any worker). Uncancellable."""
    return await _uncancellable(_claim_chat_finished_now(chat_id, message_id))


async def _claim_chat_finished_now(chat_id: str, message_id: str) -> dict | None:
    from open_webui.models.chats import Chats
    from sqlalchemy.orm.attributes import flag_modified

    async with Chats._chat_transaction(chat_id) as (db, chat):
        if chat is None:
            return None
        data = chat.chat or {}
        history = data.get("history") or {}
        msg = (history.get("messages") or {}).get(message_id)
        if msg is None or msg.get("done") is not True or (msg.get("meta") or {}).get(CHAT_FINISHED_META):
            return None
        msg["meta"] = {**(msg.get("meta") or {}), CHAT_FINISHED_META: True}
        chat.chat = {**data, "history": history}
        flag_modified(chat, "chat")
        return dict(msg)


async def _publish_chat_finished(chat_id: str, message_id: str, user_id: str,
                                 text: str | None = None) -> None:
    """Publish `chat.finished` for a reply saved whole, shaped like the
    middleware's. Its own fires at request end, too early for a handed-over
    reply and never for an agent turn. Once per reply."""
    app = getattr(sys.modules.get("open_webui.main"), "app", None)
    if app is None or not message_id:
        return
    try:
        from open_webui.events import EVENTS, publish_event
        from open_webui.models.chats import Chats
        from open_webui.models.users import Users
        from open_webui.utils.chat_id import is_saved_chat_id
        from starlette.requests import Request

        if not is_saved_chat_id(chat_id):
            return
        row = await _claim_chat_finished(chat_id, message_id)
        if row is None:
            return
        if text is None:
            text = row.get("content") or ""
        title = await Chats.get_chat_title_by_id(chat_id) or ""
        user = await Users.get_user_by_id(user_id)
        try:
            from open_webui.models.config import Config
            base = (await Config.get("webui.url") or "").rstrip("/")
        except Exception:
            base = ""
        # Sinks read `request.app`; an agent turn has no request.
        request = Request({"type": "http", "app": app, "method": "POST", "path": "/",
                           "headers": [], "query_string": b""})
        await publish_event(
            request, EVENTS.CHAT_FINISHED,
            actor=user or {"id": user_id}, subject_id=chat_id, subject_type="chat",
            source=CHAT_FINISHED_SOURCE,
            data={"user_id": user_id, "chat_id": chat_id, "message_id": message_id,
                  "model_id": row.get("model"), "title": title,
                  "url": f"{base}/c/{chat_id}", "message": text},
            message=title or "Chat finished")
    except Exception as ex:
        pipe_log(f"  turn writer: publishing chat.finished for {message_id[:8]}... failed: {ex!r}")


def _owui_request_task(task_id: str | None):
    """Open WebUI's asyncio task for a chat request (Pipe call, then its
    end-of-stream save). None once ended or unknown."""
    if not task_id:
        return None
    return (getattr(sys.modules.get("open_webui.tasks"), "tasks", None) or {}).get(task_id)

# The Gateway's error for a claude-cli turn with no final text. A
# `sessions_send` turn often ends silent on purpose and still fails (ELI-336).
EMPTY_RESPONSE_ERROR = "CLI backend returned an empty response."

TURN_CUT_OFF_NOTE = ("_(This reply was cut off: the run was interrupted again after "
                     f"{MAX_TURN_RESUMES} attempts to continue it.)_")


def _run_prompt_text(span: list | None) -> str:
    """The needs-input prompt a run's text ends with, or ""."""
    return _prompt_tail(_last_item_text(_history_renderer(span))) if span else ""


def _last_item_text(renderer: "_TurnRenderer") -> str:
    """The last message item's text (fences never span items), or ""."""
    last = renderer.output[-1] if renderer.output else None
    if last is None or last.get("type") != "message":
        return ""
    return ((last.get("content") or [{}])[0].get("text")) or ""


def _prompt_tail(text: str, start: int = 0) -> str:
    """`text` from its last needs-input trigger line on, or "". A trigger in
    a code fence is a quote (ELI-107)."""
    if not text:
        return ""
    last = None
    while True:
        at = _marker_line_index(text[start:], _fence_open_after(text[:start]))
        if at is None:
            break
        last = start + at
        start = text.find("\n", last) + 1
        if not start:
            break
    return text[last:] if last is not None else ""


RESUME_DIRECTIVE_PREFIX = "[system] Your previous "


# A request longer than this is quoted as its head and tail.
RESUME_REQUEST_MAX = 6000
RESUME_REQUEST_HEAD = 2000
# OpenClaw's inbound metadata blocks at the start of a stored user turn.
_INBOUND_META_RE = re.compile(
    r"\A\s*[A-Z][^\n]{0,80}\(untrusted metadata\):[ \t]*\n```[^\n]*\n.*?\n```[ \t]*(?:\n+|\Z)", re.S)


def _strip_inbound_meta(text: str) -> str:
    """`text` without the metadata blocks in front of it."""
    while True:
        m = _INBOUND_META_RE.match(text or "")
        if not m:
            return text
        text = text[m.end():]


def _quote_block(text: str) -> str:
    """`text` between dash delimiters longer than any dash-only line in it."""
    dashes = [len(x.strip()) for x in text.split("\n") if x.strip() and set(x.strip()) == {"-"}]
    delim = "-" * max([3] + [n + 1 for n in dashes])
    return f"{delim}\n{text}\n{delim}"


def _clip_middle(text: str, limit: int = RESUME_REQUEST_MAX, head: int = RESUME_REQUEST_HEAD) -> str:
    """`text` clipped to head and tail, keeping the closing question."""
    if len(text) <= limit:
        return text
    tail = limit - head
    return f"{text[:head]}\n[... {len(text) - limit} characters omitted ...]\n{text[-tail:]}"


def _resume_directive(shown: str | None, request: str | None = None,
                      attachments: int = 0) -> str:
    """The message a resume sends. It explains the kill (a killed tool reads
    as exit 137) and carries `request`, since the resume runs in a new
    claude-cli session. Attachments do not travel."""
    cause = (
        "The Gateway restarted or your process was killed from outside while you "
        "were working. A tool call that was still running was killed by that, so "
        "its result (such as exit code 137 or 143) says nothing about the command "
        "itself: rerun it if the request still needs it.")
    request = (request or "").strip()
    if request:
        cause += (" The request you were answering, which this session may no longer "
                  f"hold, was:\n\n{_quote_block(_clip_middle(request))}\n")
    if attachments:
        cause += (f" The request also carried {attachments} attachment"
                  f"{'s' if attachments > 1 else ''} (an image or a file) that this session "
                  "cannot see; if the request needs it, ask the user to send it again.")
    shown = (shown or "").strip()
    if shown:
        return (
            f"[system] Your previous reply was cut off partway through. {cause} The "
            "user can already see the following partial text, and it cannot be edited "
            f"or retracted:\n\n{_quote_block(shown[-1500:])}\n\n"
            "Continue that reply seamlessly from exactly where it stops and finish the "
            "request. Do not repeat any of it, do not restart the answer, and do not "
            "mention the interruption.")
    return (
        f"[system] Your previous run was cut off before you produced any output. {cause} "
        "Answer the most recent message now and finish the request. Do not mention "
        "the interruption.")


def _is_sentinel_message_item(item: dict) -> bool:
    if item.get("type") != "message":
        return False
    text = "".join(c.get("text", "") for c in item.get("content") or [])
    return text.strip() in _SILENT_SENTINELS


def _turn_note_item(note: str) -> dict:
    return {"type": "message", "id": f"msg_note_{uuid.uuid4().hex[:12]}", "status": "completed",
            "role": "assistant", "content": [{"type": "output_text", "text": note}]}


def _keep_pipe_notes(streamed: list, renderer: "_TurnRenderer") -> None:
    """Put the Pipe's own notes back after a transcript rebuild (ELI-229)."""
    output = renderer.output
    have = {i.get("id") for i in output}
    for at, item in enumerate(streamed):
        if not str(item.get("id") or "").startswith(_NOTE_ITEM_PREFIX) or item.get("id") in have:
            continue
        before = next((p.get("id") for p in reversed(streamed[:at]) if p.get("id") in have), None)
        pos = next((n + 1 for n, i in enumerate(output) if i.get("id") == before), len(output)) \
            if before else 0
        output.insert(pos, copy.deepcopy(item))
        have.add(item.get("id"))


# Notes for a reply interrupted before it sent its message (ELI-188).
REPLY_SENT_WITH_NEXT_NOTE = ("_(This message was sent together with your next one: "
                             "the answer is in the next reply.)_")
REPLY_NOT_SENT_NOTE = "_(Stopped: this message was not sent to the agent.)_"
# The Gateway (2026.10.10+) steers a message sent mid-run into that run.
STEER_PENDING_STATUS = "Sent while the agent works: it reads it at its next step…"
REPLY_SEND_FAILED_NOTE = ("_(This message was to go together with your next one, "
                          "which could not be sent: see the next reply.)_")


async def _close_reply_status(ref: dict) -> None:
    """Close a status line left open in the saved message (ELI-200), after the
    request's own save. The saved state decides: on a Stop two concurrent
    writes race and the status one can be lost."""
    request = _owui_request_task(ref.get("request_task_id"))
    if request is not None and not request.done():
        await asyncio.wait({request})
    from open_webui.models.chats import Chats
    from open_webui.socket.main import get_event_emitter

    message_id = ref["message_id"]
    try:
        saved = await Chats.get_message_by_id_and_message_id(ref["chat_id"], message_id) or {}
        last = (saved.get("statusHistory") or [None])[-1]
        if not isinstance(last, dict) or last.get("done") is not False:
            return
        emit = await get_event_emitter({"chat_id": ref["chat_id"], "message_id": message_id,
                                        "user_id": ref.get("user_id")}, update_db=True)
        await emit({"type": "status", "data": {"description": "", "done": True}})
        pipe_log(f"  reply {message_id[:8]}... closed: its status line was left open")
    except Exception as ex:
        pipe_log(f"  reply {message_id[:8]}...: closing its status failed: {ex!r}")


async def _close_unsent_reply(conn: "_GatewayConnection", ref: dict, note: str) -> None:
    """End a reply cancelled before it sent its message, with `note`. Waits
    for the request to end first, or Open WebUI's own save lands over this."""
    request = _owui_request_task(ref.get("request_task_id"))
    if request is not None and not request.done():
        await asyncio.wait({request})
    from open_webui.models.chats import Chats
    from open_webui.socket.main import get_event_emitter

    chat_id, message_id = ref["chat_id"], ref["message_id"]
    try:
        emit = await get_event_emitter({"chat_id": chat_id, "message_id": message_id,
                                        "user_id": ref.get("user_id")}, update_db=True)
        await emit({"type": "status", "data": {"description": "", "done": True}})
        async with conn._chat_write_lock(chat_id):
            current = await Chats.get_message_by_id_and_message_id(chat_id, message_id) or {}
            text = (current.get("content") or "").strip()
            text = f"{text}\n\n{note}" if text else note
            output = list(current.get("output") or []) + [_turn_note_item(note)]
            await _owui_upsert_message(
                chat_id, message_id, {"content": text, "output": output, "done": True})
        await emit({"type": "chat:completion", "data": {"done": True, "content": text,
                                                         "output": output}})
        pipe_log(f"  reply {message_id[:8]}... ended: {note}")
    except Exception as ex:
        pipe_log(f"  reply {message_id[:8]}...: closing note failed: {ex!r}")


def _settle_text(text: str) -> str:
    return "".join((text or "").split())


def _settle_misplaced(saved: list, parts: list) -> bool:
    """The saved replies hold the transcript's parts with only the split
    points moved: in order, each one a piece of the run's text that starts
    no later than where the ones before reach, together all of it. A piece
    may repeat what an earlier reply shows (after a late steer the first
    reply runs on into the next answers). Whitespace-blind."""
    if saved == parts or len(saved) != len(parts):
        return False
    whole, end = "".join(parts), 0  # `end`: how far the replies so far reach
    for was in saved:
        start = whole.rfind(was, 0, end + len(was))  # the latest start at or before `end`
        if start < 0:
            return False
        end = max(end, start + len(was))
    return end == len(whole)


def _steer_chain(history: dict, refs: list) -> list:
    """`refs` in the transcript's order: the host run's reply, then the reply
    of each message steered into it. A message whose steer came after the
    run ended (2026.10.10 publishes the steer target with no order to the
    rest) is in no reply's chain; the transcript still shows it, so it
    joins here. `refs` as they are when the transcript does not show them all."""
    messages = (history or {}).get("messages")
    if not refs or not isinstance(messages, list):
        return refs
    host, by_message = refs[0]["span_run"], {r["message_id"]: r for r in refs[1:]}
    # A turn after the host's last closing message is a turn of its own, even
    # before its answer is stored.
    closers = [n for n, m in enumerate(messages) if _run_closed_by(m) == host]
    chain = [refs[0]]
    for n, message in enumerate(messages[:closers[-1] if closers else len(messages)]):
        run = _history_user_run_id(message)
        ref = _settle_ref(run) if run else None
        if ref is not None and _history_steered_into(history, n) == host:
            chain.append(by_message.pop(ref["message_id"], None) or ref)
    return refs if by_message else chain


# The Pipe's notes that a steered message's answer is in another reply: no
# run text, and wrong once the settle gives the reply its answer.
_STEER_NOTES = (REPLY_SENT_WITH_NEXT_NOTE, REPLY_SEND_FAILED_NOTE)


def _settle_shown(content: str) -> str:
    """A saved reply's text as the settle compares it: no steer notes."""
    for note in _STEER_NOTES:
        content = (content or "").replace(note, "")
    return _settle_text(content)


# A tool card in a message's `output` (`_tool_call_started_event`).
_TOOL_CARD_TYPE = "function_call"


def _tool_card_ids(output: list) -> set:
    """The tool cards in `output`, by `call_id or id` (how consumers read them)."""
    return {i.get("call_id") or i.get("id") for i in output or ()
            if isinstance(i, dict) and i.get("type") == _TOOL_CARD_TYPE}


async def _settle_waits(conn: "_GatewayConnection", refs: list) -> None:
    """Until no one still saves a reply of `refs`: a turn writer (also while it
    finalizes), or an Open WebUI request in its chat, which saves at its end."""
    for writer in (conn._turn_writers.get((r["chat_id"], r["message_id"])) for r in refs):
        if writer is not None and writer.saving():
            await writer.wait_done()
    try:
        from open_webui.tasks import list_task_ids_by_item_id, tasks
        for chat_id in dict.fromkeys(r["chat_id"] for r in refs):
            for task_id in await list_task_ids_by_item_id(_owui_redis(), chat_id):
                task = tasks.get(task_id)
                if task is not None and not task.done() and task is not asyncio.current_task():
                    await asyncio.wait({task})
    except ImportError:
        pass  # no Open WebUI tasks to wait for


async def _settle_steered_replies(conn: "_GatewayConnection", session_key: str, refs: list) -> None:
    """Re-split the replies around a steer from the transcript once the run
    ended. On claude-cli the Gateway forwards the answer before it commits
    the steered message, so the switch can land late. Only the split moves."""
    refs = [r for r in refs if r and r.get("chat_id") and r.get("message_id") and r.get("span_run")]
    if len(refs) < 2:
        return
    for ref in refs:
        request = _owui_request_task(ref.get("request_task_id"))
        if request is not None and not request.done():
            await asyncio.wait({request})
    from open_webui.models.chats import Chats
    from open_webui.socket.main import get_event_emitter

    try:
        while True:
            # A reply is read once it is saved, and the transcript after that:
            # a turn writer ends when the session settled.
            await _settle_waits(conn, refs)
            hist = await conn.session_history(session_key, limit=RUN_HISTORY_LIMIT)
            chain = _steer_chain(hist, refs)
            if chain == refs:
                break
            refs = chain  # replies the transcript added: their writers too
        spans = [_history_span_messages(hist, r["span_run"]) for r in refs]
        if any(s is None for s in spans):
            pipe_log(f"  replies around a steer left as they are: the transcript closes no span of "
                     f"{', '.join(r['span_run'][:24] + '...' for r, s in zip(refs, spans) if s is None)}")
            return
        parts = [_history_renderer(s) for s in spans]
        saved = [await Chats.get_message_by_id_and_message_id(r["chat_id"], r["message_id"]) or {}
                 for r in refs]
        texts = [(m.get("content") or "") for m in saved]
        shown, truth = [_settle_shown(t) for t in texts], [_settle_text(p.text) for p in parts]
        if not _settle_misplaced(shown, truth):
            if shown != truth:
                pipe_log(f"  replies around a steer left as they are: {len(refs)} replies hold more "
                         "than the transcript's text of the run")
            return
        lost = set().union(*(_tool_card_ids(m.get("output")) for m in saved)) - set().union(
            *(_tool_card_ids(p.finished_output()) for p in parts))
        if lost:
            pipe_log(f"  replies around a steer left as they are: the transcript lacks "
                     f"{len(lost)} tool card(s) they show")
            return
        user_id = (conn.parse_owui_session_key(session_key) or (None, None))[0]
        for ref, part, was, message in zip(refs, parts, shown, saved):
            if was == _settle_text(part.text):
                continue
            # The Pipe's own notes are in no transcript (ELI-229).
            _keep_pipe_notes(list(message.get("output") or []), part)
            text, output = part.text.strip(), part.finished_output()
            async with conn._chat_write_lock(ref["chat_id"]):
                await _owui_upsert_message(ref["chat_id"], ref["message_id"],
                                           {"content": text, "output": output, "done": True})
            emit = await get_event_emitter({"chat_id": ref["chat_id"], "message_id": ref["message_id"],
                                            "user_id": user_id}, update_db=False)
            await emit({"type": "chat:completion", "data": {"done": True, "content": text, "output": output}})
            pipe_log(f"  reply {ref['message_id'][:8]}... settled from the transcript around a steer")
    except Exception as ex:
        pipe_log(f"  settling the replies around a steer failed: {ex!r}")


def _end_unsent_replies(conn: "_GatewayConnection", refs: list, *, sent: bool,
                        note: str | None = None) -> None:
    """End each reply in `refs` in the background (`_close_unsent_reply`)."""
    note = note or (REPLY_SENT_WITH_NEXT_NOTE if sent else REPLY_NOT_SENT_NOTE)
    for ref in refs:
        spawn_background(_close_unsent_reply(conn, ref, note))


# Open WebUI cancels identically for Stop and Send now (both call
# stopTasksByChatId), so only the page can tell them apart. This hook records
# per chat which one the user pressed. Labels are localized, so a non-English
# UI falls back to the timer.
_INTENT_HOOK_JS = r"""
if (!window.__ocIntentHook) {
  window.__ocIntentHook = true;
  window.__ocIntents = {};
  const chat = () => (location.pathname.match(/\/c\/([^/?#]+)/) || [])[1] || null;
  const mark = (kind) => { const c = chat(); if (c) window.__ocIntents[c] = { kind, t: Date.now() }; };
  // The Stop button's aria-label is translated; its icon is not (R15).
  const STOP_ICON = 'M2.25 12c0-5.385 4.365-9.75 9.75-9.75s9.75';
  const isStop = (b) => b.getAttribute('aria-label') === 'Stop' || b.id === 'stop-response-button'
    || [...b.querySelectorAll('svg path')].some((p) => (p.getAttribute('d') || '').startsWith(STOP_ICON));
  const running = () => [...document.querySelectorAll('button')].some(isStop);
  document.addEventListener('click', (e) => {
    const b = e.target && e.target.closest ? e.target.closest('button') : null;
    if (!b) return;
    // Send now needs no mark: an unknown intent already keeps writing.
    if (b.getAttribute('aria-label') === 'Send now') mark('send_now');
    else if (isStop(b)) mark('stop');
  }, true);
  document.addEventListener('keydown', (e) => {
    if (!running()) return;
    if (e.key === 'Escape') { mark('stop'); return; }
    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing && e.target && e.target.closest
        && e.target.closest('#chat-input')) mark('send_now');
  }, true);
  // One click answers every task it cancelled (ELI-198), so a query does not
  // clear it: a new message, sent with nothing running, does.
  document.addEventListener('submit', (e) => {
    const f = e.target;
    const input = document.querySelector('#chat-input');
    if (running() || !f || !input || !f.contains(input)) return;
    const c = chat();
    if (c) delete window.__ocIntents[c];
  }, true);
}
return true;
"""


# Open WebUI queues a message sent mid-reply in the browser only. With
# AUTO_SEND_WHILE_RUNNING on, this hook clicks Send now as soon as one
# appears, marked as Send now so the run is kept. The button is found by its
# untranslated icon. One click at a time: Open WebUI ignores a Send now while
# it is still submitting the previous one.
_AUTO_SEND_HOOK_JS = r"""
if (!window.__ocAutoSendHook) {
  window.__ocAutoSendHook = true;
  window.__ocAutoSend = window.__ocAutoSend || {};
  const SEND_NOW_ICON = 'M4.5 10.5 12 3m0 0 7.5 7.5M12 3v18';
  const chat = () => (location.pathname.match(/\/c\/([^/?#]+)/) || [])[1] || null;
  const lastUser = () => {
    const all = document.querySelectorAll('.user-message[id^="message-"]');
    return all.length ? all[all.length - 1].id : null;
  };
  let inFlight = null;
  const sendQueued = () => {
    const c = chat();
    if (!c || !window.__ocAutoSend[c]) return;
    if (inFlight && inFlight.chat === c && inFlight.lastUser === lastUser()) return;
    inFlight = null;
    const path = document.querySelector(`button:not([disabled]) path[d="${SEND_NOW_ICON}"]`);
    const b = path && path.closest('button');
    if (!b) return;
    inFlight = { chat: c, lastUser: lastUser() };
    window.__ocIntents = window.__ocIntents || {};
    window.__ocIntents[c] = { kind: 'send_now', t: Date.now() };
    b.click();
  };
  new MutationObserver(sendQueued).observe(document.body, {
    childList: true, subtree: true, attributes: true, attributeFilter: ['disabled'] });
  window.__ocAutoSendScan = sendQueued;
}
"""


def _page_hooks_js(chat_id: str | None, auto_send: bool) -> str:
    """The intent and auto-send page hooks, with this chat's setting."""
    code = "(function () {" + _INTENT_HOOK_JS + "})();\n(function () {" + _AUTO_SEND_HOOK_JS + "})();\n"
    if chat_id:
        code += ("window.__ocAutoSend[" + json.dumps(chat_id) + "] = " + ("true" if auto_send else "false")
                 + ";\nwindow.__ocAutoSendScan();\n")
    return code


def _auto_send_on(valves) -> bool:
    return bool(getattr(valves, "AUTO_SEND_WHILE_RUNNING", True))


def _intent_query_js(chat_id: str) -> str:
    """Read the page's recorded intent. The record is not cleared: one Stop
    cancels every task of the chat and each asks (ELI-198). "none": hook but
    no click; null: no hook."""
    return (
        "const c = " + json.dumps(chat_id) + ";"
        "const all = window.__ocIntents;"
        "if (!all) return null;"
        "const i = all[c];"
        "return (i && Date.now() - i.t < 60000) ? i.kind : 'none';"
    )


# RPC bound for a tab that never answers (ELI-95).
_INTENT_QUERY_TIMEOUT_S = 3.0


def _intent_answer(resp) -> str | None:
    if isinstance(resp, str):
        return resp.strip() or None
    if isinstance(resp, dict) and "error" not in resp:
        for key in ("value", "result", "text"):
            if isinstance(resp.get(key), str):
                return resp[key].strip() or None
    return None


async def _page_cancel_intent(user_id: str, chat_id: str, message_id: str) -> str | None:
    """Which button cancelled the writer's task: "stop", "send_now" or None.
    Asks every tab showing the chat; a Stop anywhere wins."""
    try:
        from open_webui.socket import main as socket_main
    except Exception:
        return None
    pool = getattr(socket_main, "SESSION_POOL", None) or {}
    sids = [sid for sid, sess in list(pool.items())
            if isinstance(sess, dict) and sess.get("id") == user_id
            and chat_id in (sess.get("chat_ids") or [])]
    answers = set()
    for sid in sids:
        try:
            resp = await socket_main.sio.call("events", {
                "chat_id": chat_id, "message_id": message_id,
                "data": {"type": "execute", "data": {"code": _intent_query_js(chat_id)}},
            }, to=sid, timeout=_INTENT_QUERY_TIMEOUT_S)
        except Exception as ex:
            pipe_log(f"  turn writer: intent query to {sid[:8]}... failed: {ex!r}")
            continue
        answers.add(_intent_answer(resp))
    for kind in ("stop", "send_now"):
        if kind in answers:
            return kind
    return None


class _TurnWriter:
    """Writes run `run_id` into message `message_id` of chat `chat_id`."""

    def __init__(self, conn: "_GatewayConnection", *, session_key: str, chat_id: str,
                 user_id: str, run_id: str, message_id: str | None,
                 takeover: bool = False, renderer: "_TurnRenderer | None" = None,
                 thinking: str | None = None, wake: dict | None = None, shown: str = "",
                 request: "asyncio.Future | None" = None):
        self.conn = conn
        self.session_key, self.chat_id, self.user_id = session_key, chat_id, user_id
        self.run_id, self.message_id = run_id, message_id
        # A pipe run's message already exists (Open WebUI's stub) (DESIGN 2.6).
        self.takeover = takeover
        self.renderer = renderer if renderer is not None else _TurnRenderer()
        self.thinking = thinking  # ELI-85: a resume keeps the user's level
        # A cron wake (ELI-103): its transcript span is a time window.
        self.wake = wake
        # What earlier replies showed of an adopted run (ELI-147).
        self.shown = {run_id: shown} if shown else {}
        self.opened = False
        self._claim: dict | None = None  # a locked open resumes after it
        self.task_id: str | None = None
        self.runs = [run_id]
        # (run, output index, text length) per run. See `_from_transcript`.
        self.run_marks: list = [(run_id, 0, 0)]
        # Lifecycle `startedAt` (ms) bounds a run's transcript span.
        self.run_started: dict[str, float] = {}
        self.resumes = 0                # resume budget, counted on M (MAX_TURN_RESUMES)
        self.pending_resume = False     # a resume the Gateway refused; sent on the next hello-ok
        self.request: str | None = None  # the user's message M answers, quoted by a resume
        self.request_attachments = 0    # its images or files, which a resume cannot carry
        self.awaiting_row = False       # kept open for a Gateway recovery
        self.closed = False
        self.finalizing = False  # closed, its message still being saved
        # M's message was steered into another run (2026.10.10+): its own run
        # gets only a `chat` final with no message.
        self.steered_message = False
        # Images of a steered reply are that run's (`finish_final_images`).
        self.steered_into: str | None = None
        # A later run works: M's end leaves the active state to its reply.
        self.newer_run = False
        self.sent_output: list = []     # the `output` open tabs hold
        self.sent_text = ""
        # A handover owes M one write after the request's `done: true` save,
        # since the orphan reconcile adopts only `done: false` (ELI-115).
        self.handover_owed = renderer is not None
        self.request_task = request
        if renderer is not None:
            # Tabs hold these items under Open WebUI's ids: unknown items make
            # the first diff replace them in place, not duplicate (ELI-158).
            self.sent_output = [{"type": "_shown_by_request"} for _ in renderer.output]
        self._media_failed: set = set()  # MEDIA directives that did not resolve
        # Media as the inline reply keeps them (ELI-328).
        self.gateway_media: set[str] = set()
        self.event_media: list[str] = []
        self.images_made = 0
        self._emit = None
        self._done = asyncio.Event()
        # A running push of M never lands after its final one (`_push_running`).
        self._push_lock = asyncio.Lock()
        # Two pumps can feed one writer; only one may claim it.
        self._open_lock = asyncio.Lock()
        self._emit_lock = asyncio.Lock()

    async def open(self, takeover: bool = False) -> bool:
        """Claim, introduce and register the message. False when another live
        writer holds it or there is nothing to open."""
        async with self._open_lock:
            return await self._open(takeover)

    async def _open(self, takeover: bool) -> bool:
        if self.opened:
            return True
        if not self.message_id:
            return False
        _register_turn_writer(self.conn.writer_id)
        # Each step once: a locked DB (ELI-167) can stop the open after the
        # claim committed, and a retry must not read it as another writer's.
        if self._claim is None:
            claim = await _claim_turn_message(self.chat_id, self.user_id, self.message_id,
                                              self.run_id, self.conn.writer_id, takeover=takeover)
            if not claim["claimed"]:
                if claim["how"] == "gone":
                    pipe_log(f"  turn writer: chat {self.chat_id[:8]}... is gone; run "
                             f"{self.run_id[:24]}... is not written")
                else:
                    pipe_log(f"  turn writer: message {self.message_id[:8]}... is held by another writer")
                return False
            self._claim = claim
            if claim["how"] == "new":
                await _introduce_turn_message(self.chat_id, self.user_id, claim["messages"],
                                              self.message_id)
        claim = self._claim
        from open_webui.tasks import create_task

        if self.task_id is None:
            self.task_id, _ = await create_task(_owui_redis(), self._hold(), id=self.chat_id)
        meta = {"task_id": self.task_id}
        if self.wake is not None:
            # For a successor to adopt this message (ELI-103 step 4).
            meta["openclaw_wake"] = {k: self.wake.get(k) for k in ("key", "at", "job")}
        await _set_turn_meta(self.chat_id, self.message_id, meta)
        self.opened = True
        try:
            # Case 8: lets a cancel ask the page Stop or Send now. Idempotent.
            await (await self._emitter())({"type": "execute", "data": {
                "code": _page_hooks_js(self.chat_id, _auto_send_on(self.conn._valves()))}})
        except Exception as ex:
            pipe_log(f"  turn writer: intent hook install failed: {ex!r}")
        pipe_log(f"  turn writer: opened {self.message_id[:8]}... ({claim['how']}) for run "
                 f"{self.run_id[:24]}... in chat {self.chat_id[:8]}...")
        return True

    async def hold_open(self) -> None:
        """M's steered message is not yet taken in and its request ended: open
        M now, not done, so it does not read finished and empty meanwhile."""
        if self.opened or not await self.open(takeover=self.takeover):
            return
        await self._push_running()
        # The DB says so once the request's own save is in (ELI-115).
        self.handover_owed = True
        await self._stream()

    async def _push_running(self) -> None:
        """Push M not done to the chat's tabs, after its request ends: that end
        marks M done in a tab, though its run goes on here."""
        if self.request_task is not None and not self.request_task.done():
            await asyncio.wait({self.request_task}, timeout=FINAL_STATUS_REQUEST_WAIT_S)
        async with self._push_lock:
            if self.closed:
                return   # being finalized: its final push shows M done, with its lines
            message = {**self._claim["messages"][self.message_id], "content": self.sent_text,
                       "output": copy.deepcopy(self.sent_output), "done": False}
            await _introduce_turn_message(
                self.chat_id, self.user_id,
                _turn_message_patch(self.message_id, self._claim.get("parent"), message), self.message_id)

    async def show_running(self) -> None:
        """A taken-over M reads running in a tab until it is finalized, never
        done without its final lines (ELI-371, ELI-377)."""
        if self.opened or await self.open(takeover=self.takeover):
            try:
                await self._push_running()
            except Exception as ex:
                pipe_log(f"  turn writer: running push of {self.message_id[:8]}... failed: {ex!r}")

    async def working(self) -> None:
        """M's message went into the running run: show it as working."""
        if self.opened and not self.closed:
            line = {"description": "Thinking...", "done": False}
            emit = await self._emitter()
            await emit({"type": "status", "data": line})
            # Saved too, for a tab that loads the chat now.
            from open_webui.models.chats import Chats
            async with self.conn._chat_write_lock(self.chat_id):
                saved = await Chats.get_message_by_id_and_message_id(self.chat_id, self.message_id) or {}
                await _owui_upsert_message(self.chat_id, self.message_id, {
                    "statusHistory": [*(saved.get("statusHistory") or []), line]})

    def _showable(self) -> bool:
        """Condition B: a tool call, or text that is no silent sentinel."""
        if any(i.get("type") == "function_call" for i in self.renderer.output):
            return True
        return _relay_content_is_showable(self.renderer.visible_text or "")

    async def feed(self, payload: dict | None) -> None:
        """Feed one event, open on the first showable item, stream the change.
        None streams what the renderer already holds."""
        if self.closed:
            return
        try:
            if payload is not None:
                data = payload.get("data") or {}
                if payload.get("stream") == "lifecycle" and data.get("phase") == "start" \
                        and isinstance(data.get("startedAt"), (int, float)) and payload.get("runId"):
                    self.run_started.setdefault(payload["runId"], data["startedAt"])
                if payload.get("stream") == "assistant":
                    for url in _event_media_urls(data):
                        if _is_gateway_media_name(url):
                            self.gateway_media.add(url)
                        elif url not in self.event_media:
                            self.event_media.append(url)
                elif (payload.get("stream") == CODEX_ITEM_STREAM and data.get("phase") == "completed"
                      and data.get("type") == "imageGeneration"):
                    self.images_made += 1
                elif (payload.get("state") == "final" and not payload.get("message")
                      and payload.get("runId") == self.run_id and not self.renderer.output
                      and steers_mid_run_messages(self.conn.gateway_version)):
                    self.steered_message = True
                self.renderer.feed(payload)
        except Exception as ex:
            pipe_log(f"  turn writer: renderer feed failed: {ex}")
        if not self.opened:
            if not self._showable():
                return
            try:
                opened = await self.open(takeover=self.takeover)
            except Exception as ex:
                if not _db_locked(ex):
                    raise
                # The run's next event tries again (ELI-167).
                pipe_log(f"  turn writer: open of {self.message_id[:8]}... waits: Open WebUI's "
                         f"database is locked; the run's next event tries again")
                return
            if not opened:
                self.closed = True
                return
        await self._stream()

    async def _emitter(self):
        if self._emit is None:
            from open_webui.socket.main import get_event_emitter

            # update_db=False: the writer owns this message's DB writes.
            self._emit = await get_event_emitter(
                {"chat_id": self.chat_id, "message_id": self.message_id,
                 "user_id": self.user_id}, update_db=False)
        return self._emit

    async def _stream(self) -> None:
        """Emit the output change and keep the response stream current.
        Mid-turn the DB is written only once, at a handover."""
        output, text = await self._view(final=False)
        emit = await self._emitter()
        async with self._emit_lock:
            for ev in _relay_output_events(self.sent_output, output):
                await emit({"type": "response:completion", "data": ev})
            self.sent_output = copy.deepcopy(output)
            self.sent_text = text
        await _save_response_stream(self.task_id, self.chat_id, self.message_id, text, self.sent_output)
        if self.handover_owed and (self.request_task is None or self.request_task.done()):
            self.handover_owed = False
            await self._persist(done=False, output=output, text=text)

    def _introduced(self) -> bool:
        """M is a message this writer inserted and introduced to open tabs."""
        return bool(self._claim and self._claim.get("how") == "new" and self._claim.get("parent"))

    def _rewrite(self, text: str) -> str:
        for raw, shown in self.conn.turn_rewrites(self.chat_id, self.message_id or ""):
            if raw not in text:
                continue
            # Not over the same directive quoted in code (ELI-111).
            if _media_directives(raw, True) == [raw]:
                text = _replace_directive(text, raw, shown)
            else:
                text = text.replace(raw, shown)
        # Drop an unanswered prompt's directive line (ELI-58), not in a fence (ELI-107).
        return _strip_needs_input_lines(text)

    def _note_transcript_answers(self, messages: list) -> None:
        """Rebuild answered ask-user cards from the transcript when the inline
        rewrite is gone (an Open WebUI restart, PR #20). Recorded ones stay."""
        if not self.message_id:
            return
        recorded = {raw for raw, _ in self.conn.turn_rewrites(self.chat_id, self.message_id)}
        hist, prev = {"messages": messages}, None
        for run, _tool in _history_user_turns(messages):
            if run_message_id(self.session_key, self.chat_id, run, messages) != self.message_id:
                continue
            parsed = parse_pipe_run_id(run)
            if prev is not None and parsed and parsed["kind"] == "input":
                prompt = _run_prompt_text(_history_span_messages(hist, prev))
                answer = next((_strip_inbound_meta((_history_item(m) or {}).get("text") or "").strip()
                               for m in messages if _history_user_run_id(m) == run), "")
                if prompt and answer and prompt not in recorded:
                    self.conn.note_turn_rewrite(self.chat_id, self.message_id, prompt,
                                                _ask_user_detail_block(prompt, answer))
            prev = run

    async def _view(self, *, final: bool) -> tuple[list, str]:
        """(output, text) of M as the inline reply shows it: rewrites applied,
        new directives resolved, a half-arrived directive held back mid-run."""
        output = self.renderer.finished_output() if final else copy.deepcopy(self.renderer.output)
        items = [i for i in output if i.get("type") == "message" and i.get("content")]
        # Per item: an item ends a directive (ELI-147).
        for item in items:
            await self._resolve_media(self._rewrite(item["content"][0].get("text") or ""),
                                      final or item is not output[-1])
        def show(text: str, tail: bool) -> str:
            text = self._rewrite(text)
            return _advance_media_buffer("", text)[0] if tail and not final else text
        for n, item in enumerate(output):
            if item in items:
                part = item["content"][0]
                part["text"] = show(part.get("text") or "", n == len(output) - 1)
        if not items:
            return output, show(self.renderer.text, True)
        return output, "".join(i["content"][0]["text"] for i in items)

    async def _resolve_media(self, text: str, final: bool) -> None:
        """Upload each new complete `MEDIA:` directive once; record a rewrite."""
        if "MEDIA:" not in text:
            return
        for directive in _media_directives(text, final):
            if directive in self._media_failed:
                continue
            fname = directive[len(_MEDIA_TRIGGER):].strip()
            if _is_gateway_media_name(fname):
                # Its image is the run's stored block, shown as M ends (ELI-328).
                self.gateway_media.add(fname)
                self.conn.note_turn_rewrite(self.chat_id, self.message_id, directive, "")
                continue
            try:
                shown, handled = await _resolve_media_text(
                    directive, valves=self.conn._valves(), __event_emitter__=await self._emitter())
            except Exception as ex:
                pipe_log(f"  turn writer: {directive[:60]} did not resolve: {ex!r}")
                shown, handled = directive, False
            if handled and shown != directive:
                self.conn.note_turn_rewrite(self.chat_id, self.message_id, directive, shown)
            else:
                self._media_failed.add(directive)

    async def _persist(self, *, done: bool, output: list | None = None,
                       text: str | None = None, status_history: list | None = None) -> bool:
        """Write M; whether it saved. A failed upsert returns None (ELI-90)."""
        message = {"content": self.renderer.text if text is None else text,
                   "output": output if output is not None else copy.deepcopy(self.renderer.output),
                   "done": done}
        if status_history is not None:
            message["statusHistory"] = status_history
        try:
            row = await _owui_upsert_message(self.chat_id, self.message_id, message)
        except Exception as ex:
            pipe_log(f"  turn writer: persist failed: {ex}")
            return False
        if row is None:
            pipe_log(f"  turn writer: persist failed: chat {self.chat_id[:8]}... not saved")
            return False
        return True

    async def _persist_final(self, output: list, text: str, stopped: bool,
                             run_usage: dict | None = None) -> tuple[list, list, bool]:
        """M's `done: true` write with its final status lines (ELI-210), after
        the handed-over request ends. Returns M's whole status history, the new
        lines and whether the row reads back finished. `run_usage`: for a row
        with no totals (ELI-177)."""
        from open_webui.models.chats import Chats

        if self.request_task is not None and not self.request_task.done():
            await asyncio.wait({self.request_task}, timeout=FINAL_STATUS_REQUEST_WAIT_S)
            if not self.request_task.done():
                pipe_log(f"  turn writer: chat {self.chat_id[:8]}... message {self.message_id[:8]}...: "
                         f"request still running after {FINAL_STATUS_REQUEST_WAIT_S} s; "
                         f"its own status write may land after this one")
        lines = [] if stopped else await _build_usage_status_lines(
            self.conn, self.session_key, run_usage=run_usage)
        async with self.conn._chat_write_lock(self.chat_id):
            try:
                saved = await Chats.get_message_by_id_and_message_id(self.chat_id, self.message_id) or {}
            except Exception as ex:
                saved = {}
                pipe_log(f"  turn writer: reading M's status lines failed: {ex!r}")
            history, new = _final_status_history(saved.get("statusHistory"), lines, stopped)
            whole = await self._persist(done=True, output=output, text=text, status_history=history)
            if whole:
                try:
                    row = await Chats.get_message_by_id_and_message_id(self.chat_id, self.message_id) or {}
                    whole = row.get("done") is True
                except Exception as ex:
                    whole = False
                    pipe_log(f"  turn writer: reading M back failed: {ex!r}")
        return history, new, whole

    async def _push_final(self, text: str, output: list, status_history: list) -> bool:
        """Push M finished to the chat's room with its whole status history,
        the one source of its final lines in a tab: a tab never shows M done
        without them (ELI-371), and a tab replaces M's history with the push's
        while it appends each status event. Only an inserted M carries the
        parent link and moves the view: a taken-over M can have later
        messages. Returns whether the push went out."""
        if not self._claim or self.message_id not in self._claim["messages"]:
            return False
        message = {**self._claim["messages"][self.message_id],
                    "content": text, "output": output, "done": True, "statusHistory": status_history}
        new = self._introduced()
        try:
            await _introduce_turn_message(
                self.chat_id, self.user_id,
                _turn_message_patch(self.message_id, self._claim["parent"] if new else None, message),
                self.message_id if new else None, self.message_id)
        except Exception as ex:
            pipe_log(f"  turn writer: final push failed: {ex!r}")
            return False
        return True

    def adopt(self, run_id: str) -> None:
        """Write a run that continues M (resume or recovery) into M."""
        self.awaiting_row = False       # the recovery took M over
        if run_id not in self.runs:
            self.runs.append(run_id)
            self.run_marks.append((run_id, len(self.renderer.output), len(self.renderer.text)))
            self.renderer.run_boundary = True
        self.run_id = run_id

    def _adopt_recoveries_from(self, messages: list) -> None:
        """Add M's runs whose events never arrived (case 4), in transcript order."""
        order = []
        for run, tool in _history_user_turns(messages):
            if run in self.runs or (
                    (tool == RECOVERY_SOURCE_TOOL or parse_pipe_run_id(run) is not None)
                    and run_message_id(self.session_key, self.chat_id, run, messages) == self.message_id):
                order.append(run)
        self.runs = [*order, *(r for r in self.runs if r not in order)]

    async def end(self, row: dict, stop_notice_before: bool = False,
                  after_restart: bool = False) -> None:
        """The run settled (DESIGN 2.5, 2.7): keep M open, resume, or finalize."""
        if self.closed:
            return
        decision = next_continuation(row, stop_notice_before, self.resumes, after_restart)
        if decision in ("gateway", "wait"):
            # A recovery the Gateway gives up on tombstones the row to failed
            # (main-session-restart-recovery-CPJjd8da.mjs:1150).
            self.awaiting_row = True
            pipe_log(f"  turn writer: {self.message_id and self.message_id[:8]}... stays open "
                     f"({decision}) after run {self.run_id[:24]}...")
            return
        self.awaiting_row = False
        last = (row or {}).get("lastRunId")
        if decision == "resume" and last and last not in self.runs:
            # Only the named run's writer resumes: a second resume fails (ELI-159).
            decision = "finalize"
        if decision == "resume":
            self.resumes += 1
            self.pending_resume = True
            await self._send_resume()
            return
        note = None
        if turn_owner(row, stop_notice_before) == "pipe":
            note = TURN_CUT_OFF_NOTE
        elif (row or {}).get("status") in ("failed", "timeout") and row.get("lastRunError"):
            if not (row["lastRunError"].strip() == EMPTY_RESPONSE_ERROR and await self._run_is_inter_session()):
                request = self.request or (await self._run_request())[0]
                note = _plain_error(ERROR_RUN, row["lastRunError"], request)
        if note is None and await self._ask_question():
            return
        if not self._showable():
            await self._await_steered_answer()
        await self.finalize(note)

    async def _await_steered_answer(self) -> None:
        """Wait for the transcript to hold the answer of the run M's message
        was steered into. The idle push can come before the Gateway stores that
        answer, or commits the message. Ends on the answer, a failed run, or a
        restart without the run."""
        if not (self.takeover and steers_mid_run_messages(self.conn.gateway_version)
                and (parse_pipe_run_id(self.run_id) or {}).get("kind") == "reply"):
            return
        await _await_steered_answer(self.conn, self.session_key, self.run_id,
                                    f"turn writer: {self.message_id[:8]}...", steered=self.steered_message)

    async def _run_is_inter_session(self) -> bool:
        """True when this run answers another session's `sessions_send`."""
        try:
            hist = await self.conn.session_history(self.session_key, limit=RUN_HISTORY_LIMIT)
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history failed reading the run's source: {ex!r}")
            return False
        for m in (hist or {}).get("messages") or []:
            if _history_user_run_id(m) == self.run_id:
                return (m.get("provenance") or {}).get("kind") == "inter_session"
        return False

    async def _ask_question(self) -> bool:
        """Ask a closing question as a card on the chat's tab (ELI-107) and
        adopt the answer's `input` run. False when nothing was sent; M then
        ends with the question as text."""
        if self.closed or not self.opened:
            return False
        # Only after the last question already answered in M.
        text = _last_item_text(self.renderer)
        start = 0
        for raw, _ in self.conn.turn_rewrites(self.chat_id, self.message_id):
            at = text.rfind(raw)
            if at >= 0:
                start = max(start, at + len(raw))
        prompt = _prompt_tail(text, start)
        if not prompt or not _is_user_input_prompt(prompt):
            return False
        if await self._ask_card(prompt):
            return True
        # A JSON form shows as readable text (ELI-142).
        self.conn.note_turn_rewrite(self.chat_id, self.message_id, prompt,
                                    _ask_user_fallback_text(prompt))
        return False

    async def _ask_card(self, prompt: str) -> bool:
        """Show the card for `prompt` and send its answer; False if not sent."""
        payload = _native_ask_user_payload(prompt)
        if payload is None:
            return False
        try:
            response = await _call_on_chat_tab(
                self.user_id, self.chat_id, self.message_id, payload, _NATIVE_CARD_TIMEOUT_MS / 1000)
        except Exception as ex:
            pipe_log(f"  turn writer: question card failed: {ex!r}")
            return False
        if response is None:
            pipe_log(f"  turn writer: no tab views chat {self.chat_id[:8]}...; the question stays text")
            return False
        if self.closed or not (isinstance(response, dict) and response.get("status") == "answered"):
            return False
        answer = _format_native_answers(payload["data"]["questions"], response.get("answers") or {})
        if not answer:
            return False
        key = pipe_run_id(self.chat_id, self.message_id, "input")
        try:
            resp = await _run_request(self.conn, RUN_SEND, _owui_chat_send_params(
                session_key=self.session_key, message=answer, idempotency_key=key,
                owui_chat_id=self.chat_id, owui_user_id=self.user_id,
                thinking=self.thinking), timeout=30)
        except Exception as ex:
            pipe_log(f"  turn writer: sending the answer failed ({ex}); the question stays text")
            return False
        self.conn.note_turn_rewrite(self.chat_id, self.message_id, prompt,
                                    _ask_user_detail_block(prompt, answer))
        self.adopt(resp.get("runId") or key)
        pipe_log(f"  turn writer: answer sent for {self.message_id[:8]}... as {self.run_id[:32]}...")
        await self._stream()
        return True

    async def on_hello(self) -> None:
        """A new socket: send a resume the closing Gateway refused."""
        if self.pending_resume and not self.closed:
            await self._send_resume()

    async def _run_request(self) -> tuple[str | None, int]:
        """(text, attachments) of the user's message M answers: the first
        non-resume user turn naming M. (None, 0) when unreadable."""
        try:
            hist = await self.conn.session_history(self.session_key, limit=RUN_HISTORY_LIMIT)
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for the resume failed: {ex!r}")
            return None, 0
        messages = (hist or {}).get("messages") or []
        for m in messages:
            run = _history_user_run_id(m)
            if not run or not (run in self.runs or run_message_id(
                    self.session_key, self.chat_id, run, messages) == self.message_id):
                continue
            if (parse_pipe_run_id(run) or {}).get("kind") in ("input", "resume"):
                continue
            content = m.get("content")
            blocks = content if isinstance(content, list) else []
            text = content if isinstance(content, str) else "".join(
                str(b.get("text") or "") for b in blocks
                if isinstance(b, dict) and b.get("type") == "text")
            text = _strip_inbound_meta(text)
            # The Gateway stores an Open WebUI image turn's images in `__openclaw.media`.
            media = (m.get("__openclaw") or {}).get("media")
            attachments = max(sum(1 for b in blocks if isinstance(b, dict) and b.get("type") != "text"),
                              len(media) if isinstance(media, list) else 0)
            if text.lstrip().startswith(RESUME_DIRECTIVE_PREFIX):
                continue
            if text.strip() or attachments:
                return text, attachments
        return None, 0

    async def _send_resume(self) -> None:
        if not self.request and not self.request_attachments:
            self.request, self.request_attachments = await self._run_request()
        directive = _resume_directive(self.renderer.visible_text, self.request,
                                      self.request_attachments)
        key = pipe_run_id(self.chat_id, self.message_id, "resume")
        try:
            resp = await _run_request(self.conn, RUN_SEND, _owui_chat_send_params(
                session_key=self.session_key, message=directive, idempotency_key=key,
                owui_chat_id=self.chat_id, owui_user_id=self.user_id,
                thinking=self.thinking), timeout=30)
        except Exception as ex:
            pipe_log(f"  turn writer: resume refused ({ex}); sending it on the next hello")
            return
        self.pending_resume = False
        self.adopt(resp.get("runId") or key)
        pipe_log(f"  turn writer: resumed {self.message_id[:8]}... as {self.run_id[:32]}... "
                 f"({self.resumes}/{MAX_TURN_RESUMES})")

    def steered_away(self) -> dict:
        """Dedup baselines of M's run, for the steered message's reply."""
        return {"received": self.renderer.received, "stream": self.renderer.received,
                "item": self.renderer.last_item}

    async def finalize(self, note: str | None = None, stopped: bool = False,
                       steered: bool = False) -> None:
        """Write M `done: true`, from the transcript when it can, else what
        streamed. `steered`: M ends with what streamed, since the run goes on."""
        if self.closed:
            return
        self.closed = self.finalizing = True
        try:
            try:
                hist = None if steered else await self.conn.session_history(
                    self.session_key, limit=RUN_HISTORY_LIMIT)
            except Exception as ex:
                hist = None
                pipe_log(f"  turn writer: chat.history failed at the end: {ex!r}")
            streamed = list(self.renderer.output)
            if steered:
                self.renderer.flush()
            elif self.wake is not None:
                self._rebuild_wake(hist)
                self.renderer.flush()
            else:
                if hist:
                    self._adopt_recoveries_from(hist.get("messages") or [])
                if hist:
                    self._note_transcript_answers(hist.get("messages") or [])
                rebuilt = self._from_transcript(hist) if hist else None
                if rebuilt is not None:
                    self.renderer = rebuilt
                self.renderer.flush()
                if (hist and steers_mid_run_messages(self.conn.gateway_version)
                        and _history_steered_host(hist, self.run_id) is not None):
                    # Also when its lone final came after the settle.
                    self.steered_message = True
                if self.steered_message and not self._showable():
                    # The later message's reply has the answer.
                    note = note or REPLY_SENT_WITH_NEXT_NOTE
                elif not self._showable():
                    await self._show_silent_announce(hist)
            _keep_pipe_notes(streamed, self.renderer)
            # A run whose reply is only an image has no text to show.
            blocks, missing = ([], []) if steered else await self._stored_media(hist)
            if not self.opened:
                if not (self._showable() or note or blocks or missing or self.event_media) \
                        or not await self._open_at_end():
                    return
            output, text = await self._view(final=True)
            output = [i for i in output if not _is_sentinel_message_item(i)]
            text = text.strip()
            if text in _SILENT_SENTINELS:
                text = ""
            images = (await self._media_text(blocks, missing)).strip()
            if images:
                text = f"{text}\n\n{images}" if text else images
                output.append(_turn_note_item(images))
            if note:
                text = f"{text}\n\n{note}" if text else note
                output.append(_turn_note_item(note))
            run_usage = next(filter(None, (_history_usage_for_run(hist, r) for r in reversed(self.runs))),
                             None) if hist else None
            history, status, saved = await self._persist_final(output, text, stopped, run_usage)
            # ELI-340: drop the mid-turn copy, then push M finished: a tab
            # loading across the save shows M cut, and keeps the push over its
            # fetch. A failed save keeps the copy, the only whole one left.
            pushed = False
            if saved:
                await _clear_response_stream(self.task_id)
                async with self._push_lock:
                    pushed = await self._push_final(text, output, history)
                if not stopped and getattr(self.conn._valves(), "PUBLISH_CHAT_FINISHED", False):
                    await _publish_chat_finished(self.chat_id, self.message_id, self.user_id, text)
            else:
                pipe_log(f"  turn writer: chat {self.chat_id[:8]}... message {self.message_id[:8]}...: "
                         f"FINAL SAVE FAILED; keeping the mid-turn copy, M is not sent finished")
            emit = await self._emitter()
            # Without the push, the final status lines go as status events,
            # before the completion that shows M done (ELI-371). With it, a tab
            # already has them: a status event would add each one again.
            for line in status if not pushed else ():
                await emit({"type": "status", "data": line})
            await emit({"type": "chat:completion", "data": {"done": True, "content": text,
                                                             "output": output}})
            if not self.newer_run:
                await emit({"type": "chat:active", "data": {"active": False}})
            tools = sum(1 for i in output if i.get("type") == "function_call")
            pipe_log(f"  turn writer: finalized {self.message_id[:8]}... ({len(text)} chars, "
                     f"{tools} tool card(s), {len(self.runs)} run(s))")
        finally:
            self._done.set()

    async def _stored_media(self, hist: dict | None) -> tuple[list, list]:
        """(image blocks, unstored file names) of M's runs. The Gateway stores
        images after the run's final, so re-read until they arrive (ELI-328)."""
        if self.steered_into:
            return [], []
        for _s, _e, fname in _media_scan(self.renderer.text)[0]:
            if _is_gateway_media_name(fname):
                self.gateway_media.add(fname)
        names = {os.path.basename(p) for p in self.gateway_media}
        expected = self.images_made + len(self.gateway_media)

        def stored(h):
            blocks, errors = [], []
            for run in self.runs:
                blocks += _history_image_blocks_for_run(h, run)
                errors += [e for e in _history_media_errors_for_run(h, run)
                           if os.path.basename(e) in names]
            return blocks, errors
        last = [stored(hist)]

        async def read(fresh):
            if fresh:
                last[0] = stored(await self.conn.session_history(
                    self.session_key, limit=RUN_HISTORY_LIMIT))
            return last[0]
        try:
            _got, complete = await self.conn.read_until_stored(
                self.session_key, read, lambda got: len(got[0]) + len(got[1]) >= expected,
                _RUN_IMAGES_MAX_WAIT_S)
            if not complete:
                pipe_log(f"  turn writer: WARNING: the runs' images not all stored after "
                         f"{_RUN_IMAGES_MAX_WAIT_S:.0f} s; written without the rest")
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for the run's images failed: {ex!r}")
        blocks, errors = last[0]
        if expected:
            pipe_log(f"  turn writer: runs made {self.images_made} image(s) and named "
                     f"{len(self.gateway_media)} file(s); {len(blocks)} stored")
        return blocks, _unstored_gateway_media(sorted(self.gateway_media),
                                               len(blocks) - self.images_made, errors)

    async def _media_text(self, blocks: list, missing: list) -> str:
        """M's images: stored blocks, then the events' `mediaUrls`."""
        try:
            emit = await self._emitter()
            text = await _gateway_images_text(blocks, valves=self.conn._valves(),
                                              __event_emitter__=emit, missing=missing) \
                if blocks or missing else ""
            if self.event_media:
                shown, _handled = await _resolve_media_text(
                    "\n".join(f"MEDIA:{u}" for u in self.event_media) + "\n",
                    valves=self.conn._valves(), __event_emitter__=emit)
                text = f"{text}\n\n{shown}"
        except Exception as ex:
            pipe_log(f"  turn writer: the run's images could not be shown: {ex!r}")
            return ""
        return text

    async def _open_at_end(self) -> bool:
        """Retry a locked open after the run ended (no event left to retry on).
        A DB still locked is reported, not dropped silently (ELI-167)."""
        last = None
        for _ in range(OPEN_AT_END_LOCKED_TRIES):
            try:
                return await self.open(takeover=self.takeover)
            except Exception as ex:
                if not _db_locked(ex):
                    raise
                last = ex
        pipe_log(f"  turn writer: ERROR: run {self.run_id[:24]}... NOT WRITTEN to chat "
                 f"{self.chat_id[:8]}... (message {self.message_id[:8]}...): Open WebUI's database "
                 f"stayed locked for {OPEN_AT_END_LOCKED_TRIES} tries after the run ended ({last!r})")
        try:
            await (await self._emitter())({"type": "notification", "data": {
                "type": "error",
                "content": "OpenClaw: a reply could not be saved to this chat because Open WebUI's "
                           "database stayed locked. See the pipe log."}})
        except Exception as ex:
            pipe_log(f"  turn writer: notification failed: {ex!r}")
        return False

    async def _show_silent_announce(self, hist: dict | None) -> None:
        """Show a sub-agent result the parent met with silence as one card."""
        child = next(filter(None, (parse_announce_run_id(r) for r in self.runs)), None)
        if child is None:
            return
        result = await _child_result(self.conn, child)
        if not result:
            return
        # The spawn call naming the child, in either tool shape, direct or
        # through a deferred-tool wrapper (2026.10).
        label, args = None, {}
        for ev in _history_events((hist or {}).get("messages") or []):
            data = ev.get("data") or {}
            if ev.get("stream") != "tool":
                continue
            if data.get("phase") == "start":
                call = (_bare_tool_name(data.get("name") or ""), json.dumps(data.get("args") or {}))
                name, args_str = _deferred_call_view(*call) or call
                if _is_spawn_tool(name):
                    args[data.get("toolCallId")] = _json_object(args_str)
            elif (data.get("toolCallId") in args
                  and child["child_session"] in json.dumps(data.get("result"))):
                label = _spawn_title(args[data["toolCallId"]])
        tcid = f"subagent-{child['child_run']}"
        args_str = json.dumps({"label": label or child["child_session"]})
        call = _tool_call_started_event("Sub-agent", tcid, args_str)["item"]
        call["status"] = "completed"
        self.renderer = _TurnRenderer()
        self.renderer.output = [call, _tool_call_result_event(tcid, result)["item"]]
        if not self.opened:
            # A message of its own (ELI-217): 2026.10.5 retries a silent
            # delivery under the same run id; a reply must not land over the card.
            self.conn._turn_writers.pop((self.chat_id, self.message_id), None)
            self.message_id = turn_message_id(self.session_key, tcid, self.chat_id)
            self.conn._turn_writers[(self.chat_id, self.message_id)] = self

    def release(self) -> None:
        """Retired by a newer deploy: end the task (a registered one keeps the
        chat "generating"). M stays unfinished for the successor to adopt."""
        if self.closed:
            return
        self.closed = True
        self._done.set()

    def _rebuild_wake(self, hist: dict | None) -> None:
        """Repair lost events from the wake's transcript window. A wake has no
        closing message, so the rebuild is used only if it holds at least as much."""
        if not hist or self.wake.get("at") is None or self.wake.get("end") is None:
            return
        rebuilt = _history_renderer(wake_span(hist.get("messages"), self.wake["at"],
                                              self.wake["end"]))
        # The transcript may lack a wake's tool calls (not imported while a
        # user turn is queued behind it).
        if (self._holds_streamed_calls(rebuilt, "wake's")
                and len(rebuilt.output) >= len(self.renderer.output)
                and len(rebuilt.text) >= len(self.renderer.text) and rebuilt.output):
            self.renderer = rebuilt

    def _from_transcript(self, hist: dict) -> "_TurnRenderer | None":
        """M rebuilt from the transcript for the trailing runs it covers (holds
        every streamed call); earlier streamed content is kept. A killed
        claude-cli run is never imported. None while a run is open or none is
        covered."""
        spans = [_history_span_messages(hist, r, self.run_started.get(r)) for r in self.runs]
        if self.steered_into and self.runs == [self.run_id] and spans[0] is not None:
            # What streamed may be a later message's answer: the span decides.
            return _history_renderer(spans[0])
        if any(s is None for s in spans):
            pipe_log(f"  turn writer: the transcript does not show {self.message_id[:8]}...'s "
                     f"{len(self.runs)} run(s) closed; keeping what streamed")
            return None
        out, text = self.renderer.output, self.renderer.text
        starts = {run: (o, t) for run, o, t in self.run_marks}
        order = sorted(self.run_marks, key=lambda m: m[1])

        def streamed(run):
            if run not in starts:
                return []
            o = starts[run][0]
            end = min((m[1] for m in order if m[1] > o), default=len(out))
            owner = [m for m in order if m[1] == o][-1][0]   # adopted last at this point
            return out[o:end] if owner == run else []

        def covered(run, span):
            rebuilt = _history_renderer(span)
            calls = {i.get("id") for i in rebuilt.output if i.get("type") == "function_call"}
            seg = streamed(run)
            return ({i.get("id") for i in seg if i.get("type") == "function_call"} <= calls
                    and (bool(rebuilt.output) or not seg))
        k = len(self.runs)
        while k > 0 and covered(self.runs[k - 1], spans[k - 1]):
            k -= 1
        if k == len(self.runs):
            pipe_log(f"  turn writer: the transcript covers none of {self.message_id[:8]}...'s "
                     f"{len(self.runs)} run(s); keeping what streamed")
            return None
        rest = _history_renderer([m for s in spans[k:] for m in s])
        shown = self.shown.get(self.runs[k], "")
        if shown and not rest.drop_shown(shown):
            pipe_log(f"  turn writer: run {self.runs[k][:24]}... does not start with what earlier "
                     f"replies showed; keeping what streamed in {self.message_id[:8]}...")
            return None
        if not rest.output:
            return None
        cut = min((starts[r] for r in self.runs[k:] if r in starts), default=(len(out), len(text)))
        if k == 0 or cut == (0, 0):
            return rest
        prefix_out, prefix_text = copy.deepcopy(out[:cut[0]]), text[:cut[1]]
        rest_out = rest.finished_output()
        sep = _message_boundary_separator(prefix_text, rest.text) \
            if prefix_text.strip() and rest.text else ""
        if sep:
            first = next(i for i in rest_out if i.get("type") == "message")
            first["content"][0]["text"] = sep + first["content"][0]["text"]
        composed = _TurnRenderer()
        composed.output = prefix_out + rest_out
        composed.text = composed.visible_text = prefix_text + sep + rest.text
        pipe_log(f"  turn writer: {self.message_id[:8]}... keeps {len(prefix_out)} streamed item(s) of "
                 f"{k} run(s) the transcript lacks, then {len(self.runs) - k} run(s) from it")
        return composed

    def _holds_streamed_calls(self, rebuilt, whose: str) -> bool:
        """Whether a rebuild holds every tool call that streamed into M."""
        streamed = {o.get("id") for o in self.renderer.output if o.get("type") == "function_call"}
        missing = streamed - {o.get("id") for o in rebuilt.output if o.get("type") == "function_call"}
        if missing:
            pipe_log(f"  turn writer: the transcript lacks {len(missing)} of the {whose} "
                     f"{len(streamed)} streamed call(s); keeping what streamed")
        return not missing

    async def _stopped(self) -> None:
        """The task was cancelled; ask the page which button (case 8). Only a
        Stop aborts and finalizes; otherwise keep writing (case 7)."""
        intent = await _page_cancel_intent(self.user_id, self.chat_id, self.message_id)
        pipe_log(f"  turn writer: task of {self.message_id[:8]}... cancelled, page intent "
                 f"{intent or 'unknown'}")
        if intent != "stop" or self.closed:
            return
        wake = bool(self.wake and self.wake.get("job"))
        # An agent-started run first, by its id: on 2026.10.5 chat.abort says
        # `aborted` but stops only the running command.
        aborted = parse_pipe_run_id(self.run_id) is None and await self._abort_agent_run()
        if not aborted:
            try:
                resp = await _run_request(
                    self.conn, RUN_ABORT, {"sessionKey": self.session_key, "runId": self.run_id}, timeout=15)
                aborted = bool((resp or {}).get("aborted"))
            except Exception as ex:
                pipe_log(f"  turn writer: chat.abort failed: {ex}")
        if not aborted and wake:
            await self._cancel_wake_run()
        await _mark_stopped(self.chat_id, self.message_id, self.request_task)
        await self.finalize(stopped=True)

    async def _abort_agent_run(self) -> bool:
        """`sessions.abort` by run id: stops that run only, keeping the queue
        (2026.10.x). On 2026.9 it finds no run."""
        try:
            res = await self.conn.send_request("sessions.abort", {"key": self.session_key, "runId": self.run_id},
                                               timeout=15)
        except Exception as ex:
            pipe_log(f"  turn writer: sessions.abort for the wake's run failed: {ex}")
            return False
        aborted = (res or {}).get("status") == "aborted"
        if aborted:
            pipe_log(f"  turn writer: run {self.run_id[:24]}... aborted by its id")
        return aborted

    async def _cancel_wake_run(self) -> None:
        """Stop a cron wake's run on 2026.9 via its job's task (ELI-192):
        chat.abort finds no run under the sessionId."""
        job = self.wake["job"]
        try:
            resp = await self.conn.send_request("tasks.list", {"sessionKey": self.session_key, "limit": 100},
                                                timeout=10)
        except Exception as ex:
            pipe_log(f"  turn writer: tasks.list for the wake's run failed: {ex}")
            return
        tasks = [t for t in (resp or {}).get("tasks") or []
                 if t.get("runtime") == "cron" and t.get("sourceId") == job
                 and t.get("status") in ("queued", "running")
                 and self.session_key in (t.get("childSessionKey"), t.get("sessionKey"))]
        if not tasks:
            pipe_log(f"  turn writer: no running task of wake job {job[:8]}...: its run is not stopped")
        for task in tasks:
            try:
                res = await self.conn.send_request("tasks.cancel", {"taskId": task["taskId"]}, timeout=15)
                pipe_log(f"  turn writer: wake job {job[:8]}... run cancelled: "
                         f"{bool((res or {}).get('cancelled'))} {(res or {}).get('reason') or ''}")
            except Exception as ex:
                pipe_log(f"  turn writer: tasks.cancel for wake job {job[:8]}... failed: {ex}")

    def saving(self) -> bool:
        """It may still save its message: open, or closed and finalizing."""
        return not self._done.is_set() and (not self.closed or self.finalizing)

    async def wait_done(self) -> None:
        """Until this writer is done with its message."""
        await self._done.wait()

    async def _hold(self) -> None:
        """The Open WebUI task, alive while this writer owns the run."""
        try:
            await self._done.wait()
        except asyncio.CancelledError:
            if not self.closed:
                spawn_background(self._stopped())
            raise


# ---------------------------------------------------------------------------
# Routing: which writer gets a run's events (DESIGN 2.1, 2.2)
# ---------------------------------------------------------------------------
# The receive loop also reads RPC replies, so it must never await an RPC.
# Each routed run gets a queue and a pump task that feeds events in order.


def _media_directives(text: str, final: bool) -> list[str]:
    """Each complete `MEDIA:` directive in `text`, outside code (ELI-111)."""
    out = []
    for start, end, _fname in _media_scan(text, final=final)[0]:
        if text[start:end] not in out:
            out.append(text[start:end])
    return out


def _replace_directive(text: str, raw: str, shown: str) -> str:
    """`text` with `shown` for each `raw` outside code (ELI-111, ELI-117)."""
    hits = [d for d in _media_scan(text)[0] if text[d[0]:d[1]] == raw]
    return _replace_media(text, hits, lambda _fname: shown) if hits else text


async def _transcript_view(conn: "_GatewayConnection", *, session_key: str, chat_id: str,
                           user_id: str, message_id: str, runs: list, messages: list,
                           rendered: "_TurnRenderer") -> tuple[list, str]:
    """(output, text) of M from the transcript, as the writer finalizes it."""
    view = _TurnWriter(conn, session_key=session_key, chat_id=chat_id, user_id=user_id,
                       run_id=runs[-1], message_id=message_id, renderer=rendered)
    view.runs = list(runs)
    view._note_transcript_answers(messages)
    output, text = await view._view(final=True)
    output = [i for i in output if not _is_sentinel_message_item(i)]
    text = text.strip()
    return output, "" if text in _SILENT_SENTINELS else text


def _history_span_messages(history: dict, run_id: str, started_ms: float | None = None) -> list | None:
    """One run's messages, or None while it may still write. A run cut off
    with no closing turn ends where the next admitted turn begins."""
    closed = _history_run_messages(history, run_id, started_ms)
    if closed is not None:
        # After a steered-in message comes that message's answer.
        cut = next((n for n, m in enumerate(closed) if _history_user_run_id(m) not in (None, run_id)), None)
        return closed if cut is None else closed[:cut]
    steered = _history_steered_span(history, run_id)
    if steered is not None:
        return steered
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    starts = [i for i, m in enumerate(messages) if _history_user_run_id(m)]
    for n, i in enumerate(starts):
        if _history_user_run_id(messages[i]) == run_id and n + 1 < len(starts):
            return messages[i + 1:starts[n + 1]]
    return None


class _RunPump:
    def __init__(self):
        self.queue: asyncio.Queue = asyncio.Queue()
        self.writer: "_TurnWriter | None" = None
        self.handover: dict | None = None  # {message_id, renderer} of a request that ended early
        self.stop_notice_before = False
        self.wake = False               # a cron wake: runId is the sessionId (ELI-103)
        self.held: list = []            # a wake's events before its turn is known
        self.restarts_before = 0        # conn.gateway_restarts when the pump began
        self.terminal = asyncio.Event()  # the run's terminal event was queued
        # Sent more than a lone message-less final (`_steer`).
        self.started = False
        self.heartbeat = False          # a wake-id run the Gateway flagged isHeartbeat
        # A cleanly ended run a later message was steered into (`_turn_next_run`).
        self.ended_clean: str | None = None
        # Its writer's message was steered in after this reply (`_steer`).
        self.steered_earlier: dict | None = None


def _turn_route_now(conn: "_GatewayConnection", payload: dict) -> bool:
    """Queue `payload` for its run's writer when no live request consumes it
    (DESIGN 2.6). True when handled. Never awaits (`drain_held` order)."""
    sess, run = payload.get("sessionKey") or "", payload.get("runId") or ""
    if not (getattr(conn, "writes_turns", False) and sess and run) or conn._retired:
        return False
    conn.note_session_id(sess, payload.get("sessionId"))
    parsed = conn.parse_owui_session_key(sess)
    if not parsed:
        _note_child_result(conn, payload)
        return False
    if conn.consumers_for_event(payload) or _served_by_retired(payload):
        return False  # a live reply, here or on an earlier load's connection, writes it
    if owui_shutting_down():
        # The next startup's reconcile finishes them (ELI-90, ELI-94); a writer
        # opened now would save done:false and die (ELI-173).
        return True
    if run.startswith(ACTION_RUN_PREFIX):
        return True  # the Status Action's own runs render nothing
    if (sess, run) in conn._held_for_live:
        conn.drain_held(sess, run)  # the earlier ones first
    if conn.live_reply_owns(sess, run):
        conn.hold_for_live(sess, run, payload)
        return True
    _note_heartbeat_run(conn, payload)
    if (sess, run) in conn._turn_skip_runs:
        return True
    if conn.was_delivered_live(sess, run):
        # A late event reopens nothing.
        return True
    if not _turn_kind_known(conn, sess, run, payload):
        return True
    return _turn_queue(conn, sess, run, parsed, payload)


def _turn_queue(conn: "_GatewayConnection", sess: str, run: str, parsed: tuple,
                payload: dict) -> bool:
    pump = conn._turn_pumps.get((sess, run))
    if pump is None:
        pump = conn._turn_pumps[(sess, run)] = _RunPump()
        pump.restarts_before = conn.gateway_restarts
        target = conn._run_targets.get(f"{sess}:{run}")
        if target is not None:
            # DESIGN 2.6: continue from the shadow renderer, which holds this event.
            pump.handover = conn.handover_of(sess, run)
            pump.started = _handover_started(pump.handover)
            conn.unregister_run_target(sess, run)
        spawn_background(_turn_pump_loop(conn, sess, run, parsed, pump))
        spawn_background(conn.ensure_message_subscription(sess))
        child = parse_announce_run_id(run)
        if child is not None:
            # Read before the Gateway deletes a `cleanup: "delete"` child.
            spawn_background(_child_result(conn, child))
        if target is not None:
            return True
    if payload.get("state") in ("final", "error", "aborted"):
        pump.stop_notice_before = conn._stop_notice_seen
    if _is_terminal_event(payload):
        pump.terminal.set()
    if not (payload.get("state") == "final" and not payload.get("message")):
        pump.started = True
    pump.queue.put_nowait(("event", payload))
    if _is_error_event(payload) and parse_pipe_run_id(run) is None:
        # ELI-217: on 2026.10.5 an erroring agent-started run gets no settle
        # push, so its error events re-read the row.
        spawn_background(_turn_reread_row(conn, sess))
    return True


def _handover_started(handover: dict) -> bool:
    """The handed-over run showed something, so it is not waiting on a steer."""
    renderer = handover.get("renderer")
    return bool(getattr(renderer, "received", "") or getattr(renderer, "output", None))


def _is_error_event(payload: dict) -> bool:
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    return payload.get("state") == "error" or (
        payload.get("stream") == "lifecycle" and data.get("phase") == "error")


def _note_child_result(conn: "_GatewayConnection", payload: dict) -> None:
    """Keep a spawned sub-agent's result from its chat final
    (server-chat-CbnqM5f6.mjs emitChatTerminal): a `cleanup: "delete"` child
    is gone by its announce's end (subagent-announce-BIG31XbZ.mjs:413)."""
    if payload.get("state") != "final" or not conn.parse_owui_session_key(payload.get("spawnedBy") or ""):
        return
    text = (_history_item(payload.get("message")) or {}).get("text") or ""
    if text.strip():
        _keep_child_result(conn, payload["sessionKey"], payload["runId"], text.strip())


def _keep_child_result(conn: "_GatewayConnection", child_session: str, child_run: str,
                       text: str) -> None:
    conn._child_results[(child_session, child_run)] = text
    if len(conn._child_results) > 200:
        for stale in list(conn._child_results)[:100]:
            conn._child_results.pop(stale, None)


async def _child_result(conn: "_GatewayConnection", child: dict) -> str | None:
    """The announced sub-agent run's result: kept, else from its transcript."""
    key = (child["child_session"], child["child_run"])
    if key in conn._child_results:
        return conn._child_results[key]
    try:
        child_hist = await conn.session_history(child["child_session"], limit=20)
    except Exception as ex:
        pipe_log(f"  turn writer: child transcript of {child['child_session'][-12:]} "
                 f"unreadable: {ex!r}")
        return None
    found, result = _history_text_for_run(child_hist, child["child_run"])
    if not (found and result):
        return None
    _keep_child_result(conn, *key, result)
    return result


def _note_heartbeat_run(conn: "_GatewayConnection", payload: dict) -> None:
    """Condition B: a heartbeat run gets no message. Only its agent events
    carry isHeartbeat (server-chat-CbnqM5f6.mjs:791, 823-826), so remember it."""
    sess, run = payload.get("sessionKey"), payload.get("runId")
    if payload.get("isHeartbeat") is not True or not (sess and run):
        return
    if run == conn._session_ids.get(sess):
        return  # a wake's id: never skip it for good (handled in _wake_step)
    held = conn._turn_unkinded.pop((sess, run), None)
    if held:
        pipe_log(f"  turn writer: heartbeat run {run[:24]}...: {len(held)} earlier event(s) not shown")
    conn._turn_skip_runs[(sess, run)] = True
    if len(conn._turn_skip_runs) > 500:
        for stale in list(conn._turn_skip_runs)[:250]:
            conn._turn_skip_runs.pop(stale, None)


# Bounds on runs held unclassified; past these is a leak, not a wait.
_UNKINDED_RUNS_MAX = 64
_UNKINDED_EVENTS_MAX = 500


def _classifies(payload: dict) -> bool:
    """An event that tells a heartbeat run apart: a non-tool agent event
    (session.tool copies lack the flag) or the run's end."""
    stream = payload.get("stream")
    return (bool(stream) and stream != "tool") or _is_terminal_event(payload)


def _turn_kind_known(conn: "_GatewayConnection", sess: str, run: str, payload: dict) -> bool:
    """Hold an agent run's events in order until it is known not to be a
    heartbeat. Pipe runs and cron wakes need no wait."""
    if (sess, run) in conn._turn_kinded or parse_pipe_run_id(run) is not None \
            or run == conn._session_ids.get(sess):
        return True
    if not _classifies(payload):
        held = conn._turn_unkinded.setdefault((sess, run), [])
        if len(held) < _UNKINDED_EVENTS_MAX:
            held.append(payload)
        while len(conn._turn_unkinded) > _UNKINDED_RUNS_MAX:
            stale = next(iter(conn._turn_unkinded))
            pipe_log(f"  turn writer: run {stale[1][:24]}... never classified: released")
            _release_unkinded(conn, *stale)
        return False
    _release_unkinded(conn, sess, run)
    return True


def _release_unkinded(conn: "_GatewayConnection", sess: str, run: str) -> None:
    conn._turn_kinded[(sess, run)] = True
    if len(conn._turn_kinded) > 500:
        for stale in list(conn._turn_kinded)[:250]:
            conn._turn_kinded.pop(stale, None)
    for ev in conn._turn_unkinded.pop((sess, run), []):
        _turn_route_now(conn, ev)


def _hand_over_run(conn: "_GatewayConnection", session_key: str, run_id: str, *,
                   thinking: str | None = None, read_row: bool = False,
                   reply: dict | None = None) -> bool:
    """Hand an interrupted run's message to the turn writer (DESIGN 2.6); its
    settled row decides who continues (2.7). `read_row`: read it now, in
    case the resync already passed. `reply`: a request's own state at an
    event gap; `no_resume` for a run Send now kept (ELI-158)."""
    key = f"{session_key}:{run_id}"
    target = conn._run_targets.get(key)
    parsed = conn.parse_owui_session_key(session_key)
    if ((target is None and reply is None) or not parsed or not conn.writes_turns
            or conn._retired or (session_key, run_id) in conn._turn_pumps):
        return False
    pump = conn._turn_pumps[(session_key, run_id)] = _RunPump()
    pump.restarts_before = conn.gateway_restarts
    if reply is None:
        pump.handover = conn.handover_of(session_key, run_id, thinking)
        pump.started = _handover_started(pump.handover)
    else:
        pump.handover = {"message_id": reply["message_id"], "renderer": reply["renderer"],
                         "thinking": thinking or (target or {}).get("thinking"), "shown": "",
                         "no_resume": bool(reply.get("no_resume")),
                         "request_task_id": (target or {}).get("request_task_id"),
                         "steer_pending": bool(reply.get("steer_pending")
                                               or (target or {}).get("steer_pending"))}
        pump.started = _handover_started(pump.handover)
        for payload in reply["events"]:
            pump.queue.put_nowait(("event", payload))
            pump.started = pump.started or not (payload.get("state") == "final"
                                                and not payload.get("message"))
    pump.stop_notice_before = conn._stop_notice_seen
    conn.unregister_run_target(session_key, run_id)
    spawn_background(_turn_pump_loop(conn, session_key, run_id, parsed, pump))
    spawn_background(conn.ensure_message_subscription(session_key))
    if read_row:
        spawn_background(_turn_resync(conn, skip=set(conn.active_run_snapshot)))
    pipe_log(f"  handed run {run_id[:24]}... over to the turn writer "
             f"(message {pump.handover['message_id'][:8]}...)")
    return True


def _turn_settled(conn: "_GatewayConnection", session_key: str, row: dict) -> None:
    """The session went idle: its row decides each writer (DESIGN 2.5, 2.7).
    A run still unclassified is no heartbeat and is released first."""
    for (sess, run) in [k for k in conn._turn_unkinded if k[0] == session_key]:
        _release_unkinded(conn, sess, run)
    pumps = [run for (sess, run) in conn._turn_pumps if sess == session_key]
    if pumps:
        pipe_log(f"  session settled (status {row.get('status')!r}, last run "
                 f"{str(row.get('lastRunId'))[-24:]}): {len(pumps)} turn writer run(s)")
    for (sess, _run), pump in list(conn._turn_pumps.items()):
        if sess == session_key:
            pump.queue.put_nowait(("settled", row))


def _turn_next_run(conn: "_GatewayConnection", payload: dict) -> None:
    """A new run's event means earlier runs are over: end cleanly ended
    steered runs from the transcript. 2026.10.10 pushes no idle after a
    follow-up run (ELI-215). A terminal event starts no run."""
    if _is_terminal_event(payload):
        return
    sess, run_id = payload.get("sessionKey"), payload.get("runId")
    for (s, run), pump in list(conn._turn_pumps.items()):
        if s == sess and pump.ended_clean and pump.ended_clean != run_id:
            pump.ended_clean = None
            if pump.writer is not None:
                pump.writer.newer_run = True
            pipe_log(f"  next run {str(run_id)[:24]}... started: run {run[:24]}... ends from the transcript")
            pump.queue.put_nowait(("settled", None))


async def _await_recovery_turn(conn: "_GatewayConnection", sess: str, run: str,
                               pump: _RunPump) -> None:
    """Rule E needs a recovery run's `:user` turn, which 2026.10 commits about
    0.7 s after the first event: wait for the next append or the run's end."""
    if parse_pipe_run_id(run) is not None:
        return
    while not pump.terminal.is_set():
        if not any(w.session_key == sess and not w.closed and (w.awaiting_row or w.takeover)
                   for w in list(conn._turn_writers.values())):
            return
        appended = conn.session_message_event(sess)
        try:
            messages = (await conn.session_history(sess, limit=50, max_chars=200)).get("messages")
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for run {run[:24]}... failed: {ex!r}")
            return
        if any(r == run for r, _tool in _history_user_turns(messages)):
            return
        waits = [asyncio.ensure_future(appended.wait()), asyncio.ensure_future(pump.terminal.wait())]
        try:
            await asyncio.wait(waits, return_when=asyncio.FIRST_COMPLETED)
        finally:
            for w in waits:
                w.cancel()


async def _turn_writer_for(conn: "_GatewayConnection", sess: str, run: str,
                           user_id: str, chat_id: str) -> "_TurnWriter | None":
    # Two runs can name one message, so resolve and register in one step.
    async with conn._turn_resolve_lock:
        return await _turn_writer_for_locked(conn, sess, run, user_id, chat_id)


async def _turn_writer_for_locked(conn, sess, run, user_id, chat_id):
    messages = None
    if parse_pipe_run_id(run) is None:
        # Rule E: only the transcript names a recovery's message.
        try:
            messages = (await conn.session_history(sess, limit=50, max_chars=200)).get("messages")
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for rule E failed: {ex!r}")
    mid = run_message_id(sess, chat_id, run, messages)
    if mid is None:
        return None
    writer = conn._turn_writers.get((chat_id, mid))
    if writer is not None and not writer.closed:
        writer.adopt(run)
        return writer
    # A pipe run takes over Open WebUI's stub (no request left after a restart).
    writer = _TurnWriter(conn, session_key=sess, chat_id=chat_id, user_id=user_id,
                         run_id=run, message_id=mid,
                         takeover=parse_pipe_run_id(run) is not None)
    conn._turn_writers[(chat_id, mid)] = writer
    return writer


async def _turn_pump_loop(conn: "_GatewayConnection", sess: str, run: str,
                          parsed: tuple, pump: _RunPump) -> None:
    user_id, chat_id = parsed
    try:
        handed = pump.handover
        if pump.writer is not None:
            pass  # adopted from a gone writer's message (_adopt_turn_message)
        elif handed is not None:
            request = _owui_request_task(handed.get("request_task_id"))
            pump.writer = _TurnWriter(conn, session_key=sess, chat_id=chat_id, user_id=user_id,
                                      run_id=run, message_id=handed["message_id"], takeover=True,
                                      renderer=handed["renderer"], thinking=handed.get("thinking"),
                                      shown=handed.get("shown", ""), request=request)
            if request is not None and not request.done():
                # Stream again after its save, to write the handover.
                request.add_done_callback(lambda _t: pump.queue.put_nowait(("event", None)))
            conn._turn_writers[(chat_id, handed["message_id"])] = pump.writer
            if handed.get("no_resume"):
                # Kept by Send now (ELI-158): a resume would race the new
                # message (ELI-159).
                pump.writer.resumes = MAX_TURN_RESUMES
            await pump.writer.feed(None)
            if handed.get("steer_pending"):
                await pump.writer.hold_open()
            else:
                spawn_background(pump.writer.show_running())
        elif re.fullmatch(_UUID_RE, run) and run == await conn.session_id_for(sess):
            pump.wake = True
        else:
            await _await_recovery_turn(conn, sess, run, pump)
            pump.writer = await _turn_writer_for(conn, sess, run, user_id, chat_id)
        while True:
            kind, item = await pump.queue.get()
            if kind == "retired":
                return
            if pump.wake:
                if await _wake_step(conn, sess, run, user_id, chat_id, pump, kind, item):
                    return
                continue
            writer = pump.writer
            if kind == _PUMP_STEERED_IN:
                if writer is not None:
                    writer.steered_into = item.get("run")
                    writer.renderer.seed(item.get("run_text"))
                    await writer.working()
                    pipe_log(f"  turn writer: {writer.message_id[:8]}... shows run "
                             f"{str(item.get('run'))[:24]}... from its message's commit")
                continue
            if kind == "steered":
                # A later message was steered in: its reply continues from M.
                try:
                    item.set_result({**writer.steered_away(), "earlier": {
                        "chat_id": writer.chat_id, "message_id": writer.message_id,
                        "request_task_id": None, "span_run": run}} if writer is not None else None)
                    if writer is not None:
                        await writer.finalize(steered=True)
                        conn._turn_writers.pop((chat_id, writer.message_id), None)
                finally:
                    if not item.done():
                        item.set_result(None)
                return
            if kind == "event":
                if writer is not None:
                    await writer.feed(item)
                if not (writer is not None and writer.run_id == run and _ends_on_own_final(run, item)):
                    continue
                # 2026.10.5 pushes no settle for a Gateway-started run (ELI-215),
                # so its clean final ends it.
                item = None
            # Only the pump of the writer's current run ends it.
            if writer is not None and writer.run_id == run:
                unjudged = (conn.gateway_restarts > pump.restarts_before and not pump.terminal.is_set()
                            and judges_cut_runs_after_listening(conn.gateway_version))
                await writer.end(item, stop_notice_before=pump.stop_notice_before,
                                 after_restart=unjudged)
                if writer.closed:
                    conn._turn_writers.pop((chat_id, writer.message_id), None)
                elif writer.awaiting_row and writer.run_id == run:
                    continue  # R2: the next row of the session decides again
            return
    except Exception as ex:
        pipe_log(f"  turn writer: pump for run {run[:24]}... failed: {ex!r}")
    finally:
        if conn._turn_pumps.get((sess, run)) is pump:
            conn._turn_pumps.pop((sess, run), None)
            # Wakes share this run id: what queued after the end is the next one's.
            while pump.wake and not pump.queue.empty():
                kind, item = pump.queue.get_nowait()
                if kind == "event" and item is not None:
                    _turn_queue(conn, sess, run, parsed, item)


def _ends_on_own_final(run: str, payload) -> bool:
    """An agent-started run's chat final: over whatever the row says."""
    return (isinstance(payload, dict) and payload.get("state") == "final"
            and parse_pipe_run_id(run) is None)


def _is_terminal_event(payload: dict) -> bool:
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    return payload.get("state") in ("final", "error", "aborted") or (
        payload.get("stream") == "lifecycle" and data.get("phase") in ("end", "error"))


def _event_ms(payload: dict) -> float:
    """The event's `ts`, else receive time (the Gateway shares this clock)."""
    ts = payload.get("ts")
    return float(ts) if isinstance(ts, (int, float)) else time.time() * 1000


# chat.history returns at most this many messages (CHAT_HISTORY_MAX_ENTRIES,
# chat-history-constants-C-H8nkgi.mjs:3).
CHAT_HISTORY_MAX = 1000


async def _wake_bind(conn: "_GatewayConnection", sess: str, run: str, user_id: str,
                     chat_id: str, pump: _RunPump, at_ms: float) -> tuple[str, float | None]:
    """Bind the wake to its turn's message: ("bound", job start), ("wait",
    None) until the turn is committed, or ("stray", None) when no wake runs."""
    try:
        jobs = (await conn.send_request("cron.list", {"includeDisabled": True}, timeout=15)).get("jobs")
    except Exception as ex:
        pipe_log(f"  turn writer: cron.list for a wake failed: {ex!r}")
        return "wait", None
    starts = [(j.get("state") or {}).get("runningAtMs") for j in jobs or []
              if j.get("sessionTarget") == f"session:{sess}"]
    running_start = min((s for s in starts if isinstance(s, (int, float))), default=None)
    # A heard job run counts even once a one-shot job left cron.list.
    heard = conn.cron_run_at(sess, at_ms)
    if heard is not None:
        running_start = heard["start"]
    bound = conn._wake_turns_bound.setdefault(sess, set())
    # Read back until the window reaches before the job start.
    limit, turn = 50, None
    while True:
        try:
            messages = (await conn.session_history(sess, limit=limit, max_chars=200)).get("messages") or []
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for a wake failed: {ex!r}")
            return "wait", None
        turn = (wake_turn_of_run(messages, heard["job"], heard["start"], bound) if heard is not None
                else wake_turn_at(messages, at_ms, bound))
        oldest = min((m.get("timestamp") for m in messages
                      if isinstance(m.get("timestamp"), (int, float))), default=None)
        if (turn is not None or running_start is None or len(messages) < limit
                or limit >= CHAT_HISTORY_MAX or (oldest is not None and oldest < running_start)):
            break
        limit = min(limit * 4, CHAT_HISTORY_MAX)
    if heard is not None:
        start = heard["start"] if turn is not None else None
    else:
        start = await _wake_job_start(conn, turn, at_ms, jobs) if turn is not None else None
    if start is None:
        return ("wait", None) if running_start is not None else ("stray", None)
    bound.add(turn["key"])
    mid = turn_message_id(sess, turn["key"], chat_id)
    pump.writer = _TurnWriter(conn, session_key=sess, chat_id=chat_id, user_id=user_id,
                              run_id=run, message_id=mid, wake=dict(turn))
    conn._turn_writers[(chat_id, mid)] = pump.writer
    pipe_log(f"  turn writer: wake turn {turn['key'][:8]}... (cron job {turn['job'][:8]}...) "
             f"is message {mid[:8]}...")
    return "bound", start


async def _wake_job_start(conn: "_GatewayConnection", turn: dict, at_ms: float,
                          jobs: list | None) -> float | None:
    """Start of the cron job run that wrote `turn`, if the event at `at_ms` is
    that run's; else None. Other runs with runId = sessionId (a compaction)
    are no wake."""
    job, at = turn.get("job"), turn.get("at") or 0
    running = next(((j.get("state") or {}).get("runningAtMs") for j in jobs or []
                    if j.get("id") == job), None)
    if running and running <= at:
        return running
    run = await _wake_job_run(conn, job, at)
    if run is not None and at_ms <= (run.get("ts") or 0):
        return run.get("runAtMs") or 0
    return None


async def _wake_job_run(conn: "_GatewayConnection", job: str, turn_at: float) -> dict | None:
    """The finished `cron.runs` entry of `job` spanning `turn_at`."""
    try:
        runs = (await conn.send_request("cron.runs", {"id": job, "limit": 20}, timeout=15)).get("entries")
    except Exception as ex:
        pipe_log(f"  turn writer: cron.runs for wake job {str(job)[:8]}... failed: {ex!r}")
        return None
    done = [e for e in runs or [] if e.get("action") == "finished"
            and (e.get("runAtMs") or 0) <= turn_at <= (e.get("ts") or 0)]
    return min(done, key=lambda e: e.get("ts") or 0, default=None)


async def _wake_step(conn: "_GatewayConnection", sess: str, run: str, user_id: str,
                     chat_id: str, pump: _RunPump, kind: str, item) -> bool:
    """One queue item of a cron wake; True when it is over. Only its own
    terminal ends a wake: the row stays idle while it runs."""
    if kind == "settled":
        return False
    if kind == "event" and (pump.heartbeat or item.get("isHeartbeat") is True):
        # Condition B per pump, not per run id: wakes share it (ELI-103 f).
        pump.heartbeat = True
        pump.held.clear()
        if pump.writer is not None and not pump.writer.opened:
            pump.writer.closed = True
        if _is_terminal_event(item):
            await _wake_finish(conn, sess, run, pump, _event_ms(item))
            return True
        return False
    if kind == "wake-ended":
        await _wake_finish(conn, sess, run, pump, item)
        return True
    if pump.writer is None:
        pump.held.append(item)
        state, start = await _wake_bind(conn, sess, run, user_id, chat_id, pump, _event_ms(item))
        if state == "stray":
            # Holding them would hand them to the next wake (same run id).
            pipe_log(f"  turn writer: {len(pump.held)} sessionId event(s) on {sess[-12:]} with no "
                     "running cron wake: not shown")
            pump.held.clear()
            return True
        if pump.writer is not None:
            held, pump.held = pump.held, []
            for ev in held:
                if _event_ms(ev) >= start:  # older ones predate this wake's run
                    await pump.writer.feed(ev)
    else:
        await pump.writer.feed(item)
    if _is_terminal_event(item):
        await _wake_finish(conn, sess, run, pump, _event_ms(item))
        return True
    return False


async def _wake_finish(conn: "_GatewayConnection", sess: str, run: str, pump: _RunPump,
                       end_ms: float) -> None:
    writer = pump.writer
    if writer is None:
        if not pump.heartbeat:
            pipe_log(f"  turn writer: a sessionId run on {sess[-12:]} ended with no running "
                     f"cron wake turn; {len(pump.held)} event(s) not shown")
    elif not writer.closed:  # a heartbeat that already showed something is finished too
        writer.wake["end"] = end_ms
        # Off this pump: the next wake (same run id) must not wait on a card.
        spawn_background(_wake_close(conn, writer, ask=not pump.heartbeat))
    else:
        conn._turn_writers.pop((writer.chat_id, writer.message_id), None)
    # The next wake reuses this run id: nothing remembered for it may carry over.
    conn._turn_skip_runs.pop((sess, run), None)
    conn._delivered_live.pop(f"{sess}:{run}", None)


async def _wake_close(conn: "_GatewayConnection", writer: "_TurnWriter", *, ask: bool) -> None:
    """End a wake's message: ask a closing question (ELI-180), else finalize.
    Stays registered until closed so the answer run finds it."""
    try:
        if not (ask and await writer._ask_question()):
            await writer.finalize()
    except Exception as ex:
        pipe_log(f"  turn writer: ending wake message {writer.message_id[:8]}... failed: {ex!r}")
    finally:
        if writer.closed:
            conn._turn_writers.pop((writer.chat_id, writer.message_id), None)


async def _wake_resync(conn: "_GatewayConnection") -> None:
    """After a reconnect, end wakes whose terminal was missed. The row is idle
    during a wake, so the cron job's `runningAtMs` decides."""
    wakes = [(k, p) for k, p in conn._turn_pumps.items()
             if p.wake and p.writer is not None and p.writer.wake]
    if not wakes:
        return
    try:
        jobs = (await conn.send_request("cron.list", {"includeDisabled": True}, timeout=15)).get("jobs")
    except Exception as ex:
        pipe_log(f"  turn writer: cron.list after hello failed: {ex!r}")
        return
    running = {j.get("id") for j in jobs or [] if (j.get("state") or {}).get("runningAtMs")}
    for (_sess, _run), pump in wakes:
        wake = pump.writer.wake
        if wake["job"] not in running:
            # It ended at the job run's finish, not now: a queued run may have
            # written since. None keeps what streamed.
            run = await _wake_job_run(conn, wake["job"], wake.get("at") or 0)
            pump.queue.put_nowait(("wake-ended", (run or {}).get("ts")))


async def _adopt_turn_message(conn: "_GatewayConnection", *, chat_id: str, user_id: str,
                              session_key: str, message_id: str, meta: dict) -> str:
    """Take over a message a retired or dead writer left unfinished, by the
    run its meta names. Returns "adopted" or "skip"."""
    run = meta.get("openclaw_run")
    if not run or (session_key, run) in conn._turn_pumps or conn._retired:
        return "skip"
    pump = conn._turn_pumps[(session_key, run)] = _RunPump()
    pump.restarts_before = conn.gateway_restarts
    wake = meta.get("openclaw_wake") if isinstance(meta.get("openclaw_wake"), dict) else None
    if wake and wake.get("key"):
        pump.wake = True
        conn._wake_turns_bound.setdefault(session_key, set()).add(wake["key"])
    pump.writer = _TurnWriter(conn, session_key=session_key, chat_id=chat_id, user_id=user_id,
                              run_id=run, message_id=message_id, takeover=True,
                              wake=dict(wake) if pump.wake else None)
    conn._turn_writers[(chat_id, message_id)] = pump.writer
    spawn_background(_turn_pump_loop(conn, session_key, run, (user_id, chat_id), pump))
    spawn_background(conn.ensure_message_subscription(session_key))
    pipe_log(f"  turn writer: adopted {message_id[:8]}... (run {run[:24]}...) from writer "
             f"{str(meta.get('openclaw_writer'))[:12]}...")
    if pump.wake:
        await _wake_resync(conn)
        return "adopted"
    try:
        lst = await conn.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                      timeout=15)
    except Exception as ex:
        pipe_log(f"  turn writer: row read for an adopted message failed: {ex!r}")
        return "adopted"
    row = next((r for r in (lst.get("sessions") or []) if r.get("key") == session_key), None)
    if row is not None and not row.get("hasActiveRun"):
        pump.queue.put_nowait(("settled", row))
    return "adopted"


async def _turn_after_hello(conn: "_GatewayConnection") -> None:
    """After a reconnect: send refused resumes and end runs whose settle was missed."""
    for writer in list(conn._turn_writers.values()):
        if writer.pending_resume:
            await writer.on_hello()
    await _turn_resync(conn, skip=set(conn.active_run_snapshot))
    await _wake_resync(conn)


async def _turn_resync(conn: "_GatewayConnection", skip: set = frozenset()) -> None:
    """Re-read rows of sessions with a pump or inline reply and end the idle
    ones. Inline replies get the row even when busy: one may have lost its
    final in the gap while a later run runs. While the socket is coming back
    it reads nothing: that reconnect's hello runs this again (ELI-369)."""
    if conn.reconnecting:
        return
    idle = {sess for (sess, _run) in [*conn._turn_pumps, *conn._turn_unkinded] if sess not in skip}
    idle |= {c.session_key for c in list(conn._consumers.values()) if c.session_key not in skip}
    for sess in idle:
        read_at = time.monotonic()
        try:
            lst = await conn.send_request("sessions.list", {"search": sess[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  turn writer: row read for a resync failed: {ex!r}")
            continue
        row = next((r for r in (lst.get("sessions") or []) if r.get("key") == sess), None)
        if row is None:
            continue
        if not row.get("hasActiveRun"):
            _turn_settled(conn, sess, row)
        conn.row_to_consumers(sess, row, resync=True, read_at=read_at, outside_loop=True)


def _history_run_messages(history: dict, run_id: str, started_ms: float | None = None) -> list | None:
    """One closed run's messages, back to the previous run's closing message;
    None until it closes. `started_ms` cuts a silent previous run's leftovers
    (ELI-227). The walk goes past steered-in messages (ELI-271) and drops a
    wake prompt that sorts inside the run."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id:
        return None
    for end in range(len(messages) - 1, -1, -1):
        message = messages[end]
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        if run_id not in _idempotency_keys(message) and _run_closed_by(message) != run_id:
            continue
        start, queued = end, set()
        while start > 0 and _run_closed_by(messages[start - 1]) in (None, run_id) \
                and not _stamped_before(messages[start - 1], started_ms):
            if (messages[start - 1] or {}).get("role") == "user":
                if _history_queued_prompt(messages, start - 1, run_id):
                    queued.add(start - 1)
                # Past messages steered into it (2026.10.10).
                elif not (_history_steered_into(history, start - 1) == run_id
                          or (_history_imported_copy(messages, start - 1)
                              and _history_steered_into(history, start - 2) == run_id)):
                    break
            start -= 1
        return [m for i, m in enumerate(messages[start:end + 1], start) if i not in queued]
    return None


def _history_ran(history: dict, run_id: str) -> bool:
    """`run_id` wrote a message of its own: it ran, not steered into another."""
    return any(isinstance(m, dict) and m.get("role") == "assistant"
               and (run_id in _idempotency_keys(m) or _run_closed_by(m) == run_id)
               for m in (history or {}).get("messages") or [])


def _history_imported_copy(messages: list, index: int) -> bool:
    """The unkeyed copy claude-cli imports right after a `chat.send` message."""
    m = messages[index] if 0 <= index < len(messages) else None
    return (isinstance(m, dict) and m.get("role") == "user" and not _history_user_run_id(m)
            and index > 0 and bool(_history_user_run_id(messages[index - 1])))


def _history_steered_into(history: dict, index: int) -> str | None:
    """The run the user message at `index` was steered into (2026.10.10+):
    its own run never wrote, and the last run before it did."""
    messages = (history or {}).get("messages") or []
    own = _history_user_run_id(messages[index]) if 0 <= index < len(messages) else None
    if not own or _history_ran(history, own) or _history_wake_prompt(messages[index]):
        return None
    for k in range(index - 1, -1, -1):
        m = messages[k]
        rid = _history_user_run_id(m)
        if rid:
            if _history_ran(history, rid):
                closers = {_run_closed_by(x) for x in messages[k + 1:index]} - {None}
                return rid if closers <= {rid} else None
            continue
        if isinstance(m, dict) and m.get("role") == "user" and not _history_imported_copy(messages, k):
            return None
    return None


def _history_wake_prompt(message: dict) -> bool:
    """A cron wake's prompt, never steered: on 2026.10.10 it runs after the
    busy run but sorts inside it by fire time. Pipe messages never count."""
    own = _history_user_run_id(message)
    return bool(own) and not parse_pipe_run_id(own) and bool(_cron_turn_job(message))


def _history_next_turn(message: dict) -> bool:
    """A later send that ends a steered message's answer (not a wake prompt)."""
    return bool(_history_user_run_id(message)) and not _history_wake_prompt(message)


def _history_steered_host(history: dict, run_id: str) -> str | None:
    """The run `run_id`'s message was steered into, or None."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id or _history_ran(history, run_id):
        return None
    start = next((n for n, m in enumerate(messages) if _history_user_run_id(m) == run_id), None)
    return _history_steered_into(history, start) if start is not None else None


def _history_steered_answer_pending(history: dict, run_id: str, uncommitted: bool = False,
                                    steered: bool = False) -> bool:
    """`run_id`'s steered message has no answer in the transcript yet and no
    later turn began. `uncommitted`/`steered` also count an uncommitted or
    not yet hosted message as pending."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return False
    start = next((n for n, m in enumerate(messages) if _history_user_run_id(m) == run_id), None)
    if start is None:
        return uncommitted
    if any(_history_next_turn(m) for m in messages[start + 1:]):
        return False
    if _history_steered_host(history, run_id) is None:
        return steered and not _history_ran(history, run_id) and not any(
            isinstance(m, dict) and m.get("role") == "assistant" for m in messages[start + 1:])
    return _history_steered_span(history, run_id) is None


def _history_steered_span(history: dict, run_id: str) -> list | None:
    """The answer to a steered message: the host run's messages after it, up
    to the next turn or the host's closing message. None if not steered or
    the host has not closed."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id or _history_ran(history, run_id):
        return None
    start = next((n for n, m in enumerate(messages) if _history_user_run_id(m) == run_id), None)
    host = _history_steered_into(history, start) if start is not None else None
    if host is None:
        return None
    closers = [n for n in range(start + 1, len(messages)) if _run_closed_by(messages[n]) == host]
    if not closers:
        return None
    end = next((n for n in range(start + 1, len(messages)) if _history_next_turn(messages[n])),
               len(messages))
    last = max((n for n in closers if n < end), default=end - 1)
    span = [m for m in messages[start + 1:min(end, last + 1)] if not _history_wake_prompt(m)]
    own = [m for m in span if not any(k.startswith("cli-assistant:") for k in _idempotency_keys(m))]
    # The closing copy replaces Claude Code's own record when texts match
    # (cli-session-history mergeCliHistoryRow).
    answered = any(m.get("role") == "assistant" and _history_renderer([m]).text.strip() for m in own
                   if isinstance(m, dict))
    return own if answered else span


def _history_steered_tail(history: dict, run_id: str) -> list | None:
    """What follows `run_id`'s message up to the next turn, without the host's
    closing copy (the whole run): its answer when the run it went into never
    closed it. None without the message."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    start = next((n for n, m in enumerate(messages) if _history_user_run_id(m) == run_id), None)
    if start is None:
        return None
    end = next((n for n in range(start + 1, len(messages)) if _history_next_turn(messages[n])), len(messages))
    return [m for m in messages[start + 1:end] if not _history_wake_prompt(m)
            and not any(k.startswith("cli-assistant:") for k in _idempotency_keys(m))]


def _history_later_turn(history: dict, run_id: str) -> bool:
    """A turn began after `run_id`'s message."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return False
    start = next((n for n, m in enumerate(messages) if _history_user_run_id(m) == run_id), None)
    return start is not None and any(_history_next_turn(m) for m in messages[start + 1:])


async def _await_steered_answer(conn, session_key: str, run_id: str, who: str, *,
                                steered: bool = False, host: str | None = None) -> dict | None:
    """Wait for the transcript to hold the answer of the run `run_id`'s
    message was steered into. The run's terminal and its idle push can come
    before the Gateway commits the message. Ends on the answer, a failed run,
    or a restart without the run, with the last transcript read (None if none).
    `host`: the run it went into, when the steer was seen here; then it also
    ends once the session settled. A claude-cli run stops counting as active
    only after it stored its answer (2026.10.10: `finishCliAttempt` awaits
    Claude Code's flush and the closing copy before the run resolves, and
    `deferredLifecycle.complete()` clears the active run after that), so the
    settled transcript holds the answer if there is one."""
    restarts = conn.gateway_restarts
    while True:
        appended = conn.session_message_event(session_key)
        changed = conn.session_change_event(session_key) if host else None
        pump = conn._turn_pumps.get((session_key, run_id))
        # A terminal means no commit, except the lone steered final: the
        # commit can come after it and the idle row.
        ended = pump is not None and pump.terminal.is_set() and not steered
        try:
            hist = await conn.session_history(session_key, limit=RUN_HISTORY_LIMIT)
        except Exception as ex:
            pipe_log(f"  {who}: chat.history failed waiting for a steered answer: {ex!r}")
            return None
        pending = _history_steered_answer_pending(hist, run_id, uncommitted=not ended, steered=steered)
        if host and not pending:
            # On claude-cli the transcript names the host only once it closed.
            pending = _history_steered_span(hist, run_id) is None and not _history_later_turn(hist, run_id)
        if not pending:
            return hist
        into = host or _history_steered_host(hist, run_id)
        if into and conn.runs_failed.get(f"{session_key}:{into}"):
            pipe_log(f"  {who}: the run its message went into "
                     f"ended {conn.runs_failed[f'{session_key}:{into}']} before answering it")
            return hist
        if conn.gateway_restarts > restarts and await _session_list_active(conn, session_key) is False:
            pipe_log(f"  {who}: the Gateway restarted without the "
                     "run its message went into; it ends without the answer")
            return hist
        if host and await _session_list_active(conn, session_key) is False:
            # The run it went into ended and the session settled: the
            # transcript holds all it will, closed or not.
            try:
                hist = await conn.session_history(session_key, limit=RUN_HISTORY_LIMIT)
            except Exception as ex:
                pipe_log(f"  {who}: chat.history failed after the session settled: {ex!r}")
            pipe_log(f"  {who}: the session settled with its steered message's answer not closed "
                     "in the transcript")
            return hist
        pipe_log(f"  {who} waits for its steered message's answer in the transcript")
        waits = [asyncio.ensure_future(appended.wait())]
        if changed is not None:
            waits.append(asyncio.ensure_future(changed.wait()))
        if pump is not None and not pump.terminal.is_set():
            waits.append(asyncio.ensure_future(pump.terminal.wait()))
        try:
            await asyncio.wait(waits, return_when=asyncio.FIRST_COMPLETED)
        finally:
            for w in waits:
                w.cancel()


def _history_queued_prompt(messages: list, index: int, run_id: str) -> bool:
    """Whether the message at `index` is a wake prompt sorted inside another
    run: 2026.10.10 stores it at fire time, and claude-cli imports the run's
    messages with their own times around it."""
    own = _history_user_run_id(messages[index])
    if own == run_id or not _history_wake_prompt(messages[index]):
        return False
    for message in reversed(messages[:index]):
        if _run_closed_by(message) not in (None, run_id):
            return False
        if _history_user_run_id(message):
            return True
    return False


def _stamped_before(message: dict, started_ms: float | None) -> bool:
    ts = (message or {}).get("timestamp")
    return started_ms is not None and isinstance(ts, (int, float)) and ts < started_ms


def _relay_output_events(sent: list[dict], current: list[dict]) -> list[dict]:
    """Responses events taking a tab's output from `sent` to `current`, as
    OWUI's `applyResponseStreamEvent` folds them. `added` needs an explicit
    `output_index`, or it is spliced in before the last item."""
    events: list[dict] = []
    for i, item in enumerate(current):
        old = sent[i] if i < len(sent) else None
        is_message = item.get("type") == "message"
        text = (item.get("content") or [{}])[0].get("text", "") if is_message else ""
        if old is None:
            added = copy.deepcopy(item)
            if is_message:
                added["content"] = [{"type": "output_text", "text": ""}]
            events.append({"type": "response.output_item.added",
                           "output_index": i, "item": added})
            if text:
                events.append({"type": "response.output_text.delta", "item_id": item["id"],
                               "output_index": i, "content_index": 0, "delta": text})
            continue
        if is_message and old.get("id") == item.get("id"):
            old_text = (old.get("content") or [{}])[0].get("text", "")
            if text != old_text and text.startswith(old_text):
                events.append({"type": "response.output_text.delta", "item_id": item["id"],
                               "output_index": i, "content_index": 0,
                               "delta": text[len(old_text):]})
                continue
        if item != old:
            events.append({"type": "response.output_item.done",
                           "output_index": i, "item": copy.deepcopy(item)})
    return events


def _relay_content_is_showable(text: str) -> bool:
    """True once text is non-empty and can no longer be a silent sentinel,
    so a sentinel-only run never flashes an empty bubble."""
    t = text.strip()
    if not t or t in _SILENT_SENTINELS:
        return False
    if any(s.startswith(t) for s in _SILENT_SENTINELS):
        return False
    return True


async def _relay_emit_event(user_id: str, chat_id: str, message_id: str | None,
                            data: dict) -> bool:
    """Emit one `events` envelope to the user room. False on failure."""
    if not message_id:
        return False
    try:
        from open_webui.socket.main import sio
    except Exception as ex:
        pipe_log(f"  socket emit unavailable (not inside OWUI process?): {ex}")
        return False
    try:
        await sio.emit(
            "events",
            {"chat_id": chat_id, "message_id": message_id, "data": data},
            room=f"user:{user_id}",
        )
        return True
    except Exception as ex:
        pipe_log(f"  socket emit failed: {ex}")
        return False


# ── Orphaned reply stubs (ELI-90) ──
# Only the streaming request sets a reply stub `done: True`. After an Open
# WebUI restart mid-turn the stub stays "running" forever, so the first load
# finishes it from the Gateway transcript.

ORPHAN_STUB_NOTE = (
    "*This reply was cut off before it finished (Open WebUI restarted or "
    "lost the run), and no reply for it could be recovered from OpenClaw. "
    "Send the message again if you still need an answer.*"
)
ORPHAN_STUB_SILENT_NOTE = "*The run for this message stopped without leaving a reply in the transcript.*"


def _run_id_sent_at(run_id: str) -> float | None:
    """The send time at the end of a pipe run id."""
    try:
        return float(run_id.rsplit("-", 1)[1]) if run_id.startswith("msg-") else None
    except (IndexError, ValueError):
        return None


def _stub_turn(history: dict, stub_id: str, user_text: str,
               stub_ts: float | None = None, steers: bool = False) -> dict | None:
    """The transcript turn a reply stub waited for: {"run_id", "messages",
    "closed", "by"} or None. Found by message id in the run id, else by user
    text: the first match sent after `stub_ts`, since short texts recur."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    starts = [i for i, m in enumerate(messages) if _history_user_run_id(m)]
    pick, by = None, "id"
    if stub_id:
        by_id = [i for i in starts if f"-{stub_id}-" in _history_user_run_id(messages[i])]
        pick = by_id[-1] if by_id else None
    text = (user_text or "").strip()
    if pick is None and text:
        by, by_text = "text", [i for i in starts if _recovery_user_text_matches(
            ((_history_item(messages[i]) or {}).get("text") or "").strip(), text)]
        if stub_ts is not None:
            # 2s of slack: Open WebUI stamps whole seconds.
            by_text = [i for i in by_text
                       if (_run_id_sent_at(_history_user_run_id(messages[i])) or 0) >= stub_ts - 2]
            pick = by_text[0] if by_text else None
        else:
            pick = by_text[-1] if by_text else None
    if pick is None:
        return None
    run_id = _history_user_run_id(messages[pick])
    if steers and _history_steered_host(history, run_id) is not None:
        span = _history_steered_span(history, run_id)
        return {"run_id": run_id, "messages": span or [], "closed": span is not None, "by": by}
    end = next((i for i in starts if i > pick), len(messages))
    turn = messages[pick + 1:end]
    closing = f"cli-assistant:{run_id}"
    for j, m in enumerate(turn):
        if closing in _idempotency_keys(m):
            return {"run_id": run_id, "messages": turn[:j + 1], "closed": True, "by": by}
    return {"run_id": run_id, "messages": turn, "closed": end < len(messages), "by": by}


def _owui_message_ts(message: dict) -> float | None:
    ts = message.get("timestamp")
    if isinstance(ts, (int, float)) and ts > 0:
        return ts / 1000 if ts > 1e11 else float(ts)  # ms or s
    return None


def _owui_process_started_at() -> float | None:
    """This process's start time (epoch seconds) from /proc, or None."""
    try:
        with open("/proc/self/stat") as fh:
            # Field 22; the command name may hold spaces, so count from ")".
            ticks = int(fh.read().rsplit(")", 1)[1].split()[19])
        with open("/proc/stat") as fh:
            btime = next(int(line.split()[1]) for line in fh if line.startswith("btime "))
        return btime + ticks / os.sysconf("SC_CLK_TCK")
    except Exception:
        return None


def _stub_predates_process(stub: dict) -> bool:
    """True when `stub` predates this process, so no request can fill it.
    Stamps are whole seconds, so the start's own second does not count."""
    started, ts = _owui_process_started_at(), _owui_message_ts(stub)
    return started is not None and ts is not None and ts < int(started)


async def _owui_chat_has_live_task(chat_id: str) -> bool:
    """True while Open WebUI runs a task for `chat_id`, or when unsure."""
    try:
        from open_webui.main import app
        from open_webui.tasks import list_task_ids_by_item_id
        return bool(await list_task_ids_by_item_id(getattr(app.state, "redis", None), chat_id))
    except Exception as ex:
        pipe_log(f"  orphan stub: cannot read Open WebUI tasks ({ex}); leaving chat {chat_id[:8]}... alone")
        return True


async def _session_list_active(conn: "_GatewayConnection", session_key: str,
                               *, missing: bool | None = False) -> bool | None:
    """`sessions.list` `hasActiveRun` for one session (unlike
    `sessions.describe`, counts a sub-agent yield gap). Searched by key: an
    unfiltered list holds only the newest 100 rows. `missing` when no such
    session; None when unknown."""
    try:
        lst = await conn.send_request(
            "sessions.list", {"search": session_key, "limit": _SESSION_READ_LIMIT}, timeout=15)
    except Exception as ex:
        pipe_log(f"  sessions.list for {session_key[-36:][:8]}... failed: {ex}")
        return None
    rows = lst.get("sessions") or []
    row = next((r for r in rows if r.get("key") == session_key), None)
    if row:
        return bool(row.get("hasActiveRun"))
    total = lst.get("totalCount")
    if len(rows) >= _SESSION_READ_LIMIT or (total is not None and total > len(rows)):
        pipe_log(f"  sessions.list for {session_key[-36:][:8]}...: {total or len(rows)} rows match, "
                 "none is the session; its state is unknown")
        return None
    return missing


async def _wait_for_session_idle(conn: "_GatewayConnection", session_key: str, is_active,
                                 on_busy=None) -> bool | None:
    """Wait until the Gateway says `session_key` has no run, with no ceiling
    (ELI-88): a ceiling drops the message. Only the flag decides, not
    `endedAt`. The event is taken before the read so no push slips between.
    Returns whether it was ever busy, or None when unknown."""
    ever_busy = False
    while True:
        changed = conn.session_change_event(session_key)
        active = await is_active()
        if active is None:
            return None
        if not active:
            return ever_busy
        if not ever_busy:
            ever_busy = True
            if on_busy is not None:
                await on_busy()
        await changed.wait()


# A long transcript takes the Gateway over the default 10 s RPC bound.
ORPHAN_HISTORY_TIMEOUT_S = 60


def _stub_session_key(conn: "_GatewayConnection", agent_id: str, user_id: str, chat_id: str,
                      stub_id: str) -> str:
    """The session of a stub's run, including another model's column (ELI-329)."""
    column = 0
    try:
        state_dir = _state_dir(getattr(conn._valves(), "STATE_DIR", ""))
        column = _history_column_of(state_dir, chat_id, [stub_id]) or 0
    except Exception as ex:
        pipe_log(f"  orphan stub {stub_id[:8]}...: no column ({ex!r}); using the chat's session")
    return _owui_session_key(agent_id, user_id, chat_id, column)


async def _reconcile_stub(conn: "_GatewayConnection", agent_id: str,
                          chat_id: str, stub_id: str, *, wait: bool = True) -> str:
    """Finish an orphaned reply stub from the transcript, waiting on the
    pushed settle for a live run. Returns "done", "wait" or "skip"."""
    from open_webui.models.chats import Chats
    waiting = False
    while True:
        chat = await Chats.get_chat_by_id(chat_id)
        msgs = ((chat.chat or {}).get("history") or {}).get("messages") or {} if chat else {}
        stub = msgs.get(stub_id) or {}
        if stub.get("role") != "assistant" or stub.get("done") is not False:
            return "skip"  # gone or finished meanwhile
        if _ended_by_stop(stub):
            # Stopped by the user: closed as it is, never rebuilt.
            async with conn._chat_write_lock(chat_id):
                if await _owui_upsert_message(chat_id, stub_id, {"done": True}) is None:
                    return "skip"
            pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: stopped by the user, "
                     "closed as it was")
            return "done"
        writer = (stub.get("meta") or {}).get("openclaw_writer")
        if writer:
            # A turn writer's message: adopt it once that writer is gone.
            if _turn_writer_alive(writer):
                return "skip"
            return await _adopt_turn_message(
                conn, chat_id=chat_id, user_id=chat.user_id, message_id=stub_id,
                session_key=_stub_session_key(conn, agent_id, chat.user_id, chat_id, stub_id),
                meta=stub.get("meta") or {})
        # No task id: its request may still be on its way, since that
        # request's model listing starts this sweep (ELI-156). Unless the stub
        # predates this process.
        task_id = (stub.get("meta") or {}).get("task_id")
        if not task_id and not _stub_predates_process(stub):
            return "skip"
        if await _owui_chat_has_live_task(chat_id):
            return "skip"  # a live request owns it
        session_key = _stub_session_key(conn, agent_id, chat.user_id, chat_id, stub_id)
        changed = conn.session_change_event(session_key)
        try:
            hist = await conn.session_history(session_key, limit=RUN_HISTORY_LIMIT,
                                              timeout=ORPHAN_HISTORY_TIMEOUT_S)
        except Exception as ex:
            pipe_log(f"  orphan stub {stub_id[:8]}...: chat.history failed: {ex!r}")
            return "skip"
        parent = msgs.get(stub.get("parentId")) or {}
        user_text = _coerce_text(parent.get("content")) if parent.get("role") == "user" else ""
        turn = _stub_turn(hist, stub_id, user_text, _owui_message_ts(stub),
                          steers=steers_mid_run_messages(conn.gateway_version))
        if turn is None or turn["closed"]:
            break  # no run to wait for, or it is over
        active = await _session_list_active(conn, session_key)
        if active is None:
            return "skip"
        if not active:
            break
        if not wait:
            return "wait"
        if not waiting:
            waiting = True
            pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: "
                     "its run is still going; finishing it when the run settles")
        await changed.wait()

    run_id = (turn or {}).get("run_id")
    # A stub with content is rebuilt only from a run matched by id.
    has_content = bool(_coerce_text(stub.get("content")).strip() or stub.get("output"))
    fields: dict = {"done": True}
    output: list | None = None
    text = ""
    if turn and (turn["by"] == "id" or not has_content):
        rendered = _history_renderer(turn["messages"])
        if not rendered.text.strip() and not rendered.output and not has_content:
            rendered._add_text(ORPHAN_STUB_SILENT_NOTE)
        if rendered.output:
            output = rendered.finished_output()
            text = rendered.text.strip()
            fields.update(content=text, output=output)
    elif not has_content:
        rendered = _TurnRenderer()
        rendered._add_text(ORPHAN_STUB_NOTE)
        output, text = rendered.finished_output(), rendered.text
        fields.update(content=text, output=output)
    async with conn._chat_write_lock(chat_id):
        chat = await Chats.get_chat_by_id(chat_id)
        msgs = ((chat.chat or {}).get("history") or {}).get("messages") or {} if chat else {}
        current = msgs.get(stub_id) or {}
        if current.get("done") is not False:
            return "skip"
        if _turn_writer_alive((current.get("meta") or {}).get("openclaw_writer")):
            return "skip"  # a turn writer took it over (DESIGN 2.6) and finishes it
        if (current.get("meta") or {}).get("task_id") != task_id:
            return "skip"  # a new request took it while the transcript was read
        claim = f"{session_key}:{run_id}" if run_id else None
        if claim:
            if claim in conn._claimed_runs:
                return "skip"  # another connection finished this run's stub
            conn._claimed_runs[claim] = True
        # Open WebUI returns None silently when the write fails.
        if await _owui_upsert_message(
                chat_id, stub_id, fields) is None:
            if claim:
                conn._claimed_runs.pop(claim, None)
            pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: "
                     "Open WebUI did not save the write (ELI-90)")
            return "skip"
        if run_id:
            conn.mark_delivered_live(session_key, run_id)
    if output is not None:
        await _relay_emit_event(chat.user_id, chat_id, stub_id,
                                {"type": "chat:completion", "data": {"output": output}})
    await _relay_emit_event(chat.user_id, chat_id, stub_id,
                            {"type": "chat:active", "data": {"active": False}})
    if getattr(conn._valves(), "PUBLISH_CHAT_FINISHED", False):
        await _publish_chat_finished(chat_id, stub_id, chat.user_id)
    cards = sum(1 for i in output or [] if i.get("type") == "function_call")
    if output is None:
        how = "closed, content kept"
    elif run_id:
        how = f"filled from run {run_id[:48]} by {turn['by']}"
    else:
        how = "no run in the transcript, note written"
    pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: {how} "
             f"({len(text)} chars, {cards} tool card(s)) (ELI-90)")
    return "done"


async def _orphan_stub_ids(prefixes: list[str]) -> list[tuple[str, str]]:
    """(chat_id, message_id) of this pipe's unfinished assistant messages.
    `chat_message` ids are `<chat_id>-<message_id>`."""
    from sqlalchemy import or_, select
    from open_webui.internal.db import get_async_db_context
    from open_webui.models.chat_messages import ChatMessage
    async with get_async_db_context() as db:
        rows = (await db.execute(
            select(ChatMessage.chat_id, ChatMessage.id)
            .where(ChatMessage.role == "assistant")
            .where(ChatMessage.done.is_(False))
            .where(or_(*[ChatMessage.model_id.startswith(p) for p in prefixes]))
        )).all()
    out = []
    for chat_id, composite in rows:
        prefix = f"{chat_id}-"
        out.append((chat_id, composite[len(prefix):] if composite.startswith(prefix) else composite))
    return out


_orphan_reconcile_task: "asyncio.Task | None" = None


async def _reconcile_orphan_stubs(valves_getter) -> None:
    try:
        conn = await _get_gateway_connection(valves_getter)
        agent_id = getattr(valves_getter(), "AGENT_ID", "") or "main"
        stubs = await _orphan_stub_ids(
            _composer_model_prefixes(own_id=_composer_own_function_id()))
    except Exception as ex:
        pipe_log(f"  orphan stub reconcile could not start: {ex}")
        return
    if stubs:
        pipe_log(f"  orphan stub reconcile: {len(stubs)} unfinished OpenClaw "
                 "repl(y/ies) in Open WebUI")
    # One at a time: SQLite rejects concurrent chat writes.
    counts: dict = {}
    for chat_id, stub_id in stubs:
        status = await _reconcile_stub_logged(conn, agent_id, chat_id, stub_id, wait=False)
        counts[status] = counts.get(status, 0) + 1
        if status == "wait":
            spawn_background(_reconcile_stub_logged(conn, agent_id, chat_id, stub_id))
    if stubs:
        pipe_log(f"  orphan stub reconcile: {counts}")
    try:
        await _reconcile_ended_while_down(conn, agent_id)
    except Exception as ex:
        pipe_log(f"  ended-while-down reconcile failed: {ex!r}")


def _history_closed_runs(messages: list) -> list:
    """[(run_id, closing ms)] of closed runs: claude-cli by its
    `cli-assistant:<runId>` key, an embedded run by the run id itself."""
    started = {run for run, _tool in _history_user_turns(messages)}
    out = []
    for m in messages or []:
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        for k in _idempotency_keys(m):
            run = k[len("cli-assistant:"):] if k.startswith("cli-assistant:") else (k if k in started else "")
            if run and isinstance(m.get("timestamp"), (int, float)):
                out.append((run, m["timestamp"]))
                break
    return out


def _settled_run_span(history: dict, run_id: str) -> list | None:
    """A settled run's span, else everything after its user turn."""
    span = _history_span_messages(history, run_id)
    if span is not None:
        return span
    messages = (history or {}).get("messages")
    for i, m in enumerate(messages if isinstance(messages, list) else []):
        if _history_user_run_id(m) == run_id:
            return messages[i + 1:]
    return None


async def _reconcile_ended_while_down(conn: "_GatewayConnection", agent_id: str) -> None:
    """ELI-94 (agent-turns.md case 4): a graceful stop saves a reply `done:
    true`, and its run closes while Open WebUI is down. Chats whose session
    `updatedAt` is newer than their `updated_at` get those runs rebuilt."""
    from open_webui.models.chats import Chats
    lst = await _list_all_sessions(conn)
    prefix = f"agent:{agent_id}:openwebui-"
    fixed = 0
    for row in lst.get("sessions") or []:
        key = row.get("key") or ""
        if not key.startswith(prefix) or row.get("hasActiveRun"):
            continue  # not ours, or a run still going: the handover (2.6) owns it
        after = key[len(prefix):]
        if len(after) != 73 or after[36] != "-":
            continue
        user_id, chat_id = after[:36], after[37:]
        updated = row.get("updatedAt")
        if not isinstance(updated, (int, float)):
            continue
        chat = await Chats.get_chat_by_id(chat_id)
        if chat is None or chat.user_id != user_id:
            continue
        written = int(getattr(chat, "updated_at", 0) or 0)
        if int(updated // 1000) <= written:
            continue
        fixed += await _reconcile_chat_ended_runs(conn, key, chat_id, written,
                                                  session_id=row.get("sessionId"),
                                                  last_run=row.get("lastRunId"), settled_ms=updated)
    if fixed:
        pipe_log(f"  ended-while-down reconcile: completed {fixed} repl(y/ies) (ELI-94)")


async def _reconcile_chat_ended_runs(conn: "_GatewayConnection", session_key: str,
                                     chat_id: str, written: int, *,
                                     session_id: str | None, last_run: str | None = None,
                                     settled_ms: float | None = None) -> int:
    """Rebuild finished replies whose run closed after `written` and that hold
    less than the transcript. `lastRunId` counts as closed at `settled_ms`
    (the embedded runtime writes no closer). Returns how many."""
    from open_webui.models.chats import Chats
    if await _owui_chat_has_live_task(chat_id):
        return 0  # a reply is streaming: its own request finishes it
    hist = await conn.session_history(session_key, limit=RUN_HISTORY_LIMIT,
                                      timeout=ORPHAN_HISTORY_TIMEOUT_S)
    messages = (hist or {}).get("messages") or []
    closed = _history_closed_runs(messages)
    if last_run and settled_ms and last_run not in {r for r, _ms in closed}:
        closed.append((last_run, settled_ms))
    targets: dict = {}
    for run, closed_ms in closed:
        # A wake's closer is keyed by the sessionId and deduplicated (ELI-103).
        if run == session_id or int(closed_ms // 1000) <= written:
            continue
        mid = run_message_id(session_key, chat_id, run, messages)
        if mid:
            targets.setdefault(mid, run)
    fixed = 0
    for mid, run in targets.items():
        runs = [r for r, _tool in _history_user_turns(messages)
                if r != session_id and run_message_id(session_key, chat_id, r, messages) == mid]
        if run not in runs:
            runs.append(run)
        spans = [_settled_run_span(hist, r) if r == last_run else _history_span_messages(hist, r)
                 for r in runs]
        if any(s is None for s in spans):
            continue  # a run written into it has not closed
        rendered = _history_renderer([m for s in spans for m in s])
        output, text = await _transcript_view(
            conn, session_key=session_key, chat_id=chat_id,
            user_id=session_key.rsplit("openwebui-", 1)[-1][:36], message_id=mid,
            runs=runs, messages=messages, rendered=rendered)
        if not output:
            continue
        async with conn._chat_write_lock(chat_id):
            chat = await Chats.get_chat_by_id(chat_id)
            msgs = ((chat.chat or {}).get("history") or {}).get("messages") or {} if chat else {}
            current = msgs.get(mid) or {}
            if current.get("role") != "assistant" or current.get("done") is not True:
                continue  # missing, or still generating: the ELI-90 pass owns done:false
            if _ended_by_stop(current):
                continue  # what the user stopped is what it shows
            held_cards = sum(1 for i in current.get("output") or [] if i.get("type") == "function_call")
            cards = sum(1 for i in output if i.get("type") == "function_call")
            held_text = _coerce_text(current.get("content")).strip()
            if cards < held_cards or (cards == held_cards and len(text) <= len(held_text)):
                continue  # holds as much as the transcript: never rewritten
            if await _owui_upsert_message(
                    chat_id, mid, {"content": text, "output": output, "done": True}) is None:
                pipe_log(f"  ended-while-down {mid[:8]}... in chat {chat_id[:8]}...: "
                         "Open WebUI did not save the write (ELI-94)")
                continue
            conn.mark_delivered_live(session_key, run)
        await _relay_emit_event(chat.user_id, chat_id, mid,
                                {"type": "chat:completion", "data": {"output": output}})
        if getattr(conn._valves(), "PUBLISH_CHAT_FINISHED", False):
            await _publish_chat_finished(chat_id, mid, chat.user_id)
        pipe_log(f"  ended-while-down {mid[:8]}... in chat {chat_id[:8]}...: completed from "
                 f"{len(runs)} run(s) ({len(text)} chars, {cards} tool card(s), "
                 f"held {held_cards}) (ELI-94)")
        fixed += 1
    return fixed


async def _reconcile_stub_logged(conn, agent_id, chat_id, stub_id, *, wait=True) -> str:
    try:
        return await _reconcile_stub(conn, agent_id, chat_id, stub_id, wait=wait)
    except Exception as ex:
        pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: reconcile failed: {ex!r}")
        return "failed"


def _ensure_orphan_reconcile(valves_getter) -> None:
    """Once per Function load (a deploy is harmless: live replies are skipped)."""
    global _orphan_reconcile_task
    if _orphan_reconcile_task is not None:
        return
    try:
        import open_webui.models.chat_messages  # noqa: F401  (inside Open WebUI only)
    except Exception:
        return
    _orphan_reconcile_task = spawn_background(_reconcile_orphan_stubs(valves_getter))


def _turn_session_message(conn: "_GatewayConnection", sess: str) -> None:
    """Re-read the row on an append while a message waits for a recovery: a
    give-up tombstones it unpushed (9.3 main-session-restart-recovery-
    CPJjd8da.mjs:1135-1153, 10.10 -DnTvOdiE.mjs:1040-1062)."""
    if any(w.session_key == sess and not w.closed and w.awaiting_row
           for w in list(conn._turn_writers.values())):
        spawn_background(_turn_reread_row(conn, sess))


async def _turn_reread_row(conn: "_GatewayConnection", sess: str) -> None:
    try:
        lst = await conn.send_request("sessions.list", {"search": sess[-36:], "limit": 10}, timeout=15)
    except Exception as ex:
        pipe_log(f"  turn writer: row read after an append failed: {ex!r}")
        return
    row = next((r for r in (lst.get("sessions") or []) if r.get("key") == sess), None)
    if row is not None and not row.get("hasActiveRun"):
        _turn_settled(conn, sess, row)


class _TurnHooks:
    """What `_GatewayConnection` calls into the turn writer with (`_TURNS`)."""
    route_now = staticmethod(_turn_route_now)
    after_hello = staticmethod(_turn_after_hello)
    resync = staticmethod(_turn_resync)
    settled = staticmethod(_turn_settled)
    next_run = staticmethod(_turn_next_run)
    note_heartbeat = staticmethod(_note_heartbeat_run)
    hand_over = staticmethod(_hand_over_run)
    session_message = staticmethod(_turn_session_message)
    end_unsent_replies = staticmethod(_end_unsent_replies)
    settle_steered_replies = staticmethod(_settle_steered_replies)


_TURNS = _TurnHooks


